class Facts

  def initialize(mod : (Int64|Int32) = 10**9+7, n_max : (Int64|Int32) = 1_i64 )
    @mod = mod
    @n_max = n_max
    @fact = [1_i64, 1_i64]
    @inv = [0_i64, 1_i64]
    @factinv = [1_i64, 1_i64]
    setup_table(n_max) if 1 < @n_max
  end

  def cmb(n,r)
    return 0 if (r < 0 || n < r)
    setup_table(n) if @n_max < n
    @fact[n] * (@factinv[r] * @factinv[n-r] % @mod) % @mod
  end

  def factorial(n)
    setup_table(n) if @n_max < n
    @fact[n]
  end

  def prm(n,k)
    setup_table(n) if @n_max < n
    @fact[n] * @factinv[n-k] % @mod
  end

  # O(t - @n_max)
  private def setup_table(t)
    (@n_max+1).upto(t) do |i|
      @fact.push( @fact[-1] * i % @mod )
      @inv.push( -@inv[@mod % i] * (@mod // i) % @mod )
      @factinv.push( @factinv[-1] * @inv[-1] % @mod )
    end
    @n_max = t
  end
end

struct Int

  # O(log n)
  def pow(n : Int, mod = nil ) : Int
    a = to_i64
    res = 1_i64
    while n > 0
      if (n & 1) != 0
        res *= a
        res %= mod if mod
      end
      a *= a
      a %= mod if mod
      n >>= 1
    end
    res
  end
end

