import java.io._
import java.util.StringTokenizer
import scala.util.control.Breaks.{breakable,break}
import scala.collection.mutable.{Map, Stack, Queue, PriorityQueue, Set}

object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val MOD = 998244353L
  val N, M, K = in.next().toInt  

  //
  val p = MOD
  // 素数modulo `p` の世界での割り算

  // (x ^ n) % p
  def repeatSquares(x: Long, n: Long): Long = {
    if(n == 0)
      1
    else if(n % 2 == 0)
      repeatSquares(x*x % p, n/2)
    else
      (x * repeatSquares(x*x % p, n/2)) % p
  }


  // a / b
  def modDiv(a: Long, b: Long): Long = {
    val numer = a % p
    val denom = repeatSquares(b, p-2)

    (numer * denom) % p
  }

  val mc = new ModComb(N, MOD)

  var base: Long =
    if (M-1 == 0 && N >= 2)
      0L
    else
      repeatSquares(M-1, N-1)

  base *= M
  base %= MOD

  var ans = base

  for (i <- 1 to K) {
    base = modDiv(base, M-1)

    val hoge = (base * mc.comb(N-1, i)) % MOD

    ans += hoge
    ans %= MOD
  }

  if (M == 1 && K == N-1)
    println(N)
  else
    println(ans)
}


class ModComb(maxNum: Int, mod: Long) {

  private def repeatSquares(x: Long, n: Long): Long = {
    if(n == 0)
      1
    else if(n % 2 == 0)
      repeatSquares(x*x % mod, n/2)
    else
      (x * repeatSquares(x*x % mod, n/2)) % mod
  }

  val fact = new Array[Long](maxNum + 1)

  fact(0) = 1
  for (i <- 1 to maxNum)
    fact(i) = (i * fact(i-1)) % mod

  val factInv = new Array[Long](maxNum + 1)

  factInv(maxNum) = repeatSquares(fact(maxNum), mod-2)
  for (i <- (1 to maxNum).reverse)
    factInv(i-1) = (i * factInv(i)) % mod


  // nCk
  def comb(n: Int, k: Int): Long = {
    val numer = fact(n)
    val denom = (factInv(n-k) * factInv(k)) % mod

    (numer * denom) % mod
  }

}


