struct Problem{
    UL N, M, K;
    static const ULL MOD = 998244353;
    static const UL X = 500000;
    ULL F[X+1];
    ULL I[X+1];
    ULL iF[X+1];

    ULL C(UL n, UL r) {
        return F[n] * iF[r] % MOD * iF[n - r] % MOD;
    }
    static ULL POW(ULL a, ULL i) {
        if (i == 0) return 1;
        if (i & 1) return POW(a * a % MOD, i >> 1) * a % MOD;
        return POW(a * a % MOD, i >> 1);
    }

    void Solve() {
        cin >> N >> M >> K;
        F[0] = 1; for (UL i = 1; i <= X; i++) F[i] = F[i - 1] * i % MOD;
        I[1] = 1; for (UL i = 2; i <= X; i++) I[i] = MOD - MOD / i * I[MOD % i] % MOD;
        iF[0] = 1; for (UL i = 1; i <= X; i++) iF[i] = iF[i - 1] * I[i] % MOD;
        ULL ans = 0;
        for (UL x = 0; x <= K; x++) {
            ULL Cs = N - x;
            ULL tmp = M * POW(M - 1, Cs - 1) % MOD;
            tmp = tmp * C(N - 1, Cs - 1) % MOD;
            ans += tmp;
        }
        ans %= MOD;
        cout << ans << endl;
    }
};
int main() {
    unique_ptr<Problem> p(new Problem());
    p->Solve();
    return 0;
}

