using namespace std;

class Solution {
    public:
        long long solve(int n, int m, int K) {
            init(n + K + 123);

            vector<long long> cnts(n + 2, 1);
            cnts[1] = m;
            for (int i = 2; i <= n; ++i) {
                cnts[i] = cnts[i - 1] * (m - 1) % MOD;
            }

            long long res = 0;

            for (int i = 1; i <= n; ++i) {
                if (n - i <= K) {
                    res += cnts[i] * nCr(n - 1, i - 1) % MOD;
                    res %= MOD;
                }
            }

            return res;
        }

    private:
    const static long long MOD = 998244353;

    vector<long long> pow2;
    vector<long long> F;
    vector<long long> IF;

    long long norm(long long a) {
        a %= MOD;
        if (a < 0) {
            a += MOD;
        }
        return a;
    }

    long long inverse(long long a) {
        long long b = MOD;
        long long u = 0, v = 1;
        a = norm(a);
        while (a != 0) {
            long long d = b / a;
            b -= d * a;
            u -= d * v;
            swap(a, b);
            swap(u, v);
        }
        return norm(u);
    }

    long long powM(long long x, long long e) {
        long long res = 1;
        while (e > 0) {
            if (e & 1) {
                res = res * x % MOD;
            }
            x = x * x % MOD;
            e >>= 1;
        }
        return res;
    }

    void init(int n) {
        F.clear();
        F.resize(n + 1, 1);
        IF = F;
        pow2.clear();
        pow2.resize(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            pow2[i] = pow2[i - 1] * 2 % MOD;
        }

        for (int i = 1; i <= n; ++i) {
            F[i] = F[i - 1] * i % MOD;
        }
        IF[n] = inverse(F[n]);
        for (int i = n - 1; i > 0; --i) {
            IF[i] = IF[i + 1] * (i + 1) % MOD;
        }
    }

    long long nCr(int n, int r) {
        if (r < 0 || r > n) {
            return 0;
        }
        long long res = F[n] * IF[r] % MOD * IF[n - r] % MOD;
        return res;
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);


    int n, m, k;
    cin >> n >> m >> k;

    Solution sol;

    cout << sol.solve(n, m, k) << '\n';

    return 0;
}

