// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
// 二項係数計算
long long COM(int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
template< typename T >
T mod_pow(T x, T n, const T &p) {
  T ret = 1;
  while(n > 0) {
    if(n & 1) (ret *= x) %= p;
    (x *= x) %= p;
    n >>= 1;
  }
  return ret;
}
int main() {
    // 前処理
    COMinit();
  ll N,M,K;
  cin>>N>>M>>K;
  ll ans=0;
  for(int i=0;i<=K;i++){
    ll memo;
    memo=COM(N-1,i);
    memo=(M*memo)%MOD;
    memo=(memo*mod_pow(M-1,N-i-1ll,(ll)(MOD)))%MOD;
    ans=(ans+memo)%MOD;
  }
  cout<<ans;
}

