const int MOD = 998244353;

ll powmod(ll a, ll b) {
  a %= MOD;
  ll res = 1;
  while (b > 0) {
    if (b % 2 == 1) res = res * a % MOD;
    a = a * a % MOD;
    b /= 2;
  }
  return res;
}
ll f[210000];
void cominit() {
  f[0] = 1;
  for (int i = 0; i < 200000; i++) {
    f[i + 1] = f[i] * (i + 1) % MOD;
  }
}

ll nCr(ll n, ll r) {
  if (n < r) return 0;
  if (n < 0 or r < 0) return 0;
  return f[n] * powmod(f[r] * f[n - r], MOD - 2) % MOD;
}

ll nPr(ll n, ll r) {
  if (n < r) return 0;
  if (n < 0 or r < 0) return 0;
  return f[n] * powmod(f[n - r], MOD - 2) % MOD;
}

ll nHr(ll n, ll r) {
  if (n < r) return 0;
  if (n < 0 or r < 0) return 0;
  return nCr(n + r - 1, r);
}

int main() {
  ll n, m, k;
  cin >> n >> m >> k;
  cominit();
  ll ans = 0;
  for (int i = 0; i < k + 1; i++) {
    ll res = nCr(n - 1, i);
    res *= m * powmod(m - 1, n - i - 1) % MOD;
    res %= MOD;
    ans = (ans + res) % MOD;
  }
  cout << ans << endl;
}

