ll mod = 998244353;

ll ml(ll a, ll b){
    return (a * b) % mod;
}

ll bin_pow(ll b, ll p){
    if (p == 0)
        return 1;

    if (p % 2 == 1) {
        return ml(b, bin_pow(b, p - 1));
    }
    ll val = bin_pow(b, p >> 1);
    return ml(val, val);
}

ll get_back(ll elem){
    return bin_pow(elem, mod - 2);
}

ll facts[MAXN];

ll backs[MAXN];

ll add(ll a, ll b){
    return (a + b) % mod;
}


ll nCr(int n, int r) {
    return ml(facts[n],
              get_back(
                      ml(facts[r],
                         facts[n - r])));
}

void solve() {
    ll n, m, k;
    cin >> n >> m >> k;

    facts[0] = 1;

    for (int i = 1; i <= n; ++ i) {
        facts[i ] = ml(facts[ i - 1], i);
        backs[i] = get_back(facts[i]);
    }

    ll answr = 0;


    for (int i = 0;i <= k; ++ i) {
        ll curr = m;

        ll cnts = nCr(n - 1, i);

        curr = ml(curr, cnts);

        ll nums = bin_pow(m - 1, n - 1 - i);
        curr = ml(curr, nums);

        answr = add(answr, curr);
    }

    cout << answr;
}

