using namespace std;

#define MODNUMBER 998244353

long long pow_mod(long long a, long long n)
{ // a^n mod MODNUMBER
	long long result = 1;
	long long a_i = a;
	long long n_tmp = n;
	while (n_tmp > 0)
	{
		if (n_tmp & 0b1)
		{
			result = (result * a_i) % MODNUMBER;
			// cout << result << "\n";
		}
		a_i = a_i * a_i % MODNUMBER;
		n_tmp = n_tmp >> 1;
	}
	return result;
}

long long fact_mod(long long k)
{ // k! mod MODNUMBER

	long long result = 1;
	for (int i = 1; i <= k; i++)
	{
		result = (result * i) % MODNUMBER;
	}
	return result;
}
vector<long long> fact_mod_vector(long long k)
{ // k! mod MODNUMBER

	vector<long long> result(k + 1, 1);
	result[0] = 1;
	for (int i = 1; i <= k; i++)
	{
		result[i] = (result[i - 1] * i) % MODNUMBER;
	}
	return result;
}

long long inv_mod(long long k)
{ // k^(-1) mod MODNUMBER

	return pow_mod(k, MODNUMBER - 2);
}

/* TODO: fact_mod()の途中経過を使いまわす実装にすれば早くなるらしい */
long long comb_mod(long long n, long long k, vector<long long> *fact_result)
{ // nCk mod MODNUMBER
	return ((*fact_result)[n] *
			inv_mod(((*fact_result)[k] * (*fact_result)[n - k]) % MODNUMBER)) %
		   MODNUMBER;
}

int main()
{
	//cin.tie(0);
	//ios::sync_with_stdio(false);

	long long N, M, K;
	scanf("%lld %lld %lld", &N, &M, &K);

	long long result = 0;

	vector<long long> fact_result = fact_mod_vector(N - 1);

	for (int i = 0; i <= K; i++)
	{
		// M *(N - 1Ci * (M - 1) ^ (M - 1 - i))
		long long tmp = (comb_mod(N - 1, i, &fact_result) * pow_mod(M - 1, M - 1 - i)) % MODNUMBER;
		// cout << "i=" << i << "tmp=" << tmp << "\n";
		result = (result + tmp) % MODNUMBER;
	}

	cout << ((result * M) % MODNUMBER);
