ll modex(ll x,ll y)
{
    x=x%mod;
    ll r=1;
    while(y>0)
    {
        if(y%2==1)
            r=(r*x)%mod;
        y/=2;
        x=(x*x)%mod;
    }
    return r;
}

ll mm(ll x,ll y)
{
    return (x*y)%mod;
}
ll fact[200001];
ll inv_fact[200001];
void build(void)
{
    fact[0]=1;
    ll i;
    fs(i,1,200001)
    {
        fact[i]=mm(fact[i-1],i);
    }
    inv_fact[200000]=modex(fact[200000],mod-2);
    fr(i,199999)
    {
        inv_fact[i]=mm(inv_fact[i+1],i+1);
    }
}

ll C(ll n,ll r)
{
    if(n<r)
        return 0;
    ll res=fact[n];
    res=mm(res,inv_fact[n-r]);
    return mm(res,inv_fact[r]);
}

