  long long ans = 0;
  for ( int i = 0; i <= k; i++ ) {
    long long now = m;
    now = now * BC.combination(n-1, i) % mod;
    now = now * pow_mod(m-1, n-1-i) % mod;
    ans = (ans + now) % mod;
  }

  cout << ans << endl;
  return 0;
}

