template <uint_fast64_t MOD> class ModInt {
    using u64 = uint_fast64_t;

  public:
    u64 a;

    ModInt(const u64 x = 0) : a(x % MOD) {}
    constexpr u64 &value() { return a; }
    constexpr ModInt operator-() { return a ? MOD - a : 0; }
    constexpr ModInt operator+(const ModInt rhs) {
        return ModInt(*this) += rhs;
    }
    constexpr ModInt operator-(const ModInt rhs) {
        return ModInt(*this) -= rhs;
    }
    constexpr ModInt operator*(const ModInt rhs) {
        return ModInt(*this) *= rhs;
    }
    constexpr ModInt operator/(const ModInt rhs) {
        return ModInt(*this) /= rhs;
    }
    constexpr ModInt &operator+=(const ModInt rhs) {
        a += rhs.a;
        if(a >= MOD) {
            a -= MOD;
        }
        return *this;
    }
    constexpr ModInt &operator-=(const ModInt rhs) {
        if(a < rhs.a) {
            a += MOD;
        }
        a -= rhs.a;
        return *this;
    }
    constexpr ModInt &operator*=(const ModInt rhs) {
        a = a * rhs.a % MOD;
        return *this;
    }
    constexpr ModInt &operator/=(const ModInt rhs) {
        *this *= rhs.inv();
        return *this;
    }

    constexpr bool operator==(const ModInt rhs) { return this->a == rhs.a; }
    constexpr bool operator!=(const ModInt rhs) { return this->a != rhs.a; }
    friend constexpr ostream &operator<<(ostream &os, const ModInt<MOD> &x) {
        return os << x.a;
    }
    friend constexpr istream &operator>>(istream &is, ModInt<MOD> &x) {
        return is >> x.a;
    }

    constexpr ModInt inv() {
        u64 x = a, y = MOD, u = 1, v = 0, t = 0;
        while(y > 0) {
            t = x / y;
            a -= t * y;
            swap(x, y);
            u -= t * v;
            swap(u, v);
        }
        return ModInt(u);
    }

    constexpr ModInt pow(int e) {
        u64 x = 1, p = a;
        while(e > 0) {
            if(e % 2 == 0) {
                p = (p * p) % MOD;
                e /= 2;
            } else {
                x = (x * p) % MOD;
                e--;
            }
        }
        return ModInt(x);
    }
};

