uint64_t inverse(uint64_t x, uint64_t n){
  uint64_t a, b, v, u;
  a = n, b = (x % n + n) % n;
  v = 0, u = 1;
  while(b > 0){
    uint64_t t;
    t = u;
    u = v - a / b * u;
    v = t;
    t = b;
    b = a % b;
    a = t;
  }
  return (v + n) % n;
}

