  }
  REP(i, min(n, k + 1)){
    r += p;
    (p *= n - 1 - i) %= mod;
    (p *= inverse(i + 1, mod)) %= mod;
    (p *= mi) %= mod;
  }
  (r *= m) %= mod;
  cout << r << endl;
  return 0;
}

