{
	if(m > n)return 0;
	if(m == n)return 1;
	if(m > n - m)m = n - m;
	ll a = 1, b = 1 ;
	for(ll i = 0 ; i < m ; i++){
		a = a * (n - i) % p;
		b = b * (i + 1) % p;
	}
