        int n_inv = fast_pow(factorials[n], MOD - 2, MOD);
        invs.push_back(n_inv);
        accumulation = n_inv;
        for (int i = n; i >= 2; --i) {
            accumulation *= i;
            accumulation %= MOD;
            invs.push_front(accumulation);
        }
        invs.push_front(1);
    }

    int calc(int n, int r) {
        long long signed res = 1ll * factorials[n] * invs[r] % MOD;
        return 1ll * res * invs[n - r] % MOD;
    }

    std::deque<int> factorials;
    std::deque<int> invs;
};

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    Combination<P> comb(n);
    ll ans = 0;
    for (int i = 0; i <= k; ++i) {
        ans += (1ll * m * comb.calc(n - 1, i) % P) * fast_pow(m - 1, n - 1 - i, P);
        ans %= P;
    }
    cout << ans;

    return 0;
}

