vector<pll> prime_factorize(ll number)
{
	vector<pll> res;
	for (ll divisor = 2; divisor * divisor <= number; divisor++)
	{
		if (number % divisor != 0)
			continue;
		ll exponent = 0;
		while (number % divisor == 0)
		{
			number /= divisor;
			exponent++;
		}
		res.push_back({ divisor, exponent });
	}
	if (number != 1)
		res.push_back({ number, 1 });
	return res;
}

