int N, M, K;
const int modConst = 998244353;

int facMemo[200005];
long long fastExp(int A, int B)
{
	if(B == 0)
		return 1 % modConst;

	long long Sqrt = fastExp(A, B / 2), ans = (Sqrt * Sqrt) % modConst;
	if(B % 2 == 1)
		ans *= (long long)A % modConst;

	return ans % modConst;
}

long long modInverse(int X)
{
	return fastExp(X, modConst - 2);
}

long long choose(int N, int R)
{
	//return N! / (N - R)! / R!
	long long ans = (facMemo[N] * modInverse(facMemo[N - R])) % modConst;
	ans = (ans * modInverse(facMemo[R])) % modConst;

	return ans;

}

int main()
{
	scanf("%d%d%d", &N, &M, &K);

	facMemo[0] = 1 % modConst;
	for(int i = 1; i <= N; i++)
	{
		long long tmp = (long long)(facMemo[i - 1]) * i;
		facMemo[i] = tmp % modConst;
	}

	long long ans = 0;
	for(int i = 0; i <= K; i++)
	{
		//ans += M * choose(N - 1, N - K - 1) * fastExp(M - 1, N - K - 1);
		long long temp = (choose(N - 1, N - i - 1) * fastExp(M - 1, N - i - 1)) % modConst;

		temp = (temp * M) % modConst;
		ans += temp;

		ans %= modConst;
	}

	printf("%lld", ans);
}

