class segment_tree_max {
private:
    vector<ll> m;
    vector<ll> delta;
    int n;
    bool is_bulk;

    ll get_val(int i) {
        if (!is_bulk) {
            return m[i];
        }

        ll ans = m[i] + delta[i];
        i /= 2;
        while (i >= 1) {
            ans += delta[i];
            i /= 2;
        }
        return ans;
    }

    void inc(int i, ll val) {
        delta[i] += val;
        i /= 2;
        while (i >= 1) {
            m[i] = max(m[2 * i] + delta[2 * i], m[2 * i + 1] + delta[2 * i + 1]);
            i /= 2;
        }
    }
public:
    segment_tree_max() {
    }
    segment_tree_max(int nn, int def, bool bulk=false) {
        is_bulk = bulk;

        n = 1;
        while (n < nn) {
            n *= 2;
        }

        m.assign(2 * n, def);
        if (is_bulk) {
            delta.assign(2 * n, 0);
        }
    }

    ll get_max(int l, int r) {
        if (l > r) {
            swap(l, r);
        }
        l += n; r += n;

        ll ans = -INF;
        while (l <= r) {
            if (l % 2 == 1) {
                ans = max(ans, get_val(l));
                l++;
            }
            if (r % 2 == 0) {
                ans = max(ans, get_val(r));
                r--;
            }

            l /= 2; r /= 2;
        }

        return ans;
    }

    void inc_bulk(int l, int r, ll val) {
        if (!is_bulk) {
            cout << "cant inc_bulk in not bulk mode" << endl;
            exit(1);
        }

        if (l > r) {
            swap(l, r);
        }
        l += n;
        r += n;

        while (l <= r) {
            if (l % 2 == 1) {
                inc(l, val);
                l++;
            }
            if (r % 2 == 0) {
                inc(r, val);
                r--;
            }

            l /= 2; r /= 2;
        }
    }

    void update(int i, ll val) {
        i += n;
        m[i] = val;
        i /= 2;
        while (i >= 1) {
            if (is_bulk) {
                m[i] = max(m[2 * i] + delta[2 * i], m[2 * i + 1] + delta[2 * i + 1]);
            } else {
                m[i] = max(m[2 * i], m[2 * i + 1]);
            }
            i /= 2;
        }
    }
};

class segment_tree_min {
private:
    segment_tree_max max_tree;
public:
    segment_tree_min() {
    }
    segment_tree_min(int nn, int def=INF, bool bulk=false) {
        max_tree = segment_tree_max(nn, -def, bulk);
    }

    ll get_min(int l, int r) {
        return -max_tree.get_max(l, r);
    }

    void inc_bulk(int l, int r, ll val) {
        max_tree.inc_bulk(l, r, -val);
    }

    void update(int i, ll val) {
        max_tree.update(i, -val);
    }
};

