const int mod = 998'244'353;
const int inf = 1e9 + 5;

struct mint {
    ll x;
    mint(ll x=0) : x(x%mod) {}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x -= a.x) < 0) x += mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) {
        mint res(*this);
        return res*=a;
    }
};

const int MAX = 200'000 + 5;
ll fac[MAX], finv[MAX], inv[MAX];

void initComb() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    srep(i, 2, MAX) {
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}
ll comb(ll n, ll k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << std::setprecision(10);

    initComb();
    int n, m, k; std::cin >> n >> m >> k;
    mint ans = m;
    rep(i, n-1) ans *= m-1;
    mint mm = m;
    rrep(i, k) {
        ans += mm * comb(n-1, i);
    }
    std::cout << ans.x << "\n";
}

