int64_t inverse(int64_t x, int64_t n){
  int64_t a, b, v, u;
  a = n, b = (x % n + n) % n;
  v = 0, u = 1;
  while(b > 0){
    int64_t t;
    t = u;
    u = v - a / b * u;
    v = t;
    t = b;
    b = a % b;
    a = t;
  }
  return (v % n + n) % n;
}

