class mod_factorial
{
public:
	mod_factorial(int n)
		: f(n + 1)
		, f_inv(n + 1)
	{
		f[0] = 1;
		for (int i = 1; i <= n; ++i) {
			f[i] = mulm(i, f[i - 1]);
		}

		f_inv[n] = invm(f[n]);
		for (int i = n - 1; i >= 0; --i) {
			f_inv[i] = mulm(i + 1, f_inv[i + 1]);
		}
	}

	int fact(int i) {
		return f[i];
	}
	int fact_inv(int i) {
		return f_inv[i];
	}

	int comb(int n, int r) {
		if (r < 0 || n < r) {
			return 0;
		}
		return mulm(f[n], mulm(f_inv[r], f_inv[n - r]));
	}

private:
	std::vector<int> f;
	std::vector<int> f_inv;
};

