    inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD; ///n^{-1}の計算
    finv[i]=finv[i-1]*inv[i]%MOD;//n!^{-1}の計算
  }


}

long long comb(long long X,long long Y)
{
  if(X<Y) return 0;
  else if(X<0||Y<0) return 0;
