const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, m, k;
ll dp[MAX_N];
ll facts[MAX_N], facts_inv[MAX_N], inv[MAX_N];

void fact_memo(ll n){
    facts[0] = facts[1] = 1;
    facts_inv[0] = facts_inv[1] = 1;
    inv[1] = 1;

    For(i, 2, n + 1){
        facts[i] = (i * facts[i - 1]) % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        facts_inv[i] = facts_inv[i - 1] * inv[i] % MOD;
    }
}

ll nCk(ll n, ll r){
    if (n == r && n == 0) return 1;
    else if (n <= 0 || r < 0 || r > n) return 0;
    ll val = (facts[n] * facts_inv[n - r]) % MOD;
    val *= facts_inv[r];
    return val % MOD;
}

void solve(){
    dp[0] = 0, dp[1] = m;
    For(i, 2, n + 1) dp[i] = (dp[i - 1] * (m - 1)) % MOD;

