ll mod_mult(ll a,ll b,ll m){  //计算 a*b
    ll res = 0;
    ll exp = a % m;
    while(b){
        if (b&1){
            res += exp;
            if (res > m) res -= m;
        }
        exp<<=1;
        if (exp > m) exp -= m;
        b>>=1;
    }
    return res;
}


ll mod_exp(ll a,ll b,ll m){
    ll res = 1;
    ll exp = a % m;
    while(b){
        if (b & 1) res = mod_mult(res,exp,m);
        exp = mod_mult(exp,exp,m);
        b>>=1;
    }
    return res;
}

