const int MAX = 310000;
const int GMOD = 998244353;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % GMOD;
    inv[i] = GMOD - inv[GMOD % i] * (GMOD / i) % GMOD;
    finv[i] = finv[i - 1] * inv[i] % GMOD;
  }
}

// 二項係数計算
long long COM(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % GMOD) % GMOD;
}

