    for (ll i = 0; i <= k; i++) {
        ll tmp = (m * COM(n - 1, i)) % MOD;
        ans += tmp * modpow(m - 1, n - i - 1);
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

