    cin >> N >> M >> K;

    init_comb(N - 1);
    mint res = 0;
    for (int i = 0; i < K + 1; i++)
    {
        res += mint(M) * comb(N - 1, i) * mint(M - 1).pow(N - 1 - i);
    }
    cout << res.x << endl;
}

