const long long MOD = 998244353;

long long dp(long long left, long long K, long long N, long long M, vector<vector<long long> >& memo) {
    if (left == 0) {
        return 0LL;
    }
    if (left == 1) {
        if (K == 0) {
            return M - 1;
        }
        else {
            return M;
        }
    }
    if (K > 0) {
        if (memo[left][1] >= 0) {
            return memo[left][1];
        }
    }
    else {
        if (memo[left][0] >= 0) {
            return memo[left][0];
        }
    }

    long long ret = 0;
    if (left == N) {
        ret += M * dp(left - 1, K, N, M, memo);
        ret %= MOD;
    }
    else {
        if (K > 0) {
            ret += (M - 1) * dp(left - 1, K, N, M, memo);
            ret %= MOD;
            ret += dp(left - 1, K - 1, N, M, memo);
            ret %= MOD;
        }
        else {
            ret += (M - 1) * dp(left - 1, 0, N, M, memo);
            ret %= MOD;
        }
    }
    memo[left][(K > 0 ? 1 : 0)] = ret;
    return ret;
}

void Main() {
    long long N, M, K;
    cin >> N >> M >> K;

    vector<vector<long long> > memo(N + 1, vector<long long>(2, -1LL));
    long long ans = dp(N, K, N, M, memo);
    cout << ans << endl;
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

