		return a;
	}
	ll g = ext_euclid(b, a%b);
	/*
		bx + (a-a/b*b)y = 1	
		ay + b(x-a/b*y) = 1
	*/
	ll tmp = x;
	x = y;
	y = tmp-a/b*y;
	return g;
}

