    ll denom = 1;
    for (int i = n - k + 1; i <= n; i++) {
        numer *= i;
        numer %= mod;
    }
    for (int i = 1; i <= k; i++) {
        denom *= i;
        denom %= mod;
    }
    return numer * power(denom, mod - 2) % mod;
}

