const ll MOD = 998244353;

// mod p における掛け算
ll mul_mod(ll a, ll b, ll modp){
    return (a * b) % modp;
}

// mod p における累乗
ll mod_pow(ll x, ll n, ll modp){
    ll res = 1;
    while(n > 0){
        if(n & 1) res = res * x % modp;
        x = x * x % modp;
        n >>= 1;
    }
    return res;
}

// nCkの計算 : O(k)
ll mod_comb(ll n, ll k, ll modp){
    ll X = 1;
    for(int i=0; i<k; i++){
        X = mul_mod(X, n-i, modp);
    }
    ll Y = 1;
    for(int i=0; i<k; i++){
        Y = mul_mod(Y, k-i, modp);
    }
    ll Y_pow = mod_pow(Y, modp-2, modp);
    return mul_mod(X, Y_pow, modp);
}

int main(void){
    ll n, m, k;
    cin >> n >> m >> k;

    ll ans = 0;
    for(int i=0; i<=k; i++){
        ll cmb = mod_comb(n-1, i, MOD);
        ll Mn = mod_pow(m-1, n-i-1, MOD);
        ll tmp_ans = mul_mod(cmb, Mn, MOD);
        tmp_ans = mul_mod(tmp_ans, m, MOD);
        ans += tmp_ans;
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

