//べき乗高速化
ll mpow(ll x, ll n){
	ll ans = 1;
	while(n != 0){
		if (n&1) ans = ans * x % M;
		x = x*x % M;
		n  = n >> 1;
	}
	return ans;
}

//aCbを計算
ll comb(ll a, ll b){
	if (a == 0 && b == 0) return 1;
	if (a < b || a < 0){
		return 0;
	}
	ll temp = ifac[a-b] * ifac[b] % M;
	return temp * fac[a] % M;
}

int main(){
	ll n,m,k;
	cin >> n >> m >> k;
	fac[0] = 1;
	ifac[0] = 1;
	for(ll i = 0; i<= 200000; i++){
		fac[i+1] = fac[i]*(i+1) % M; // n!(mod M)
		ifac[i+1] = ifac[i]*mpow(i+1, M-2) % M; // k!^{M-2} (mod M) ←累乗にmpowを採用
	}
	ll ans = 0;
	rep(i,k+1){
		ll temp =m*mpow(m-1,n-i-1);
		temp %= M;
		temp *= comb(n-1,i);
		ans += temp;
		ans %= M;
	}
	if(ans < 0){
		ans += M;
	}
	cout << ans << endl;
    return 0;
}

