long long int mypow(long long int x,long long int n)
{
	long long int res = 1;
	while(n>0)
	{
		if(n%2==1)
		{
			res = ((res%MOD)*(x%MOD)%MOD);
			res%=MOD;
		}
		x = ((x%MOD)*(x%MOD)%MOD);
		n/=2;
	}
	return res;
}

int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    long long int res = 0;
    long long int n,m,k;

    cin >> n >> m >> k;

    if(n==m && n==k)
    {
    	cout << n << '\n';
    	return 0;
    }

    f[0] = 1;
    for(int i=1;i<400005;i++)
    {
    	f[i] = ((f[i-1]%MOD)*(i%MOD)%MOD);
    	f[i]%=MOD;
    }
    invf[400004] = mypow(f[400004],MOD-2);
    for(int i=400003;i>=0;i--)
    {
    	invf[i] = ((invf[i+1]%MOD)*((i+1)%MOD)%MOD);
    	invf[i]%=MOD;
    }

    long long int A = m;
    for(int i=1;i<n;i++)
    {
    	A = ((A%MOD)*((m-1)%MOD)%MOD);
    	A%=MOD;
    }

    res = A;
    long long int B = mypow(m-1,MOD-2);
    for(int i=1;i<=k;i++)
    {
    	long long int C = f[n-1];
    	C = ((C%MOD)*(invf[i]%MOD)%MOD);
    	C%=MOD;
    	C = ((C%MOD)*(invf[n-1-i]%MOD)%MOD);
    	A = ((A%MOD)*(B%MOD)%MOD);
    	A%=MOD;
    	C = ((C%MOD)*(A%MOD)%MOD);
    	C%=MOD;
    	res = ((res%MOD) + (C%MOD)%MOD);
    	res%=MOD;
    }

    cout << res << '\n';

    return 0;
}

