template <typename T>
T modpow(T m, T n, const T &p) {
  if (n == 0) return 1;
  T ret = modpow(m * m % p, n / 2, p);
  if (n % 2) ret *= m;
  return ret % p;
}

template <typename T>
T binomial(T n, T r, const T &p) {
  if (r > n - r) return binomial(n, n - r, p);
  T ansMul = 1;
  T ansDiv = 1;
  for (T i = 0; i < r; i++) {
    ansMul *= (n - i);
    ansDiv *= (i + 1);
    ansMul %= p;
    ansDiv %= p;
  }

  T ans = (ansMul * modpow(ansDiv, p - 2, p)) % p;
  return ans;
}

int main() {
  llint n, m, k;
  cin >> n >> m >> k;
  llint ans = 0;
  for (llint i = 0; i <= k; i++) {
    ans += (m * binomial(n - 1, i, MOD)) % MOD * modpow(m - 1, n - 1 - i, MOD) % MOD;
    ans %= MOD;
  }
  cout << ans << endl;

  return 0;
}

