    scanInt(M);
    scanInt(K);
    Factorial fact(N);
    FactorialInverse factinv(N, fact);
    auto nCr = [&](uint n, uint r){
        return modMultiple(modMultiple(fact(n), factinv(r)), factinv(n - r));
    };
    PowerN mypow(M - 1, N);
    int result = 0;
    for (int k = 0; k <= K; k++){
        auto temp = modMultiple(nCr(N - 1, k), modMultiple(M, mypow(N - 1 - k)));
        result = modPlus(result, temp);
    }
    cout << result << endl;
}

