// a,b の最大公約数と、ax + by = gcd(a,b) となる x,y を求める
ll extgcd(ll a, ll b, ll &x, ll &y) {
  ll g = a;
  if (b != 0) {
    g = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  } else {
    x = 1;
    y = 0;
  }
  return g;
}

// ax ≡ gcd(a, m) (mod m) となる x を求める
// a, m が互いに素ならば、関数値は mod m での a の逆数となる
ll mod_inverse(ll a, ll m) {
  ll x, y;
  extgcd(a, m, x, y);
  return (x % m + m) % m;
}

// 組み合わせ (r<10^7, n,r<m, m:素数)
int nCr(int n, int r, int m) {
  if (n < r) {
    return 0;
  }
  if (n - r < r) {
    r = n - r;
  }
  ll ret = 1;
  for (int i = 0; i < r; i++) {
    ret = ret * (n - i) % m;
  }
  ll imul = 1;
  for (int i = 0; i < r; i++) {
    imul = imul * (i + 1) % m;
  }
  ret = ret * mod_inverse(imul, m) % m;
  return (int)ret;
}

/*
 * 計算量は O(log(n)) で次式の計算結果を返す
 * x**n (mod mod)
 * つまり，xを乗して，modで割った余りを返す．
 * ex) mod_pow(2, 3, 3) = 2
 * 素数pに対して x**p = x (mod p) が成り立つ
 */
ll mod_pow(ll x, ll n, ll mod) {
  if (n == 0)
    return 1;
  ll res = mod_pow(x * x % mod, n / 2, mod);
  if (n & 1)
    res = res * x % mod;
  return res;
}

void solve(long long N, long long M, long long K) {
  ll sum = 0;
  REP(i, K + 1) {
    ll x = M * nCr(N - 1, i, MOD);
    x %= MOD;
    ll y = x * mod_pow(M - 1, N - i - 1, MOD);
    y %= MOD;
    sum += y;
    sum %= MOD;
  }
  cout << sum << endl;
}

int main() {
  long long N;
  scanf("%lld", &N);
  long long M;
  scanf("%lld", &M);
  long long K;
  scanf("%lld", &K);
  solve(N, M, K);
  return 0;
}

