template<class ModIntT>
class BinomialFactory
{
    std::vector<ModIntT> stock;
    std::vector<ModIntT> inv;

public:
    explicit BinomialFactory(int N)
    {
        stock.resize(N + 1);
        inv.resize(N + 1);
        stock[0] = 1;
        inv[0] = 1;
        for (int i = 1; i <= N; i++)
        {
            stock[i] = stock[i - 1] * i;
            inv[i] = stock[i].inv();
        }
    }

    ModIntT bi(int n, int r) const
    {
        if (r == 0 || r == n) return 1;

        return stock[n] * inv[n - r] * inv[r];
    }
};


