const ll MAX = 2e5 + 1;
ll MOD = 998244353;
ll INV[MAX] = {}, FACTORIAL[MAX] = {}, FACTORIAL_INV[MAX] = {};

void calc_init() {
  INV[1] = 1;
  FACTORIAL[0] = FACTORIAL[1] = 1;
  FACTORIAL_INV[0] = FACTORIAL_INV[1] = 1;

  for (int i = 2; i <= MAX; i++) {
    ll q = MOD / i, r = MOD % i;
    INV[i] = (-INV[r] * q) % MOD;
    INV[i] = (INV[i] + MOD) % MOD;
    FACTORIAL[i] = (i * FACTORIAL[i - 1]) % MOD;
    FACTORIAL_INV[i] = (INV[i] * FACTORIAL_INV[i - 1]) % MOD;
  }
}

ll nCk(ll n, ll k) {
  ll ans = FACTORIAL[n];
  ans = (ans * FACTORIAL_INV[k]) % MOD;
  ans = (ans * FACTORIAL_INV[n - k]) % MOD;
  return ans;
}


int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll N; cin >> N;
  ll M; cin >> M;
  ll K; cin >> K;

  calc_init();
  ll ex = 1;
  for (ll i = 0; i < (N - K - 1); i++) {
    ex = (ex * (M - 1)) % MOD;
  }
  ll ans = 0;
  for (ll i = K; i >= 0; i--) {
    ll nck = nCk(N - 1, i);
    ll temp = (nck * M) % MOD;
    ans = (ans + (temp * ex) % MOD ) % MOD;
    ex = (ex * (M - 1)) % MOD;
  }

  cout << ans << '\n';
  return 0;
}

