    return power(M - 1, n);
  }
  pair<int, int> p = make_pair(n, k);
  if (memo.count(p)) return memo[p];
  int r = f(M, n - 1, k - 1) + (M - 1) * f(M, n - 1, k);
  r %= MOD;
  return memo[p] = r;
}
signed main() {
  int N, M, K; cin >> N >> M >> K;
  cout << (M * f(M, N - 1, K)) % MOD << endl;
}

