long long int expp(long long int p, long long int q) {
	long long int r = 1;
	long long int z = p % M;
	while (q) {
		if (q & 1) { r = (r * z) % M; }
		q >>= 1;
		if (q) { z = (z * z) % M; }
	}
	return r;
}
void inil() {
	long long int w = expp(3, Mp);
	wlist[21] = w;
