void fft(vector <long long int>& a, bool invert)
{
	int n = a.size();
	for (int i = 1, j = 0; i < n; i++) {
		int bit = n >> 1;
		for (; j >= bit; bit >>= 1) j -= bit;
		j += bit;
		if (i < j) swap(a[i], a[j]);
	}
	int li = 1;
	for (int len = 2; len <= n; len <<= 1) {
		long long int wlen = invert ? wlist_inv[li] : wlist[li];
		for (int i = 0; i < n; i += len) {
			long long int w = 1;
			for (int j = 0; j < len / 2; j++) {
				long long int u = a[i + j], v = (a[i + j + len / 2] * w) % M;
				a[i + j] = (u + v) % M;
				a[i + j + len / 2] = (u + M - v) % M;
				w = (w * wlen) % M;
			}
		}
		li++;
	}
	if (invert) {
		static unordered_map<int, long long int> memoi;
		if (memoi.find(n) == memoi.end())memoi[n] = expp(n, M - 2);
		long long int invzn = memoi[n];
		for (int i = 0; i < n; i++) a[i] = (a[i] * invzn) % M;
	}
}

void multiply(const vector<long long int>& a, const vector<long long int>& b, vector<long long int>& res)
{
	vector <long long int> fa(a.begin(), a.end()), fb(b.begin(), b.end());
	int n = 1;
	while (n < a.size() + b.size()) n <<= 1;
	fa.resize(n); fb.resize(n);
	fft(fa, false); fft(fb, false);
	for (int i = 0; i < n; i++) fa[i] = (fa[i] * fb[i]) % M;
	fft(fa, true);
	res.resize(n);
	for (int i = 0; i < n; i++) res[i] = fa[i];
	while (n > 1) { if (res[n - 1] == 0)n--; else break; }
	res.resize(n);
}
