const int maxn = 2e5 + 228;

int binpow(int n, int k){
	if(!k)
		return 1;
	if(k&1)
		return binpow(n, k-1)*n%MOD2;
	int b = binpow(n, k/2);
	return b*b%MOD2;
}

int fac[maxn];
int rfac[maxn];

int C(int n, int k){
	return fac[n] * rfac[n-k] % MOD2 * rfac[k] % MOD2;
}

