ll mod = 998244353, u = 1, d[300001];

ll mypow(ll x, ll y){
  if(x <= 0 || y <= 0) return 1;
  if(y == 1) return x;
  ll z = mypow(x, y / 2) % mod;
  if(y % 2 == 1){
    return ((z * z) % mod) * x % mod;
  }
  else{
    return (z * z) % mod;
  }
}

void pc(ll l){
  for(ll i = l; i >= 1; i--){
    u = (u * i) % mod;
  }
  d[0] = 1;
  for(ll i = 1; i <= l; i++){
    d[i] = (d[i - 1] * i) % mod;
  }
}

ll choose(ll l, ll r){
  return (((u * mypow(d[r], mod - 2)) % mod) * mypow(d[l - r], mod - 2)) % mod;
}

void solve(){
  ll n, m, k, x, y, z; cin >> n >> m >> k;
  x = (mypow(m - 1, n - 1) * m) % mod;
  ll ans = x;
  //z = mypow(m - 1, n - k - 2);
  pc(n - 1);
  for(ll i = 1; i <= k; i++){
    y = choose(n - 1, i);
    z = mypow(m - 1, n - i - 1);
    ans = (ans + (m * ((y * z) % mod) % mod)) % mod;
    //cout << y << " " << z << " " << ans << endl;
  }
  cout << ans << endl;
  return;
}

int main(){
  solve();
  return 0;
}

