  cin >> n >> m >> k;

  // Precompute factorials
  auto fs = mfactorials(n + k);
  auto binom = [&](ll n, ll k) { return mmul(fs[n], mmul(minv(fs[n - k]), minv(fs[k]))); };

  ll res = 0;
  FOR(c, 0, k + 1) {
    ll x = binom(n - 1, c);
    ll y = mexp(m - 1, n - 1 - c);
    ll z = mmul(x, mmul(y, m));
    res = madd(res, z);
  }
  cout << res << endl;
}

