using namespace std;

int div(int A, int B, int mod_p) {
  stack<int> q_stack;
  int a = B, b = mod_p, r;
  while (b) {
    q_stack.push(a / b);
    r = a % b; a = b; b = r;
  }
  long u = 1, v = 0;
  while (!q_stack.empty()) {
    int q = q_stack.top(); q_stack.pop();
    long u1 = v, v1 = u-q*v; u = u1 % mod_p; v = v1 % mod_p;
  }
  return (long)A * (u + mod_p) % mod_p;
}

int main() {
  int DIV = 998244353;
  int N, M, K; cin >> N >> M >> K;
  if (M == 1) {
    if (K == N-1) cout << 1 << endl;
    else cout << 0 << endl;
    return 0;
  }
  int sum = 0, x = 1;
  for (int i = 0; i < N-1; i++) x = (long)x * (M-1) % DIV;
  sum += x;
  for (int i = 0; i < K; i++) {
    x = (long)x * (N - i - 1) % DIV;
    x = div(x, i + 1, DIV);
    x = div(x, M - 1, DIV);
    sum = (sum + x) % DIV;
  }
  cout << (long)sum * M % DIV << endl;
}

