ll modpow(ll n, ll p)
{
    ll ans = 1;
    while(p) {
        if(p&1)
            (ans *= n) %= md;
        (n *= n) %= md, p /= 2;
    }
    return ans;
}

ll ncr(ll n, ll k) {
    if(!k)
        return 1;
    ll res = (fact[n] * inv[k]) % md;
    return (res * inv[n - k]) % md;
}

