int pwr(int x, int y) {
	int res = 1;
	while (y) {
		if (y & 1) {
			res = res * x % mod;
		}
		y >>= 1;
		x = x * x % mod;
	}
	return res;
}
void solve() {
	vector<int> fact(N + 1);
	fact[0] = 1;
	for (int i = 1; i <= N; i++) {
		fact[i] = fact[i - 1] * i % mod;
