ll FPM(ll x,ll power)
{
    ll ans = 1;
    while(power)
    {
        if(power & 1)
        {
            ans = (ans * x) % mod;
        }
        x = (x * x) % mod;
        power >>= 1;
    }
    return ans % mod;
}

ll C(ll a, ll b)
{
    return f[a] * inv[a - b] % mod * inv[b] % mod;
}

