int Mod = 998244353;
class Modular {
private:
    int value;
    static int mod_inverse(int a, int mod) {
        a %= mod;
        assert(a);
        if (a == 1)
            return 1;
        return int(mod - ll(mod_inverse(mod, a)) * ll(mod) / a);
    }
public:
    Modular(): value(0) {}
    Modular(ll val):value(val % Mod) { if (value < 0) value += Mod;}
    friend std::ostream& operator << (std::ostream& out, const Modular& n) {return out << n.value;}
    friend std::istream& operator >> (std::istream& in, Modular& n) {ll v; in >> v; n = Modular(v); return in;}

    friend bool operator == (const Modular& a, const Modular& b) {return a.value == b.value;}
    friend bool operator != (const Modular& a, const Modular& b) {return a.value != b.value;}

    Modular inverse() const {
        Modular ret;
        ret.value = mod_inverse(this->value, Mod);
        return ret;
    }
    Modular neg() const {
        Modular ret;
        ret.value = this->value ? Mod - this->value : 0;
        return ret;
    }
    Modular operator- (){return neg();}
    Modular& operator++ () {this->value++; if (this->value == Mod) this->value = 0; return *this;}
    Modular& operator-- () {if (this->value == 0) this->value = Mod; --this->value; return *this;}
    Modular& operator+= (const Modular& other) {this->value += other.value; if (this->value >= Mod) this->value -= Mod; return *this;}
    Modular& operator-= (const Modular& other) {this->value -= other.value; if (this->value < 0) this->value += Mod; return *this;}
    Modular& operator*= (const Modular& other) {this->value = ll(this->value) * ll(other.value) % Mod; return *this;}    
    Modular& operator/= (const Modular& other) {return *this *= other.inverse();}
    friend Modular operator ++ (Modular& a, int) {Modular ret = a; ++a; return ret;}
    friend Modular operator -- (Modular& a, int) {Modular ret = a; --a; return ret;}
    friend Modular operator + (const Modular& a, const Modular& b) {Modular ret = a; ret += b; return ret;}
    friend Modular operator - (const Modular& a, const Modular& b) {Modular ret = a; ret -= b; return ret;}
    friend Modular operator * (const Modular& a, const Modular& b) {Modular ret = a; ret *= b; return ret;}
    friend Modular operator / (const Modular& a, const Modular& b) {Modular ret = a; ret /= b; return ret;}
};
