		stack<char> st;
		for(int i = 0; i < (int)s.size(); i++){
			if(st.empty()){
				st.push(s[i]);
			}
			else if(st.top()=='(' && s[i] == ')'){
				st.pop();
			}
			else {
				st.push(s[i]);
			}
		}
		string ss="";
		while(!st.empty()){
			ss.push_back(st.top());
			st.pop();
		}
		reverse(ss.begin(),ss.end());	
		return ss;
	};
	string a = "";
	vector<pair<int,int>> vv;
	string c = "";
	for(int i = 0; i < n; i++){
		string res = simplify(v[i]);
