using namespace std;
typedef long long ll;
typedef long double ld;

const int MAX = 510000;
const int MOD = 998244353;

ll fac[MAX], finv[MAX], inv[MAX];

void init_ncr() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll ncr(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll modpow(ll a, ll n, ll mod) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res % mod;
}
int main(int argc, char *argv[]) { ios::sync_with_stdio(false);cin.tie(nullptr);cout.tie(nullptr);

  init_ncr();
  ll n,m,k;cin>>n>>m>>k;

  ll ans=0;
  for(ll i=0;i<=k;i++){
    ll t = m; t %= MOD;
    t *= modpow(m - 1ll, n - 1ll - i, MOD); t %= MOD;
    t *= ncr(n - 1ll, i); t %= MOD;
    ans += t; ans %= MOD;
  }
  cout<<ans<<endl;

  return 0;
}

