long long power(long long X,long long P,long long M)
{
  long long s;

  if(P==0)
  {
    return 1;
  }
  else if(P%2==0)
  {
    s=power(X,P/2,M);
    s*=s;
    s%=M;
    return s;
  }
  else
  {
    s=power(X,P-1,M)*X;
    s%=M;
    return s;
  }
}

void COMint()
{
