  finv[0]=1;
  fac[1]=1;
  finv[1]=1;
  inv[1]=1;
  for(i=2;i<MAX;i++)
  {
    fac[i]=fac[i-1]*i%MOD;  ///n!の計算
    inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD; ///n^-1の計算
    finv[i]=finv[i-1]*inv[i]%MOD;//n!^-1の計算
  }


}

long long comb(long long X,long long Y)
{
  if(X<Y) return 0;
  else if(X<0||Y<0) return 0;
  return fac[X]*(finv[Y]*finv[X-Y]%MOD)%MOD;
}

