namespace mod {
using u64 = uint_fast64_t;
template <uint_fast64_t MOD> class modInt {

private:
  u64 a;

public:
  constexpr modInt(const long long x = 0) : a(((x % MOD) + MOD) % MOD) {}
  constexpr inline u64 value() const { return a; }
  constexpr modInt pow(u64 p) const {
    if (p == 0)
      return modInt(1);
    if (p % 2 == 0) {
      modInt d = pow(p / 2);
      return d * d;
    } else {
      return *this * pow(p - 1);
    }
  }
  constexpr modInt inverse() const { return pow(MOD - 2); }
  constexpr modInt &operator+=(const modInt x) {
    a += x.a;
    if (a >= MOD) {
      a -= MOD;
    }
    return *this;
  }
  constexpr modInt &operator-=(const modInt x) {
    if (a < x.a) {
      a += MOD;
    }
    a -= x.a;
    return *this;
  }
  constexpr modInt &operator*=(const modInt x) {
    a = a * x.a % MOD;
    return *this;
  }
  constexpr modInt &operator/=(const modInt x) {
    assert(x.a != 0);
    *this *= x.inverse();
    return *this;
  }
  constexpr modInt operator++() { return *this += modInt(1); }
  constexpr modInt operator--() { return *this -= modInt(1); }
};
template <u64 MOD>
