vector<mint> invtbl;
vector<mint> finvtbl;
vector<mint> facttbl;

mint factMod(lint n) {
	if (n == 0)
	{
		return 1;
	}
	mint ans = 1;
	while (n > 1) {
		ans *= n;
		n--;
	}
	return ans;
}
mint powMod(mint x, lint y)
{
	if (x.n <= 1)
	{
		return x;
	}
	if (y == 0)
	{
		return 1;
	}
	else if (y == 1)
	{
		return x;
	}
	else if (y % 2 == 0)
	{
		mint tmp = powMod(x, y / 2);
		return tmp * tmp;
	}
	else
	{
		mint tmp = powMod(x, y / 2);
		return tmp * tmp * x;
	}
}
mint modinv(mint n)
{
	return powMod(n, mod - 2);
}

void preCalcInv(lint up)
{
	invtbl.resize(up + 1);
	invtbl[1] = 1;
	repb(a, 2, up)
	{
		invtbl[a] = invtbl[a] = mod - invtbl[mod % a] * (mod / a);
	}
}

mint operator/(mint a, mint b)
{
	if (b.n < invtbl.size())
	{
		a *= invtbl[b.n];
	}
	else
	{
		a *= modinv(b);
	}
	return a;
}
mint& operator/=(mint& a, mint b)
{
	a = a / b;
	return a;
}


void preCalcFactInv(lint up)
{
	finvtbl.resize(up + 1);
	finvtbl[0] = 1;
	finvtbl[up] = modinv(factMod(up));
	repbr(a, 1, up - 1)
	{
		finvtbl[a] = finvtbl[a + 1] * (a + 1);
	}
}
void preCalcFact(lint up)
{
	facttbl.resize(up + 1);
	facttbl[0] = 1;
	repb(a, 1, up)
	{
		facttbl[a] = facttbl[a - 1] * a;
	}
}
void preCalc(lint up)
{
	invtbl.resize(up + 1);
	finvtbl.resize(up + 1);
	facttbl.resize(up + 1);
	invtbl[1] = 1;
	facttbl[0] = facttbl[1] = 1;
	finvtbl[0] = finvtbl[1] = 1;
	repb(a, 2, up)
	{
		facttbl[a] = facttbl[a - 1] * a;
		invtbl[a] = invtbl[a] = mod - invtbl[mod % a] * (mod / a);
		finvtbl[a] = finvtbl[a - 1] * invtbl[a];
	}
}


mint factModInv(lint a)
{
	if (a < finvtbl.size())
	{
		return finvtbl[a];
	}
	else
	{
		return modinv(factMod(a));
	}
}
mint nCrMod(lint n, lint r)
{
	if (n < r || n < 0 || r < 0)
	{
		return 0;
	}
	r = mmin(r, n - r);
	mint a = 1;
	if (n < finvtbl.size() && n < facttbl.size())
	{
		a *= facttbl[n];
		a *= finvtbl[r];
		a *= finvtbl[n - r];
		return a;
	}
	else
	{
		repb(i, n - r + 1, n)
		{
			a *= i;
		}
		a *= factModInv(r);
		return a;
	}
}
mint nHrMod(lint n, lint r)
{
	return nCrMod(n + r - 1, r);
}


