#define NMAX 200000
#define MOD 998244353

//senor氏の講義を受けて com_init, combi, pow_init を実装

vector<ll> fac(NMAX+1);
vector<ll> inv(NMAX+1);
vector<ll> fnv(NMAX+1);
vector<ll> power(NMAX+1);

void com_init(){

    fac[0]=1;
    fac[1]=1;
    inv[0]=0;
    inv[1]=1;
    fnv[0]=1;
    fnv[1]=1;

    for(int i=2; i<NMAX+1; i++){
        fac[i] = fac[i-1]*i % MOD;
        inv[i] = MOD - (MOD/i) * inv[MOD%i] % MOD;
        fnv[i] = fnv[i-1] * inv[i] % MOD;
    }
    return;
}

ll combi(int n, int k){
    if(n<k)return 0;
    if(k<0 || n<0 )return 0;

    return fac[n] * (fnv[k]*fnv[n-k] % MOD) % MOD;
}

void pow_init(int M){

    power[0] = 1;
    for(int i=1; i<NMAX+1; i++){
        power[i] = power[i-1] * M % MOD;
    }
    return;
}

int main(){

    int n, m, k;

    cin >> n >> m >> k;

    com_init();
    pow_init(m-1);

    ll ans = 0;

    for(int i=0; i<=k; i++){
        //k=0のとき M*(M-1)^(N-1)
        //k=1のとき (N-1)C1 * M * (M-1)^(N-2)
        //一般に    (N-1)Ck * M * (M-1)^(N-1-k)
        ans += combi(n-1, i) * ( m * power[n-1-i] % MOD ) % MOD;
        ans %= MOD;
    }

    cout << ans << endl;

    return 0;
}

