ll calc(ll a, ll b, ll p)
{
	if (b == 0) return 1;
	if (b % 2 == 0)
	{
		ll d = calc(a, b / 2, p);
		return (d * d) % p;
	}
	else
		return (a * calc(a, b - 1, p)) % p;
}

ll nCr(ll n, ll r)
{
	ll dp[n + 1];
	dp[0] = dp[1] = 1;
	for(int i = 2; i <= n; i++)
	{
		dp[i] = dp[i - 1] * i;
		dp[i] %= mod;
	}
	return dp[n] * calc(dp[r] * dp[n - r] % mod, mod - 2, mod) % mod;
}

