		return (d * d) % p;
	}
	else
		return (a * calc(a, b - 1, p)) % p;
}

ll nCr(ll n, ll r)
{
  ll x = 1;
  ll y = 1;
  for (ll i = 1; i <= r; ++i)
  {
  	  x *= (n-i+1);
	  x %= mod;
  	  y  *= i;
	  y %= mod;
  }
  return x * calc(y, mod - 2, mod) % mod;
}

