void COMinit(){
    fac[0] = 1,fac[1] = 1;
    finv[0]=1,finv[1] = 1;
    inv[1]=1;
    FOR(i,2,limit){
        fac[i] = fac[i-1]*i%prime;
        inv[i] = (prime-inv[prime%i]*(prime/i))%prime;
        finv[i] = finv[i-1]*inv[i]%prime;
    }
}

m_int factorical(int n){
    if(fac[0] == 0) COMinit();
    m_int ans;
    if(n >= limit){
        ans = 1;
        FOR(i,2,n+1){
            ans *= i;
        }
        return ans;
    }
    else{
        ans = fac[n];
        return ans;
    }
}
m_int comb(int n,int r){
    if(r>n || n < 0 || r < 0) return 0;
    if(fac[0] == 0) COMinit();
    m_int tmp = finv[r] * finv[n-r];
    tmp *= fac[n];
    return tmp;
}

m_int pow(int x,int exp){
    if(exp <= 0) return 1;
    if(exp%2==0){
        m_int d = pow(x,exp/2);
        return d*d;
    }
    else{
        return (m_int)((m_int)x*(m_int)pow(x,exp-1));
    }
}

