vector<long long> pow_a(int a, int digit, int p) {
    vector<long long> v(digit);
    v[0] = (a % p);
    for (int i = 1; i < digit; ++i) {
        v[i] = ((v[i-1] * v[i-1]) % p);
    }
    return v;
}

// aのmod pでの逆元a^(p-2)を計算
long long inv_mod(int a, int p) {
    vector<long long> v;
    int digit = 30;
    v = pow_a(a, digit, p);

    long long ans = 1;
    for (int i = 0; i < digit; ++i) {
        if (((p-2) >> i) & 1) {
            ans = ((ans * v[i]) % p);
        }
    }
    return ans;
}

