ll fastpow(ll a, ll n) 
{
	if (n < 0)return 0;
	ll res = 1;
	a %= MOD;
	while (n) {
		if (n & 1)res = (res * a) % MOD;
		a = (a * a) % MOD;
		n >>= 1;
	}
	return res % MOD;
}
ll inv(ll a)
{
	return a == 1l ? 1l : (ll)(MOD - MOD / a) * inv(MOD % a) % MOD;
}
ll C(ll n, ll m)
{
	if (m < 0)return 0;
	if (n < m)return 0;
	if (m > n - m)m = n - m;
	ll up = 1, down = 1;
	for (ll i = 0; i < m; i++)
	{
		up = up * (n - i) % MOD;
		down = down * (i + 1) % MOD;
	}
	return up * inv(down) % MOD;
}

