  u64 im = modpow(m-1, mod-2);
  inv[1] = 1;
  for(int i = 0; i <= k; i++){
    ans += r;
    r = r * im % mod;
    r = r * (n-1-i) % mod * inv[i+1] % mod;
    inv[i+2] = mod - (u64) inv[mod % (i+2)] * (mod / (i+2)) % mod;
  }
  ans %= mod;
  ans = ans * m % mod;
  std::cout << ans << std::endl;
  return 0;
}

