long long fastpow(long long a, long long n){
  long long ans = 1;
  while(n > 0){
    if(n & 1){
      ans = modmult(ans, a);
    }
    a *= a;
    a %= MOD;
    n = n >> 1;
  }
  return ans;
}

long long comp(long long a, long long b){
  return modmult(modmult(fact_tbl[(int)a], modinv(fact_tbl[(int)(a - b)], MOD)), modinv(fact_tbl[(int)b], MOD));
}

