vector<mint> g_mfac(Nfac+1), g_ifac(Nfac+1);
void fact_modp_init(int N= Nfac){
  static bool initialized = false;
  if(!initialized){
    g_mfac.at(0)= 1;
    mint buf;
    for(int i=1; i<=N; i++){
      buf= i;
      g_mfac.at(i)= g_mfac.at(i-1)* buf;
    }

    g_ifac.at(N)= g_mfac.at(N).inv();
    for(int i=N; i>0; i--){
      buf= i;
      g_ifac.at(i-1)= g_ifac.at(i)* buf;
    }

    initialized= true;
  }
}
inline mint mfac(int N){
  fact_modp_init();
  return g_mfac.at(N);
}
inline mint ifac(int N){
  fact_modp_init();
  return g_ifac.at(N);
}
#else
// 前処理を回避するver.
mint mfac(int N){
  mint ans= 1;
  mint buf;
  for(int i=1; i<=N; i++){
    buf= i;
    ans*= buf;
  }

  return ans;
}
#endif

mint binom_modp(int n, int k){
  if(n < 0 || min(k,n-k) < 0) return 0;
  else{
#if (MEMORY==1)
    fact_modp_init();
    return g_mfac.at(n)* g_ifac.at(k)* g_ifac.at(n-k);
#else
    k= min(k, n-k);
    mint ans= 1;
    for(int i=1; i<=k; i++){
      mint num= n-i+1;
      ans*= num;
    }
    ans/= mfac(k);

    return ans;
#endif
  }
}

mint multiset_modp(int n, int r){
  if(n==0 && r==0) return 1;
  else{
    return binom_modp(n+r-1, r);
  }
}
