ll go(ll x, ll y) {
	if (y == 0)return 1;
	else if (y == 1)return x;
	else if (y & 1) {
		return x * go(x, y - 1) % mod;
	}
	else {
		ll tmp = go(x, y / 2);
		return tmp * tmp % mod;
	}
}
ll go2(ll x, ll y) {
	ll cnt = d[x];
	ll tmp = d[x - y] * d[y] % mod;
	tmp = go(tmp, mod - 2);
	cnt *= tmp; cnt %= mod;
	return cnt;
}

