        for(i = f[0] = 1; i <= n; i ++)
            f[i] = (long long)f[i - 1] * i % MOD;
        g[n] = Power(f[n], MOD - 2);
        for(i = n - 1; i >= 0; i --)
            g[i] = (long long)g[i + 1] * (i + 1) % MOD;

