int power(int x,int y){
    int res=1;
    x%=mod;
    while(y>0){
        if(y&1){
            res*=x;
            res%=mod;
        }
        y>>=1;
        x*=x;
        x%=mod;
    }
    return res;
}

int modinv(int n){
    return power(n,mod-2);
}

int add(int a,int b){
	a%=mod,b%=mod;
	return a+b>=mod?a+b-mod:a+b;
}

int mul(int a,int b){
	a%=mod,b%=mod;
	return (a*b)%mod;
}

int C(int n,int r){
    return mul(fact[n],mul(ifact[r],ifact[n-r]));
}

void precompute(){
    fact[0]=1;
    ifact[0]=1;
    for(int i=1;i<N;++i){
        fact[i]=mul(fact[i-1],i);
        ifact[i]=mul(ifact[i-1],modinv(i));
    }
}

