const ll MOD = 998244353;

// mod p における掛け算
ll mul_mod(ll a, ll b, ll modp){
    return (a * b) % modp;
}

// mod p における累乗
ll mod_pow(ll x, ll n, ll modp){
    ll res = 1;
    while(n > 0){
        if(n & 1) res = res * x % modp;
        x = x * x % modp;
        n >>= 1;
    }
    return res;
