/*----------------------------------
// 1 : O(n)でテーブル準備 計算はO(1) //
// 使用例 : COMinit(); COM(10, 4); //
----------------------------------*/
const int MAX = 510000;
ll fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理 : O(n)
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算 : O(1)
ll COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main(void){
    ll n, m, k;
    cin >> n >> m >> k;

    COMinit();

    ll ans = 0;
    for(int i=0; i<=k; i++){
        ll cmb = COM(n-1, k);
        ll Mn = mod_pow(m-1, n-i-1, MOD);
        ll tmp_ans = mul_mod(cmb, Mn, MOD);
        tmp_ans = mul_mod(tmp_ans, m, MOD);
        ans += tmp_ans;
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

