#include <bits/stdc++.h>
using namespace std;

struct	ModCombi {
	int	sup;
	int	mod;
	vector<int64_t>	fact;
	vector<int64_t>	inv;
	vector<int64_t>	inv_fact;
	ModCombi(int sup, int mod):
		sup(sup), mod(mod), fact(sup), inv(sup), inv_fact(sup) {
		assert(1 < sup && sup <= static_cast<int>(1e+7));
		fact.at(0) = fact.at(1) = 1;
		inv.at(1) = 1;
		inv_fact.at(0) = inv_fact.at(1) = 1;
		for (int i = 2; i < sup; ++i) {
			fact.at(i) = fact.at(i - 1) * i % mod;
			inv.at(i) = mod - inv.at(mod % i) * (mod / i) % mod;
			inv_fact.at(i) = inv.at(i) * inv_fact.at(i - 1) % mod;
		}
	}
	int64_t	calc(int n, int k) {
		if (n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fact.at(n) * (inv_fact.at(k) * inv_fact.at(n - k) % mod) % mod;
	}
};

int64_t	modpow(int64_t a, int64_t n, int mod)
{
	int64_t	res = 1;
	while (n > 0) {
		if (n & 1)
			res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

int	main()
{
	const static int	mod = 998244353;
	int	N, M, K;
	cin >> N >> M >> K;
	ModCombi	modcombi(N + 1, mod);
	int64_t	total = 0;
	for (int k = 0; k <= K; ++k) {
		int64_t	num_combi = modcombi.calc(N - 1, k);
		int64_t	color_pattern = modpow(M - 1, N - 1 - k, mod) * M % mod;
		total = (total + num_combi * color_pattern % mod) % mod;
	}
	cout << total << endl;
}

