  // 逆元の計算
  for(int i=n-1;i>=0;i--)fact_inv[i]=fact_inv[i+1]*(i+1)%p;

  ll ans = 0;
  for(int i=0;i<=k;i++){
    ll work = modpow(m-1,n-1-i,p)*comb(n-1,i,p);
    work %= p;
    ans += work;
    ans %= p;
  }
  ans = (ans*m)%p;

  cout << ans << endl;
  return 0;
}

