vll mod_comb_list(ll n, ll p){
    vll res(n+1, 1);
    for(ll k=1; k <= n; k++){
        res[k] = (res[k-1] * (n - k + 1)) % p;
        res[k] = (res[k] * mod_inverse(k, p)) % p;
    }
    return res;
}

void solve(long long N, long long M, long long K){
    vll colorWay(N, 0);
    colorWay[0] = M % MOD;
    for(ll t=1; t < N; t++){
        colorWay[t] = (colorWay[t-1] * (M-1)) % MOD;
    }
    vll combList = mod_comb_list(N-1, MOD);
    ll ans = 0;
    for(ll k = 0; k<= K; k++){
        ll t = N-k;
        ans += (combList[t-1] * colorWay[t-1]) % MOD;
        ans = ans % MOD;
    }
    cout<<ans<<endl;
}

