LL big_mod(LL val,LL pow,LL mod)
{
    LL res = 1;
    val = val % mod;
    while(pow > 0)
    {
        if(pow & 1)
        {
            res = (res*val) % mod;
        }
        pow = pow >> 1;
        val = (val*val) % mod;
    }
    return res;
}

LL fact[200005],mod=998244353;

LL Fun(LL n,LL x)
{
    return (fact[n]*big_mod((fact[x]*fact[n-x])%mod,mod-2,mod))%mod;
}

