const int N = 2e5+5;
const ll M = 998244353;

ll C[N];

inline ll qpow(ll a,ll b){
	ll res = 1;
	a %= M;
	while(b){
		if(b & 1) (res *= a) %= M;
		(a *= a) %= M;
		b >>= 1;
	}
	return res%M;
}
inline ll inv(ll a){
	return qpow(a,M-2);
}

inline void C_table(ll n){
	C[0] = 1ll;
	C[1] = n;

	for(int i = 2;i <= n;++i){
		C[i] = C[i-1]%M * (ll)(n-i+1)%M * inv(i)%M;
		C[i] += M;
		C[i] %= M; 
	}
	return ;
}

int main() {
	int n,m,k;
	scanf("%d%d%d",&n,&m,&k);
	C_table(n-1);

	ll ans = 0;
	for(int i = 0;i <= k;++i){
		int t = n-1-i;

		ll l = C[t];
		ll r = t+1;

		l = l*(ll)m%M;
		r--;
		l = l*qpow(m-1,r)%M;
		(ans += l) %= M;
		(ans += M) %= M;
	}
	printf("%lld\n",ans);
	return 0;
}

