void init()
{
	f[0] = 1;
	reps(i, 1, N) f[i] = (f[i - 1] * i) % mod;
}
//---------------------------------------------------------------------------------------------------
ll inv(ll x)
{
	ll res = 1;
	ll k = mod - 2;
	ll y = x;
	while (k)
	{
		if (k & 1)
			res = (res * y) % mod;
		y = (y * y) % mod;
		k /= 2;
	}
	return res;
}
//---------------------------------------------------------------------------------------------------
ll C(int n, int k)
{
	ll a = f[n];	 // = n!
	ll b = f[n - k]; // = (n-k)!
	ll c = f[k];	 // = k!

	ll bc = (b * c) % mod;

	return (a * inv(bc)) % mod;
}

