ll extgcd(ll a, ll b, ll &x, ll &y){
    if(b == 0){
        x = 1; y = 0; return a;
    } 
    ll p = a / b;
    ll g = extgcd(b, a - p * b, x, y);
    ll z = x - p * y;
    x = y; y = z;
    return g;
}

// assert m and a is prime with each other
inline ll modinv(ll a, ll m) {
    ll x, y;
    extgcd(a, m, x, y);
    x %= m;
    if(x < 0) x += m;
    return x;
}

