template< typename T >
T mod_pow(T x, T n) {
  T ret = 1;
  while(n > 0) {
    if(n & 1) (ret *= x) %= MOD;
    (x *= x) %= MOD;
    n >>= 1;
  }
  return ret;
}

void solve(long long N, long long M, long long K){
    COMinit();
    ll ans = 0;
    for(int i=0;i<=K;i++){
        ll temp  = ((M * COM(N-1,i)) %MOD) * mod_pow(M-1,N-1-i);
        temp %= MOD;
        ans += temp;
        ans %= MOD;
    }
    cout << ans << endl;

}

