	// C function for extended Euclidean Algorithm 
long long gcdExtended(long long a, long long b, long long &x, long long &y) 
{ 
	    // Base Case 
	    if (a == 0) 
	    { 
	        x = 0, y = 1; 
	        return (long long) b; 
	    } 

	    long long x1, y1; // To store results of recursive call 
	    long long gcd = gcdExtended(b%a, a, x1, y1); 

	    // Update x and y using results of recursive 
	    // call 
	    x = y1 -  x1*(b/a); 
	    y = x1; 

	    return gcd; 
	} 
//generates any solution to ax+by = c;
long long diophantine(int a,int b,int c, long long &x,long long &y){
	long long gcd = gcdExtended(abs(a),abs(b),x,y);
	long long d = (long long) c;
	if(d%gcd == 0){
		x = (x)*(d/gcd);
		y = (y)*(d/gcd);
		if (a < 0) x = -x;
        if (b < 0) y = -y;
		return gcd;
	}
	return 0;
}
pair<long long,long long> min_dioph(int a,int b,int c){
	long long x;long long y;
	long long gcd = diophantine(a,-b,c,x,y);
	if(gcd){
		if(x>=0 && y>=0){
			long long  ma =  a/gcd;
			long long  mb =  b/gcd;
			long long t = min(x/mb,y/ma);
			return make_pair(x -(mb*t),y-(ma*t));
		}
		else if(x>=0){
			long long  ma =  a/gcd;
			long long  mb =  b/gcd;
			long long t;
			((-y)%ma ==0)? t = (-y)/ma: t = ((-y)/ma)+1;
			return make_pair(x +(mb*t),y+(ma*t));
		}
		else if(y>=0){
			long long  ma =  a/gcd;
			long long  mb =  b/gcd;
			long long t;
			((-x)%mb ==0)? t = (-x)/mb: t = ((-x)/mb)+1;
			return make_pair(x +(mb*t),y+(ma*t));
		}
		else{
			long long  ma =  a/gcd;
			long long  mb =  b/gcd;
			long long t1,t2 ;
			((-x)%mb ==0)? t1 = (-x)/mb: t1 = ((-x)/mb)+1;
			((-y)%ma ==0)? t2 = (-y)/ma: t2 = ((-y)/ma)+1;
			long long t = max(t1,t2);
			return make_pair(x +(mb*t),y + (ma*t));
		}
	}
	else{
		return make_pair(-1,-1);
	}
}

