const int MAX_N = 200000;

long long F[MAX_N + 1], RF[MAX_N + 1];

long long Pow(long long X, long long Y) {
	if (Y == 0) return 1;
	if (Y % 2 == 0) {
		long long Z = Pow(X, Y / 2);
		return (Z * Z) % MOD;
	}
	return (X * Pow(X, Y - 1)) % MOD;
}

void init() {
	F[0] = RF[0] = 1;
	for (int i = 1; i <= MAX_N; i++) {
		F[i] = (F[i - 1] * i) % MOD;
		RF[i] = Pow(F[i], MOD - 2);
	}
}

long long Comb(long long X, long long Y) {
	if (Y < 0 || X < Y) return 0;
	long long RET = 1;
	RET *= F[X];
	RET *= RF[Y];
	RET %= MOD;
	RET *= RF[X - Y];
	RET %= MOD;
}

