		COUNT = Comb(N - 1, i);
		COUNT *= M;
		COUNT %= MOD;
		COUNT *= Pow(M - 1, N - 1 - i);
		COUNT %= MOD;
		ANS += COUNT;
		ANS %= MOD;
	}
	cout << ANS << endl;
}

