        ans_i %= MOD;
        ans_i *= modpow(M-1, N-1-k, MOD);
        ans_i %= MOD;
        ans += ans_i;

        // ans += COM(N-1, k) * M * modpow(M-1, N-1-k, MOD);
        ans %= MOD;
    }

    cout << ans << endl;

    return 0;
}

