struct Furui{
  //! 1からnまでを素数を求める
  //! isPrime：素数判定
  //! factor：素因数分解した結果をvector<pair<LL,LL>>で返す
  //! factorList：素因数分解した結果をVLLで返す
  LL n;
  VLL f;
  VLL prime;

  Furui(LL n=1):n(n),f(n+1){
    f[0]=-1;
    f[1]=-1;
    for( LL i=2;i<=n;i++){
      if(f[i]){
        continue;
      }
      prime.push_back(i);
      for(LL j=i;j<=n; j+=i){
        if(f[j]==0){
          f[j] = i;
        }
      }
    }
  }
  bool isPrime(LL x){
    if(x<=1){
      return false;
    }
    return (f[x]==x);
  }
  VLL factor_vector(LL x){
    VLL res;
    if( x>=2 and x<=n){
      while( x!=1){
        res.push_back(f[x]);
        x /=f[x];
      }
    }
    return res;
  }
  vector<pair<LL,LL>> factor_pair(LL x){
    VLL factors = factor_vector(x);
    vector<pair<LL,LL>> P;
    if(factors.size()==0){
      return P;
    }
    P.emplace_back(factors[0],0);
    for(auto p : factors){
      if(P.back().first==p){
        P.back().second++;
      }else{
        P.emplace_back(p,1);
      }
    }
    return P;
  }
  map<LL,LL> factor_map(LL x){
    VLL factors = factor_vector(x);
    map<LL,LL> P;
    if(factors.size()==0){
      return P;
    }

    for(auto p : factors){
      P[p]+=1;  
    }
    return P;
  }
};

