int fpow(int a, int b) {
    int res = 1;
    while (b > 0) {
        if (b & 1) {
            res = res * a % MFFT;
        }
        a = a * a % MFFT;
        b /= 2;
    }
    return res;
}

int inv(int a) {
    return fpow(a, MFFT - 2);
}

