    auto C = [&](int n, int k) {
        return f[n] * inv(f[k]) % MFFT * inv(f[n - k]) % MFFT;
    };
    int ans = 0;
    for (int i = 0; i <= k; ++i) {
        ans = (ans + C(n - 1, i) * m % MFFT * fpow(m - 1, n - 1 - i)) % MFFT;
    }
    cout << ans;

    return 0;
}

