LL esp(LL x, LL e) {
    if (e == 0) return 1;
    if (e%2 == 1) return (x * esp(x, e-1)) % mod;
    return esp((x*x)%mod, e/2);
}

// Computes the inverse of n modulo m.
// Precondition: n, m > 0 and gcd(n, m) == 1.
// The returned value is always > 0.
// ACHTUNG: It must hold max(m, n) <= 2**31 to avoid integer overflow.
ULL Inverse(ULL n, ULL m) {
    if (n == 1) return 1;
    LL y = Inverse(m % n, n);
    return m - ((m * y - 1) / n) % m;
}

