void chk(vector<int> a, int & n, int & m, int & k) {
    if ((int)a.size() == n) {
        int i = 0;
        int tot = 0;
        while (i < n) {
            int cnt = 1;
            int j = i + 1;
            while (j < n && a[j] == a[i]) {
                cnt++;
                j++;
            }
            tot += cnt - 1;
            i = j;
        }
        if (tot == k) {
            c++;
        }
        return;
    }

    for (int i = 0; i < m; i++) {
        a.push_back(i);
        chk(a, n, m, k);
        a.pop_back();
    }
}

long long binExp(long long a, long long n, long long m) {
    long long res = 1;
    while (n) {
        if (n & 1) {
            res *= a;
            res %= m;
        }
        a *= a;
        a %= m;
        n = n >> 1;
    }
    return res;
}

vector<ll> fact;
ll M = 998244353;

void setFact(int & n) {
    fact = vector<ll>(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = i * fact[i - 1];
        fact[i] %= M;
    }
}

ll modInv(ll a) {
    return binExp(a, M - 2, M);
}

ll nCr(int n, int r) {
    return (fact[n] * modInv((fact[r] * fact[n - r]) % M)) % M;
}

void solve(){
    int n, m, K;
    cin >> n >> m >> K;

    setFact(n);

    ll ans = 0;
    for (int k = 0; k <= K; k++) {
        ans += ((m * nCr(n - 1, k) % M) * binExp(m - 1, n - 1 - k, M)) % M;
        ans %= M;
    }
    cout << ans << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    solve();

    return 0;
}

