const int64_t MAX = 510000;
const int64_t MOD = 998244353;

int64_t fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int64_t i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
int64_t COM(int64_t n, int64_t k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main() {
    int64_t N,M,K;
    cin >> N >> M >> K;
    COMinit();

    vector<int64_t> POW(N+1);
    POW[0] = 1;
    for ( int64_t i = 1; i <= N; ++i){
        POW[i] = POW[i-1] * (M-1) % MOD;
    }

    int64_t ans = 0;
    for ( int64_t k = 0; k <= K; ++k){
        ans = ( ans + M * COM(N-1,k) % MOD * POW[N-1-k] ) % MOD;
    }

    if ( ans < 0 ) ans += MOD;
    cout << ans << endl;

    return 0;
}

