class Combination {
   private:
    vector<int> fact, rev_fact;

   public:
    Combination(int n) { setFact(n); }
    void setFact(int n) {
        fact.resize(n + 1);
        rev_fact.resize(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
            fact[i] %= MOD;
        }
        rev_fact[n] = modpow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) {
            rev_fact[i] = rev_fact[i + 1] * (i + 1);
            rev_fact[i] %= MOD;
        }
    }
    int c(int n, int k) {
        if (k > n) return 0;
        return (((fact[n] * rev_fact[k]) % MOD) * rev_fact[n - k]) % MOD;
    }
    int h(int n, int k) { return c(n + k - 1, k); }
};

