ll mod_pow(ll a, ll n, ll p) {
    if (n == 1)
        return a;
    if (n%2 == 0) {
        ll t = mod_pow(a, n/2, p);
        return t * t % p;
    }
    else {
        ll t = mod_pow(a, n-1, p);
        return a * t % p;
    }
}

