inline ll qpow(ll a, ll b) //快速幂，用于求逆元
{
	ll res = 1;
	while (b)
	{
		if (b & 1) res = (res * a) % mod;
		a = a * a % mod, b >>= 1;
	}
	return res % mod;
}

inline ll work(int n, int m) //求 C(n, m)
{
    ll s = 1, c = 1;
    for (int i = 1; i <= m; i+=1)
        s = (s * i) %mod; //计算分母
    for (int i = n - m + 1; i <= n; i++) 
        c = (c * i) % mod; //计算分子
    return (c * qpow(s, mod - 2)) % mod; //求出值
}
