// Extended Euclidean Algorithm ax + by = gcd(a,b)
// returns gcd and stores x and y
int exgcd(int a, int b, int &x, int &y)
{
    int g = a; x = 1, y = 0;
    if( b ) g = exgcd( b,a%b,y,x ), y -= (a/b)*x;
