long long p(long long m, long long x) {
  if (x == 0) {
    return 1;
  }
  if (x == 1) {
    return m;
  }
  if (x % 2 == 0) {
    long long tmp = p(m, x / 2);
    long long tmp2 = tmp * tmp;
    return tmp2 % MOD;
  } else {
    long long tmp = p(m, (x - 1)/ 2);
    long long tmp2 = (tmp * tmp) % MOD;
    return (tmp2 * m) % MOD;
  }
}
