    long long tmp = p(m - 1, x - 1);
    long long tmp2 = COM(n - 1, x - 1);
    tmp = (tmp * m) % MOD;
    tmp = (tmp * tmp2) % MOD;
    ans += tmp;
    ans %= MOD;
  }
