#define MAXN 200000
int F[MAXN+4];
int invF[MAXN+4];
void build_factorial_tables(int N, int MOD) {
   F[0] = 1;
   for (int i = 1; i <= N; ++i)
      F[i] = (F[i-1] * 1LL * i) % MOD;
   VI inv(N+1);
   inv[0]  = inv[1] = 1;
   invF[0] = invF[1] = 1;
   for (int i = 2; i <= N; ++i) {
      inv[i] = (MOD - (MOD / i) * 1LL * inv[MOD % i] % MOD) % MOD;
      invF[i] = (invF[i-1] * 1LL * inv[i]) % MOD;
   }
}

int nCk(int n, int k, int P) {
   if (n < 0 || k < 0 || k > n)  // invalid n or k
      return 0;
   long long res = F[n];
   res = (res * invF[k]) % P;
   res = (res * invF[n-k]) % P;
   return res;
}

