class mint {
  public:
    ll x;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}
    ll get() const { return x; }
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const { return mint(*this) += a; }
    mint operator-(const mint a) const { return mint(*this) -= a; }
    mint operator*(const mint a) const { return mint(*this) *= a; }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        return (t & 1) ? a * a * (*this) : a * a;
    }
    operator ll() const { return x; }
    operator string() const { return to_string(x); }
    friend istream& operator>>(istream& is, mint& a) {
        is >> a.x;
        return is;
    }

    // for prime mod
    mint inv() const { return pow(mod - 2); }
    mint& operator/=(const mint a) { return (*this) *= a.inv(); }
    mint operator/(const mint a) const { return mint(*this) /= a; }
};

class Combination {
  public:
    int n;
    vector<mint> fc, fci;
    Combination(int n) : n(n), fc(n + 1, 1), fci(n + 1, 1) {
        for (int i = 2; i <= n; ++i) {
            fc[i] = fc[i - 1] * mint(i);
            fci[i] = fci[i - 1] / mint(i);
        }
    }
    mint operator()(ll n, ll k) {
        if (k == 0 || n == k) return 1;
        return fc[n] * fci[k] * fci[n - k];
    }
};

int main() {
    int N, M, K;
    cin >> N >> M >> K;

    Combination C(N - 1);
    K = min(K, N - 1);

    mint ans(0);
    for (int i = K; i >= 0; --i) {
        mint t(1);
        t *= C(N - 1, i);
        t *= mint(M) * mint(M - 1).pow(N - i - 1);
        ans += t;
    }
    cout << ans << endl;

    return 0;
}

