int CASE = 1;
int fastExp(ll x, ll p, int mod) {
    if (p == 0) return 1;
    if (p < 0) return 0;
    ll ans = 1;
    while (p) {
        if (p & 1) ans = ans * x % mod;
        x = x * x % mod;
        p >>= 1;
    }
    return ans;
}
void extgcd(ll a, ll b, ll& d, ll& x, ll& y) {
    if (!b) {
        d = a;
        x = 1;
        y = 0;
    } else {
        extgcd(b, a % b, d, y, x);
        y -= x * (a / b);
    }
}

inline ll getInv(ll x, ll mod) {
    ll g, a, b;
    extgcd(x, mod, g, a, b);
    return (a % mod + mod) % mod;
}
ll fact[MAXN];
ll choose(int n, int k) {
    if (k > n) return 1;
    return fact[n] * getInv(fact[k] * fact[n - k] % MOD, MOD) % MOD;
}

ll fact2(int x) {
    if (x <= 0) return 1;
    return fact[x];
}
