	VVL dp(n, VL(k + 1));
	dp[0][0] = m;
	FOR(i, 1, n)REP(j, k + 1) {
		dp[i][j] = (m - 1) * dp[i - 1][j];
		if (j - 1 >= 0) { dp[i][j] += dp[i - 1][j - 1]; }
		dp[i][j] %= MOD;
	}

	//dump(dp);
	ll ans = 0;
	REPC(x, dp[n - 1]) {
		ans += x;
		ans %= MOD;
	}
	return ans;
}

auto solve(ll n, ll m, ll k) {
	ll ans = m;
	//ans *= calc.pow(m, k);
