int64_t mpow(int64_t x, int64_t n)
{
	int64_t ans = 1;
	while (n != 0) {
		if (n & 1) {
			ans = ans * x % M;
		}
		x = x * x % M;
		n = n >> 1;
	}
	return ans;
}

int64_t comb(int64_t n, int64_t k)
{
	if (n == 0 && k == 0) {
		return 1;
	} else if (n < k || n < 0) {
		return 0;
	}
	int64_t temp = ifac.at(k) * ifac.at(n - k) % M;
	return temp * fac.at(n) % M;
}

