		ifac.at(i + 1) = ifac.at(i) * mpow(i + 1, M - 2) % M;
	}

	int64_t ans = 0;
	for (int i = 0; i <= k; i++) {
		int64_t temp = m;
		temp = temp * comb(n - 1, i) % M;
		temp = temp * mpow(m - 1, n - 1 - i) % M;
		ans = (ans + temp) % M;
	}

