    while (k) {
        if (k & 1) res = (res * n) % MOD;

        k >>= 1;
        n = n * n % MOD;
    }

    return res;
}

LL inv(LL a) {
    return bp(a, MOD - 2);
}

LL F[MAX];
LL RF[MAX];
LL cc(int n, int k) {
    //if (n < k) return 1;

    LL res = F[n] * RF[k] % MOD;
    res = res * RF[n - k] % MOD;
    return res;
}

