    F[0] = RF[0] = 1;
    FOR(i, 1, MAX) {
        F[i] = F[i - 1] * i % MOD;
        RF[i] = inv(F[i]);
        assert(RF[i] * F[i] % MOD == 1);
    }

    LL n, m, k;
    cin >> n >> m >> k;

    LL res = 0;
    FOR(i, 0, k + 1) {
        LL dod = m * bp(m - 1, n - i - 1) % MOD;
        //cerr << i << ": " << dod << endl;
