  return power(a, MOD - 2, MOD);
}

int fact[N], invfact[N];

void pre() {
  fact[0] = fact[1] = 1;
  for (int i = 2; i < N; i++){
    fact[i] = i * fact[i - 1];
    fact[i] %= MOD;
  }
  invfact[N - 1] = modinv(fact[N - 1]);
  for (int i = N - 2; i >= 0; --i){
    invfact[i] = invfact[i + 1] * (i + 1);
    invfact[i] %= MOD;
  }
}

int nCr(int n, int r) {
  if (r > n)
    return 0;
  return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
}

