  // n1 + n2 + n3 + ..... + np = n  [ith block = same color]
  // ways = (n - 1, p - 1) => stars and bars theorem
  // every block of length x has (x - 1) pairs of same color
  // n1 - 1 + n2 - 1 + n3 - 1 + .... np - 1 <= k
  // n1 + n2 + n3 ... + np - p <= k
  // n - p <= k => n >= p >= n - k 
  // number of ways to color first block out of p blocks
  // using m colors = m
  // total ways of coloring all p blocks = m * (m - 1) ^ (p - 1)  
  // no adjacent blocks may contain the same color

  pre();
