  for (int p = n - k; p <= n; p++){
    int ways = m * power(m - 1, p - 1, MOD);
    ways %= MOD;
    ways *= nCr(n - 1, p - 1);
    ways %= MOD;
    sum += ways;
  }
  sum %= MOD;
  cout << sum << endl;
}

