		ifc[i] = fac[i].inv();
	}
}

rem inline C(int n, int m) { return n >= m ? fac[n] * ifc[m] * ifc[n - m] : rem(0); }

rem inline f(int n, int k) { return C(n - 1, k) * m * (m - rem(1)).pow(n - k - 1); }

