class Inverse{
    public:
        vector<LL> inv;
        int sz;
    Inverse(int _sz = 0){
        sz = max(1, _sz);
        inv = vector<LL>(sz + 1);
        inv[1] = 1;
        for(int i = 2; i <= sz; i++) {
            inv[i] = inv[mod % i] * (mod - mod / i) % mod;
        }
    }
    LL get(LL x) {
        if(x <= sz) return inv[x];
        else return pow2(x, mod - 2);
    }
};

class Combination{
    //mode=1: pre cal c[n][m]
    //mode=2: pre cal fac[] invfac[] => fac[n] * invfac[m] * invfac[n - m]
    public:
        Combination(int _mode, int _sz): mode(_mode), sz(_sz){
            if(mode == 1) {
                c = vector<vector<LL>>(sz + 1, vector<LL>(sz + 1, 0));
                c[0][0] = 1;
                for(int i = 1; i <= sz; i++) {
                    c[i][0] = c[i][i] = 1;
                    for(int j = 1; j < i; j++) {
                        c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;
                    }
                }
            }
            else {
                Inverse inv(sz);
                fac = vector<LL>(sz + 1);
                invfac = vector<LL>(sz + 1);
                fac[0] = invfac[0] = 1;
                for(int i = 1; i <= sz; i++) {
                    fac[i] = fac[i - 1] * i % mod;
                    invfac[i] = invfac[i - 1] * inv.get(i) % mod;
                }
            }
        }
        LL get(int n, int m){
            assert(m <= n && n <= sz);
            if(mode == 1) return c[n][m];
            else return fac[n] * invfac[m] % mod * invfac[n - m] % mod;
        }

        int mode, sz;
        vector<vector<LL>> c;
        vector<LL> fac, invfac;
};


