class modComb
{
private:
	const int MOD;
	modFact mod_fact;

public:
	modComb( const int n, const int mod ) : MOD( mod ), mod_fact( n, mod ) {};

	int operator()( const int n, const int r )
	{
		if ( n < 0 || r < 0 || n < r )
		{
			return 0;
		}

		int e1, e2, e3;
		long long a1 = mod_fact( n, e1 ), a2 = mod_fact( r, e2 ), a3 = mod_fact( n - r, e3 );
		if ( e1 > e2 + e3 )
		{
			return 0;
		}
		return a1 * mod_inverse( a2 * a3 % MOD, MOD ) % MOD;
	}
};
