ll pow(ll n, ll k) {
  ll r = 1;

  while (k > 0) {
    if (k % 2 == 1) {
      r = r * n % MOD;
    }
    n = n * n % MOD;
    k /= 2;
  }
  return r;
}

ll fac[3000000];

ll inv(ll x) {
  return pow(x, MOD - 2);
}


ll C(ll n, ll k) {
  if (k > 0) {
    return fac[n] * inv(fac[n - k]) % MOD * inv(fac[k]) % MOD;
  } else {
    return 1;
  }
}

void solve(ll n, ll m, ll k) {
  ll ans = 0;

  rep(i, k + 1) {
    ans += m * pow(m - 1, n - 1 - i) % MOD * C(n - 1, i) % MOD;
    ans %= MOD;
  }

  cout << ans << endl;
}

