    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(ll n, ll k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll cal(ll x, ll n) {  // (x)^N　　
    int p = n;
    x %= MOD;
    ll res = 1;
    while (p > 0) {
        if (p & 1) res = (x * res) % MOD; //pが奇数ならresはx倍される
        x = x * x % MOD; //ここはxを二乗している
        p >>= 1; //pを二で割って、あまり切り捨てか。
    }
    return res;
}


void solve(){
    COMinit();
    ll n,m,k;
    cin >> n >> m >>k;
    ll ans=0;
    for(ll i=0;i<=k;i++){
        ll score=m;
        score*=COM(n-1,i);
        score%=MOD;
        score*=cal(m-1,n-1-i);
        score%=MOD;
        ans+=score;
        ans%=MOD;
    }
    kaku((ans+MOD)%MOD);
}

int main(){
    solve();
}

