        C[n] *= (N-n);
        C[n] %= MOD;
        C[n] *= modinv(n, MOD);
        C[n] %= MOD;

        pow[n] = pow[n-1]*(M-1);
        pow[n] %= MOD;
    }

    long long int ans=0;
    for(int k=0; k<=K; k++) {
        long long int tmp=C[k]*pow[N-1-k];
        tmp %= MOD;
        ans += tmp;
        ans %= MOD;
    }
    ans *= M;
    ans %= MOD;
    cout << ans << endl;

