void ifac_mod(int size) {
  // ifac[i] = 1/i! (mod M)
  ifac.resize(size);
  inv.resize(size);
  ifac[0] = 1;
  ifac[1] = 1;
  inv[1] = 1;
  int n = ifac.size();
  for (int i = 2; i < n - 1; i++) {
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    ifac[i] = ifac[i - 1] * inv[i] % MOD;
  }
}
