    vector<ll> pow(N, 1);
    for(int i = 1; i < N; i++) pow[i] = pow[i - 1] * (M - 1) % MOD;

    for(int k = 0; k <= K; k++) {
        ll tmp = M * pow[N - k - 1];
        tmp %= MOD;
        tmp *= cm.get(N - 1, k);
        tmp %= MOD;
        ans += tmp;
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

