ll mod = 998244353;

ll mypow(ll x, ll y){
  if(y == 1) return x;
  ll z = mypow(x, y / 2) % mod;
  if(y % 2 == 0){
    return ((z * z) % mod) * x % mod;
  }
  else{
    return (z * z) % mod;
  }
}

ll choose(ll l, ll r){
  ll u = 1, d = 1;
  for(ll i = l; i > l - r; i--){
    u = (u * l) % mod;
  }
  for(ll i = 1; i <= r; i++){
    d = (d * i) % mod;
  }
  d = mypow(d, mod - 2);
  return (u * d) % mod;
}

void solve(){
  ll n, m, k, x, y, z; cin >> n >> m >> k;
  x = mypow(m - 1, n - 1) * m % mod;
   ll ans = x;
   for(int i = 1; i <= k; i++){
     y = choose(n - 1, i);
     z = mypow(m - 1, n - i - 1);
     cout << y << " " << z << endl;
     ans = (ans + (m * (y * z) % mod) % mod % mod);
   }
   cout << ans << endl;
  return;
}

int main(){
  solve();
  return 0;
}

