constexpr long long MOD = 998244353;
const int MAX_N = 200000;

long long F[MAX_N + 1], RF[MAX_N + 1];

long long Pow(long long X, long long Y) {
	if (Y == 0) return 1;
	if (Y % 2 == 0) {
		long long Z = Pow(X, Y / 2);
		return (Z * Z) % MOD;
	}
	return (X * Pow(X, Y - 1)) % MOD;
}

void init() {
	F[0] = RF[0] = 1;
	for (int i = 1; i <= MAX_N; i++) {
		F[i] = (F[i - 1] * i) % MOD;
		RF[i] = Pow(F[i], MOD - 2);
	}
}

long long Comb(long long X, long long Y) {
	if (Y < 0 || X < Y) return 0;
	long long RET = 1;
	RET *= F[X];
	RET *= RF[Y];
	RET %= MOD;
	RET *= RF[X - Y];
	RET %= MOD;
	return RET;
}

int main() {
	init();
	long long N, M, K;
	cin >> N >> M >> K;
	long long ANS = 0;
	for (int i = 0; i <= K; i++) {
		long long COUNT = 1;
		COUNT = Comb(N - 1, i);
		COUNT *= M;
		COUNT %= MOD;
		COUNT *= Pow(M - 1, N - 1 - i);
		COUNT %= MOD;
		ANS += COUNT;
		ANS %= MOD;
	}
	cout << ANS << endl;
}

#include <bits/stdc++.h>
using namespace std;

template<int MAX>
struct Combination {
    vector<long long> _inv, _fac, _ifac;
    const long long MOD;
    Combination(long long mod) : _inv(MAX+1), _fac(MAX+1), _ifac(MAX+1), MOD(mod) { init(); }
    inline void init(long long mod = 0) { init_inv(), init_fac(); }

    inline void init_inv() {
        _inv[0] = 0;
        for (int i = 1; i <= MAX; i++) {
            if (i == 1) _inv[i] = 1;
            else {
                _inv[i] = (MOD - (MOD / i) * _inv[MOD % i]) % MOD;
                if (_inv[i] < 0) _inv[i] += MOD;
            }
        }
    }
    inline void init_fac() {
        _fac[0] = _ifac[0] = 1;
        for (int i = 1; i <= MAX; i++) {
            _fac[i] = _fac[i-1] * i % MOD;
            _ifac[i] = _ifac[i-1] * _inv[i] % MOD;
        }
    }

    inline long long modpow(long long n, long long r) {
        n %= MOD, r %= (MOD-1);
        if (!n) return 0;
        long long ret = 1; long long tmp = n;
        while (r != 0) {
            if (r % 2) ret *= tmp;
            tmp *= tmp; tmp %= MOD; ret %= MOD;
            r /= 2;
        }
        return ret;
    }
    inline long long invb(int i) { return (i <= MAX) ? _inv[i] : this->modpow(i, MOD-2); }
    inline long long inv(int i) { return _inv[i]; }
    inline long long fac(int i) { return _fac[i]; }
    inline long long ifac(int i) { return _ifac[i]; }

    const long long operator()(int n, int r) {
        if (n < r) return 0;
        return fac(n) * ifac(r) % MOD * ifac(n-r) % MOD;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    constexpr int mod = 998244353;
    long long n, m, k; cin >> n >> m >> k;
    Combination<500010> C(mod);
    long long ans = 0;
    if (m == 1) {
        if (k == n-1) cout << 1 << "\n";
        else cout << 0 << "\n";
        return 0; 
    }
    for (int i = 0; i <= k; i++) {
        ans += C(n-1, i) * C.modpow(m-1, n-i-1) % mod * m % mod;
    }
    cout << ans % mod << "\n";
    return 0;
}

