long long binary_search(long long key,long long size){
    //left,right,midはいずれもindex
    long long left = -1,right = size;
    while(right - left > 1){
        long long mid = left + (right-left)/2;
        long long hantei = ok(key,mid);
        if(hantei) right = mid;
        else left = mid;
    }
    if(left == -1)return 0;
    return left;
}

const int MAX = 510000;
//fac[]はn! inv[]はMODにおける逆元 finv[]はinv[]とfinv[]の累積積    
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算(nCr)
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
    long long N,M,K; cin >> N >> M >> K;
    long long ans = 0;
    long long A = 1;
    COMinit();
    for(long long i = K;i>=0;i--){
        //色の塗分けをグループごとで考えた時の場合の数
        //累乗で求まるが愚直にやるとTLEするので、逆から見ていく(指数が大きくなるように見ていく)
        //ことで、毎回mod_powせずに*(N-i)できるようになる
        if(i == K) A = M*mod_pow(M-1,N-i-1);
        if(i != K) A *= M-1;
        A %= MOD;
        //グループの分け方。N-1の間に接続部分を入れる場合の数
        long long B = COM(N-1,i);
        long long sum = A*B;
        sum %= MOD;
        ans += sum;
        ans %= MOD;
        if(ans < 0) ans += MOD;
    }
    cout << ans % MOD << endl;
}

