const int MAX = 210000;
const int MOD = 998244353;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long POW(int n, int x) {
	if (x == 0) return 1;
	if (x == 1) return n;
	if (n == 0) return 0;
	if (n == 1) return 1;
	if (x % 2 == 1) {
		return (POW(n, x - 1) * n) % MOD;
	}
	else {
		long long t = POW (n, x / 2);
		return (t * t) % MOD;
	}
}

int main()
{
