	for (int i = 0; i <= K; i++) {
		long long n1k = COM(N - 1, i);
		long long x = M * POW(M - 1, N - i - 1) % MOD;
		ans += (n1k * x) % MOD;
		ans %= MOD;
	}
	printf("%lld\n", ans);

	return 0;
}

