long long CalcModInv(long long a) {
	long long u = 1, v = 0;
	long long b = D;
	while (b) {
		long long t = a / b;
		a -= t * b;
		swap(a, b);
		u -= t * v;
		swap(u, v);
	}
	u %= D;
	if (u < 0)
		u += D;
	return u;
}

int main() {
