//組み合わせ（nCk）を求める。
struct combination {
  //fact[N] → Nの階乗
  //ifact[N] → Nの階乗の逆元。fact[N]で割りたくなったら、ifact[N]をかける。 
  vector<mint> fact, ifact;
  combination(int n) : fact(n + 1), ifact(n + 1) {
    assert(n < mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
    //Nまでの階乗の逆元を計算する（ifact[N]＝1/fact[N])
    ifact[n] = fact[n].inv();
    //N、N-1、、、の順で、ifact[N]に掛け算すると、N-1の階乗、N-2の階乗が求まる。
    for (int i = n; i >= 1; --i) ifact[i - 1] = ifact[i] * i;
  }
  mint operator()(int n, int k) {
    if (k < 0 || k > n) return 0;
    //nの階乗 / （kの階乗 * n-kの階乗） → 組み合わせの定義そのもの
    return fact[n] * ifact[k] * ifact[n - k];
  }
};

signed main() {
  int N,M,K;cin >> N >> M >> K;

  combination combi(N-1);
  mint ans = 0;
  for (int i = 0; i <= K; i++)
  {
    mint buf = (M-1);
    buf = buf.pow(N-1-i);
    buf *= M;
    buf *= combi(N - 1, i);
    ans += buf;
  }
  cout << ans << endl;

}

