    {
        if (n < k)
            return 0;
        if (n < 0 || k < 0)
            return 0;
        ll ret = fac[n];
        ret = (ret * powmod(fac[k], MOD - 2)) % MOD;
        ret = (ret * powmod(fac[n - k], MOD - 2)) % MOD;
        return ret;
    }

    ll PERM(int n, int k)
    {
        if (n < k)
            return 0;
        ll ret = fac[n];
        ret = (ret * powmod(fac[n - k], MOD - 2)) % MOD;
        return ret;
    }
};

