auto exp(ll n, ll p) {
  ll acc = 1;
  for (auto pwr = n; p; pwr = mult(pwr, pwr), p >>= 1)
    if (p & 1)
      acc = mult(acc, pwr);
  return acc;
}
auto mdiv(ll a, ll b){return mult(a, exp(b, MOD - 2));}

const int MAXN = 3 * 1e5;
ll factorial[MAXN + 5];
ll nck(ll n, ll k) {
  return mdiv(factorial[n], mult(factorial[k], factorial[n - k]));
}

