////////////////////////////////////////////////
void fac_mod(int size) {
  // fac[i] = i! (mod M)
  fac.resize(size);
  fac[0] = 1;
  fac[1] = 1;
  int n = fac.size();
  for (int i = 0; i < n - 1; i++) {
    fac[i + 1] = fac[i] * (i + 1) % MOD;
  }
}
////////////////////////////////////////////////
void ifac_mod(int size) {
  // ifac[i] = 1/i! (mod M)
  ifac.resize(size);
  inv.resize(size);
  ifac[0] = 1;
  ifac[1] = 1;
  inv[1] = 1;
  int n = ifac.size();
  for (int i = 2; i < n - 1; i++) {
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    ifac[i] = ifac[i - 1] * inv[i] % MOD;
  }
}
////////////////////////////////////////////////
void nCk_init(int m) {
  if (m <= 0) {
    cout << "error! invalid m val: m = " << m << endl;
  }
  fac_mod(m + 1);
  ifac_mod(m + 1);
}
////////////////////////////////////////////////
ll nCk_mod(int n, int k) {
  // nCk (mod M)
  if (n == 0 && k == 0) return 1;
  if (n < k || k < 0) return 0;
  return fac[n] * (ifac[n - k] * ifac[k] % MOD) % MOD;
}
////////////////////////////////////////////////
ll pow_mod(ll x, int n) {
  // x^n (mod M)
  ll pow = 1;
  while (n != 0) {
    if (n & 1) pow = pow * x % MOD;
    x = x * x % MOD;
    n = n >> 1;
  }
  return pow;
}
