static MODINT getComb(
    const vector<SQWORD> &vsqPow,
    SQWORD sqN,
    SQWORD sqM)
{
    MODINT comb(vsqPow[sqN]);

    if (0 == sqM) {
        return MODINT(1);
    }

    comb /= vsqPow[sqN - sqM];
    comb /= vsqPow[sqM];

    return comb;
}


