long long modpow(long long x, long long n, long long mod = 0) {
  if (mod == 0) {
      long long res=1;
    while (n > 0) {
      if (n%2 == 1) {
        res = ( res*x );
      }
      x = (x*x);
      n /= 2;
    }
    return res;
  }

  long long res=1;
  while (n > 0) {
    if (n%2 == 1) {
      res = ( res*x ) % mod;
    }
    x = (x*x) % mod;
    n /= 2;
  }
  return res;
}

long long modinverse(long long x, long long mod) {
  // mod must be prime number.
  return modpow(x, mod-2, mod);
}

long long modcomb(long long m, long long n, long long mod){
  if (m < n) return 0;
  if (n > m/2) n = m-n;
  if (n == 0) return 1;
  long long m1,m2,m3;
  long long fact=1;
  for (int i=1; i<=m; i++) {
    fact = fact * i % mod;
    if (i == m) m1 = fact;
    if (i == n) m2 = fact;
    if (i == m-n) m3 = fact;
  }
  long long ans = m1 * modinverse(m2, mod) % mod;
  ans = ans * modinverse(m3, mod) % mod;
  return ans;
}


long long solve(long long n, long long m, long long k, long long mod) {
  long long ans = m * modcomb(n-1,k, mod) % mod;
  ans = ans * modpow(m-1, n-k-1, mod) % mod;
  return ans;
}

