using namespace std;

const int md = 998244353;
const int N = 200005;

int f[N];

int add(int x, int y) {
  x += y;
  if (x >= md) {
    x -= md;
  }
  return x;
}

int sub(int x, int y) {
  x -= y;
  if (x < 0) {
    x += md;
  }
  return x;
}

int mul(int x, int y) {
  return (int)((long long)x * y % md);
}

int power(int x, int y) {
  int ans = 1;
  while (y) {
    if (y & 1) {
      ans = mul(ans, x);
    }
    x = mul(x, x);
    y >>= 1;
  }
  return ans;
}

int inv(int x) {
  return power(x, md - 2);
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  f[0] = f[1] = 1;
  for (int i = 2; i < N; i++) {
    f[i] = mul(i, f[i - 1]);
  }
  int n, m, k;
  cin >> n >> m >> k;
  int ans = 0;
  int num = f[n - 1];
  for (int i = 0; i <= k; i++) {
    int deno = mul(f[i], f[n - 1 - i]);
    int c = mul(num, inv(deno));
    c = mul(c, m);
    c = mul(c, power(m - 1, n - i - 1));
    ans = add(ans, c);
  }
  cout << ans << '\n';
  return 0;
}

