	for (int i = 2; i <= 400000; i++) {
		by[i] = by[i - 1] * i%MOD;
		rev[i] = power(by[i], MOD - 2, MOD);
	}
	long long int ans = 0;
	for (int i = 0; i <= K; i++) {
		ans += by[N - 1] * rev[i] % MOD*rev[N - 1 - i] % MOD * power(M - 1, N - 1 - i, MOD) % MOD*M%MOD;
		ans %= MOD;
	}
	cout << ans << endl;
}

