ll fast_pow(ll num,ll st)
{
    if(st == 0) return 1;
    ll tmp = fast_pow(num,st/2)%MOD;
    tmp*=tmp;
    tmp%=MOD;
    return (tmp*(st%2==1 ? num:1)%MOD);
}
void precalc()
{
    fact[0] = 1;
