}

/* xをk乗して余りを求める */
ll pow_mod(ll x, ll k){
    x %= 998244353; x += 998244353; x %= 998244353;
    ll res = 1;
    while(k>0){
        if(k%2){
            res *= x; res %= 998244353;
        }
        x *= x; x %= 998244353;
        k /= 2;
    }
    return res;
}

