class Combination {
 private:
  vector<T> f, invf;

 public:
  Combination(int n) : f(n + 1, 1), invf(n + 1, 1) {
    for (int i = 1; i < n + 1; i++) {
      f[i] = f[i - 1] * i;
    }
    invf[n] /= f[n];
    for (int i = n; i > 0; i--) {
      invf[i - 1] = invf[i] * i;
    }
