    for(int i = n-1; i>=0; i--){
        ifac[i] = (i+1)*ifac[i+1]%mod;
    }
}

ll ncr(ll n, ll r){
    if(n<r) return 0LL;

    return fac[n]*ifac[n-r]%mod*ifac[r]%mod;
