	cin >> N >> M >> K;

	int ans = 0;

	for (int i = 0; i <= K; i++) {
		int cnt = 0;
		cnt += M * modpow(M - 1, N - i - 1);
		cnt %= mod;
		cnt *= comb(N - 1, i);
		ans += cnt;
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

