    cin >> N >> M >> K;
    Comb comb(N+10);
    long long ans = 0;
    for(int k=0; k<=K; k++){
        long long tmp = (comb.calc(N-1, k) * bipow(M-1, N-1-k)) % MOD;
        ans += tmp;
        ans %= MOD;
    }
    ans *= M;
    ans %= MOD;
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10, mod = 998244353;
typedef long long ll;

ll f[N]; // 阶乘

ll fp(ll a, ll b){
    ll res = 1;
    while(b){
        if(b & 1) res = res * a % mod;
        b >>= 1;
        a = a * a % mod;
    }
    return res;
}

ll C(ll a, ll b){ // 计算组合数
    return f[a] * fp(f[b], mod - 2) % mod * fp(f[a - b], mod - 2) % mod;   
}

int main(){
    ll n, m, k; cin >> n >> m >> k;
    f[0] = 1;
    for(int i = 1; i <= n; i ++) f[i] = f[i - 1] * i % mod;
    ll ans = 0;
    for(int i = n - k; i <= n; i ++){
        ll tmp = C(n - 1, i - 1) * m  % mod * fp(m - 1, i - 1) % mod;
        ans = (ans + tmp) % mod;
    }
    cout << ans << endl;
    return 0;
}

