int fastModExp(int a, int b, int m)
{
	if (a < 0LL) return 0;
	if (b < 0LL) return 0;
	int res = 1;
	while (b > 0)
	{
		if (b & 1)
			res = (res * a) % m;

		a = (a * a) % m;
		b = b >> 1;
	}
	return res;
}
