using i64 = long long;

const i64 kMod = 998244353;  // 1e9 + 7;
vector<i64> fac = {1LL};     // 0! = 1
i64 add(i64 n1, i64 n2) {
  n1 %= kMod;
  n2 %= kMod;
  return (n1 + n2) % kMod;
}

i64 sub(i64 n1, i64 n2) {
  n1 %= kMod;
  n2 %= kMod;
  return (n1 - n2 + kMod) % kMod;
}

i64 mul(i64 n1, i64 n2) {
  n1 %= kMod;
  n2 %= kMod;
  return (n1 * n2) % kMod;
}

i64 pow(i64 n, i64 m) {  // n^mを計算
  n %= kMod;
  if (n == 1 || m % (kMod - 1) == 0) {
    return 1;
  } else if (m < 0) {  // n^m * n^(-m) = 1 = n^k(kMod-1)
    m = (m % (kMod - 1)) + kMod - 1;
    return pow(n, m);
  } else if (m >= kMod - 1) {  // k ^ m = k ^ q(kMod-1) * k^r = k^r
    return pow(n, m % (kMod - 1));
  } else if (m % 2) {  // m is odd
    return mul(pow(n, m - 1), n);
  } else {  // m is evem
    i64 tmp = pow(n, m / 2);
    return mul(tmp, tmp);
  }
}

i64 div(i64 n1, i64 n2) {
  n1 %= kMod;
  n2 %= kMod;
  return mul(n1, pow(n2, -1));
}

i64 fact(i64 n) {
  // assert(n >= 0);
  if (n == 0) {
    return 1;
  } else if ((i64)fac.size() > n && fac[n] != 0) {
    return fac[n];
  }

  if ((i64)fac.size() <= n) {
    fac.resize(2 * n);
  }

  i64 i = 1;

  while (fac[i] != 0 && i <= n)  // i<= n is for avoiding infinite loop
    i++;
  while (i <= n) {
    fac[i] = (fac[i - 1] * (i % kMod)) % kMod;
    i++;
  }
  return fac[n];
}

i64 ifact(i64 n) { return pow(fact(n), -1); }

i64 comb(i64 n, i64 m) {
  i64 tmp = fact(n);
  i64 tmp2 = ifact(m);
  i64 tmp3 = ifact(n - m);
  tmp = (tmp * tmp2) % kMod;
  tmp = (tmp * tmp3) % kMod;
  return tmp;
}

i64 perm(i64 n, i64 m) { return (fact(n) * ifact(n - m)) % kMod; }

