void init_fact() {
  fact[0] = 1LL;
  for(int i = 1;i < 300000; ++i) {
    fact[i] = (fact[i-1] * i) % mod;
  }

  // calc fact[299999]^(mod-2)
  ll acc = 1LL;
  ll x = mod - 2LL;
  ll p = fact[299999];
  while(x > 0) {
    if(x & 1) {
      acc = (acc * p) % mod;
    }
    p = (p * p) % mod;
    x >>= 1;
  }
  rfact[299999] = acc;

  for(int i = 299999;i > 0;--i){
    rfact[i-1] = (rfact[i] * i) % mod;
  }
}

void init_col_pow(ll m) {
  col_pow[0] = 1LL;
  for(int i = 1;i < 300000;++i) {
    col_pow[i] = (col_pow[i-1] * (m - 1LL)) % mod;
  }
}

ll comb(int n,int k) {
  ll res = 1LL;
  res = (res * fact[n]) % mod;
  res = (res * rfact[n-k]) % mod;
  res = (res * rfact[k]) % mod;
  return res; 
}

