    delta = (delta * (ll)m) % mod;
    delta = (delta * col_pow[n-1-i]) % mod;
    delta = (delta * comb(n - 1,i)) % mod;
    res = (res + delta) % mod;
  }
  cout << res << endl;
  return 0;
}

