ll modpower(ll a, ll n, ll mod) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

ll modinv(ll a, ll mod) {
    return modpower(a, mod - 2, mod);
}

ll largeCOM(ll n, ll r, ll mod) {
    ll u = 1, d = 1;
    rep (i, r) {
        u = (u * (n - i)) % mod;
        d = (d * (r - i)) % mod;
    }
    return u * modinv(d, mod) % mod;
}

int main() {
    cin.tie(nullptr);
