    ll res = 0;
    rep (i, k + 1) {
        ll tmp = 1;
        tmp = m * modpower((ll)m - 1, (ll)n - 1 - i, MOD);
        tmp %= MOD;
        tmp *= largeCOM((ll)n - 1, (ll)i, MOD);
        tmp %= MOD;
        res += tmp;
        res %= MOD;
    }
    cout << res << endl;

    return 0;
}

