ll modpower(ll x, ll y) {
	if (y == 0)
		return 1;
	ll p = modpower(x, y / 2) % mod;
	p = (p * p) % mod;
	return y & 1 ? (x * p) % mod: p;
}

ll modinverse(ll a)
{
    ll m = mod;
    ll y = 0, x = 1;
    while (a > 1)
    {
        ll q = a / m;
        ll t = m;
        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    return x < 0 ? x + mod : x;
}

vl fact(500005);

ll ncr(ll n, ll r) {
	return fact[n] * modinverse(fact[n - r]) % mod * modinverse(fact[r]) % mod;
}

