vector<bool> isprime;
void sieveInit(int s){
    isprime.resize(s);
    isprime[0] = isprime[1] = false;
    isprime[2] = true;
    for(int i=3; i<s; i++) isprime[i] = i%2 != 0;
    for(int i=3; i<sqrt(s)+1; i+=2){
        if(isprime[i]) {int m = 3*i; while(m < s){isprime[m] = false; m += 2*i;}}
        else continue;
    }
}

