};
primeFactor primeFactorInit(ll number){
    primeFactor pf;
    pf.number = number;
    for(int i=2; i<sqrt(pf.number)+1; i++){
        while(number%i == 0) {pf.exponent[i]++; number /= i;}
        if(number == 1) break;
    }
    if(number != 1) pf.exponent[number]++;
    return pf;
}
