const int MAXN=2e5+1;
const int M=998244353;

ll fac[MAXN];
ll infac[MAXN];

ll modexp(ll a,ll b){
	if(b==0)
		return 1;
	if(b%2==0){
		return modexp((a*a)%M,b/2);
	}
	else{
		return (a*modexp((a*a)%M,b/2))%M;
	}
}

ll modinver(ll num){

	return modexp(num,M-2);
}

void intialise(){
	fac[0]=1;

	for(int i=1;i<MAXN;i++){
		fac[i]=(fac[i-1]*i)%M;
	}

	infac[MAXN-1]=modinver(fac[MAXN-1]);

	for(int i=MAXN-2;i>=0;i--){
		infac[i]=(infac[i+1]*(i+1))%M;
		//cout<<i<<" "<<infac[i]<<endl;
	}
}

ll ncr(ll n,ll r){
	if(r>n)
		return 0;

	ll ans=fac[n];
	ans=(ans*infac[r])%M;
	ans=(ans*infac[n-r])%M;

	return ans;
}

void solve(){

	int n,m,k;
	sfi(n) sfi(m) sfi(k)

	ll ans=0;

	for(int i=0;i<=k;i++){
		ll temp=ncr(n-1,i);

		//cout<<temp<<" "<<endl;

		temp=(temp*m)%M;


		temp=(temp*modexp(m-1,n-1-(i)))%M;

		ans=(ans+temp)%M;


	}

	pfln(ans)
}


int main(){	
	intialise();
	solve();
	return 0;	
}

