const long long MOD = 998244353;

long long dp(int prev, long long N, long long M, long long K, vector<vector<long long> >& memo) {
    if (K < 0) {
        return 0LL;
    }
    if (N == 0) {
        return 1LL;
    }
    if (memo[N][K] >= 0) {
        return memo[N][K];
    }

    long long ret = 0LL;
    for (long long i = 0; i < M; ++i) {
        if (prev == i) {
            if (K > 0) {
                long long r = dp(i, N - 1, M, K - 1, memo);
                ret += r;
                ret %= MOD;
            }
            else {
                continue;
            }
        }
        else {
            long long r = dp(i, N - 1, M, K, memo);
            ret += r;
            ret %= MOD;
        }
    }
    memo[N][K] = ret;
    return ret;
}

