T powm(T a, T b, T mod=MOD){
    if(b && b%2){
        return a*powm(a*a,b/2)%mod;
    }else if(b){
        return powm(a*a,b/2)%mod;
    }else{
        return 1;
    }
}
long long modinv(long long a, long long m=MOD) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}
