#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 2e5 + 5;
const long long mod = 998244353;
int n, k;
long long m;
long long fact[MAX_N], inv_fact[MAX_N];

long long power(long long  x, long long y, long long p) {
    long long res = 1;
    x = x % p;
    if (x == 0) return 0;
    while (y > 0) {
        if ((y & 1) == 1)
            res = (res * x) % p;
        y = y >> 1;
        x = (x * x) % p;
    }
    return res;
}

void pre(){
    int i = 0;
    fact[0] = 1;
    for(i = 1; i < MAX_N; i++){
        fact[i] = fact[i - 1] * i;
        fact[i] %= mod;
    }
    inv_fact[MAX_N - 1] = power(fact[MAX_N - 1], mod - 2, mod);
    for(i = MAX_N - 2; i >= 0; i--){
        inv_fact[i] = inv_fact[i + 1] * (i + 1);
        inv_fact[i] %= mod;
    }
}

long n_choose_k(int n, int r){
    if(n < r)
        return 0;
    long long ans = fact[n];
    ans *= inv_fact[r];
    ans %= mod;
    ans *= inv_fact[n - r];
    ans %= mod;
    return ans;
}
void solve(){
    long long ans = 0;
    int i = 0;
    for(i = n - k; i <= n; i++){
        long long curr = n_choose_k(n - 1, i - 1);
        curr *= m;
        curr %= mod;
        if(m > 1) {
            curr *= power(m - 1, i - 1, mod);
            curr %= mod;
        }
        ans += curr;
        ans %= mod;
    }
    cout << ans;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    pre();
    cin >> n >> m >> k;
    solve();
    return 0;
}

