	vector<ll> ms(n + 1, 1);
	rep(i, n) {
		ms[i + 1] = ms[i] * (m-1);
		ms[i + 1] %= mod;
	}
	Factorial f(n);
	ll sum = 0;
	for (int i = 0; i <= k; i++) {
		auto c = f.cmb(n - 1, i);
		c *= m;
		ll u = n - i - 1;
		c %= mod;
		c *= ms[u];
		c %= mod;
		sum += c;
		sum %= mod;
	}
	cout << sum << endl;
	return 0;
}

