#include <iostream>

using namespace std;

typedef long long ll;

const ll MOD = 998244353;
const int MAXN = 2 * 1e5 + 10;

ll n, m, k;

ll factorial[MAXN] = {0};

ll fact(ll n) {
  if (n == 0) {
    return 1;
  }
  if (factorial[n]) {
    return factorial[n];
  }
  factorial[n] = n * fact(n - 1) % MOD;
  return factorial[n];
}

ll mod_pow(ll n, ll x) {
  ll res = 1;
  while (x > 0) {
    if (x & 1) {
      res = (res * n) % MOD;
    }
    n = (n * n) % MOD;
    x >>= 1;
  }
  return res;
}

ll inv_mod(ll n) {
  return mod_pow(n, MOD - 2);
}

ll nCr(ll n, ll r) {
  return fact(n) * inv_mod(fact(r) * fact(n-r) % MOD) % MOD;
}

void solve() {
  // We can calculate the case when K pairs have same color by using combination as following.
  // There are N-1 pairs, (A1, A2), (A2, A3), ... (AN-1, AN) and we can select K pairs out of it: (N-1) C K
  // After making K pairs, we can think about them as one element which results in N-K elements to color.
  // We have M colors to choose from and above elements has to be colored differently.
  // First element can pick from M colors, then next one can select M - 1 (No the one from first element), then third one has M - 1 options...
  // As a result, we can color all of them in M * (M -1) * (M - 1) * ... * (M - 1) = M * (M-1)^(N-1-K) ways
  // Thus to color K pairs, we have (N-1) C K * M * (M-1)^(N-1-K) ways to do so.
  // What we want is total ways less than or equal to K pairs, so we can just sum them up.

  factorial[0] = 1;
  ll ans = 0;
  for (ll i=0;i<=k;i++) {
    ll tmp = (nCr(n-1, i) * m % MOD) * mod_pow(m-1,n-1-i) % MOD;
    ans = (ans + tmp) % MOD;
  }
  cout << ans << endl;
}

int main() {
  cin >> n >> m >> k;
  solve();
}

