ll mpow(ll x, ll y, ll m = 998244353) {
  ll ret = 1;
  while (y != 0) {
    if (y & 1) ret = (ret * x) % m;
    x = (x * x) % m;
    y = y >> 1;
  }
  return ret;
};

ll minv(ll a, ll m = 998244353) {
  ll b = m, u = 1, v = 0;
  while (b) {
    ll t = a / b;
    a -= t * b;
    swap(a, b);
    u -= t * v;
    swap(u, v);
  }
  u %= m;
  if (u < 0) u += m;
  return u;
}

