ll modex(ll b , ll e , ll m) {
  ll r = 1;
  while (e > 0) {
    if ((e & 1) == 1) {
      r = (r * b) % m;
    }
    e >>= 1;
    b = (b * b) % m;
  }
  return (ll) r;
}

