int fast_pow(int x, int deg)
{
	int ans = 1, y = x;
	while (deg)
	{
		if (deg & 1)
		ans = 1ll * ans * y % mod;

		deg >>= 1;
		y = 1ll * y * y % mod; 
	}

	return ans; 
}

int fact[maxn], inv_fact[maxn];
void precompute()
{
	fact[0] = 1;
	for (int i = 1; i < maxn; i++)
	fact[i] = 1ll * fact[i-1] * i % mod;

	inv_fact[maxn-1] = fast_pow(fact[maxn-1], mod-2);
	for (int i = maxn-2; i >= 0; i--)
	inv_fact[i] = 1ll * inv_fact[i+1] * (i+1) % mod; 
}

int comb(int a, int b)
{
	return 1ll * fact[a] * inv_fact[b] % mod * inv_fact[a-b] % mod; 
}

int add(int a, int b)
{
	a += b;
	if (a >= mod)
	a -= mod;

	return a; 
}

