struct Combination {
  vector<long long> fac, finv, inv;
  const int mod;

  Combination(int MAX, int mod = MOD) : fac(MAX + 1), finv(MAX + 1), inv(MAX + 1), mod(mod) {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i=2; i<=MAX; ++i) {
      fac[i] = fac[i-1] * i % mod;
      inv[i] = mod - inv[mod%i] * (mod/i) % mod;
      finv[i] = finv[i-1] * inv[i] % mod;
    }
  }

  long long P(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * finv[n-r] % mod;
  }

  long long C(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return fac[n] * (finv[r] * finv[n-r] % mod) % mod;
  }

  long long H(int n, int r) const {
    if (n < r || n < 0 || r < 0) return 0;
    return C(n + r - 1, r);
  }
};

void solve() {
  int n, m, k; cin >> n >> m >> k;

  Combination comb(n, MOD2);

  ll ans = 0;

  repeq(i,k) {
    ll tmp = m * modpow(m-1, n - i - 1, MOD2) % MOD2;
    tmp = tmp * comb.C(n-1, i) % MOD2;
    ans += tmp;
  }

  cout << ans % MOD2 << endl;
}


