long long power(long long a, long long b){
	long long ret = 1;
	while(b > 0){
		if(b & 1){
			ret = (ret * a) % MOD;
		}
		a = (a * a) % MOD;
		b >>= 1;
	}
	return ret;
}

void init_nCr(long long n){
	fact[0] = 1;
	for (int i = 0; i < n; i++){
		fact[i + 1] = (fact[i] * (i + 1)) % MOD;
	}
	fact_inv[n] = power(fact[n], MOD - 2);
	for (int i = n - 1; i >= 0; i--){
		fact_inv[i] = (fact_inv[i + 1] * (i + 1)) % MOD;
	}
}

long long nCr(long long n, long long r){
	return (((fact[n] * fact_inv[r]) % MOD) * fact_inv[n - r]) % MOD;
}

long long pow(long long n, long long c){
	long long ret = 1;
	while(n != 0){
		if(n&1){
			ret = ret * c % MOD;
		}
		c = c * c % MOD;
		n /= 2;
	}
	return ret;
}

