int getMathC(int i, int j) {
	int x = 1, tmp = 1, cou = j;

	if (i == 0) return 1;
	if (i == j) return 1;
	if (j == 1) return i;

	for (; cou > 0; cou--, i--) x *= i;
	for (; j > 0; j--) tmp *= j;

