vector<ull> ifac(N_MAX+1);

void init_fac() {
    fac[0] = 1;
    ifac[0] = 1;
    for (int i = 1; i <= N_MAX; i++) {
        fac[i] = fac[i-1] * i % MOD;
        ifac[i] = ifac[i-1] * pow_mod(i, MOD-2) % MOD;
    }
}

ull comb_mod(ull a, ull b) {
    assert(a > 0 && b >= 0 && a >= b);
    ull tmp = ifac[a-b] * ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

