    ll ans = (M * powmod(M - 1, N - 1)) % MOD;
    for (int i = 1; i <= K; i++) {
        ll x = (M * powmod(M - 1, N - 1 - i)) % MOD;
        ans += (x * COM(N - i, i)) % MOD;
        ans %= MOD;
    }

