ll powMod(ll a, ll n) {
    ll ans = 1;
    while (n) {
        if (n&1) ans = ans * a % MOD;
        a = a * a % MOD;
        n >>= 1;
    }
    return ans;
}

ll fac[N], inv[N];

ll C(int n, int m) {
    return fac[n]*inv[m]%MOD*inv[n-m]%MOD;
