const int mod=998244353;

vector<int>getketa(long k){
  vector<int>ret;
  while(k>0){
    ret.push_back(k%2);
    k/=2;
  }
  return ret;
}

long getrev(long k){
  vector<int>modm2 = getketa(mod-2);
  vector<long>powk(32); // k^(2^i)
  powk[0]=k;
  for(int i=1; i<32; i++){
    powk[i]=(powk[i-1]*powk[i-1])%mod;
  }
  long ret = 1;
  for(int i=0; i<modm2.size(); i++){
    if(modm2[i]){
      ret*=powk[i];
      ret%=mod;
    }
  }
  return ret;
}

