        ans_tmp %= MOD;
        ans_tmp *= cb.COM(N-1,i);
        ans_tmp %= MOD;
        ans += ans_tmp;
        ans %= MOD;
    }

    // output
    cout << ans%MOD << endl;

    return 0;
}

