        //よってaの逆元は、-(p/a)*(p%a)^(-1)
        inv[i]=(mod-mod/i)*inv[mod%i];
        inv[i]%=mod;
    }
    fact[0]=1;
    invfact[0]=1;
    for (ll i=1;i<=2000000;++i){
        fact[i]=fact[i-1]*i;
        fact[i]%=mod;
        invfact[i]=invfact[i-1]*inv[i];
        invfact[i]%=mod;
    }
}
ll cmb(ll n, ll r) {
    if(r<0 || r>n) return 0;
    return fact[n]%mod*invfact[r]%mod*invfact[n-r]%mod;
}

