int MOD=998244353;
#define MAX_NCK 201010
ll f[MAX_NCK], rf[MAX_NCK];

// modinvも呼ぶ！！
// (a/b)%P の場合は，(a%P)*modinv(b)%P とする
ll modinv(ll a) {
    ll b = MOD, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;
    return u;
}
bool isinit = false;

void init(void) {
    f[0] = 1;
    rf[0] = modinv(1);
    for(int i = 1; i < MAX_NCK; i++) {
        f[i] = (f[i - 1] * i) % MOD;
        rf[i] = modinv(f[i]);
    }
}

ll nCk(int n, int k) {
    if(!isinit) {
        init();
        isinit = 1;
    }
    ll nl = f[n]; // n!
    ll nkl = rf[n - k]; // (n-k)!
    ll kl = rf[k]; // k!
    ll nkk = (nkl * kl) % MOD;

    return (nl * nkk) % MOD;
}
// xのn乗%modを計算
ll mod_pow(ll x,ll n,ll mod){
    ll res = 1;
    while(n > 0){
        if(n & 1) res = res*x%mod;
        x = x*x%mod;
        n >>= 1;
    }
    return res;
}

struct mint {
    ll x;
    mint(ll _x = 0):x((_x % MOD + MOD) % MOD) {}

    /* 初期化子 */
    mint operator+() const {
    return mint(x);
    }
    mint operator-() const {
    return mint(-x);
    }

    /* 代入演算子 */
    mint& operator+=(const mint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += MOD - a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint& operator/=(const mint a) {
        x *= modinv(a).x;
        return (*this);
    }
    mint& operator%=(const mint a) {
        x %= a.x;
        return (*this);
    }
    mint& operator++() {
        ++x;
        if(x >= MOD) x -= MOD;
        return *this;
    }
    mint& operator--() {
        --x;
        if(x <0) x += MOD;
        return *this;
    }
    mint& operator&=(const mint a) {
        x &= a.x;
        return (*this);
    }
    mint& operator|=(const mint a) {
        x |= a.x;
        return (*this);
    }
    mint& operator^=(const mint a) {
        x ^= a.x;
        return (*this);
    }
    mint& operator<<=(const mint a) {
        x *= pow(2, a).x;
        return (*this);
    }
    mint& operator>>=(const mint a) {
        x /= pow(2, a).x;
        return (*this);
    }

    /* 算術演算子 */
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
    mint operator%(const mint a) const {
        mint res(*this);
        return res%=a;
    }
    mint operator&(const mint a) const {
        mint res(*this);
        return res&=a;
    }
    mint operator|(const mint a) const {
        mint res(*this);
        return res|=a;
    }
    mint operator^(const mint a) const {
        mint res(*this);
        return res^=a;
    }
    mint operator<<(const mint a) const {
        mint res(*this);
        return res<<=a;
    }
    mint operator>>(const mint a) const {
        mint res(*this);
        return res>>=a;
    }

    /* 条件演算子 */
    bool operator==(const mint a) const noexcept {
        return x == a.x;
    }
    bool operator!=(const mint a) const noexcept {
        return x != a.x;
    }
    bool operator<(const mint a) const noexcept {
        return x < a.x;
    }
    bool operator>(const mint a) const noexcept {
        return x > a.x;
    }
    bool operator<=(const mint a) const noexcept {
        return x <= a.x;
    }
    bool operator>=(const mint a) const noexcept {
        return x >= a.x;
    }

    /* ストリーム挿入演算子 */
    friend istream& operator>>(istream& is, mint& m) {
        is >> m.x;
        m.x = (m.x % MOD + MOD) % MOD;
        return is;
    }
    friend ostream& operator<<(ostream& os, const mint& m) {
        os << m.x;
        return os;
    }

    /* その他の関数 */
    mint modinv(mint a) {
        return pow(a, MOD - 2);
    }
    mint pow(mint x, mint n){
        mint res = 1;
        while(n.x > 0){
            if((n%2).x) res *= x;
            x *= x;
            n.x /= 2;
        }
        return res;
    }
};

