	{
		mint cl = m;
		if (n - 1 - i > 0)
		{
			cl *= powMod(m - 1, n - 1 - i);
		}
		ans += cl * nCrMod(n-1, i);
	}
	cout << ans.n << endl;

	return 0;
}

