long long mpow(long long x, long long n) { //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
    long long ans = 1;
    while (n != 0) {
        if (n & 1) ans = ans * x % divs;
        x = x * x % divs;
        n = n >> 1;
    }
    return ans;
}

long long comb(long long a, long long b) { //aCbをmod計算
    if (a == 0 && b == 0)return 1;
    if (a < b || a < 0)return 0;
    long long tmp = ifac[a - b] * ifac[b] % divs;
    return tmp * fac[a] % divs;
}



