long long mod_pow(long long x, long long n, long long mod) {
  long long res = 1;
  while (n > 0) {
    if (n & 1) {
      res = res * x % mod;
    }
    x = x * x % mod;
    n >>= 1;
  }
  return res;
}

struct Combination {
  std::vector<long long> fac, finv, inv;
  int mod;

  Combination(int max_n, int _mod) {
    fac = finv = inv = std::vector<long long>(max_n + 10, 0);
    mod = _mod;
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < max_n + 10; i++) {
      fac[i] = fac[i - 1] * i % mod;
      inv[i] = mod - inv[mod % i] * (mod / i) % mod;
      finv[i] = finv[i - 1] * inv[i] % mod;
    }
  }

  long long mod_comb(int n, int k) {
    if (n < k || n < 0 || k < 0) {
      return 0;
    }
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
  }
};

int main() {
  const int mod = 998244353;
  long long N, M, K;
  std::cin >> N >> M >> K;

  Combination comb(N, mod);

  long long ans = 0;
  for (int k = 0; k <= K; k++) {
    long long a = M * mod_pow(M - 1, N - k - 1, mod) % mod;
    a = (a * comb.mod_comb(N - 1, k)) % mod;
    ans = (ans + a) % mod;
  }
  std::cout << ans << "\n";

  return 0;
}

