long long mpow(long long b, int p) {
    if (p == 0) {
        return 1;
    }

    if (p == 1) {
        return b%MOD;
    }

    long long half = mpow(b, p/2);
    long long ret = half*half%MOD;

    if (p%2 == 1) {
        ret *= b;
        ret %= MOD;
    }

    return ret;
}

