    }
    long long ans = 0;

    PCH pch(N);

    for (int i = 0; i <= K; i++) {
        long long x;
        x = count[N - i];
        x = x * pch.C(N - 1, i) % MOD;
        ans += x;
        ans %= MOD;
    }

    cout << ans << endl;

