  ll ans = x;
  //z = mypow(m - 1, n - k - 2);
  pc(n - 1);
  for(ll i = 1; i <= k; i++){
    y = choose(n - 1, i);
    z = mypow(m - 1, n - i - 1);
    ans = (ans + (m * ((y * z) % mod) % mod)) % mod;
  }
  cout << ans << endl;
  return;
}

