ll fpow(ll a, ll b) {
    ll ret = 1;
    while (b) {
        if (b & 1) {
            ret = (ret * a) % MOD;
        }
        b /= 2;
        a = (a * a) % MOD;
    }
    return ret;
}

const int N = 2e5 + 5;
ll f[N];

void pre(int n) {
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = i * f[i - 1];
        f[i] %= MOD;
    }
}

ll nck(int n, int k) {
    ll ret = f[n];
    ret *= fpow(f[k], MOD - 2); ret %= MOD;
    ret *= fpow(f[n - k], MOD - 2); ret %= MOD;
    return ret;
}

