    ll ans = m;
    ll lol = 0;
    for (int i = 0; i <= k; i++) {
        lol += (nck(n - 1, i) * fpow(m - 1, n - i - 1)) % MOD;
        lol %= MOD;
    }
    ans *= lol;
    ans %= MOD;
    cout << ans << '\n';
    return 0;
}

