#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int MAX = 200002;
const int MOD = 998244353;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit()
{
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++)
  {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
long long COM(int n, int k)
{
  if (n < k)
    return 0;
  if (n < 0 || k < 0)
    return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll mod_pow(ll base, ll pow, ll m = MOD)
{
  if (pow == 0)
    return 1;

  ll res = mod_pow(base, pow / 2);
  res = res * res % m;
  if (pow & 1)
    res *= base;
  return res % m;
}

int main()
{
  ll N, M, K;
  cin >> N >> M >> K;

  COMinit();
  ll ans = 0;
  for (auto k = 0; k <= K; k++)
  {
    ll base = (M * mod_pow(M - 1, N - k - 1)) % MOD;
    ll com = COM(N - 1, k);
    ll a = base * com;
    // printf("a: %lld, k: %lld, base: %lld, com: %lld\n", a, k, base, com);

    a %= MOD;
    ans += a;
    ans %= MOD;
  }

  if (ans < 0)
  {
    cout << ans + MOD << endl;
  }
  else
  {
    cout << ans << endl;
  }

  return 0;
}

