const int N = 2e5 + 5;

int fact[N], invFact[N];

void pre() {
  fact[0] = invFact[0] = 1;
  for (int i = 1; i < N; i++) {
    fact[i] = mul(fact[i - 1], i);
  }
  invFact[N - 1] = inv(fact[N - 1]);
  for (int i = N - 2; i >= 1; i--) {
    invFact[i] = mul(invFact[i + 1], i + 1);
  }
}

int nCr(int n, int r) {
  if (r > n) return 0;
  int ans = fact[n];
  ans = mul(ans, invFact[r]);
  ans = mul(ans, invFact[n - r]);
  return ans;
}

