using namespace std;

constexpr int64_t mod = 998244353;
vector<int64_t> fact, inv;

int64_t power(int64_t n, int64_t k) {
  if (k == 0) return 1;
  int64_t res = power(n * n % mod, k / 2);
  if (k % 2) {
    res = res * n % mod;
  }
  return res;
}

void init(int n) {
  fact.push_back(1);
  inv.push_back(1);
  for (int i = 0; i < n; i++) {
    fact.push_back(fact.at(i) * (i + 1) % mod);
    inv.push_back(power(fact.at(i + 1), mod - 2));
  }
}

int64_t ncr(int64_t n, int64_t r) {
  return fact.at(n) * inv.at(r) % mod * inv.at(n - r) % mod;
}

int main() {
  int n, m, k;
  cin >> n >> m >> k;
  init(n);
  int64_t ans = 0;
  for (int i = 0; i <= k; i++) {
    ans += m * power(m - 1, n - 1 - i) % mod * ncr(n - 1, i) % mod;
    ans %= mod;
  }
  cout << ans << endl;
}

