class Combination {
public:

    int mod;
    vector<long long> fact;
    vector<long long> inv;

    Combination(int n, int mod) : mod(mod) {
        assert(0 < n);
        this->fact.resize(n + 1, 1);
        this->inv.resize(n + 1, 1);

        for (int i = 1; i < fact.size(); ++i) {
            this->fact[i] = (i * this->fact[i - 1]) % this->mod;
            this->inv[i] = modpow(this->fact[i], this->mod - 2, this->mod);
        }
    }

    long long nCr(int n, int k) {
        assert(0 <= n and n < this->fact.size() and 0 <= k);
        assert(n >= k);
        auto a = this->fact[n];
        auto b = (this->inv[k] * this->inv[n - k]) % this->mod;
        return (a * b) % this->mod;
    }

    long long nHr(int n, int k) {
        return nCr(n + k - 1, k);
    }
};

