class Math {
public:
    Math(int N = 0, long long mod = 1e9 + 7)
        : N_(N)
        , mod_(mod)
    {
    }

    long long pow(long long x, long long y)
    {
        ll ans = 1;
        while (y > 0) {
            if (y & 0x1) {
                ans = (ans * x) % mod_;
            }
            x = (x * x) % mod_;
            y >>= 1;
        }
        return ans;
    }

    long long combination(long long n, long long k)
    {
        if (k < 0 || k > n) {
            return 0;
        }
        if (fact_.empty()) {
            build_fact();
        }
        return fact_[n] * (fact_inv_[k] * fact_inv_[n - k] % mod_) % mod_;
    }

    static long long powm(long long x, long long y, long long mod = 1e9 + 7)
    {
        ll ans = 1;
        while (y > 0) {
            if (y & 0x1) {
                ans = (ans * x) % mod;
            }
            x = (x * x) % mod;
            y >>= 1;
        }
        return ans;
    }

private:
    void build_fact()
    {
        if (!fact_.empty()) {
            return;
        }
        fact_.resize(N_ + 1);
        fact_[0] = 1;
        for (ll i = 1; i <= N_; i++) {
            fact_[i] = fact_[i-1] * i % mod_;
        }
        fact_inv_.resize(N_ + 1);
        fact_inv_[N_] = pow(fact_[N_], mod_ - 2);
        for (ll i = N_ - 1; i >= 0; i--) {
            fact_inv_[i] = fact_inv_[i + 1] * (i + 1) % mod_;
        }
    }

    int N_;
    long long mod_;
    vector<long long> fact_;
    vector<long long> fact_inv_;
};

void solve(long long N, long long M, long long K)
{
    Math m(N, MOD);
    ll ans = 0;
    for (ll i = 0; i <= K; i++) {
        ll val = M * m.pow(M - 1, N - i - 1);
        val %= MOD;
        val *= m.combination(N - 1, i);
        val %= MOD;
        ans += val;
        ans %= MOD;
    }
    cout << ans << endl;
}

