				lms_sort.emplace_back(bucket[i]);
			}
		}

		SINT64 ok = 0;						        // 再帰必要性判定
		SINT64 rank = 1;					        // 再帰用文字
		vector<SINT64> next(lms_sort.size(), 1);	// 再帰用文字列

		rrep(i,lms_sort.size()-2,0) {
            SINT64 A = lms_long[lms_sort[i]];
            SINT64 B = lms_long[lms_sort[i+1]];
			if (A == B) {
