ll mypow(ll x, ll y){
  if(x <= 0 || y <= 0) return 1;
  if(y == 1) return x;
  ll z = mypow(x, y / 2) % mod;
  if(y % 2 == 1){
    return ((z * z) % mod) * x % mod;
  }
  else{
    return (z * z) % mod;
  }
}

void pc(ll l){
  for(ll i = l; i >= 1; i--){
    u = (u * i) % mod;
  }
  ll x = 1;
  for(ll i = 1; i <= l; i++){
    x = (x * i) % mod;
    d[i] = mypow(x, mod - 2);
  }
}

ll choose(ll l, ll r){
  return (((u * d[r]) % mod) * d[l - r]) % mod;
}

