  if(k == n - 1){
    std::cout << modpow(m, n) << std::endl;
    return 0;
  }

  u64 ans = 0;
  u64 binom = 1;
  u64 mm = modpow(m-1, n-1);
  const u64 im = modpow(m-1, mod-2);
  inv[1] = 1;
  for(int i = 0; i <= k; i++){
    ans += mm * binom % mod;
    mm = mm * im % mod;
    binom = binom * (n-1-i) % mod * inv[i+1] % mod;
    inv[i+2] = mod - (u64) inv[mod % (i+2)] * (mod / (i+2)) % mod;
  }
  ans %= mod;
  ans = ans * m % mod;
  std::cout << ans << std::endl;
  return 0;
}

