ll power(ll x, ll y)  
{  
    ll res = 1;     // Initialize result  

    x = x % MOD; // Update x if it is more than or  
                // equal to p 

    if (x == 0) return 0; // In case x is divisible by p; 

    while (y > 0)  
    {  
        // If y is odd, multiply x with result  
        if (y & 1)  
            res = (res*x) % MOD;  

        // y must be even now  
        y = y>>1; // y = y/2  
        x = (x*x) % MOD;  
    }  
    return res;  
}  


ll ncr(ll a, ll b)
{
    ll ans = fact[a];
    ans = (ans * inv[b]) % MOD;
    ans = (ans * inv[a - b]) % MOD;
