    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

vector<long long> fac(MAX), finv(MAX), inv(MAX);
void COMinit() {
  fac.at(0) = fac.at(1) = 1;
  finv.at(0) = finv.at(1) = 1;
  inv.at(1) = 1;
  for (int i = 2; i < MAX; i++) {
    fac.at(i) = fac.at(i-1) * i % MOD;
    inv.at(i) = MOD - inv.at(MOD % i) * (MOD / i) % MOD;
    finv.at(i) = finv.at(i-1) * inv.at(i) % MOD;
  }
}
long long COM(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac.at(n) * (finv.at(k) * finv.at(n-k) % MOD) % MOD;
}

int main() {
  long long N, M, K; cin >> N >> M >> K;
  COMinit();
  long long ans = 0;
  for (int i = 0; i <= K; i++) {
    long long tmp = (M * COM(N-1, i) % MOD) * modpow(M-1, N-i-1, MOD) % MOD;
    ans = (ans + tmp) % MOD;
  }
  cout << ans << endl;
}

