lnt inline FACT(const lnt n, const lnt mod = MOD,
                const std::vector<lnt> &vcModFact = vcMODFACT_PREPARED) {
  if (vcModFact.empty()) {
    std::cout << "Warning! The SPECIFY_LISTSIZE_PRIMES function"
              << " has not been called."
