long long powMod(long long x, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

// 階乗・組み合わせのモジュラ逆数
class FactorialMod {
    // モジュラ逆数を求める(modが素数と仮定)
    void ModInv() {
        inv[0] = 0;
        inv[1] = 1;
        for (int i = 2; i <= n; i++) {
            inv[i] = mod - ((mod / i) * inv[mod % i] % mod);
        }
    }

    // n!をmodで割った余り
    void FacInv() {
        fac[0] = facinv[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
            facinv[i] = (facinv[i - 1] * (int)inv[i]) % mod;
        }
    }

  public:
    int n;
    int mod;
    vector<long long> inv;
    vector<long long> fac;
    vector<long long> facinv;

    FactorialMod(int _n, int _mod)
        : n(_n), mod(_mod), inv(vector<long long>(_n + 1)), fac(vector<long long>(_n + 1)),
          facinv(vector<long long>(_n + 1)) {
        ModInv();
        FacInv();
    }

    ll CombiMod(int r, int k) {
        if (r == 0 && k == 0) return 1;
        if (r <= 0 || k < 0 || k > r) return 0;
        if (k == 0) return 1;

        return (((fac[r] * facinv[k]) % mod) * facinv[r - k]) % mod;
    }
};

int main(void) {
    int N, M, K;
    cin >> N >> M >> K;
    FactorialMod fm(N, MOD);
    ll ans = 0;
    rep(k, K + 1) {
        ll val = (M * powMod(M - 1, N - k - 1, MOD)) % MOD;
        (val *= fm.CombiMod(N - 1, k)) %= MOD;
        (ans += val) %= MOD;
    }
    cout << ans << endl;
}

