template <class T>
struct ModInt {
    T x;
    ModInt(T x = 0) : x((x + mod) % mod) {}
    ModInt &operator+=(const ModInt a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt &operator-=(const ModInt a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt &operator*=(const ModInt a) {
        (x *= a.x) %= mod;
        return *this;
    }
    ModInt operator+(const ModInt a) const {
        ModInt res(*this);
        return res += a;
    }
    ModInt operator-(const ModInt a) const {
        ModInt res(*this);
        return res -= a;
    }
    ModInt operator*(const ModInt a) const {
        ModInt res(*this);
        return res *= a;
    }
    ModInt pow(T t) const {
        if (!t) return 1;
        ModInt a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }
    ModInt inv() const {
        return pow(mod - 2);
    }
    ModInt &operator/=(const ModInt a) {
        return (*this) *= a.inv();
    }
    ModInt operator/(const ModInt a) const {
        ModInt res(*this);
        return res /= a;
    }
};
template <class T>
std::ostream &operator<<(std::ostream &os, const ModInt<T> &m) {
    return os << m.x;
}
using mint = ModInt<long long>;

class Comb {
public:
    Comb() : fac(0), finv(0) {}
    Comb(int n) : fac(n + 1), finv(n + 1) {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i)
            fac[i] = fac[i - 1] * i;
        finv[n] = fac[n].inv();
        for (int i = n; i >= 1; --i)
            finv[i - 1] = finv[i] * i;
    }
    void resize(int size) { *this = {size}; }
    mint C(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k]);
    }
    mint P(int n, int k) {
        if (k < 0) return 0;
        return C(n, k) * fac[k];
    }
    // n!
    mint Fac(int n) {
        if (n < 0) return 0;
        return fac[n];
    }
    mint FInv(int n) {
        if (n < 0) return 0;
        return finv[n];
    }

    mint S(int n, int k) {
        mint res = 0;
        for (int i = 0; i <= k; ++i) {
            if ((k - i) % 2 == 0)
                res += C(k, i) * mint(i).pow(n);
            else
                res -= C(k, i) * mint(i).pow(n);
        }
        return res;
    }

private:
    std::vector<mint> fac;
    std::vector<mint> finv;
};

void solve() {
    int n, m, k;
    cin >> n >> m >> k;

    mod = 998244353;
    Comb com(n + 2);
    mint ans = 0;
    loops(i, n - k, n) {
        ans += com.C(n - 1, i - 1) * m * mint(m - 1).pow(i - 1);
    }

    cout << ans << endl;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
    cout.flush();
    return 0;
}

