    else
    { 
        // m is added to handle negative x 
        res = (x%m + m) % m; 
    } 
    return res;
}  
long long binpow(long long a, long long b) {
    a %= m;
    long long res = 1;
    while (b > 0) {
        if (b & 1)
            res = res * a % m;
        a = a * a % m;
        b >>= 1;
    }
    return res;
}
