        cur *= mpow(m - 1, i);
        cur %= MOD;
        cur *= mpow(m - 1, n - 1 - i);
        cur %= MOD;
        cur *= m;
        cur %= MOD;
        ans += cur;
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

