const int MAX = 2e5+100;
mint fac[MAX], inv[MAX];

void comb_init() {
  fac[0] = fac[1] = 1;
  inv[0] = inv[1] = 1;
  for (int i = 2; i < MAX; ++i){
    fac[i] = fac[i - 1] * i;
    inv[i] = inv[i-1] / i;
  }
}

mint comb(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * inv[k] * inv[n - k];
}

