void factorial_init(ll n)
{
	fac.resize(n+1);
	ifac.resize(n+1);
	fac[0] = 1;
	ifac[0] = 1;
	REP(i,n) {
		fac[i+1] = fac[i] * (i + 1) % MOD;
		ifac[i+1] = ifac[i] * mypow(i + 1, MOD - 2) % MOD;
	}
}

ll Combination(ll a, ll b)
{
	if(a == 0 && b == 0) return 1;
	if(a < b || a < 0) return 0;
	ll r = ifac[a-b] * ifac[b] % MOD;
	return r * fac[a] % MOD;
}

