vector<ll> inv;   // k!^{M-2} (mod M)
////////////////////////////////////////////////
void fac_mod(int size) {
  // fac[i] = i! (mod M)
  fac[0] = 1;
  fac[1] = 1;
  REP(i, size) { fac[i + 1] = fac[i] * (i + 1) % MOD; }
}
////////////////////////////////////////////////
void ifac_mod(int size) {
  // ifac[i] = 1/i! (mod M)
  ifac[0] = 1;
  ifac[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < size; i++) {
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    ifac[i] = ifac[i - 1] * inv[i] % MOD;
  }
}
////////////////////////////////////////////////
ll nCk_mod(ll n, ll k) {
  // nCk (mod M)
  if (n == 0 && k == 0) return 1;
  if (n < k || k < 0) return 0;
  return fac[n] * (ifac[n - k] * ifac[k] % MOD) % MOD;
}
////////////////////////////////////////////////
ll pow_mod(ll x, int n) {
  // x^n (mod M)
  ll pow = 1;
  while (n != 0) {
    if (n & 1) pow = pow * x % MOD;
    x = x * x % MOD;
    n = n >> 1;
  }
  return pow;
}
////////////////////////////////////////////////
