struct nCr{
  vector<lli> f, rf;
  lli count=0;
  nCr(lli num): f(num), rf(num){
      count = num;
      f[0] = 1;
      rep1(i, num) f[i] = (f[i - 1] * i) % MOD;
      rep0(i, num+1) rf[i] = inv(f[i]);
  }

  lli inv(lli x) {
      lli res = 1;
      lli k = MOD - 2;
      lli y = x;
      while (k) {
          if (k & 1) res = (res * y) % MOD;
          y = (y * y) % MOD;
          k /= 2;
      }
      return res;
  }
  lli C(lli n, lli k) {
      if(k > n || k<0)return 0;
      lli a = f[n];
      lli b = rf[n-k];
      lli c = rf[k];

      lli bc = (b * c) % MOD;
      return (a * bc) % MOD;
  }
};
int main(){
  lli n, m, k;
  cin >> n >> m >> k;
  nCr c(2000001);
  lli ans=0, tp=1;
  rep0(i,n){
    ans+=(c.C(n-1,i)*tp)%MOD;
    ans%=MOD;
    tp*=m-1;
    tp%=MOD;
  }
  tp=1;
  rep0(i,n-k-1){
    ans-=(c.C(n-1,i)*tp)%MOD;
    ans%=MOD;
    ans+=MOD;
    ans%=MOD;
    tp*=m-1;
    tp%=MOD;
  }

  if(n==1)cout << m;
  cout << (m*ans)%MOD;
}

