/*
  nCkを求める
  MOD(1000000007LL)で割った余りを算出
  */
ll C(int n, int k) {
  ll ret=1;
  int i;
  int a, b;

  a = k;
  b = n-k;
  if (a<b) swap(a,b);

  for (i=n; i>a; i--) {
    ret *= i;
    ret %= MOD;
  }
  for (i=2; i<=b; i++) {
    ret *= modinv(i, MOD);
    ret %= MOD;
  }
//printf("C(%d, %d)\n", n, k);
  return ret;
}


