//最大公約数 ユークリッド互除法
int gcd(int m, int n) {
  if (m<n) swap(m, n);
  while (m%n) {
    m%=n;
    swap(m, n);
  }
  return n;
}
//最大公約数 拡張ユークリッド互除法
int xgcd(int a, int b, int &x0, int &y0) {
  x0=1, y0=0;
  int x1=0, y1=1;
  int q;
  int at, x0t, y0t;
  while (b != 0) {
    q = a/b;
    at = b;
    b = a%b;
    a = at;
    x0t = x1;
    x1 = x0-q*x1;
    x0 = x0t;
    y0t = y1;
    y1 = y0-q*y1;
    y0 = y0t;
  }
  return a;
}
ll xgcd(ll a, ll b, ll &x0, ll &y0) {
  x0=1, y0=0;
  ll x1=0, y1=1;
  ll q;
  ll at, x0t, y0t;
  while (b != 0) {
    q = a/b;
    at = b;
    b = a%b;
    a = at;
    x0t = x1;
    x1 = x0-q*x1;
    x0 = x0t;
    y0t = y1;
    y1 = y0-q*y1;
    y0 = y0t;
  }
  return a;
}
//モジュラー逆数
//((ab mod n)(b^-1 mod n)) mod n = a mod n となる aを求めるのに使う
//ab mod n と b mod nがわかっているときに a mod n を算出するため
//modInverseは実績ありmodinvは不明
int modinv(int a, int m) {
  int g, x, y;
  g = xgcd(a, m, x, y);
  if (g != 1) return -1;
  x %= m;
  if (x<0) x+=m;
  return x;
}
ll modinv(ll a, ll m) {
  ll g, x, y;
  g = xgcd(a, m, x, y);
  if (g != 1) return -1;
  x %= m;
  if (x<0) x+=m;
  return x;
}
ll power(ll x, ll y, ll p) {
  ll res = 1;
  x=x%p;
  while (y>0) {
    if (y&1) res = (res*x)%p;
    y = y>>1;
    x = (x*x) %p;
  }
  return res;
}
ll modInverse(ll a, ll m) {
  ll ans = power(a, m-2, m);
  return ans;
}

