    }
  }
  if (n != 1) ret[n] = 1;
  return ret;
}

ll modpow(ll base, ll exp, ll mod) {
  base %= mod;
  ll result = 1;
  while (exp > 0) {
    if (exp & 1) result = (result * base) % mod;
    base = (base * base) % mod;
    exp >>= 1;
  }
  return result;
}

// get {1, 1, 2, 6, ..., fact(n)}, size = n + 1
vector<ll> factvec(ll n, ll mod) {
  vector<ll> v(n + 1);
  v[0] = 1;
  fr(i, 1, n + 1) { v[i] = (i * v[i - 1]) % mod; }
  return v;
}

ll nPkMod(ll n, ll k, ll mod, const vector<ll> &factvec) {
  ll tmp = 1;
  tmp = (tmp * factvec[n]) % mod;
  tmp = (tmp * invmod(factvec[n - k], mod)) % mod;
  return tmp;
}

ll nCkMod(ll n, ll k, ll mod, const vector<ll> &factvec) {
  ll tmp = nPkMod(n, k, mod, factvec);
  return (tmp * invmod(factvec[k], mod)) % mod;
}

unordered_map<ll, ll> cx;

ll cache(ll m, ll nn) {
  ll MOD = (ll)998244353;
  if (cx.count(nn) > 0) return cx[nn] % MOD;
  if (nn <= 1) return m % MOD;
  ll base = m;

  cx[nn] = cache(m, nn - 1) * (m - 1) % MOD;
  return cx[nn];
}

