const int mod = 998244353;
const int N = 2e5+23;

int n, m, k;
long long dp[N];

int rek(int pos) {
  if (pos == 0) return 1;
  long long &ret = dp[pos];
  if (ret != -1) return ret;
  ret = 0;
  for (int i = 1; i <= k; ++i) {
    if (pos - i < 0) break;
    ret = (ret + rek(pos-i)) % mod;
  }
  if (pos == n) {
    return ret = ret * m % mod;
  } else {
    return ret = ret * (m-1) % mod;
  }
}

void solve() {
  scanf("%d%d%d", &n, &m, &k); ++k;
  long long cur = 1;
  dp[0] = 1;
  for (int i = 1; i <= n; ++i) {
    dp[i] = cur;    
    if (i == n) {
      dp[i] = dp[i] * m % mod;
    } else {
      dp[i] = dp[i] * (m-1) % mod;
    }
    cur = (cur + dp[i]) % mod;
