    vector<vector<ll>> dp(k + 1, vector<ll>(n + 1));
    dp[0][1] = m;
    for (int i = 0; i <= k; i++)
    {
        for (int j = 1; j < n + 1; j++)
        {
            if (i == 0 && j == 1)
            {
                continue;
            }
            if (i == 0)
            {
                dp[i][j] = dp[i][j - 1] * (m - 1);
                dp[i][j] %= MOD;
