long long power(long long x, long long y, long long p) {
  long long res = 1;
  x = x % p;

  if (y == 0 || x == 1) return 1;
  if (x == 0) return 0;

  while (y > 0) {  
    if (y & 1) {
      res = (res*x) % p;  
    }
    y = y>>1;
    x = (x*x) % p;  
  }  

  return res;  
}

long long C(long long n, long long r) {
  if (!r) return 1;
  return (fac[n] * ( power( (fac[r]*fac[n-r]), MOD-2, MOD) ) ) %MOD;
}

