	ll up=1,down=1;
	for(ll i=0;i<m;i++){
		up=up*(n-i)%mod;
		down=down*(i+1)%mod;
	}
	return up*inv(down)%mod;
}
ll quickp(ll a,ll n){
	a%=mod;
	ll ans=1;
	while(n){
		if(n&1) ans=(ans*a)%mod;
		a=(a*a)%mod;
		n>>=1;
	}
	return ans;
}
