int N_MAX=200001;
int p=998244353;
int log2_p_MAX=32;
typedef long long ll;
ll felmer(ll a)
{
  // a^(2^i) mod p
  ll rem[log2_p_MAX];
  rem[0] = a%p;
  for(int i=1;i<log2_p_MAX;i++)
    rem[i] = (rem[i-1]*rem[i-1])%p;
  ll res = 1;
  ll expo = p-2;
  for(int i=0;i<log2_p_MAX;i++){
	if(expo%2==1){
      res *= rem[i];
      res = res%p;
    }
  	expo /= 2;
  }
  return res;
}
int main()
{
  ll n,m,k,i,res=0;
  ll com[N_MAX],col[N_MAX];
  cin >> n >> m >> k;
  com[0]=1;
  col[1]=m;
  for(i=1;i<n;i++){
    com[i]=(com[i-1]*(n-i))%p;
    com[i]*=felmer(i);
    com[i]%=p;
    col[i+1]=(col[i]*(m-1))%p;
  }
  for(i=0;i<=k;i++){
    res+=com[i]*col[n-i];
    res%=p;
  }
  cout << res << endl;
  return 0;
}

