template <typename T>
constexpr T pow(T a, int n) {
	T ret = 1;
	while(n != 0) {
		if(n % 2) {
			ret *= a;
		}
		a *= a;
		n /= 2;
	}
	return ret;
}

int main() {
	int n, m, k;
	cin >> n >> m >> k;
	auto comb = new mod_comb();
	ModInt result = 0;
	RANGE(i, n - k - 1, n) {
		ModInt shikiri = (*comb)(static_cast<ll>(n - 1), static_cast<ll>(i));
		ModInt iro = m * pow(ModInt(m - 1), i);
		result += shikiri * iro;
	}
	cout << result << endl;
	return 0;
}

