	long long N, M, K;
	scanf("%lld %lld %lld", &N, &M, &K);

	long long result = 0;
	for (int i = 0; i <= K; i++)
	{
		// M *(N - 1Ci * (M - 1) ^ (M - 1 - i))
		long long tmp = (comb_mod(N - 1, i) * pow_mod(M - 1, M - 1 - i)) % MODNUMBER;
		// cout << "i=" << i << "tmp=" << tmp << "\n";
		result = (result + tmp) % MODNUMBER;
	}

	cout << ((result * M) % MODNUMBER);

	return 0;
}

