	Polynomial q(1); q.set(0, m - 1); q.set(1, 1);
	q ^= n - 1;
	p *= q;
	i64 ans = 0;
	REP(i, k + 1) (ans += p[i]) %= MOD;
	OUT(ans)BR;

	return 0;
}

