template <class T> vector<T> Factorial(int n) {
	vector<T> f(n + 1, 1);
	for (int i = 2; i <= n; ++i) f[i] = f[i - 1] * i;
	return f;
}

template <class T> pair<vector<T>, vector<T>> InvFactorial(int n) {
	auto p = make_pair(Factorial<T>(n), vector<T>(n + 1, 1));
	p.second[n] = 1 / p.first[n];
	while (n--) p.second[n] = (n + 1) * p.second[n + 1];
	return p;
}



