    }
};

mint fac[MAX], facinv[MAX], inv[MAX];
void minit(){
    fac[0] = fac[1] = 1;
    facinv[0] = facinv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i;
        inv[i] = -mint(mod / i)*inv[mod % i];
        facinv[i] = facinv[i - 1] * inv[i];
    }   
}
mint mcomb(mint a, mint b){
    if (a.x < b.x) return 0;
    if (a.x < 0 || b.x < 0) return 0;
    return fac[a.x] * facinv[b.x] * facinv[a.x - b.x];
}
mint mperm(mint a, mint b){
    if (a.x < b.x) return 0;
    if (a.x < 0 || b.x < 0) return 0;
    return fac[a.x] * facinv[a.x - b.x];
}

