const lint MAX = 500000;
//const int MOD = 1000000007;

lint fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (lint i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

// 二項係数計算
lint COM(lint n, lint k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


int main() {
	COMinit();
	lint N, M, K;
	cin >> N >> M >> K;
	lint ans = 0;
	for (lint i = N - 1 - K; i <= N - 1; i++) {
		ans += COM(N-1, i) * M%MOD * power(M - 1, i, MOD);
		ans %= MOD;
		//cout << '!';
	}
	cout << ans << endl;
}

