ll mypow(ll x, ll y){
  if(x <= 0 || y <= 0) return 1;
  if(y == 1) return x;
  ll z = mypow(x, y / 2) % mod;
  if(y % 2 == 1){
    return ((z * z) % mod) * x % mod;
  }
  else{
    return (z * z) % mod;
  }
}

ll mypow2(ll x, ll y){
  if(y == 1) return x;
  ll z = mypow(x, y / 2) % mod;
  if(y % 2 == 1){
    return ((z * z) % mod) * x % mod;
  }
  else{
    return (z * z) % mod;
  }
}

void pc(ll l){
  for(ll i = l; i >= 1; i--){
    u = (u * i) % mod;
  }
  d[0] = 1;
  for(ll i = 1; i <= l; i++){
    d[i] = (d[i - 1] * i) % mod;
  }
}

ll choose(ll l, ll r){
  return u * mypow((d[l - r] * d[r]) % mod, mod - 2) % mod;
}

ll choose2(ll l, ll r){
  ll u = 1, d = 1;
  for(ll i = l; i > l - r; i--){
    u = (u * i) % mod;
  }
  for(ll i = 1; i <= r; i++){
    d = (d * i) % mod;
  }
  d = mypow(d, mod - 2);
  return (u * d) % mod;
}

