  for(long long i=x;i>=(x-y+1);i--){
    X*=i;
    X%=z;
  }
  for(long long i=1;i<=y;i++){
    Y*=i;
    Y%=z;
  }
  Y=modpow(Y,z-2,z);
  X*=Y;
  X%=z;
  return X;
}

