    ll prev = -1;
    ll flag = 0;
    for(char x: s){
        if(x == 'B'){
            if(c > 0){
                if(prev == -1)
                    prev = c;
                if(prev!=c)
                    return 0;
            }
            c = 0;
            flag = 0;
        }
        else if( x == '.'){
            c ++;
        }
        else{
            c++;
            if(flag == 1)
                return 0;
            flag = 1;
        }
    }
    if(c > 0){
        if(prev == -1)
            prev = c;
        if(prev!=c)
            return 0;
    }
    return 1;
}

