// a x + b y = gcd(a, b)
ll extgcd(ll a, ll b, ll &x, ll &y) {
  ll g = a; x = 1; y = 0;
  if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
  return g;
}

// 1/a mod m
ll mod_inverse(ll a){
  ll x, y;
  extgcd(a, MOD, x, y);
  return (MOD + x % MOD) % MOD;
}

int fcomb(int n, int k){
  ll l = 1, c = 1, ans;
  if(n < k) return 0;
  if(n - k < k) k = n - k;
  ans = facts[n];
  ans = ans * mod_inverse(facts[k]) % MOD;
  ans = ans * mod_inverse(facts[n - k]) % MOD;
  return (int)ans;
}

//modを引数にとるバージョン

//n**p % m
int _powMod(int n, int p, int m){
  ll ans = 1, ln = n;
  if(p <= 0) return 1;
  while(p != 0){
	if((p & 1) == 1) ans = (ans*ln) % m;
	ln = (ln * ln) % m;
	p = p >> 1;
  }
  return (int)ans;
}

// 隣り合うブロックの組で、色が違うのがK組
ll getDiffK(ll n, ll m, ll k) {
  ll tmp = fcomb(n - 1, k);
  ll colors = m * _powMod(m - 1, k, MOD) % MOD;

  // printf("getDiffK(%lld, %lld, %lld) = %lld, tmp = %lld, colors = %lld\n", n, m, k, (tmp * colors) % MOD, tmp, colors);
  return (tmp * colors) % MOD;
}

