void solve(ostringstream& aout, long long N, long long M, long long K){
	if (N == 1) {
		cout << M << "\n";
		return;
	}


	mint ans = 0;

	for (int k = 0; k <= K; k++) {
		// k 組同じ色に塗られている
		int mergedBlocks = N - k;

		// 境目の選び方
		mint cnt = binom(N - 1, k);

		// N-k 個のブロックを、隣り合うブロックが同じ色にならないように塗り分ける
		mint add = mint(M) * mint(M - 1).pow(mergedBlocks - 1) * cnt;
		ans += add;
	}

	cout << ans << "\n";
}

