static const long long MAX = 200001;
long long fact[MAX], fact_inv[MAX], inv[MAX];

// 繰り返し二乗法を用いて a の n 乗を算出する(ただし mod m の空間内)
long long modpow(long long a, long long n, long long mod)
{
    long long ret = 1;
    while (n > 0)
    {
        if (n & 1)
        {
            ret *= a;
            ret = ret % mod;
        }
        a *= a;
        a = a % mod;
        n = (n >> 1);
    }
    return ret;
}

void InitmodnCk(long long mod)
{
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    inv[0] = inv[1] = 1;
    for (long long i = 2; i < MAX; ++i)
    {
        fact[i] = fact[i - 1] * i % mod;
        inv[i] = (mod - inv[mod % i] * (mod / i) )% mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }
}

long long modnCk(long long n, long long k, long long mod)
{
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    long long ret = fact[n] * (fact_inv[k] * fact_inv[n - k] % mod) % mod;
    if (ret < 0) ret = (ret + mod) % mod;
    return ret;
}

int main()
{
    long long N, M, K;
    cin >> N >> M >> K;
    static const long long mod =  998244353;
    InitmodnCk(mod);
    long long ans = 0;
    for (long long i = 0; i <= K; ++i)
    {
        long long col = (M * modpow(M - 1, N - i - 1, mod)) % mod;
        if (col < 0) col = (col + mod) % mod;
        long long comb = modnCk(N - 1, i, mod);
        ans += (col * comb) % mod;
        ans = ans % mod;
        if (ans < 0) ans = (ans + mod) % mod;
    }
    cout << ans << endl;
    return 0;
}

