int bpow(int n, int k) {
  int res = 1;
  for (; k > 0; k >>= 1) {
    if (k & 1) {
      res = mul(res, n);
    }
    n = mul(n, n);
  }
  return res;
}

int cnk(int n, int k) {
  return mul(mul(f[n], revf[k]), revf[n - k]);
}


