  forab(i, 1, n - 1) {
    cnt[i] = mul(cnt[0], cnk(n - 1, i));
    cnt[i] = mul(cnt[i], bpow(bpow(m - 1, i), MOD - 2));
  }

  int ans = 0;
  forab(i, 0, k) {
