class FermatCombination {
public:
    vector<ll> factrial;
    vector<ll> inverse;
    ll MOD;

    FermatCombination(ll size, ll mod) {
        factrial = vector<ll>(size+1, 0);
        inverse = vector<ll>(size+1, 0);

        MOD = mod;
        factrial[0] = 1;
        inverse[0] = 1;

        for(int i = 1; i <= size; i++) {
            factrial[i] = (factrial[i - 1] * i) % MOD;
            inverse[i] = (ll)modpow(factrial[i], MOD - 2) % MOD;
        }
    }

    ll modpow(ll x, ll n) {
        ll ans = 1;
        while(n > 0) {
            if((n & 1) == 1) {
                ans = ans * x % MOD;
            }
            x = x * x % MOD;
            n >>= 1;
        }
        return ans;
    }

    long long combine(int n, int k) {
        return factrial[n] * inverse[k] % MOD * inverse[n - k] % MOD;
    }
};

int main() {
    ll n, m, k;
    cin >> n >> m >> k;
    FermatCombination fermat = FermatCombination(n+5, MOD);
    ll ans = 0;
    ll colors = m;
    for(int i = 0; i < n; i++) {
        if (n-i-1 <= k) {
            ans += (colors * fermat.combine(n-1, n-i-1)) % MOD;
            ans %= MOD;
        }
        colors *= (m-1);
        colors %= MOD;
    }

    cout << ans << endl;
}

