using namespace std;

const long long MOD = 998244353;

long long combinationFrom(long long lastColor, long long curr, long long allowance, long long N, long long M
    , vector<vector<long long> >& memoSame, vector<vector<long long> >& memoOther) {
    if (curr == N) {
        return 0LL;
    }
    if (curr == N - 1) {
        long long temp = 0LL;
        for (long long m = 0; m < M; ++m) {
            if (m == lastColor) {
                if (allowance > 0) {
                    temp += 1LL;
                }
            }
            else {
                temp += 1LL;
            }
        }
        return temp;
    }

    if (memoSame[curr][allowance] >= 0) {
        return (memoSame[curr][allowance] + memoOther[curr][allowance]) % MOD;
    }
    long long retSame = 0LL;
    long long retOther = 0LL;
    for (long long m = 0; m < M; ++m) {
        if (m == lastColor) {
            if (allowance > 0) {
                retSame += combinationFrom(m, curr + 1, allowance - 1, N, M, memoSame, memoOther);
                retSame %= MOD;
            }
        }
        else {
            retOther += combinationFrom(m, curr + 1, allowance, N, M, memoSame, memoOther);
            retOther %= MOD;
        }
    }
    memoSame[curr][allowance] = retSame;
    memoOther[curr][allowance] = retOther;

    return (retSame + retOther) % MOD;
}

void Main() {
    long long N, M, K;
    cin >> N >> M >> K;

    vector<vector<long long> > memoSame(N, vector<long long>(K + 1, -1LL));
    vector<vector<long long> > memoOther(N, vector<long long>(K + 1, -1LL));
    long long ans = combinationFrom(-1, 0LL, K, N, M, memoSame, memoOther);
    cout << ans << endl;
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

