int rek(int pos, int cnt) {
  if (pos == n) return 1;
  if (pos > n) return 0;
  bool ok = cnt < k;
  int &ret = dp[pos][ok];
  if (ret != -1) return ret;
  ret = 1LL * (m-1) * rek(pos+1, 1) % mod;
  if (ok) {
