const ll mod = 998244353;
const ll sz = 5e5;

ll fact[sz];

ll bpow(ll x, ll p) {
	if (p == 0)
		return 1;
	if (p % 2)
		return (bpow(x, p - 1) * x) % mod;
	else {
		ll b = bpow(x, p / 2);
		return (b * b) % mod;
	}
}

ll inv(ll a) {
	return bpow(a, mod - 2);
}

ll cnk(ll n, ll k) {
	return fact[n] * inv(fact[n - k]) % mod * inv(fact[k]) % mod;
}

inline void solve() {
	ll n, m, k;
