template <class T>
T pow_(T power, int n, int MOD){ //power^n % MOD
  if(n == 0){ return 1; }
  if(n == 1){ return power; }
  T Ans = 1;
  T Tmp = pow_(power, n/2, MOD);
  Ans = (Tmp * Tmp) % MOD;
  if((n % 2) == 1){
    Ans = (Ans * power) % MOD;
  }
  return Ans;
}

template <class T>
T nCk(int n, int k, int MOD){
  T Ans = 1;
  int r = (k < n-k)? k: n-k;
  for(int i = 0; i < r; i++){
    Ans = (Ans * (ll)(n-i) / (i+1)) % MOD;
  }
  return Ans;
}

