long long C(long long x, long long y){
    if (x<y) return 0;
    if (x<Mod && y<Mod) return fac[x] * inv[y] % Mod * inv[x - y] % Mod;
    return C(x / Mod, y / Mod) * C(x % Mod, y % Mod) % Mod;
}

