ll fact[N];

ll binpow(ll x, ll p) {
    ll res = 1;
    while (p) {
        if (p & 1) res = res * x % M;
        x = x * x % M;
        p >>= 1;
    }
    return res;
}

ll comb(ll n, ll k) {
    ll res = fact[n] * binpow(fact[k], M - 2) % M;
    res = res * binpow(fact[n - k], M - 2) % M;
    return res;
}

