ll pw(ll base, int ex) {
    if (ex == 0)
    {
        return 1;
    }
    else if (ex & 1)
    {
        return pw(base, ex - 1) * base %MOD;
    }
    else
    {
        ll res = pw(base, ex / 2);
        return res * res %MOD;
    }
}

