  return (a * (ll) b) % mod;
}

inline int pw(int x, int n) {
  int res = 1;
  while (n > 0) {
    if (n % 2) {
      res = mul(res, x);
      n--;
    } else {
      x = mul(x, x);
      n /= 2;
    }
  }
  return res;
}

inline int inv(int x) {
  return pw(x, mod - 2);
}

