const int mod = 998244353;

const int mex = 2e5 + 1;
int fact[mex+5], inv[mex+5];  

int toPower(int a, int p){
    int res = 1;
    while (p){
        if (p & 1) res = ll(res) * a % mod;
        p >>= 1; a = ll(a) * a % mod;
    }
    return res;
}

int Inv(int x){ 
    return toPower(x, mod - 2); 
}

int add(int a, int b) {
    a %= mod; b %= mod;
    return ((a + b) % mod);
}

int sub(int a, int b) {
    a %= mod; b %= mod;
    return  ((a - b + mod) % mod);
}

int mul(int a, int b) {
    a %= mod; b %= mod;
    return ((a * b) % mod);
}

void initialize(){
    inv[0] = Inv(fact[0]);fact[0] = inv[0] = 1;

    for(int i = 1; i <= mex; i++){
        fact[i] = (ll(i) * fact[i - 1]) % mod;
        inv[i] = Inv(fact[i]);
    }
}

int C(int n, int k){
    if (n < 0 || k < 0 || k > n) return 0;
    return ll(fact[n]) * inv[k] % mod * inv[n - k] % mod;                   
}

void solve() {
  initialize();
  int n, m, k;
  cin >> n >> m >> k;
  if(m == 1 && k < n-1) {
    cout << "0\n"; return;
  }
  int ex = m;
  for(int i = 1; i < n; i++) {
    ex = mul(ex, m-1);
  }
  int res = 0;
  for(int i = k+1; i <= n; i++) {
    int temp = C(n-1, i);
    temp = mul(temp, ex);
    temp = mul(temp, Inv(toPower(m-1, i)));
    res = add(res, temp);
  }
  int ans = toPower(m, n);
  ans = sub(ans, res);
  cout << ans << '\n';
}

