template <class T, class U>
constexpr T binpow(T a, U b) {
  T res(1);
  while (b > 0) {
    if (b % 2) res = res * a;
    a = a * a;
    b /= 2;
  }
  return res;
}

template <unsigned int Mod = 1000000007, class T = long long int>
