void init(int n)  //预处理 阶乘 及 逆元(p为质数) O(n)
{
    jc[0] = jc[1] = 1;
    for (int i = 2; i <= n; ++i) {
        jc[i] = (LL)jc[i - 1] * i % p;
    }
}
LL C(LL a, LL b)  //组合数（p为质数）
{
    if (b > a)
        return 0;
    return (LL)jc[a] * fpow(jc[b], p - 2, p) % p * fpow(jc[a - b], p - 2, p) % p;
}
