int modPow(ll a, ll n, ll p) { //繰り返し二乗法 a**n % p
  if (n == 1) return a % p;
  if (n % 2 == 1) return (a * modPow(a, n - 1, p)) % p;
  ll t = modPow(a, n / 2, p);
  return (t * t) % p;
}
ll choose(ll n, ll k){
  if(k < 1) return 1;
  ll num = 1;
  ll waru = 1;
  for(ll i = 0; i < k; i++){
    num *= n - i;
    waru *= i + 1;
    num %= mod;
    waru %= mod;
  }
  waru = modPow(waru, mod - 2, mod);
  return num * waru % mod;
}
