template<int mod>
struct modulo {
	int w;
	operator int&() { return w; }

	modulo() {}
	modulo(int w) { this->w = w; }
	void inline fix() { w %= mod; if (w < 0) w += mod; }
	modulo inline fix(int w) const { w %= mod; if (w < 0) w += mod; return w; }

	modulo inline operator + (const modulo &b) { modulo r = *this; r += b; return r; }
	modulo& operator += (const modulo &b) { if ((w += b.w) >= mod) w -= mod; return *this; }

	modulo inline operator - (const modulo &b) { modulo r = *this; r -= b; return r; }
	modulo& operator -= (const modulo &b) { if ((w -= b.w) < 0) w += mod; return *this; }

	modulo inline operator * (const modulo &b) { modulo r = *this; r *= b; return r; }
	modulo& operator *= (const modulo &b) { w = (num) w * b.w % mod, fix(); return *this; }

	modulo inline operator / (const modulo &b) { modulo r = *this; r /= b; return r; }
	modulo& operator /= (const modulo &b) { *this *= b.inv(); return *this; }

	modulo inline inv() const {
		int a = w, m = mod, u = 0, v = 1, t;
		for (; a != 0; t = m / a, m -= t * a, swap(a, m), u -= t * v, swap(u, v));
		return fix(u);
	}

	modulo inline pow(int p) const {
		if (!w)  return 0;
		modulo a = *this, res = 1;
		for (; p > 0; a *= a, p >>= 1) if (p & 1)  res *= a;
		return res;
	}
};

