ll qp(ll a,ll b){
    ll ans=1%mod;
    a%=mod;
    while(b){
        if(b&1){
            ans=(ans*a)%mod;
        }
        a=a*a%mod;
        b>>=1;
    }
    return ans;
}

void solve(ll n,ll m,ll k){
    prepare(n);
    for(ll i=n-k;i<=n;++i){
        ll tmp=(fa[n-1]/(fa[n-i]*fa[i-1]))%mod;
        ans=(ans+(tmp*m*qp(m-1,i-1)))%mod;
    }
}

