  }
}

ll choose(ll l, ll r){
  ll u = 1, d = 1;
  for(ll i = l; i > l - r; i--){
    u = (u * i) % mod;
  }
  for(ll i = 1; i <= r; i++){
    d = (d * i) % mod;
  }
  d = mypow(d, mod - 2);
  return (u * d) % mod;
}

