void calc_fact()
{
    for(int i = 1; i <= maxN; i++)
    {
        fact[i] = fact[i - 1] * i;
        fact[i] %= MOD;
    }
}

ll C(ll n, ll r)
{
    if(n == 0)
    {
        return 0;
    }
    if(n == r || r == 0)
    {
        return 1;
    }
    if(mp[{n, r}])
    {
        return mp[{n, r}];
    }

    ll x, y;

    if(mp[{n - 1, r - 1}])
    {
        x = mp[{n - 1, r - 1}];
    }
    else {
        x = C(n - 1, r - 1);
        if(x >= MOD)
            x %= MOD;
        mp[{n - 1, r - 1}] = x;
    }

    if(mp[{n - 1, r}])
    {
        y = mp[{n - 1, r}];
    }
    else {
        y = C(n - 1, r);
        if(y >= MOD)
            y %= MOD;
        mp[{n - 1, r}] = y;
    }

    ll ret = mp[{n, r}] = x + y;

    if(ret >= MOD)
        ret %= MOD;

    return ret;
}

ll power(ll X, ll N)
{
    ll res = 1;

    while(N > 0)
    {
        if(N & 1)
        {
            res *= X;
            if (res >= MOD)
                res %= MOD;
        }

        X = X * X;
        if(X >= MOD)
            X %= MOD;

        N = N >> 1;
    }

    return res;
}

ll c(ll n, ll r)
{
    ll num = fact[n];
    ll den = fact[n - r] * fact[r];
    den %= MOD;

    den = power(den, MOD - 2);

    return (num * den) % MOD;
}

ll calc(ll N, ll M, ll K)
{
    ll ans = 1;
    ans *= M;

    ans *= power(M - 1, N - K - 1);
    if(ans >= MOD)
        ans %= MOD;

    ans *= c(N - 1, K);

    if(ans >= MOD)\
        ans %= MOD;

    return ans;

}

void solve()
{
    ll N, M, K;
    cin >> N >> M >> K;

    ll ans = 0;

    for(int i = 0; i <= K; i++)
    {
        ans += calc(N, M, i);
        if(ans >= MOD)
            ans %= MOD;
    }
    cout << ans << endl;
}

