  vector<vector<mint>> dp(N+1, vector<mint> (3));
  dp[1][0] = mint(M);
  dp[1][1] = mint(0);
  dp[1][2] = mint(0);
  vector<mint> dp2(N+1);
  dp2[1] = mint(0);
