		if((x += a.x) >= mod) x -= mod;
		return *this;
	}
	mint& operator -= (const mint& a){
		if ((x += mod-a.x) >= mod) x -= mod;
		return *this;
	}
	mint& operator *= (const mint& a) {
		(x *= a.x) %= mod;
		return *this;
	}

	mint operator + (const mint& a) const { return mint(*this) += a;}
	mint operator - (const mint& a) const { return mint(*this) -= a;}
	mint operator * (const mint& a) const { return mint(*this) *= a;}

	//べき乗
	mint pow(long long t) const{
		if(!t) return 1;
