    modint operator- (modint a) const { return modint(pdiv + x - a.x); }
    modint operator* (modint a) const { return modint(x * a.x); }
    modint operator/ (modint a) const { return modint(x * a.pow(pdiv-2).x); }
    template <typename T> modint& operator+= (T a) { return *this = *this + a; }
    template <typename T> modint& operator-= (T a) { return *this = *this - a; }
    template <typename T> modint& operator*= (T a) { return *this = *this * a; }
    template <typename T> modint& operator/= (T a) { return *this = *this / a; }
    modint operator- () const { return modint(pdiv - x); }
    template <typename T>
    modint& operator= (T a) { x = a; compile(); return *this; }
};
