using namespace std;
typedef long long ll;
const int maxn = 200005;
const int mod =  998244353;
int fac[maxn]={0};
int quick_mod(int a,int b){
    int ans =  1;
    while(b){
        if(b&1) ans = (1ll*ans*a)%mod;
        a=(1ll*a*a)%mod;
        b>>=1;
    }
    return ans ;
}
int getc(int n,int m){
    return (1ll*fac[n]*quick_mod(fac[m],mod-2)%mod)*quick_mod(fac[n-m],mod-2)%mod;
}

int main()
{

    int n,m,k;
    cin >> n >> m >> k ;
    if(n==1){
        cout << m << endl;
        return 0;
    }
    if(m==1&&k==n-1){
        cout << 1 << endl;
    }
    else
        cout << 0 << endl;
    if(m==1)
        return 0;
    fac[0]=1;
    for(int i=1;i<n;i++)
        fac[i]=1ll*i*fac[i-1]%mod;

    ll ans =  0;
    ll num =  m;
    for(int i=1;i<n;i++)
        num=num*(m-1)%mod;
    for(int i=0;i<=k;i++){
        ans = ans + num*getc(n-1,i)%mod;
        //cout << ans << endl;
        ans%=mod;
        num=num*quick_mod(m-1,mod-2)%mod;
    }
    cout << ans <<endl;
    return 0;
}

