vector<ll> Factorial(ll M, ll MOD){
    vector<ll> result = vector<ll>(M + 1);
    for(int i = 0; i <= M; i++){
        if(i == 0){
            result[i] = 1;
        }else{
            result[i] = result[i-1] * i % MOD;
        }
    }
    return result;
}

vector<ll> InvFact(ll M, ll MOD){
    vector<ll> result = vector<ll>(M + 1);
    vector<ll> inv = vector<ll> (M + 1);
    result[0] = 1;
    result[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < M; i++){
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        result[i] = result[i - 1] * inv[i] % MOD;
    }
    return result;
}

ll Combination(ll n,ll k,vector<ll>& fact, vector<ll>& invFact,ll MOD){
    //nCkを計算する
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fact[n] * (invFact[k] * invFact[n - k] % MOD) % MOD;
}

int main() {
    ll N,M,K;
    cin >> N >> M >> K;
    if( N == 1){
        cout << M << endl;
        return 0;
    }
    ll res = 0;
    if(N - K == 1){
        res += M;
    }
    ll count = M;
    ll MOD = 998244353ll;
    if(M == 1){
        if(N - K > 1){
            cout << 0 << endl;
            return 0;
        }
    }
    auto fact = Factorial(200100,MOD);
    auto invFact = InvFact(200100,MOD);
    for (int i = 2; i <= N; ++i) {
        count *= M-1;
        count %= MOD;
        if(N - K <= i){
            ll tmp = count * Combination(N-1,i-1,fact,invFact,MOD);
            //cout << tmp << endl;
            res += tmp;
            res %= MOD;
        }
    }
    cout << res << endl;
}

