    static modint<mod> fact[200001], finv[200001];
    fact[0] = 1;
    for(int i=1;i<=200000;++i) fact[i] = fact[i-1] * i;
    finv[200000] = fact[200000].inverse();
    for(int i=200000;i>0;--i) finv[i-1] = finv[i] * i;
    auto comb = [&](int n, int r)->modint<mod>{ return fact[n] * finv[n-r] * finv[r]; };

