const int N = 2e5 + 5;
const int MOD = 998244353;
int n, m, K;
ll fac[N];
ll inv[N];

ll power(ll a, ll b) {
  ll res = 1;
  while (b) {
    if (b & 1) {
      res = res * a % MOD;
    }
    a = a * a % MOD;
    b >>= 1;
  }
  return res;
}

void init() {
  fac[0] = 1;
  for (int i = 1; i < N; ++i) {
    fac[i] = fac[i - 1] * i % MOD;
  }
  inv[N - 1] = power(fac[N - 1], MOD - 2);
  for (int i = N - 2; i >= 0; --i) {
    inv[i] = inv[i + 1] * (i + 1) % MOD;
  }
}

ll C(ll a, ll b) {
  return fac[a] * inv[a - b] % MOD * inv[b] % MOD;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  init();

  cin >> n >> m >> K;

  ll res = 0;
  for (int k = 0; k <= K; ++k) {
    res = (res + m * C(n - 1, k) % MOD * power(m - 1, n - 1 - k) % MOD) % MOD;
  }

  cout << res << endl;

  return 0;
}

