ll bpow(int base, int exp)
{
    if (exp == 0)
        return 1ll;
    ll ans = bpow(base, exp / 2);
    ans = (ans * ans) % M;
    if (exp % 2)
        ans = (ans * base) % M;
    return ans;
}
void pre()
{
    fact[0] = 1;
    for (int i = 1; i < N; i++)
        fact[i] = (fact[i - 1] * i) % M;
    inv_fact[N-1] = bpow(fact[N-1],M-2);
    for(int i=N-2;i>=0;i--)
    {
        inv_fact[i] = ((i+1)*inv_fact[i+1])%M;
    }
}
inline ll ncr(int n, int r)
{
    return (((inv_fact[r]*inv_fact[n-r])%M)*fact[n])%M;
}
