ll inv(ll x, ll p)
{
	if (p == 1)
	{
		return x;
	}

	ll half = inv(x, p / 2);
	ll rest = p % 2 == 0 ? 1 : x;
	return ((half * half) % mod * rest) % mod;
}

ll inv(ll x)
{
	return inv(x, mod - 2);
}

