        mexp[i]=((mexp[i-1])*(m-1))%MOD;
    }

    for(int i = 0; i <= k; i++) {
        ll add=m%MOD;
        add=(add*COM(n-1,i))%MOD;
        add=(add*mexp[n-i-1])%MOD;
        ans=(ans+add)%MOD;
    }

