ll pw(ll a, ll n) {
    if (n <= 0) {
        return 1;
    } else if (n == 1) {
        return a;
    } else if (n % 2 == 0) {
        ll work = pw(a, n / 2);
        return work * work % MOD;
    } else {
        return pw(a, n - 1) * a % MOD;
    }
}

vector<ll> f;
