// a^n % mod
long long modpow(long long a, long long n, long long mod) {
	long long ret = 1;

	while (n > 0) {
		if (n & 1) {
			ret = ret * a % mod;
		}

		a = a * a % mod;
		n >>= 1;
	}

	return ret;
}

// aの逆元
long long modinv(long long a, long long mod) {
	return modpow(a, mod - 2, mod);
}


class Combination {
public:
	vector<long long> fact, ifact;
	long long mod;
public:
	Combination(int n, int mod) : fact(n+1), ifact(n+1), mod(mod) {
		fact[0] = 1;
		for (int i = 1; i <= n; i++) {
			fact[i] = fact[i-1] * i % mod;
		}
		ifact[n] = modinv(fact[n], mod);
		for (int i = n; i > 0; i--) {
			ifact[i-1] = ifact[i] * i % mod;
		}
	};

	// nCk
	long long comb(int n, int k) {
		assert(n >= 0);
		assert(0 <= k && k <= n);
		return fact[n] * ifact[k] % mod * ifact[n-k] % mod;
	}
};


int main() {
	int n, m, k;
	cin >> n >> m >> k;

	Combination comb(n, MOD);
	vector<long long> pows(n + 1, 0);
	pows[0] = 1;
	for (int i = 1; i < pows.size(); i++) {
		pows[i] = pows[i-1] * (m - 1) % MOD;
	}

	long long ans = 0;
	for (int i = 0; i <= k; i++) {
		ans += pows[n - 1 - i] * comb.comb(n-1, i);
		ans %= MOD;
	}
	ans *= m;
	ans %= MOD;
	cout << ans << endl;
	return 0;
}

