    mint ans = 0;
    mint col = m;
    for (int x = n - 1; x >= 0; --x) {
        mint now = col;
        now *= c(n - 1, x);
        if (x <= k) ans += now;
        col *= m - 1;
    }
    cout << ans << endl;
    return 0;
}

