const int MOD = 998244353;

const int N = ten(5) * 3;
ll inverse[N];
void init_inverse() {
	/*
	M%i = M - (M/i) * i
	(M%i)*i^-1 = M*i^-1 - M/i (mod M)
	(M%i)*i^-1 = M-M/i(mod M)
	i^-1 = (M-M/i) * (M%i)^-1
	*/
	inverse[1] = 1;
	for (int i = 2; i < N; i++) inverse[i] = (MOD - MOD / i) * inverse[MOD % i] % MOD;
}

ll fact[N], infact[N];
void init_fast_fact() {
	init_inverse();
	fact[0] = fact[1] = 1;
	for (int i = 2; i < N; i++) fact[i] = fact[i - 1] * i % MOD;
	infact[0] = infact[1] = 1;
	for (int i = 2; i < N; i++) infact[i] = infact[i - 1] * inverse[i] % MOD;
}

ll fast_nCk(int n, int k) {
	if (n < 0 || k < 0) return 0;
	if (k > n) return 0;
	ll ret = fact[n] * infact[k] % MOD * infact[n - k] % MOD;
	return ret;
}

int main() {
	init_fast_fact();

	int n, m, k; reader(n, m, k);
	ll ans = 0;
	FOR(i, k + 1) {
		ans += m* mod_pow(m - 1, n - i - 1, MOD) % MOD* fast_nCk(n - 1, i) % MOD;
		ans %= MOD;
	}
	writerLn(ans);
}

