	rep(i, k + 1){
		if(i == 0) a[i] = m * PowMod(m - 1, n - 1) % MOD;
		else a[i]  = a[i - 1] * inv(m - 1) % MOD;
	}

	rep(i, k + 1){
		a[i] *= combi(n - 1, i);
		a[i] %= MOD;
	}

	ll ans = 0;
	rep(i, k + 1) ans += a[i];
	co(ans % MOD);

	return 0;
}

