long long power(long long x, long long n, long long mod = MOD) {
    if (n == 0) return 1;
    if (n % 2 == 0) return power(x * x % mod, n/2, mod);
    else return x * power(x, n-1, mod) % mod;
}

class CNK {
    vector<long long> prod, inv;
public:
    CNK(int n): prod(n+1), inv(n+1) {
        prod[0] = 1;
        for (int i = 1; i <= n; ++i) prod[i] = (prod[i-1] * i) % MOD;
        inv[n] = power(prod[n], MOD-2);
        for (int i = n - 1; i >= 0; --i) inv[i] = (inv[i+1] * (i+1)) % MOD;
    }
    int get(const int &n, const int &k) const {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return (prod[n] * ((inv[k] * inv[n-k]) % MOD)) % MOD;
    }
};

