int mod = 998244353;

int expo(int num, int p) {
    if(num == 0) {
        if(p == 0) assert(false);
        return 0;
    }
    num = num % mod;
    int ret = 1;
    while(p) {
        if(p & 1) ret = (ret * num) % mod;
        num = (num * num) % mod;
        p /= 2;
    }
    return ret;
}

signed main() {
    IOS;
    int fact[200005], inv[200005];
    fact[0] = 1;
    for(int i = 1; i < 200005; ++i) fact[i] = (fact[i - 1] * i) % mod;
    for(int i = 0; i < 200005; ++i) inv[i] = expo(fact[i], mod - 2);
    int n, m, k;
