const int MOD = 998244353;

struct Combination {
	vector<long long> inv,finv,fac;
	Combination(int n, int kmax) : inv(kmax+1),finv(kmax+1),fac(kmax){
		if(kmax>=1){
			inv.at(1)=1;
			finv.at(1)=1;
			fac.at(0) = n;
		}
	for(int i=2; i<=kmax; i++) inv.at(i) = MOD - inv.at(MOD%i) * (MOD/i) %MOD;
	for(int i=2; i<=kmax; i++) finv.at(i) = finv.at(i-1) * inv.at(i) % MOD;
	for(int i=1; i<kmax; i++) fac.at(i) = fac.at(i-1) * (n-i) % MOD;
	}
	long long comb(int k) {return (k ? fac.at(k-1) * finv.at(k) % MOD : 1 );}
};

int main(){

	int n,m,k0; cin>>n>>m>>k0;
	ll cnt{m}, sum{};
	for(int i=0; i<n-k0-1; i++) (cnt *= (m-1))%=MOD;
	Combination c(n-1,k0);
	for(int k=k0; k>=0; k--){
		ll t = (cnt * c.comb(k)) % MOD;
		(sum += t) %= MOD;
		if(k>0){
			(cnt *= m-1) %= MOD;
		}
	}
	cout << sum << endl;
}

