#include <bits/stdc++.h>
#define SIZE 400010
using namespace std;
const long long MOD = 998244353;

long long fac[SIZE], inv[SIZE]; // fac 存储阶乘  inv 存储阶乘逆元

long long qpow(long long a, long long b, long long mod) { // 快速幂 a ^ b % mod
	long long ans = 1;
	while (b) {
		if (b & 1) ans = (ans * a) % mod;
		a = (a * a) % mod;
		b >>= 1;
	}
	return ans;
}

long long getInv(long long n, long long p) { // 求 n mod p 意义下的逆元
	return qpow(n, p - 2, p);
}

void getFacInv(int n, long long p) { // 阶乘逆元
	fac[1] = 1; inv[0] = 1;
	for (long long i = 2; i <= n; ++i) fac[i] = fac[i - 1] * i % p;
	inv[n] = getInv(fac[n], p);
	for (long long i = n - 1; i; --i) inv[i] = inv[i + 1] * (i + 1) % p;
}

long long C(long long n, long long m) {
	return fac[n] * inv[m] % MOD * inv[n - m] % MOD;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	getFacInv(400000, MOD);
	long long N, M, K, ans = 0;
	cin >> N >> M >> K;

	for (int i = 0; i <= K; ++i) {
		ans += M * C(N - 1, i) % MOD * qpow(M - 1, N - i - 1, MOD) % MOD;
		ans = (ans % MOD + MOD) % MOD;
	}

	cout << (ans % MOD + MOD) % MOD;
}

