const ll MOD = mint::mod();
template<typename T> struct Combination {
    ll n_max;
    vector<T> fac, finv, inv;
    Combination(ll n_max) {
        fac.resize(n_max+1);
        finv.resize(n_max+1);
        inv.resize(n_max+1);
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[0] = 0, inv[1] = 1;
        for (int i = 2; i <= n_max; i++){
            fac[i] = fac[i - 1] * i;
            inv[i] = - inv[MOD%i] * (MOD / i);
            finv[i] = finv[i - 1] * inv[i];
        }
    }
    T C(ll n, ll k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * finv[k] * finv[n - k];
    }
    T P(ll n, ll k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * finv[n - k];
    }
    T H(ll n, ll k) {
        return C(n+k-1, k);
    }
};

ll solve() {
    ll N, M, K;
    cin >> N >> M >> K;
    Combination<mint> c(N+10);
    mint ans = 0, m(M);
    for ( int k = 0; k <= K; k++ ) {
        ans += m * (m-1).pow(N-1-k) * c.C(N-1, k);
    }
    return ans.val();
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

