struct Vect {
    T x, y;
    Vect() {
        x = 0;
        y = 0;
    }
    Vect(T x, T y) {
        this->x = x;
        this->y = y;
    }

    int posi() const {
        if(x == 0 && y == 0) exit(1);
        if(x > 0 && y == 0) return 0;
        if(x > 0 && y > 0) return 1;
        if(x == 0 && y > 0) return 2;
        if(x < 0 && y > 0) return 3;
        if(x < 0 && y == 0) return 4;
        if(x < 0 && y < 0) return 5;
        if(x == 0 && y < 0) return 6;
        if(x > 0 && y < 0) return 7;
        return -1;
    }

    bool operator<(const Vect& rhs) {
        int p1 = posi();
        int p2 = rhs.posi();
        if(p1 != p2) return p1 < p2;
        return rhs.x * y < x * rhs.y;
    }
};

template<typename T>
struct SegTree {
    using Func = function<T(T, T)>;
    int n;
    vector<T> dat;
    Func func;
    T low;

    SegTree(vector<T> a, Func _func, T _low) {
        int sz = a.size();
        n = 1;
        low = _low;
        func = _func;
        while(n < sz) n *= 2;
        dat.resize(n * 2 - 1, low);
        rep(i, sz) {
            dat.at(i + n - 1) = a.at(i);
        }
        for(int i = n - 2; i >= 0; i--) {
            dat.at(i) = func(dat.at(i * 2 + 1), dat.at(i * 2 + 2));
        }
    }

    void update(int k, T val) {
        k += n - 1;
        dat.at(k) = val;
        while(k > 0) {
            k = (k - 1) / 2;
            dat.at(k) = func(dat.at(k * 2 + 1), dat.at(k * 2 + 2));
        }
    }

    T _query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return low;
        if(a <= l && r <= b) return dat.at(k);
        T vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
        return func(vl, vr);
    }

    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }
};

