    for(int i = 1; i <= n; i++) p[i] = p[i - 1] * (m - 1) % MOD;
    ll ans = 0;
    for(int i = 0; i <= k; i++){
        ans = (ans + com.com(n - 1, i) * m % MOD * p[n - i - 1]) % MOD;
    }
    cout << ans << endl;
}

