struct factorials{
	vector<vector<long long>> arr;
	long long modpow(long long a, long long b, const long long &mod){
		if(b == 0) return 1 % mod;
		long long ret = modpow(a, b / 2, mod);
		ret = (ret * ret) % mod;
		if(b % 2) ret = (ret * a) % mod;
		return ret;
	}
	factorials(long long n, const long long &mod) : arr(n + 1, vector<long long>(2)){
		arr[0][0] = arr[0][1] = 1;
		for(long long i = 1; i <= n; i++){
			arr[i][0] = (arr[i - 1][0] * i) % mod;
			arr[i][1] = modpow(arr[i][0], mod - 2, mod);
		}
	}
	long long binomial(long long n, long long r, const long long &mod){
		return ((arr[n][0] * arr[n - r][1]) % mod * arr[r][1]) % mod;
	}
};

