long long gcdExtended(long long a, long long b, long long *x, long long *y) 
{ 
    if (a == 0) { 
        *x = 0, *y = 1; 
        return b; 
    } 

    long long x1, y1; 
    long long gcd = gcdExtended(b % a, a, &x1, &y1); 

    *x = y1 - b / a * x1; 
    *y = x1; 

    return gcd; 
} 

long long modInverse(long long a, long long m) 
{ 
    long long x, y; 
    long long g = gcdExtended(a, m, &x, &y); 
    if (g != 1) return -1; 
    else return (x % m + m) % m; 
} 

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    long long const modulo = 998244353;
    long long n, m, k;
    cin >> n >> m >> k;

    vector<long long> pows(n);
    pows[0] = 1;
    for (long i = 1; i < n; i++) pows[i] = (pows[i-1] * (m-1)) % modulo;

    vector<long long> factorials(n);
    factorials[0] = 1;
    for (long i = 1; i < n; i++) factorials[i] = (factorials[i-1] * i) % modulo;

    vector<long long> invFactorials(n);
    for (long i = 0; i < n; i++) invFactorials[i] = modInverse(factorials[i], modulo);

    long long s = 0;
    for (long i = 0; i <= k; i++) {
        long long comb = (((factorials[n-1] * invFactorials[i]) % modulo) * invFactorials[n-1-i]) % modulo;
        s = (s + (comb * ((m * pows[n-i-1]) % modulo) % modulo)) % modulo; 
    } 

    cout << s << "\n";

    return 0;
}

