int modPow(ll a, ll n, ll p) { //繰り返し二乗法 a**n % p
  if(n == 1) return a % p;
  if(!n) return 1;
  if(n % 2 == 1) return (a * modPow(a, n - 1, p)) % p;
  ll t = modPow(a, n / 2, p);
  return (t * t) % p;
}
int main(){
  vector<ll> fact(200001), invfact(200001);
  fact[0] = 1;
  for(int i = 1; i <= 200000; i++){
    fact[i] = fact[i - 1] * i % mod;
  }
  invfact[200000] = modPow(fact[200000], mod - 2, mod);
  for(int i = 200000 - 1; i >= 0; i--){
    invfact[i] = invfact[i + 1] * (i + 1) % mod;
  }
  ll n,m,k;
  cin >> n >> m >> k;
  ll ans = 0;
  for(ll i = 0; i <= k; i++){
    ll num = m * modPow(m - 1, n - i - 1, mod) % mod;
    ll val = fact[n - 1] * (invfact[i] * invfact[n - i - 1] % mod) % mod;
    ans += num * val % mod;
    ans %= mod;
  }
  cout << ans << endl;
}

