const int MOD = 998244353;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
    return a;
}

int mul(int a, int b) {
    return 1LL * a * b % MOD;
}

int binpow(int a, ll n) {
    if (n < 0)
        a = binpow(a, MOD - 2), n *= -1;

    int res = 1;
    while (n) {
        if (n & 1)
            res = mul(res, a);
        a = mul(a, a);
        n /= 2;
    }
    return res;
}

int inv(int x) {
    return binpow(x, MOD - 2);
}

const int N = 2e5 + 3;

int fact[N];

int C(int n, int k) {
    if (k > n) return 0;
    return mul(fact[n], inv(mul(fact[k], fact[n - k])));
}

void solve() {
    fact[0] = 1;
    for (int i = 1; i < N; ++i)
        fact[i] = mul(i, fact[i - 1]);

    int n, m, k;
    cin >> n >> m >> k;

    int ans = 0;
    for (int i = 0; i <= k; ++i) {
        int free = n - i;
        int res = mul(C(n - 1, i), mul(m, binpow(m - 1, free - 1)));
//        err(res);
        ans = add(ans, res);
    }
    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(nullptr); cout.tie(nullptr);
    srand(time(0));

    int t = 1;
//    cin >> t;
    while (t--)
        solve();

    return 0;
}

