namespace matching {
    std::vector<int> unweighted_max_match(const int n, const int m, const std::vector<std::vector<int>> &e) {
        // return match of rows to cols (vector of size n, where all values are in [0,m-1] or -1 if not matched.
        std::vector<int> rowm(n, -1);
        std::vector<int> colm(m, -1);
        std::vector<bool> visited(n);
        std::function<bool(int)> try_match = [&](int i) {
            if (visited[i]) return false;
            bool res = false;
            visited[i] = true;
            for (int j: e[i]) {
                if (j != rowm[i]) {
                    if (colm[j] == -1 || try_match(colm[j])) {
                        colm[j] = i;
                        res = true;
                        break;
                    }
                }
            }
            visited[i] = false;
            return res;
        };

        for (int i = 0; i < n; i++) {
            if (rowm[i] == -1) try_match(i);
        }
        return rowm;
    }
}

