	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
	return;
}

long long COM(int n, int k) {
	if (n < k) {
		return 0;
	}
	if (n < 0 || k < 0) {
		return 0;
	}
	long long res = fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;

}


long long  calc_amari(long long  x) {
	if (x >= MOD) {
		return x % MOD;
	}
	return x;
}

long long  pow(long long  x, long long  n) {
	long long  ans = 1;
	for (int i = 0; i < n; i++) {
		ans *= x;
	}
	return ans;
}

long long  pow_amari(long long  x, long long  n) {
	long long  res = 1;
	long long xk = x;
	while (n > 0) {
		string temp = to_binString(n);
		if ((n & 1) == 1) {
			res = res * xk % MOD;
		}
		xk = xk * xk % MOD;
		n = (n >> 1);
	}
	return res;
}


long long  kaijo(long long n) {
	long long  ans = 1;
	for (int i = 1; i <= n; i++) {
		ans = ans * i % MOD;
	}
	return ans;
}
long long div(long long a) {
	return pow_amari(a, MOD - 2);
}


long long  calc_C(long long N, long long K) {
	long long  ans = 1;
	ans = kaijo(N);
	ans *= div(kaijo(N - K));
	ans	*= div(kaijo(K));
	ans = calc_amari(ans);
	return ans;
}


int main() {
	long long N, M, K;
	cin >> N >> M >> K;
	long long  ans = 0;
	COMinit();
	for (int k = 0; k <= K; k++) {
		int temp = M * COM(N-1, k) * pow_amari(M - 1, N - 1 - k) % MOD;
		ans = (ans + temp) % MOD;
	}
	cout << ans << endl;

	return 0;
}

