ll mpow(ll x, ll n){ 
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll comb(ll a, ll b){
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}


int main(){
    int n,m,k;
    cin>>n>>m>>k;
    ll ans=0;
    ll numlist[200005];

    fac[0] = 1;
    ifac[0] = 1;
    for(ll i = 0; i<300000; i++){
        fac[i+1] = fac[i]*(i+1) % MOD;
        ifac[i+1] = ifac[i]*mpow(i+1, MOD-2) % MOD;
    }
    ll t=m;
    for(int j=0;j<n;j++){
        t*=(m-1);
        t%=MOD;
        numlist[j]=t;
    }

    for(int i=0;i<=k;i++){//i:隣り合うブロックが同じ色なのがi組
        ll t=numlist[n-2-i];
        t*=comb(n-1,i);
        t%=MOD;
        ans+=t;
        ans%=MOD;
    }

    cout<<ans;
    return 0;
}

