//BellmanFord
struct Edge{
    int from, to;
    long cost;
    Edge(int f, int t, long c){
        from = f;
        to = t;
        cost = c;
    }
};

struct BellmanFord{
    vector<Edge> es;
    vector<long> d;
    int E, V; // E 辺 V 頂点
    long inf = 1000000000000000000;

    BellmanFord(int ee=1, int vv=1){
        E = ee;
        V = vv;
        d.resize(vv);
    }

    void update(int from, int to, long cost){
        es.push_back(Edge(from, to, cost));
    }

    void shortest_path(int start){
        REP(i, V) d[i] = inf;
        d[start] = 0l;
        while(true){
            bool upd = false;
            REP(i, E){
                Edge e = es[i];
                if(d[e.from] != inf && d[e.to] > d[e.from] + e.cost){
                    d[e.to] = d[e.from] + e.cost;
                    upd = true;
                }
            }
            if(!upd) break;
        }
        cout << -d[V-1] << endl;

    }

    //true : there is a negative loop.
    //false : there is NOT a negative loop.
    bool find_negative_loop(){
        REP(i, V) d[i] = 0l;
        REP(i, V){
            REP(j, E){
                Edge e = es[j];
                if(d[e.to] > d[e.from] + e.cost){
                    d[e.to] = d[e.from] + e.cost;
                    if(i==V-1) return true;
                }
            }
        }
        return false;
    }

    //true : there is a negative loop including start.
    //false : there is NOT a negative loop including start.
    bool find_negative_loop_from_start(int start){
        REP(i, V) d[i] = inf;
        d[start] = 0l;
        int itr = 0;
        bool ok = false;
        while(true){
            bool upd = false;
            REP(i, E){
                Edge e = es[i];
                if(d[e.from] != inf && d[e.to] > d[e.from] + e.cost){
                    d[e.to] = d[e.from] + e.cost;
                    upd = true;
                    if(itr > V && e.to == V-1) ok = true;
                }
            }
            if(!upd) break;
            itr++;
            if(itr == 100*V) break;
        }
        if(itr == 100*V && ok){
            return true;
        }else return false;
    }

};

