#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
const LL mod = 998244353;
LL quick_pow(LL x, LL n, LL p)// 快速幂求x^n mod p 的结果
{
    if(n==0)
        return 1;
    if(n==1)
        return x%p;
    LL ans = 1;
    LL tmp = x%p;
    while(n)
    {
        if(n&1)
        {
            ans = (ans*tmp)%p;
        }
        tmp = tmp*tmp%p;
        n>>=1;
    }
    return ans%p;
}
LL inv(LL b,LL p) //求数 b mod p 的逆元
{
    return quick_pow(b,p-2,p);
}
LL C(LL n,LL m,LL p)//组合数取模
{
    if(m==0|| m== n)
        return 1;
    if(m==1||m==n-1)
        return n%p;
        m = min(m,n-m);
    LL up = 1,down = 1;
    for(LL i = n-m+1;i<=n;i++)
        up=(up*i)%p;
    for(LL i = 1;i<=m;i++)
        down=(down*i)%p;
    up%=p;
    down%=p;
    return (up*(inv(down,p)%p))%p;
}
LL lucas(LL n,LL m,LL p)//递归lucas函数
{
    if(m==0)
        return 1;
    return lucas(n/p,m/p,p)*C(n%p,m%p,p)%p;
}

int main()
{
    LL n ,m,k;
    cin >> n >> m >> k;
    LL ans = 0;
    for(LL i = 0;i<=k;++i){
        ans = (ans+(C(n-1,i,mod)*quick_pow(m-1,n-i-1,mod))%mod)%mod;
    }
    ans = (ans*m)%mod;
    cout << ans << "\n";
    return 0;
}

