        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll cme;

ll modpow(ll b, ll e, ll m){  // bのe乗のmod m を返す
  if (e == 0) return 1;
  cme = modpow(b, e / 2, m);
  cme = (cme * cme) % m;
  if (e % 2 == 1) cme = (cme * b) % m;
  return cme;
}

ll N,M,K;

int main(){
  ll ANS=0;
  COMinit();
  cin >> N >> M >>  K;
  Rep(i,0,K+1){
    ll Z=(M*modpow(M-1,N-i-1,MOD))%MOD;
    Z*=COM(N-1,i);
    Z%=MOD;
    ANS=(ANS+Z)%MOD;
  }
  cout << ANS << endl;
}

