    rep(i, 0, K+1){
        ll tmp = M * mod_pow(M-1, N-1-i, mod);
        tmp %= mod;
        if(i != 0) tmp *= mod_nck(N-1, i);
        tmp %= mod;
        ans += tmp;
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

