struct Combination{
	vmll f, g; // factorial, factorial^-1
	Combination(){}
	Combination(ll maxN): f(maxN+1, 1), g(maxN+1){ InitSub(maxN); }
	void Init(ll maxN){ f.resize(maxN+1, 1); g.resize(maxN+1); InitSub(maxN); }
	mll operator () (ll n, ll r){ return (n<0||r<0||n<r) ? mll(0) : f[n]*g[n-r]*g[r]; }
	mll P(ll n, ll r){ return (n<0 || r<0 || n<r) ? mll(0) : f[n]*g[n-r]; }
	mll Inv(ll n) { return f[n-1] * g[n]; }
	mll Fact(ll n) { return f[n]; }
	mll FInv(ll n) { return g[n]; }
	void InitSub(ll maxN){
		REPS(i, 1, maxN){ f[i] = f[i-1] * i; }
		g[maxN] = 1 / f[maxN];
		DEPS(i, 1, maxN){ g[i-1] = g[i] * i; }
	}
};



