const int COM_MAX = 510000;
template <long long p>
class Zp{
    long long content;

    // for comb()
    static array<long long, COM_MAX> fac;
    static array<long long, COM_MAX> finv;
    static array<long long, COM_MAX> inv_;
    static bool is_initialized_com_table;

    // By rng_2 (See https://drken1215.hatenablog.com/entry/2018/06/08/210000)
    // テーブルを作る前処理
    static void COMinit() {
        auto MOD = p;
        auto MAX = COM_MAX;
        fac.at(0) = fac.at(1) = 1;
        finv.at(0) = finv.at(1) = 1;
        inv_.at(1) = 1;
        for (int i = 2; i < MAX; i++){
            fac.at(i) = fac.at(i - 1) * i % MOD;
            inv_.at(i) = MOD - inv_.at(MOD%i) * (MOD / i) % MOD;
            finv.at(i) = finv.at(i - 1) * inv_.at(i) % MOD;
        }
        is_initialized_com_table = true;
    }

    // 二項係数計算
    static long long COM(int n, int k){
        auto MOD = p;
        auto MAX = COM_MAX;
        if(!is_initialized_com_table){
            assert(false);
        }
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac.at(n) * (finv.at(k) * finv.at(n - k) % MOD) % MOD;
    }



    public:
    Zp(long long content_){
        if(content_ >= 0){
            content = content_ % p;
        }else{
            long long temp = p;
            while(temp < -content_){
                temp *= p;
            }
            content = (temp + content_) % p;
        }
    }

    bool operator==(const Zp<p>& rhs) const{
        return this->content == rhs.content;
    }

    bool operator!=(const Zp<p>& rhs) const{
        return !(*this == rhs);
    }

    Zp<p> operator+(const Zp<p>& rhs) const{
        return Zp<p>(this->content + rhs.content);
    }

    Zp<p> operator-() const{
        return Zp<p>(p - this->content);
    }

    Zp<p> operator-(const Zp<p>& rhs) const{
        return Zp<p>(this->content - rhs.content + p);
    }

    Zp<p> operator*(const Zp<p>& rhs) const{
        return Zp<p>(this->content * rhs.content);
    }

    Zp<p> inv() const{
        if(this->content == 0){
            assert(false);
        }

        auto res = gcd(this->content, p);
        return Zp<p>(res.x);
    }

    Zp<p> operator/(const Zp<p>& rhs) const{
        if(rhs.content == 0){
            assert(false);
        }

        return (*this)*rhs.inv();
    }

    Zp<p> pow(int n){
        auto res = Zp<p>(1);
        Zp<p> mult = (*this);
        while(n > 0){
            if(n & 1 == 1){
                res = res*mult;
            }
            n >>= 1;
            mult = mult*mult;
        }
        return res;
    }

    void operator+=(const Zp<p>& rhs){
        *this = *this + rhs;
    }

    void operator-=(const Zp<p>& rhs){
        *this = *this - rhs;
    }

    void operator*=(const Zp<p>& rhs){
        *this = *this * rhs;
    }

    void operator/=(const Zp<p>& rhs){
        *this = *this / rhs;
    }

    long long raw(){
        return this->content;
    }

    static void initializeCom(){
        COMinit();
    }

    static Zp<p> com(int n, int k){
        return Zp<p>(COM(n, k));
    }

};

template <long long p>
bool Zp<p>::is_initialized_com_table = false;
template <long long p>
array<long long, COM_MAX> Zp<p>::fac;
template <long long p>
array<long long, COM_MAX> Zp<p>::finv;
template <long long p>
array<long long, COM_MAX> Zp<p>::inv_;


void solve(long long N, long long M, long long K){
    Zp<MOD>::initializeCom();
    Zp<MOD> res(0);
    Zp<MOD> prod(1);
    for(int p=K; p >= 0; p--){
        if(0 <= p && p <= N-1){
            res += Zp<MOD>::com(N-1, p)*Zp<MOD>(M)*Zp<MOD>(M-1).pow(N-1-p);
            // prod = Zp<MOD>(M-1);
        }
    }

    cout << res.raw() << endl;
}

