  }
  long long ans = 0;
  for (int i = 0; i <= k; ++i) {
    ans = ans + 1LL * m * C(n-1, i) % mod * binpow(m-1, n-1-i) % mod;
    ans %= mod;
  }
  printf("%lld", ans);
