ll nc[MAXN], mc[MAXN], N, M, K, fac[MAXN];

ll POW(ll a, ll b) {
	if(b == 0) return 1;
	if(b == 1) return a;
	ll t = POW(a, b/2); t = (t * t) % MOD;
	if(b % 2) t = (t * a) % MOD;
	return t;
}

ll MOD_INV(ll x) {
	return POW(x, MOD-2);
}

ll ans;

int main() {
