		fac[i] = (fac[i-1] * i) % MOD;
	}
	for(ll i=1; i<=M; i++) {
		mc[i] = (mc[i-1] * (M-i+1) % MOD) * MOD_INV(i);
	}

	for(ll i=N-K-1; i<=N-1; i++) {
		ans = (ans + (POW(M-1, i) * M % MOD) * nc[i] % MOD) % MOD;
	}
	cout << ans;
}

