using namespace std;
const int MOD = 998244353;
const int MAX = 200000;

long long inverse[MAX];
long long factorial[MAX];
long long factorial_inverse[MAX];
long long pow_M_minus[MAX];

void calc(int n) {
	inverse[1] = 1;
	factorial[0] = factorial[1] = 1;
	factorial_inverse[0] = factorial_inverse[1] = 1;
	for (int i = 2; i <= n; i++) {
		inverse[i] = MOD - inverse[MOD%i] * (MOD/i) % MOD;
		factorial[i] = i * factorial[i-1] % MOD;
		factorial_inverse[i] = inverse[i] * factorial_inverse[i-1] % MOD;
	}
}

long long comb(int n, int k) {
	return factorial[n] * (factorial_inverse[k] * factorial_inverse[n-k] % MOD) % MOD;
}


int main() {
	long long n, m, k;
	cin >> n >> m >> k;
	calc(n-1);
	pow_M_minus[0] = 1;
	for (int i = 1; i < n; i++) pow_M_minus[i] = pow_M_minus[i-1] * (m-1) % MOD;
	long long ans = 0;
	for (int i = 0; i <= k; i++) {
		ans += m * pow_M_minus[n-1-i] % MOD * comb(n-1, i) % MOD;
		ans %= MOD;
	}	
	cout << ans << endl;
	return 0;
}

