const static int MOD = 998244353;

ll RepeatSquaring(ll N, ull P){
	if(P == 0 || N == 1) return 1;
	if(N == -1) return P & 1 ? -1 : 1;
	if(!(P & 1)){
		ll t = RepeatSquaring(N, P >> 1);
		return t*t % MOD;
	}
	//Pが偶数のときN^(P/2)を求めてからそれの2乗を返す
	return N*RepeatSquaring(N, P - 1) % MOD;
	//Pが奇数のときN^((P - 1)/2)を求めてからそれの2乗を返す
}

ull Combination(ull n, ull r){
	ull ret = 1;
	if(n - r < r) r = n - r;
	for (int i = 0; i < r; ++i){
		ret = ret*(n - i) %MOD *RepeatSquaring(i+1, MOD-2) %MOD;
	}
	return ret;
}
int main(){
	ull N, M, K;
	scanf("%llu %llu %llu", &N, &M, &K);
	ull answer = (RepeatSquaring(M, N) + MOD - (RepeatSquaring(M, N-K-1)*Combination(N-1, K+1)%MOD)) %MOD;
	printf("%llu\n", answer);
	return 0;
}

