    fac[0] = 1;
    inverseFac[0] = 1;
    for (long long i = 0; i < MAX; i++) {
        fac[i + 1] = fac[i] * (i + 1) % MOD;
        inverseFac[i + 1] = inverseFac[i] * modPow(i + 1, MOD - 2) % MOD;
    }
}

