long long fac[MAX], finv[MAX], inv[MAX];

// a^n mod を計算する
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}


// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
    // 前処理
    COMinit();

    ll N ,M ,K; cin >> N >> M >> K;

    ll ans = 0;
    ll tmp1;
    // 連続回数K回のそれぞれの組み合わせを求める
    rep(i,K + 1){
      //　初めの一つはM種類から、それ以降のN - (i + 1)回はM - 1種類から選べる
      tmp1 = M * modpow(M - 1, N - (i + 1), MOD) % MOD;
      // N - i個の中から重複するものをi個選ぶ
      ll tmp2 = 0;
      // N - i個の中からiこj種類それぞれについて考える
      repn(j, i){
        tmp2 += COM(N - i, j) * COM(i - 1 , j - 1);
        tmp2 %= MOD;
      }
      ans += tmp1 * tmp2 % MOD;
      // cout << ans <<endl;
