ll exp(ll x, ll a)
{
    if (a == 0)
    {
        return 1;
    }
    if (a % 2 == 0)
    {
        ll xx = (x * x) % MOD;
        return exp(xx, a / 2) % MOD;
    }
    else
    {
        return (x * exp(x, a - 1)) % MOD;
    }
}

ll comb(ll n, ll r)
{
    if (n == 0 && r == 0)
    {
        return 1;
    }
    if (n < r || n < 0)
    {
        return 0;
    }
    ll tmp = (ifac.at(n - r) * ifac.at(r)) % MOD;
    return (tmp * fac.at(n)) % MOD;
}

