ll n, m, k;
ll f1[200001], f2[200001];

ll expo(ll a, ll b) {
  if (a == 1) return 1;
  if (a == 0) return 0;
  if (b <= 0) return 1;
  ll ans = 1, base = a;
  for (; b; base*=base, b >>= 1) {
    base %= MOD;
    if (b&1) ans *= base;
    ans %= MOD;
  }
  return (ans + MOD) % MOD;
}

ll choose(ll n, ll r) {
  return (((((f1[n] * f2[r] % MOD) + MOD) % MOD) * f2[n-r] % MOD) + MOD) % MOD;
}

