    f1[i] = ((f1[i-1]*i)%MOD + MOD) % MOD;
  for (ll i = 2; i <= 200000; i++)
    f2[i] = expo(f1[i], MOD-2);

  for (ll i = 0; i <= k; i++) {
    ll j = n-i;
    ll tmp = m * expo(m-1, j-1) % MOD;
    tmp = ((tmp + MOD) % MOD) * choose(i+j-1, i) % MOD;
    ans = (ans + tmp + MOD) % MOD;
  }
  cout << ans;
  return 0;
}

