//素因数分解
//引数の整数を素因数分解する。
//mapクラスのキーに基数、対応する値に指数が入っている
map<int, int> lc;
map<int, int> fact(int n) {
  map<int, int> ret;
  int base, ix;

  int i;
  for (i=0; n>1; i++) {
    base = prime(i);
    ix = 0;
    while (n%base == 0) {
      ix++;
      n /= base;
    }
    if (ix > 0) {
      ret[base] = ix;
      auto itr = lc.find(base);
      if (itr == lc.end()) {
        lc[base] = ix;
      } else {
        lc[base] = max(ix, lc[base]);
      }
    } else {
      if (base * base >= n) {
        ret[n] = 1;
        auto itr = lc.find(n);
        if (itr == lc.end()) {
          lc[n] = 1;
        } else {
          lc[n] = max(1, lc[n]);
        }
        break;
      }
    }
  }
  return ret;
}

// 最大公約数
// 素因数分解された値での最大公約数算出
map<int, int> lcm(map<int, int> m, map<int, int> n) {
  map<int, int> ret;

  for (auto itm=m.begin(); itm!=m.end(); itm++) {
    auto itn = n.find(itm->first);
    if (itn == n.end()) {
      ret[itm->first] = itm->second;
    } else {
      ret[itm->first] = max(itm->second, itn->second);
      n.erase(itm->first);
    }
  }
  for (auto itn=n.begin(); itn!=n.end(); itn++) {
    ret[itn->first] = itn->second;
  }

  return ret;
}

//除算
// 素因数分解された値の除算
map<int, int> vdiv(map<int,int> m, map<int, int> n) {
  map<int, int> ret;

  for (auto itm=m.begin(); itm!=m.end(); itm++) {
    auto itn = n.find(itm->first);
    if (itn == n.end()) {
      ret[itm->first] = itm->second;
    } else {
      ret[itm->first] = itm->second - itn->second;
      n.erase(itm->first);
    }
  }
  for (auto itn=n.begin(); itn!=n.end(); itn++) {
    ret[itn->first] = -itn->second;
  }
  return ret;
}
