ll fast(ll a, ll n)
{
  ll ret=1;
  while (n>0)
  {
    if (n & 1)
    {
      ret = ret * a % MOD;
    }
    n = (n>>1);
    a = a * a % MOD;
  }
  return (ret);
}

ll comb(ll n, ll r)
{
  ll top=1;
  ll bot=1;
  ll ans;

  ll d[n+1];
  d[0]=1;
  for (int i=1;i<=n;i++)
  {
     d[i]=d[i-1]*i % MOD;
  }

  top = d[n];
  bot = d[r]*d[n-r] % MOD;
  ans = top * fast(bot,MOD-2) %MOD;
  return (ans);
}

int main()
{
  int N,M,K;
  cin>>N>>M>>K;

  ll ans=0;
  for (int i=0;i<=K;i++)
  {
    ll sum = M*fast(M-1,N-i-1) % MOD;
    sum *= comb(N-i,i);
    sum %= MOD;
    ans += sum;
    ans %= MOD;
  }
  cout<<ans<<endl;
}

