void solve()
{
	READ(llong, N, M, K);
	if (N == 1)
	{
		WRITE(M);
		return;
	}

	if (M == 1)
	{
		WRITE(K <= N - 1 ? 1 : 0);
		return;
	}

	llong mod = 998244353;
	ModCombination MOD(200000, mod);

	llong ans = 0;
	REP(i, K+1)
	{
		llong ad = M;
		ad *= modPow(M - 1, N - i - 1, mod);
		ad %= mod;
		ad *= MOD.Combination(N - 1, i);
		ad %= mod;
		ans += ad;
		ans %= mod;
	}
	WRITE(ans);
}

