const ll mod = 998244353;

ll expMod(ll a, ll b, ll mod){
    ll ans = 1;
    while(b){
        if(b&1) ans = (ans*a)%mod;
        a = (a*a)%mod;
        b >>= 1;
    }
    return ans;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    ll n , k, m;
    cin >> n >> m >> k;
    ll cmb = 1; // C(n-1,i)
    ll ans = 0;

    for(int i=0;i<=k;i++){
        ll cr = (m*expMod(m-1, n-i-1,mod))%mod;
        cr = (cr*cmb)%mod;
        ans += cr;
        ans %= mod;

        //C(n-1,i+1) = C(n-1,i) * (n-1 - (i+1) + 1) / (i+1)
        cmb = (cmb*(n-1-(i+1)+1))%mod;
        cmb *= expMod(i+1, mod-2, mod);
        cmb %= mod;
    }

    cout << ans << "\n";

    return 0;
}

