ll pat(ll n, ll k) {
  ll ret=0;
  ll i;
  for (i=0; i<=k; i++) {
    ret += M*mpow(M-1, n-i-1)%MOD*C(n-1, i)%MOD;
    ret %= MOD;
  }
  return ret;
}
ll _pat(ll n, ll k) {
  ll ret;

//printf("%*spat(%lld, %lld)\n", (int)(N-n), "", n, k);
  if (n==1) {
//printf("%*spat(%lld, %lld)=1\n", (int)(N-n), "", n, k);
    return M;
  }
  auto it = mp.find(make_pair(n, min(n,k+1)));
  if (it != mp.end()) {
    return it->second;
  }

  if (n <= k + 1) { // 隣り合うブロックの色が同じ数の制限がない
    ret = mpow(M, n);
    mp.emplace(make_pair(n, min(n,k+1)), ret);
    return ret;
  }
  if (k == 0) { // 隣り合うブロックはすべて異なる色の場合
    ret = M*mpow(M-1, n-1);
    ret %= MOD;
    mp.emplace(make_pair(n, min(n,1LL)), ret);
    return ret;
  }

  if (k == 1) {  // 必ずn>=2
    ret = M*mpow(M-1, n-2)%MOD*((n-1)+(M-1))%MOD;
//printf("%lld pat(%lld, %lld)\n", ret, n, k);
    mp.emplace(make_pair(n, min(n,k+1)), ret);
    return ret;
  }


  //前のブロックと異なる色で始まるものの個数
  ret = (M-1)*pat(n-1, k)%MOD;
  //前のブロックと同じ色で始まるものの個数
  if (k>0) {
    ret += pat(n-1, k-1);
    ret %= MOD;
  }
  mp.emplace(make_pair(n, min(n,k+1)), ret);
//printf("%*spat(%lld, %lld)=%lld\n", (int)(N-n), "", n, k, ret);
//printf("%lld pat(%lld, %lld)\n", ret, n, k);
  return ret;
}
ll mpow(ll m, ll n) {
  ll ret;
  if (n==0) return 1;
  if (n==1) return m;
  auto it = mp.find(make_pair(m, n));
  if (it != mp.end()) return it->second;
  ret = m * mpow(m, n-1)%MOD;
  mp.emplace(make_pair(m, n), ret);
//printf("mpow(%lld, %lld) = %lld\n", m, n, ret);
  return ret;
}
ll _mpow(ll m, ll n) {
  ll i;
  ll ret=m;
  if (n==0) return 1;
  for (i=1; i<n; i++) {
    ret *= m;
    ret %= MOD;
  }
//printf("mpow(%lld, %lld)\n", m, n);
  return ret;
}
