/*
  nCkを求める
  MOD(1000000007LL)で割った余りを算出
  */
ll fact(int n) {
  ll ret=1;
  if (n == 0 || n == 1) return 1;
  auto it = mf.find(n);
  if (it != mf.end()) return it->second;
  ret = n * fact(n-1) % MOD;
  mf.emplace(n, ret);
//printf("fact(%d) = %lld\n", n, ret);
  return ret;
}
ll C(int n, int k) {
  ll f1, f2, f3;
  ll ret;

  f1 = fact(n);
  f2 = fact(k);
  f3 = fact(n-k);
  ret = f1;
  ret *= modinv(f2, MOD);
  ret %= MOD;
  ret *= modinv(f3, MOD);
  ret %= MOD;
  return ret;
}
ll _C(int n, int k) {
  ll ret=1;
  int i;
  int a, b;

  a = k;
  b = n-k;
  if (a<b) swap(a,b);

  for (i=n; i>a; i--) {
    ret *= i;
    ret %= MOD;
  }
  for (i=2; i<=b; i++) {
    ret *= modinv(i, MOD);
    ret %= MOD;
  }
//printf("C(%d, %d)\n", n, k);
  return ret;
}


