}


/*
  ブロックの塗り方は M^N通り
  隣り合うブロックの色が同じ個所
  0個:  M*(M-1)^(N-1)
    最初のブロックの色はM通り2番目以降は前の色と異なるのでM-1通り
  1個:  (M*(M-1)^(N-2))*(N-1)
    同色の個所はN-1通り、同色以外のブロックはM-1色のN-2個分
  2個:  M*(M-1)^(N-3)*(N-1)*(N-2)/2
    隣り合うブロックが同色のものを1まとめと考えると、
    N-2個のグループに分けられる
    同色の個所はN-1C2=(N-1)*(N-2)/2通り
  k個:  M*(M-1)^(N-k-1)*((N-1)Ck)

  3 3 1
  112 113 121 122 123 131 132 133
  */

#include <bits/stdc++.h>

class ModInt {
public:
    ModInt() 
      : val(0), mod(0) 
    {
    }

    ModInt(int64_t v, int64_t m) 
      : val(v % m), mod(m)
    {
    }

    inline int64_t getVal() const noexcept {
        return this->val;
    }

    inline int64_t getMod() const noexcept {
        return this->mod;
    }

    inline ModInt operator - () const noexcept {
        return this->val ? ModInt(this->mod - this->val, this->mod) : ModInt(0, this->mod);
    }

    inline ModInt operator + (const ModInt& r) const noexcept {
        return ModInt(*this) += r;
    }

    inline ModInt operator - (const ModInt& r) const noexcept {
        return ModInt(*this) -= r;
    }

    inline ModInt operator * (const ModInt& r) const noexcept {
        return ModInt(*this) *= r;
    }

    inline ModInt operator / (const ModInt& r) const noexcept {
        return ModInt(*this) /= r;
    }

    inline ModInt& operator += (const ModInt& r) noexcept {
        this->val += r.val;
        this->val %= this->mod;
        return *this;
    }

    inline ModInt& operator -= (const ModInt& r) noexcept {
        this->val -= r.val;
        if (this->val < 0) {
            this->val += this->mod;
        }
        return *this;
    }

    inline ModInt& operator *= (const ModInt& r) noexcept {
        this->val = this->val * r.val % this->mod;
        return *this;
    }

    inline ModInt& operator /= (const ModInt& r) noexcept {
        int64_t a = r.val, b = this->mod, u = 1, v = 0;
        while (b) {
            int64_t t = a / b;
            a -= t * b; std::swap(a, b);
            u -= t * v; std::swap(u, v);
        }
        this->val = this->val * u % this->mod;
        if (val < 0) {
            val += this->mod;
        }

        return *this;
    }

    inline bool operator == (const ModInt& r) const noexcept {
        return this->val == r.val;
    }

    inline bool operator != (const ModInt& r) const noexcept {
        return this->val != r.val;
    }

    friend std::ostream& operator << (std::ostream& os, const ModInt& x) noexcept {
        return os << x.val;
    }

private:
    int64_t val;
    int64_t mod;
};

ModInt modpow(int64_t a, int64_t n, int64_t mod) {
    ModInt ret(1, mod);
    ModInt ma(a, mod);
    while (n > 0) {
        if (n & 1) {
            ret *= ma;
        }
        ma *= ma;
        n >>= 1;
    }

    return ret;
}

ModInt modfact(int64_t n, int64_t mod) {
    static std::vector<ModInt> facts;
    if (n < (int64_t)(facts.size())) {
        return facts[n];
    } else {
        const int64_t org_size = facts.size();
        facts.resize(n + 1);
        for (int64_t i = org_size; i <= n; ++i) {
            facts[i] = ((i == 0) ? ModInt(1, mod) : facts[i-1] * ModInt(i, mod));
        }

        return facts[n];
    }
}

ModInt modconb(int64_t n, int64_t k, int64_t mod) {
    return modfact(n, mod) / (modfact(n-k, mod) * modfact(k, mod));
}

static constexpr int64_t MOD = 998244353;

int main() {
    int64_t N, M, K;
    std::cin >> N >> M >> K;

    ModInt ans(0, MOD);
    ModInt m(M, MOD);
    for (int64_t i = 0; i <= K; ++i) {
        ans += m * modconb(N - 1, i, MOD) * modpow(M - 1, N - 1 - i, MOD);
    }

    std::cout << ans << std::endl;

    return 0;
}

