  for(int i = 0; i <= K; i++){
    ll num = c(N-1, i);
    num *= M % MOD;
    num %= MOD;
    num *= modbeki(M-1, N-i-1);
    num %= MOD;
    ans += num;
    ans %= MOD;
  }
  cout << ans << endl;
}

