int main() {
    // input, ready
    int N,M,K;
    cin >> N >> M >> K;

    // resolve
    if (N==1) {
        cout << M << endl;
        return 0;
    }
    Combination cb(N);
    cb.COMinit(N);
    ll ans = 0;
    for (int i=N-1; i>=0; i--) {
        ll ans_tmp = M;
        ans_tmp *= modPow(M-1, N-1-i);
        ans_tmp %= MOD;
        ans_tmp *= cb.COM(N-1,i);
        ans_tmp %= MOD;
        if (i<=K)ans += ans_tmp;
        ans %= MOD;
    }

    // output
    cout << ans%MOD << endl;

    return 0;
}

