void solve() {
    ANS = 0;
    init_combination(1e6);
    for(ll k = 0; k <= K; k++) {
        ll tmp = M;
        tmp *= combination(N - 1, k);
        tmp %= mod;
        tmp *= beki(M - 1, N - 1 - k);
        tmp %= mod;
        ANS += tmp;
        ANS %= mod;
    }
    cout << ANS << endl;
}

