// modulo x ^ y 
int modpow(int x, int y, int p = mod) 
{ 
	int res = 1;       
	x %= p;   
	while (y > 0) 
	{ 
		if (y & 1) 
			res = (res * x) % p; 
		y >>= 1;
		x = (x * x) % p;   
	} 
	return res; 
} 

// modulo x + y
int add(int x, int y) 
{
	x += y;
	if (x >= mod) return x - mod;
	return x;
}

// modulo x - y
int sub(int x, int y) 
{
	x -= y;
	if (x < 0) return x + mod;
	return x;
}

// modulo inv
int inv(int a, int m = mod)
{
	return modpow(a, m - 2, m);
}

// modulo x * y
int mul(int a, int b) 
{
	return (long long) ((a % mod) * (b % mod)) % mod;
}

void calc_fact(int n)
{
	fact.resize(n);
	invfact.resize(n);
	fact[0] = invfact[0] = 1;
	for(int i = 1; i < n; ++ i)
	{
		fact[i] = mul(fact[i - 1], i);
		invfact[i] = inv(fact[i]);
	}
}

int ncr(int n, int r)
{
	int ans = mul(fact[n], mul(invfact[n - r], invfact[r]));
	return ans;
}

