	for(int i = 0; i <= k; ++ i)
	{
		int cur = ncr(n - 1, i);
		int is = mul(m, modpow(m - 1, n - i - 1));
		cur = mul(cur, is);
		ans = add(ans, cur);
	}
	cout << ans << '\n';
}

