ll factorials[200005];

void do_fact(){
	factorials[0] = 1;
	for(ll i = 1; i < 200005; i++){
		factorials[i] = (factorials[i-1]%M * i%M)%M; 
	}
}

ll modexp(ll x, ll y){
	ll res = 1;
	x =  x % M;

	while(y > 0){
		if(y % 2 != 0){
			res = (res%M * x%M)%M;
		}

		x = (x%M * x%M)%M;
		y /= 2;
	}

	return res;
}

ll invmod(ll a){
	return modexp(a, M-2);
}

ll func(ll n, ll m, ll k){
	ll temp = (factorials[n-1]%M * invmod(factorials[k]))%M;
	temp = (temp * invmod(factorials[n-1-k]))%M;
	temp = (temp * m%M)%M;
	temp = (temp * modexp(m-1, n-1-k))%M;
	return temp;
}	

int main(){

	ll n, m, k, ans=0;
	cin >> n >> m >> k;
	do_fact();
	for(ll i = 0; i <= k; i++){
		ans = (ans%M + func(n, m, i))%M;
	}
