    com[i] = (com[i-1]%MODP*((N-i)%MODP*gen(i,MODP-2))%MODP)%MODP;
  }


  ll ans = 0;
  for(ll i = 0;i <= K;i++){
    ll add = (M*com[i])%MODP;
      add = (add*gen(M-1,N-i-1))%MODP;
    ans = (ans+add)%MODP;
  }

  cout << ans%MODP << endl;

  return 0;
}

