// 組合せを素数で割った値を求める
const int MAX = 510000;
const ll MOD = 998244353;
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
long long COM(int n, int k) {
  if (n < k || n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

// 繰り返し自乗法(x^nをmで割った余り) O(logn)
ll power(ll x, ll n, ll m) {
  ll res = 1;
  if (n > 0) {
    res = power(x, n / 2, m);
    if (n % 2 == 0) res = (res * res) % m;
    else res = (((res * res) % m) * x) % m;
  }
  return res;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll n, m, k;
  cin >> n >> m >> k;

  COMinit();

  ll ans = 0;
  for (ll i = 0; i <= k; i++) {
    ll nown = n - i;
    ll keep = COM(n - 1, i);
    //cout << keep << endl;
    keep *= (m * power(m - 1, nown - 1, MOD)) % MOD;
    keep %= MOD;
    ans += keep;
    //cout << keep << endl;
    ans %= MOD;
    //cout << ans << endl;
  }

  cout << ans << '\n';
}

