void init(int n)
{
	Fac[0] = 1;
	rep(i,1,n + 1) Fac[i] = Fac[i - 1] * i % mod;
	Inv[n] = inv(Fac[n],mod);
    for( int i = n - 1; i >= 0; --i ) Inv[ i ] = Inv[ i + 1 ] * ( i + 1 ) % mod;
