const ll MOD = 998'244'353;

ll rem(ll x) { x %= MOD; if(x < 0) x += MOD; return x; }
ll madd(ll x, ll y) { return (rem(x) + rem(y)) % MOD; }
ll msub(ll x, ll y) { return madd(x, -y); }
ll mmul(ll x, ll y) { return rem(x) * rem(y) % MOD; }
ll mpow(ll x, ll n) { assert(n >= 0); ll res = 1; while (n > 0) { if (n & 1) res = mmul(res, x); x = mmul(x, x); n >>= 1; } return res; }
ll inv(ll x) { assert(x % MOD != 0); return mpow(x, MOD - 2); }
ll mdiv(ll x, ll y) { return mmul(x, inv(y)); }
void mad(ll &x, const ll y) { x = madd(x, y); }
void msb(ll &x, const ll y) { x = msub(x, y); }
void mml(ll &x, const ll y) { x = mmul(x, y); }
void mdv(ll &x, const ll y) { x = mdiv(x, y); }

vl facts(int nMAX) { assert(nMAX >= 0); vl res(nMAX + 1); res[0] = 1; rep2(k, 1, nMAX + 1) res[k] = mmul(res[k - 1], k); return res; }
ll cmb(int n, int r, vl &facts) { assert(n >= 0);	assert(r >= 0);	assert(r <= n); assert(n < facts.size()); return mdiv(facts[n], mmul(facts[r], facts[n - r])); }
vl cmbs(int nMAX, vl &facts) { assert(nMAX >= 0); assert(nMAX < facts.size()); vl res(nMAX + 1); rep(r, nMAX + 1) res[r] = cmb(nMAX, r, facts); return res; }

// N個のブロックがあるとき，隣り合うブロックの組は(N-1)。このうちi(<=K)組の色が同じであるとすると，i個のブロックの色は他のブロックによって決定するため，残りの(N-i)個のブロックの色を決めることになる。
// i組のブロックの選び方は C(N-1, i) 通り。
// この色の決め方は，M * (M-1)^(N-i-1) 通り
// これを i=0~K について足し合わせればよい。

ll N, M, K;
vl f, c;

ll solve(int i) {
	ll res = c[i];
	mml(res, M);
	mml(res, mpow(M - 1, N - i - i));
	return res;
}

int main() {
	cin >> N >> M >> K;
	f = facts(N);
	c = cmbs(N - 1, f);
	ll ans = 0;
	rep(i, K + 1) mad(ans, solve(i));
	print(ans);
}

