ll pow_mod(ll n, ll k, ll m){ // n^k mod m
    if(k==0){
        return 1;
    } else if(k%2==1){
        return pow_mod(n, k-1, m) * n % m;
    } else {
        ll t=pow_mod(n, k/2, m);
        return t * t % m;
    }
}

