#include<bits/stdc++.h>
using namespace std;

const int MAX = 200001;
const int mod = 998244353;

long long fac[MAX], fac_inv_mod[MAX],inv_mod[MAX];

void comb_init(){
    fac[0] = fac[1] = 1;
    fac_inv_mod[0] = fac_inv_mod[1] = 1;
    inv_mod[1]=1;
    for(int i=2; i<MAX; i++){
        fac[i] = fac[i-1] * i % mod;
        inv_mod[i] = mod - inv_mod[mod%i] * (mod / i) % mod;
        fac_inv_mod[i] = fac_inv_mod[i-1] * inv_mod[i] % mod;
    }
}

long long comb(int n, int k){
    if(n<k) return 0;
    if(n<0 || k<0) return 0;
    return fac[n] * (fac_inv_mod[k] * fac_inv_mod[n-k] % mod) % mod;
}

int main(){
    comb_init();
    int n,m,k; cin>>n>>m>>k;
    long long ans = 0;
    long long base = m;
    for (int i=0; i<n-k-1;i++) base=base*(m-1)%mod;

    for(int j=0; j<=k; j++){
        long long tmp = base*comb(n-1,k-j) % mod;
        ans = (ans+tmp)%998244353;
        base = base*(m-1)%mod;
    }
    if (ans < 0) ans += 998244353;
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using lint     = long long;
const lint inf = 1LL << 60;
const lint mod = 998244353;

struct mint {
    lint v;
    lint _mod;
    mint() : v(0) {}
    mint(signed v, lint _mod = mod) : v(v), _mod(_mod) {}
    mint(lint t, lint _mod = mod) : _mod(_mod) {
        v = t % _mod;
        if (v < 0)
            v += _mod;
    }

    mint pow(lint k) {
        mint res(1), tmp(v);
        while (k) {
            if (k & 1)
                res *= tmp;
            tmp *= tmp;
            k >>= 1;
        }
        return res;
    }
    static mint add_identity() { return mint(0); }
    static mint mul_identity() { return mint(1); }
    mint inv() { return pow(_mod - 2); }

    mint &operator+=(mint a) {
        v += a.v;
        if (v >= _mod)
            v -= _mod;
        return *this;
    }
    mint &operator-=(mint a) {
        v += _mod - a.v;
        if (v >= _mod)
            v -= _mod;
        return *this;
    }
    mint &operator*=(mint a) {
        v = v * a.v % _mod;
        return *this;
    }
    mint &operator/=(mint a) { return (*this) *= a.inv(); }

    mint operator+(mint a) const { return mint(v) += a; };
    mint operator-(mint a) const { return mint(v) -= a; };
    mint operator*(mint a) const { return mint(v) *= a; };
    mint operator/(mint a) const { return mint(v) /= a; };

    mint operator-() const { return v ? mint(_mod - v) : mint(v); }

    bool operator==(const mint a) const { return v == a.v; }
    bool operator!=(const mint a) const { return v != a.v; }
    bool operator<(const mint a) const { return v < a.v; }
};
ostream &operator<<(ostream &os, mint m) { return os << m.v; }

struct Combination {
    vector<lint> fac, finv, inv;
    Combination(lint maxN) : fac(maxN + 100), finv(maxN + 100), inv(maxN + 100) {
        maxN += 100; // for safety
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1]            = 1;
        for (lint i = 2; i <= maxN; ++i) {
            fac[i]  = fac[i - 1] * i % mod;
            inv[i]  = mod - inv[mod % i] * (mod / i) % mod;
            finv[i] = finv[i - 1] * inv[i] % mod;
        }
    }
    lint operator()(lint n, lint k) {
        if (n < k)
            return 0;
        if (n < 0 || k < 0)
            return 0;
        return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    lint n, m, k;
    cin >> n >> m >> k;
    Combination nCk(400000);
    mint ret = 0;
    for (lint i = 0; i <= k; ++i) {
        mint t = nCk(n - 1, i);
        t *= mint(m - 1).pow(n - 1 - i);
        ret += t;
    }
    ret *= m;
    cout << ret << "\n";
    return 0;
}

