   for (int i = 2; i < MAX ; i++){
       fac[i] = fac[i - 1] * i % MOD;
       inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
       finv[i] = finv[i - 1] * inv[i] % MOD;
   }
}
ll choose(ll n, ll k){
   if (n < k) return 0;
   if (n < 0 || k < 0) return 0;
