  }

  Comb C(N);

  LL sum = 0;
  for (int k = 0; k <= K; ++k) {
    LL v = f[N-k-1] % kMod;
    LL c = C.nCr(N-1, k) % kMod;
    v = (v * c) % kMod;
    sum = (sum + v) % kMod;
  }
  cout << sum << endl;
}

