template<typename T>
map<T, ll> prime_factorize(T x){  
  map<T, ll> res;
  if(x == 0) return res;
  while(x%2==0){
    x/=2;
    res[2]++;
  }
  for(ll i=3;i*i<=x;i+=2){
    while(x%i==0){
      x/=i;
      res[i]++;
    }
  }
  if(x!=1) res[x]++;
  return res;
}

