ll powmod(int a, int b) {
  a %= mod;
  ll res = 1;
  while (b > 0) {
    if (b % 2 == 1) res = res * a % mod;
    a = a * a % mod;
    b /= 2;
  }
  return res;
}

ll f[200005];
void cominit() {
  f[0] = 1;
  for (int i = 0; i < 200000; i++) f[i + 1] = f[i] * (i + 1) % mod;
}

ll nCr(int n, int r) {
  if (n < r) return 0;
  if (n < 0 || r < 0) return 0;
  return f[n] * powmod(f[r] * f[n - r], mod - 2) % mod;
}

int main() {
  int n, m, k;
  cin >> n >> m >> k;
  cominit();
  ll ans = 0;
  for (int i = 0; i <= k; i++) {
    ll res = nCr(n - 1, i);
    res *= m * powmod(m - 1, n - i - 1) % mod;
    res %= mod;
    ans = (ans + res) % mod;
  }
  cout << ans << endl;
}

