int main() {
    int N, M, K;
    std::cin >> N >> M >> K;

    auto pow = [](long long a, int n) {
        long long res = 1;
        for (; n; n >>= 1) {
            if (n & 1) res = res * a % MOD;
            a = a * a % MOD;
        }
        return res;
    };

    std::vector<long long> fact(N + 1), inv_fact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++)
        fact[i] = fact[i - 1] * i % MOD;
    inv_fact[N] = pow(fact[N], MOD - 2);
    for (int i = N; i > 0; i--)
        inv_fact[i - 1] = inv_fact[i] * i % MOD;

    auto comb = [&fact, &inv_fact](int n, int r) {
        if (n < r) return 0LL;
        long long tmp = inv_fact[n - r] * inv_fact[r] % MOD;
        return fact[n] * tmp % MOD;
    };

    long long ans = 0;
    for (int i = 0; i <= K; i++) {
        ans += (comb(N - 1, i) * M) % MOD * pow(M - 1, N - i - 1) % MOD;
        ans %= MOD;
    }

    std::cout << ans << "\n";
}

