ll pwr(ll b, ll e)
{
	ll ans = 1;
	while (e)
	{
		if (e & 1)
			ans = (ans * b) % md;
		b = (b * b) % md;
		e >>= 1;
	}
	return ans;
}
void pre()
{
	fac[0] = ifac[0] = 1;
	for (int i = 1; i <= 200000; ++i)
	{
		fac[i] = (i * fac[i - 1]) % md;
		ifac[i] = (ifac[i - 1] * pwr(i, md - 2)) % md;
	}
}
ll ncr(ll n, ll r)
{
	if (r > n)
		return 0;
	ll ans = fac[n];
	ans = (ans * ifac[r]) % md;
	ans = (ans * ifac[n - r]) % md;
	return ans;
}
