ll fastpow(ll b, ll e)
{
    ll res = 1;
    while(e)
    {
        if(e&1)
            res = mul(res, b);
        e >>= 1;
        b = mul(b, b);
    }
    return res;
}

ll INV(ll x)
{
    return fastpow(x, MOD-2);
}

void pre()
{
    fact[0] = 1;
    inv_fact[0] = 1;
    for(ll i=1 ; i<maxS ; i++)
    {
        fact[i] = mul(fact[i-1], i);
        inv_fact[i] = INV(fact[i]);
    }
}

ll nCr(ll n, ll r)
{
    ll res = mul(fact[n], inv_fact[r]);
    res = mul(res, inv_fact[n-r]);
    return res;
}

