int main() {
  const int MOD = 998244353;
  int N, M, K;
  cin >> N >> M >> K;

  // i == 0, always M patterns
  // i > 0, M - 1 or M
  // choose K pairs of M patterns in i > 0, N-1 blocks;

  vector<vector<long long>> dp(N);
  rep(i, N) {
    dp[i].resize(K+1);
  }

  dp[0][0] = M;
  rep(i, N-1) {
    rep(j, K+1) {
      dp[i+1][j] += dp[i][j] * (M-1);  // different color
      dp[i+1][j] %= MOD;

      if (j+1 <= K) {
        dp[i+1][j+1] += dp[i][j] * 1;  // same color
        dp[i+1][j+1] %= MOD;
      }
    }
  }

  long long sum = 0;
  rep(i, K+1) {
    sum += dp[N-1][i];
    sum %= MOD;
  }

  cout << sum << endl;

