ll modpow(ll a,ll n,ll &mod){
  if(!n) return 1;
  ll x = modpow(a,n/2,mod)%mod;
  x *=x%mod;
  if(n%2==1)x*=a%mod;
  return x%mod;
}

ll modpow3(ll a,ll n,ll &mod){
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

