        cnt = (cnt * i) % mod;
        f[i] = base * ksm(cnt, mod - 2) % mod;
    }

    for (int i = 0; i <= k; i++){
        ans += (m % mod * ksm(m - 1, n - i - 1)) % mod * f[i];
        ans %= mod;
    }
    cout << ans << endl;
}
