//前処理
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;//i!(mod MOD)を計算
        inv[i] = MOD - inv[MOD%i]* (MOD / i) % MOD;//iの逆元を計算
        finv[i] = finv[i - 1] * inv[i] % MOD;//i!(mod MOD)の逆元を計算
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;//nCk = n!/(k!*(n-k)!)を計算
}
long long mod_pow(long long x, long long n){//x^nのmodのmodを計算する
    if(n == 0) return 1;
    if(n % 2 == 0){
        long long t = mod_pow(x, n / 2) % MOD; //nが偶数のときはx^n = x^(n / 2) * x^(n / 2)
        return t * t % MOD;
    } 
    return x * mod_pow(x, n - 1)% MOD;//nが奇数のときはx^n = x * x^(n - 1)
}
int main(){
    COMinit();
    long long N, M, K;
    cin >> N >> M >> K;
    long long ans = 0;
    for(long long i = 0; i <= K; i++){
        ans += ((M*mod_pow(M - 1, N - 1 - i)) % MOD * COM(N - 1, i))%MOD;
        ans = (ans+MOD) % MOD;
    }
    cout << ans << endl;
}

