		:m_size(size)
	{
		m_bit.resize(m_size);
	}

	void add(lint a, lint w) noexcept { for (lint x = a; x <= m_size; x += (x & -x)) m_bit[x] += w; }

	lint sum(lint a) const noexcept {
		lint res = 0;
		for (lint x = a; x > 0; x -= (x & -x)) res += m_bit[x];
		return res;
	}
};

