long long qmod(long long a,long long b,long long mod)  //快速幂
{
	long long ans=1;
	a=a%mod;
	while(b)
	{
		if(b&1==1)
			ans=ans*a%mod;
		a=a*a%mod;
		b>>=1;
	}
	return ans;
}
ll POW(ll a,ll b,ll p)
{
	ll ans = 1;
	while(b){
		if(b&1)
			ans = (ans%p*a%p) % p;
		a = (a%p*a%p) % p;
		b >>= 1;
	}
	return ans%p;
}
ll C(ll n,ll m,ll p)
{
	if(m > n)return 0;
	if(m == n)return 1;
	if(m > n - m)m = n - m;
	ll a = 1, b = 1 ;
	for(ll i = 0 ; i < m ; i++){
		a = a * (n - i) % p;
		b = b * (i + 1) % p;
	}
	return a * POW(b,p-2,p) % p;
}
