    }
    REP(i,1,n+1){
        modinv[i] = (modinv[i-1] * power(i,mod-2)) % mod;
    }

    ll ans = 0;
    ll val = 1;
    REP(i,0,n-1){
        val = (val * (m-1)) % mod;
    }
    ll val1 = power(m-1,mod-2);

    REP(i,0,k+1){
        if(n-1-k < 0) continue;

        ll p1 = (((fact[n-1]*modinv[i]) % mod)* modinv[n-1-i]) % mod;

        ll p = (((m*p1) % mod) * val) % mod;
        ans = (ans + p) % mod;
        val = (val * val1) % mod;
    }
    if(m == 1){
        if(n-1-k == 0){
            ans = 1;
        }
    }
    cout<<ans<<endl;
	return 0;
}

