    int now = 0;
    rep(i, k) now = G[now][0];
    cout << now + 1 << endl;
    return;
  } */

  vector<int> seen(n);
  int pos = -1; // cycle 中に含まれる頂点 pos
  stack<int> hist; // 訪問履歴
  auto dfs = [&](auto&& dfs, int v, int p) -> void {
    seen[v] = 1;
    hist.push(v);
    for (auto nv : G[v]) {
      if (nv == p) continue;
      if (seen[nv] == 2) continue;
      if (seen[nv] == 1) { // cycle を検出
        pos = nv;
        return;
      }
      dfs(dfs, nv, v);
      if (pos != -1) return;
    }
    hist.pop();
    seen[v] = 2;
  };
  dfs(dfs, 0, -1);
  if (pos != -1) { // cycle
    // 経路復元, cycle に限らず
    vector<int> cycle;
    while (!hist.empty()) {
      int t = hist.top();
      cycle.eb(t);
      hist.pop();
      if (t == pos) break;
    }
    reverse(all(cycle));
    // cout << cycle << endl;

    int now = 0, cnt = 0;
