        return;
      }
    }
    // cout << "cnt " << cnt << endl;

    k %= sz(cycle);
    // cout << k << endl;
    (k = k - cnt + sz(cycle)) %= sz(cycle);

    cout << cycle[k] + 1 << endl;
    return;
  }

  // 2 頂点ループ
  vector<int> v(n + 5);
  v[1] = G[0][0];
  rep3(i, 2, n + 5) v[i] = G[v[i - 1]][0];
  // cout << v << endl;
  rep3(i, 2, n + 5) {
    if (v[i] == v[i - 2]) {
      k %= 2;
      (k = k - i % 2 + 2) %= 2;
      if (k % 2 == 0) cout << v[i] + 1 << endl;
      else cout << v[i + 1] + 1 << endl;
      return;
    }
  }
}

