long long int mpow(int m, int k)
{
    if (k == 1)
    {
        return m;
    }
    else
    {
        if (k % 2 == 1)
        {
            long long int a = mpow(m, k / 2);
            return (a * a * m) % big;
        }
        else
        {
            long long int a = mpow(m, k / 2);
            return (a * a) % big;
        }
    }
}

void COMinit()
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
    {
        fac[i] = fac[i - 1] * i % big;
        inv[i] = big - inv[big % i] * (big / i) % big;
        finv[i] = finv[i - 1] * inv[i] % big;
    }
}

long long int COM(long long int n, long long int k)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    long long int res = 1;
    for (int i = 0; i < k; i++)
    {
        res *= (n - i);
        res %= big;
    }
    return res * (finv[k] % big) % big;
}

