class m_int{
    public:
    int_fast32_t MOD = prime;
    int_fast32_t d=0;
    m_int(int val=0){
        if (val >= MOD) { val %= MOD; } else if (val < 0) { val %= MOD; val += MOD; }d = val;
    }
    m_int operator =(constexpr m_int x){
        this->d = x.d;
        return *this;
    }
    m_int operator+(const m_int another){
        m_int tmp;
        if(d+another.d>MOD){
            tmp.d = d+another.d-MOD;
            return tmp;
        }
        else{
            tmp.d = d+another.d;
            return tmp;
        }
    }
    m_int operator-(const m_int &another) const{
        m_int tmp;
        if(d-another.d<(int_fast32_t)0){
            tmp.d = d-another.d+MOD;
            return tmp;
        }
        else{
            tmp.d = d-another.d;
            return tmp;
        }
    }
    m_int operator*(const m_int &another) const{
        m_int tmp;
        tmp.d = d*another.d%MOD;
        return tmp;
    }
    m_int operator/(const m_int &another) const{
        m_int tmp;
        tmp.d = d/another.d%MOD;
        return tmp;
    }
    m_int operator+=(const m_int another){
        (*this) = (*this) + another;
        return *this;
    }
    m_int operator-=(const m_int another){
        (*this) = (*this) - another;
        return *this;
    }
    m_int operator*=(const m_int another){
        (*this) = (*this) * another;
        return *this;
    }
    bool operator<(const m_int &another) const{
        return d < another.d;
    }
    bool operator>(const m_int &another) const{
        return d > another.d;
    }
};
