const LL INF = LLONG_MAX;
const LL MOD = 998244353;
const LL N = 2e5+1;

LL powm (LL x, LL p, LL m) {
	LL res = 1;
	x %= m;
	while (p) {
		if (p & 1) {
			res = (res * x) % m;
		}
		x = (x * x) % m;
		p >>= 1;
	}
	return res;
}

LL fac[N], invfac[N];

int main() {
	fastio();

	fac[0] = 1;
	for (LL i = 1; i < N; ++i) {
		fac[i] = (fac[i-1] * i) % MOD;
	}

	invfac[N-1] = powm(fac[N-1], MOD-2, MOD);
	for (LL i = N-2; i >= 0; --i) {
		invfac[i] = (invfac[i+1] * (i+1)) % MOD;
	}

	auto binom = [] (const LL& n, const LL& r) -> LL {
		if (n < r) {
			return 0;
		}
		else {
			LL ans = (((fac[n] * invfac[r]) % MOD) * invfac[n-r]) % MOD;
			return ans;
		}
	};

	LL n, m, k;
	cin >> n >> m >> k;

	LL result = 0;
	for (LL j = 0; j <= k; ++j) {
		LL term = (binom(n-1, j) * m) % MOD;
		term = (term * powm(m-1, n-j-1, MOD)) % MOD;
		result = (result + term) % MOD;
	}
	cout << result << "\n";

}

