constexpr ll mod_num = 998244353;

ll dp1[200001][200001] = {0};
ll dp2[200001][200001] = {0};

ll repeatSquare(ll a,ll n){
	ll answer = 1;

	while(n > 0){
		if(n & 1){	//nが奇数なら先に答えの方にa^1をかけておく事で残りのa^n-1を2分割できるようにしている
			answer = answer * a % mod_num;
		}
		a = a * a % mod_num;
		n = n>>1;	//nを2で割ると同じ
	}
	return answer;
}

ll junretu(ll num,ll p){
	if(dp1[num][p] != 0)return dp1[num][p];
	if(num < p) return 0;
	ll ans = 1;
	REP(i,p){
		ans *= (num - i);
		ans = ans % mod_num;
	}
	return dp1[num][p] = ans;
}

ll conv(ll num,ll p){
	if(dp2[num][p] != 0)return dp2[num][p];
	if(num < p) return 0;
	ll ans = 1;
	for(ll i = 0; i < p; i++){
		ans = ans * (num-i) % mod_num;
		ans = ans * (repeatSquare(i+1,mod_num-2) % mod_num) % mod_num;
	}
	return dp2[num][p] = ans;
}

