}


mod_ll mod_fact(int x)
{
	static vector<mod_ll> memo(1, mod_ll(998244353, 1));

	if(x>=memo.size())
	{
		if(memo.size()==1)
		{
			memo.reserve(200010);
		}
		mod_ll ret=memo.back();
		for(int i=memo.size();i<=x;i++)
		{
			ret*=i;
			memo.push_back(ret);
		}
	}
	return memo[x];
}


mod_ll mod_nCr(int n, int r)
