const int MAXN = 2e5 + 10;
const int mod = 998244353;

int f[MAXN];

int powmod(int a, int p) {
    if (p == 0) return 1;
    if (p == 1) return a % mod;
    int k = powmod(a, p / 2);
    if (p & 1) return (k * k % mod) * a % mod;
    return k * k % mod;
}

int rev(int x) {
    return powmod(x, mod - 2);
}

int C(int n, int k) {
    int ans = f[n];
    ans = (ans * rev(f[n - k])) % mod;
    ans = (ans * rev(f[k])) % mod;
    return ans;
}

