    int ans = (powmod(m - 1, n - 1) * m) % mod;
    for (int i = 1; i <= k; i++) {
        ans += (C(n - 1, i) * m % mod) * powmod(m - 1, n - i - 1) % mod;
        ans %= mod;
    }
    cout << ans;
}
