  rep(i, k+1) {
    ll tmp = m * mod_pow(m-1, n-1-i, MOD) % MOD;
    tmp *= comb(n-1, i);
    tmp %= MOD;

    ans += tmp;
  }

  cout << ans % MOD << endl;

  return 0;
}

