template<long long MOD=1000000007ll>
struct ModCombination{
    vector<long long> f,fi;
    ModCombination(){}
    ModCombination(int N){
        init(N);
    }

    // x^-1
    long long invp(long long x){
        return mod_pow(x,MOD-2);
    }

    long long mod_pow(long long x,long long n){
        long long res=1;
        while(n){
            if(n&1) res=(res*x)%MOD;
            x=(x*x)%MOD;
            n>>=1;
        }
        return res;
    }

    void init(int N){
        f.resize(N+1);
        fi.resize(N+1);
        f[0]=1;
        for(int i=1;i<N+1;i++) f[i]=(f[i-1]*i)%MOD;
        for(int i=0;i<N+1;i++) fi[i]=invp(f[i]);
    }

    // nCr
    long long get(long long n,long long r){
        long long ret=f[n];
        ret=(ret*fi[r])%MOD;
        ret=(ret*fi[n-r])%MOD;
        return ret;
    }
};


// x^n
long long mod_pow(long long x,long long n,long long MOD=1000000007LL){
    long long res=1;
    while(n){
        if(n&1) res=(res*x)%MOD;
        x=(x*x)%MOD;
        n>>=1;
    }
    return res;
}

int main(){
    ll N,M,K; cin >> N >> M >> K;
    ModCombination<mod> C(N+10);
    ll ans = 0;
    for(ll k=0;k<=K;k++){
        ll t =  M * mod_pow(M-1, N-1-k, mod) % mod;
        ll t2 = C.get(N-1,k);
        ll x = t * t2 % mod;
        ans += x;
        ans %= mod;
    }
    cout << ans << endl;
}


