  invfact[0] = 1;
  repi(i, 1, N + 1) {
    fact[i] = fact[i - 1] * i % MOD;
    invfact[i] = invfact[i - 1] * powMod(i, MOD - 2) % MOD;
  }

  ll ans = 0;
  rep(i, K + 1) {
    ll color = M * powMod(M - 1, N - i - 1) % MOD;
    ll place = combMod(N - 1, i);
    ans += color * place % MOD;
    ans %= MOD;
  }

  cout << ans << endl;
}

