llong POW(llong a, llong b){
  if(b == 0) return 1;
  else{
    if(b%2 == 0) return POW(a * a % MOD9, b / 2) % MOD9;
    else return a * POW(a * a % MOD9, b / 2) % MOD9;
  }
}

int main(){
  llong ans = 0;
  llong N, M, K;
  cin >> N >> M >> K;
  llong com = 1;
  for(llong i=0; i<=K; ++i){
    if(i==0 || i==N-1){
      ans += M * POW(M-1, N-1-i) % MOD9;
    }else{
      com *= N - 1 - i + 1;
      com %= MOD9;
      com *= POW(i, MOD9 - 2);
      com %= MOD9;
      ans += M * POW(M-1, N-1-i) % MOD9 * com % MOD9;
    }
  }
  if(ans < 0) ans += MOD9;
  cout << ans%MOD9 << endl;
}

