ll mpow(ll x, ll n){
  //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
  ll ans = 1;
  while(n != 0){
	if(n&1) ans = ans*x % M;
	x = x*x % M;
	n = n >> 1;
  }
  return ans;
}

ll comb(ll a, ll b){ //aCbをmod計算
  if(a == 0 && b == 0)return 1;
