using namespace std;

ll modinv(ll a, ll m = MOD) {
  ll b = m, u = 1, v = 0;
  while(b) {
    ll t = a / b;
    a -= t * b;
    swap(a, b);
    u -= t * v;
    swap(u, v);
  }
  u %= m;
  if(u < 0) u += m;
  return u;
}

ll fact[200001];
ll C(ll n, ll r) {
  return fact[n] * modinv(fact[r]) % MOD * modinv(fact[n - r]) % MOD;
}
ll H(ll n, ll r) { return C(n + r - 1, r); }

