void solve()
{
    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<int>> dp(k + 1, vector<int>(n + 1));
    dp[0][1] = m;
    for (int i = 0; i <= k; i++)
    {
        for (int j = 1; j < n + 1; j++)
        {
            if (i == 0 && j == 1)
            {
                continue;
            }
            if (i == 0)
            {
                dp[i][j] = dp[i][j - 1] * (m - 1);
                dp[i][j] %= MOD;
                continue;
            }
            if (j == 1)
            {
                dp[i][j] = 0;
                continue;
            }
            dp[i][j] = (dp[i - 1][j - 1] * 1) % MOD + (dp[i][j - 1] * (m - 1)) % MOD;
            dp[i][j] %= MOD;
        }
    }
    ll ans = 0;
    for (int i = 0; i <= k; i++)
    {
        ans += dp[i][n];
        ans %= MOD;
    }
    cout << ans << endl;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int T = 1;
    // cin >> T;
    while (T--)
    {
        solve();
    }
    return 0;
}

