	VLL st, inv, sinv;
	stairs(N, st,MOD);
	modinvs(N, inv, sinv, MOD);
	for (LL k = K; k >= 0; k--) {
		LL temp = powa(M-1, N-k-1);
		temp *= Comb(N - 1, k, st, sinv, MOD);
		temp %= MOD;
		ans += temp;
	}
	ans %= MOD;
	ans = (ans * M) % MOD;
	cout << ans << "\n";
	return 0;
}

