const int lmod = 998244353;
ll modpow(ll a, ll b) {
  if (b == 0)
    return 1;
  ll f = modpow(a, b / 2);
  f = (f * f) % lmod;
  if (b & 1)
    f = (f * a) % lmod;
  return f;
}
ll fact(int n) {
  ll f = 1;
  for (int i = 1; i <= n; i++)
    f = (f * i) % lmod;
  return f;
}
inline ll mult(ll a, ll b) { return ((a % lmod) * (b % lmod)) % lmod; }
inline ll sum(ll a, ll b) { return ((a % lmod) + (b % lmod)) % lmod; }
ll ncr(ll n, ll r) {
  ll num = fact(n);
  ll den = mult(fact(r), fact(n - r));
  ll iden = modpow(den, lmod - 2);
  return mult(num, iden);
}
ll solve(ll n, ll m, ll K) {
  ll ans = 0, ncrVal = 1;
  for (ll k = 0; k <= K; k++) {
    ans = sum(ans, mult(mult(m, modpow(m - 1, n - 1 - k)), ncrVal));
    ncrVal = mult(mult(ncrVal, modpow(k + 1, lmod - 2)), n - 1 - k);
  }
  return ans;
}
