const ll mod = 998244353;
ll fact[MAXN], inv[MAXN], finv[MAXN];


ll power(ll a, ll b, ll mod=1e9+7) {
  ll ret = 1;
  while (b) {
    if (b & 1) ret = ret * a;
    b >>= 1;
    a = a * a;

    ret %= mod;
    a %= mod;
  }

  return ret;
}

struct Ncr {
  void build() {
    fact[0] = fact[1] = 1;
    for (int i = 2; i < MAXN; ++i) {
      fact[i] = (i * fact[i-1]) % mod;
    }

    inv[0] = inv[1] = 1;
    for (int i = 2; i < MAXN; ++i) {
      inv[i] = (inv[mod%i] * (mod-mod/i)) % mod;
    }

    finv[0] = finv[1] = 1;
    for (int i = 2; i < MAXN; ++i) {
      finv[i] = (finv[i-1] * inv[i]) % mod;
    }
  }

  ll query(ll n, ll r) {
    return (((fact[n] * finv[n-r]) % mod) * finv[r]) % mod;
  }
};


