ll mpow(ll x, ll n)
{
    ll ans = 1;
    while (n != 0)
    {
        if (n & 1)
            ans = ans * x % MOD;
        x = x * x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll comb(ll n, ll r)
{
    if (n == 0 && r == 0)
    {
        return 1;
    }
    if (n < r || n < 0)
    {
        return 0;
    }
    ll tmp = (fac_inv.at(n - r) * fac_inv.at(r)) % MOD;
    return (tmp * fac.at(n)) % MOD;
}

