int my_upper(vector<int> & v, int X){
  if(v.size() == 0)
    return -1;
   int lo = 0, hi = v.size()-1;
  while(hi-lo > 1){
    int mi = (lo+hi)/2;
    if(v[mi] < X){
      lo = mi+1;
    }
    else
      hi = mi;
  }
  int ans = -1;
  for(int i = hi;i>=lo;i--){
    if(v[i] > X){
      ans = i;
    }
  }
  if(ans != -1 && v[ans] > X){
    return ans;
  }
  else
    return -1;
}
