typedef int64_t Int;

struct Combination{
    Int MOD, MAX_N;
    vector<Int> f, f_inv;

    //---------- 初期化 ----------
    Combination(Int mod, Int max_n){
        MOD = mod;
        MAX_N = max_n;

        f = factorial(MAX_N);
        rep(i,f.size()) f_inv.push_back(inv(f[i]));
    }

    //---------- べき乗 ----------
    Int power(Int a, Int n){
        if(a == 0) return 0;
        if(n == 0) return 1;

        Int res = 1;
        while(n > 0){
            if(n % 2 == 1) res = res * a % MOD;
            a = a * a % MOD;
            n /= 2;
        }
        return res;
    }

    //---------- 逆元 ----------
    Int inv(Int a){
        return power(a, MOD-2);
    }

    //---------- 階乗 ----------
    vector<Int> factorial(Int n){
        vector<Int> res(n+1, 1);
        rep1(i,n) res[i] = i * res[i-1] % MOD;

        return res; // nまでの階乗の配列を返す
    }


    //--------- 組み合わせ ---------
    Int comb(Int n, Int r){
        return (f[n] * f_inv[r] % MOD) * f_inv[n-r] % MOD;
    }
};


