const int mod = 998244353;
const int MX = 5e5+5;
int modpow(int a, int b);

inline int mul(int a, int b) {
    long long res = ((long long)a % mod * b % mod) % mod;
    return (int)res;
}

inline int add(int a, int b) {
    long long res = a + b;
    if(res >= mod) res -= mod;
    return (int)res;
}

inline int sub(int a, int b) {
    long long res = a - b;
    if(res < 0) res += mod;
    return (int)res;
}

long long pw(int a, int b) {
    long long res = 1;
    if(a < 2) return a;
    long long _a = a;
    while(b) {
        if(b % 2) res = res * _a;
        b /= 2;
        _a = _a * _a;
    }
    return res;
}

int modpow(int a, int b) {
    long long res = 1;
    if(a < 2) return a;
    while(b) {
        if(b % 2) res = mul(res, a);
        b /= 2;
        a = mul(a, a);
    }
    return res;
}

int MI(int a) {
    return modpow(a, mod - 2);
}

int fac[MX];
int ifac[MX];

void pre() {
    fac[0] = fac[1] = 1;
    ifac[0] = ifac[1] = 1;
    for(int i=2; i<MX; i++) fac[i] = mul(fac[i-1], i);
    for(int i=2; i<MX; i++) ifac[i] = MI(fac[i]);
}

long long C(int n, int k) {
    long long res = 1;
    res = mul(res, fac[n]);
    res = mul(res, ifac[k]);
    res = mul(res, ifac[n-k]);
    return res;
}

long long P(int n, int k) {
    long long res = 1;
    res = mul(res, fac[n]);
    res = mul(res, ifac[n-k]);
    return res;
}

