void solve(int TC) { 
    int n, m, k; cin >> n >> m >> k;
    int ans = 0;
    int totalPairs = n - 1;
    for(int i=0; i<=k; i++) {
        int diffColor = totalPairs - i;
        int partitions = diffColor + 1;
        int cur = C(totalPairs, diffColor);
        cur = mul(cur, m);
        cur = mul(cur, modpow(m - 1, partitions - 1));
        ans = add(ans, cur);
    }
    cout << ans << endl;
}

signed main() {

    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(12);

    pre();

    int T = 1;
    //cin >> T;
    for(int i=1; i<=T; i++) {
        solve(i);
    }
    return 0;

}

