	for (int i = 1; i <= N; i++) {
		power[i] = power[i - 1] * (M - 1);
		power[i] %= large_P;

		combination[i] = combination[i - 1] * (N - i);
		combination[i] %= large_P;

		combination[i] *= my_pow(i, large_P - 2, large_P);
		combination[i] %= large_P;
	}




	for(int i = 0; i <= K; i++) {
		dp[i] = power[N - 1 - i];
		dp[i] *= M;
		dp[i] %= large_P;

		dp[i] *= combination[i];
		dp[i] %= large_P;
	}

	rep(i, K + 1) {
		res += dp[i];
		res %= large_P;
	}


