vector<ll> rf;

ll binom(ll n, ll k) {
    if(k < 0) return 0;
    if(k == 0) return 1;
    return (rf[k] * rf[n - k]% MODD * f[n]) % MODD;
}

ll solve() {
    LL(n, m, k);
    f.assign(n + 1, 0);
    rf.assign(n + 1, 0);
    f[0] = 1;
    rf[0] = 1;
    rep(i, 1, n + 1) {
        f[i] = (i * f[i - 1]) % MODD;
        rf[i] = modinv(f[i], MODD);
    }
    ll ans = 0;

    rep(i, 0, k + 1) {
        ans += (binom(n - 1, k - i) * modpow(m - 1, n - (k - i) - 1, MODD)) % MODD;
    }
    ans %= MODD;
    out(m * ans % MODD);
    return 0;
}

