using namespace std;

#define MODNUMBER 998244353

long long pow_mod(long long a, long long n)
{ // a^n mod MODNUMBER
	long long result = 1;
	long long a_i = a;
	long long n_tmp = n;
	while (n_tmp > 0)
	{
		if (n_tmp & 0b1)
		{
			result = (result * a_i) % MODNUMBER;
			// cout << result << "\n";
		}
		a_i = a_i * a_i % MODNUMBER;
		n_tmp = n_tmp >> 1;
	}
	return result;
}

long long fact_mod(long long k)
{ // k! mod MODNUMBER

	long long result = 1;
	for (int i = 1; i <= k; i++)
	{
		result = (result * i) % MODNUMBER;
	}
	return result;
}
vector<long long> fact_mod_vector(long long k)
{ // k! mod MODNUMBER

	vector<long long> result(k + 1, 1);
	result[0] = 1;
	for (int i = 1; i <= k; i++)
	{
		result[i] = (result[i - 1] * i) % MODNUMBER;
	}
	return result;
}

long long inv_mod(long long k)
{ // k^(-1) mod MODNUMBER

	return pow_mod(k, MODNUMBER - 2);
}

