long long comb_mod(long long n, long long k, vector<long long> *fact_result)
{ // nCk mod MODNUMBER
	return ((*fact_result)[n] *
			inv_mod(((*fact_result)[k] * (*fact_result)[n - k]) % MODNUMBER)) %
		   MODNUMBER;
}

