int power(int x, unsigned int y, int p = MOD)  
{  
    int res = 1;     // Initialize result  

    x = x % p; // Update x if it is more than or  
                // equal to p 

    if (x == 0) return 0; // In case x is divisible by p; 

    while (y > 0)  
    {  
        // If y is odd, multiply x with result  
        if (y & 1)  
            res = (res*x) % p;  

        // y must be even now  
        y = y>>1; // y = y/2  
        x = (x*x) % p;  
    }  
    return res;  
}  

int nCr(int n, int r){
    int num = f[n];
    int den = power(f[n-r],MOD-2);
    int den2 = power(f[r],MOD-2);

    num = (num*den)%MOD;

    return (num*den2)%MOD;
}

