const int MAX = 210000;
const int MOD = 998244353;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit(){
  fac[0]=fac[1]=1;
  finv[0]=finv[1]=1;
  inv[1]=1;
  for(int i=2; i<MAX; i++){
    fac[i]=fac[i-1]*i%MOD;
    inv[i]=MOD-inv[MOD%i]*(MOD/i)%MOD;
    finv[i]=finv[i-1]*inv[i]%MOD;
  }
}

ll COM(int n, int k){
  if(n<k)
    return 0;
  if(n<0 || k<0)
    return 0;
  return fac[n]*(finv[k]*finv[n-k]%MOD)%MOD;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(0);
  COMinit();

  ll N, M, K; cin >> N >> M >> K;
  ll ans = 0;
  vector<ll> Z(N+1, 1);
  rep(i, N){
    Z[i+1] = Z[i] * (M-1);
    Z[i+1] %= MOD;
  }
  for(ll k=K; k>=0; k--){
//cout << "k;"<<k<<" ans:"<<ans<<endl;
//M * (M-1)^(N-1-K)*(N-1)CK
    ll tmp = M * Z[N-1-k];
    tmp %= MOD;
    tmp *= COM(N-1, k);
    tmp %= MOD;
    ans += tmp;
    ans %= MOD;
  }
  cout << ans << endl;
}

