// a^n mod m を求める
Int modpow(Int a, Int n, Int m) {
    Int b, t;
    if (n == 0) return 1;
    a %= m;
    b = a * a;
    b %= m;
    t = modpow(b, n / 2, m);
    if (n % 2 != 0) {
        t *= a;
        t %= m;
    }
    return t;
}


