VLL haba_yuusen_kyori(VVLL &V, LL n ){
  LL N = V.size();
  VLL D(N,-1);
  queue<pair<LL,LL>> Q;
  Q.push({n,0});
  while(!Q.empty()){
    auto q = Q.front();
    Q.pop();
    LL no = q.first;
    LL d  = q.second;
    D[no] = d;
    for(auto v : V[no]){
      if(D[v]!=-1){
        continue;
      }
      D[v] = d+1;
      Q.push({v,d+1});
    }    
  }
  return move(D);  
}  

