ll fact[mx],inv[mx];

ll power(ll b,ll n)
{
	if(n==0) return 1;
	ll ans=power(b,n/2)%mod;
	ans*=ans;
	ans%=mod;
	if(n%2) ans*=b;
	ans%=mod;

	return ans;
}

void make()
{
	fact[0]=1;
	inv[0]=1;
	for(ll i=1;i<(ll)mx;i++)
	{
		fact[i]=fact[i-1]*i;
		fact[i]%=mod;
		inv[i]=power(fact[i],mod-2);
	}
}

ll ncr(int n,int r)
{
	if(n<r) return 0;
	if(n<0 || r<0) return 0;

	ll ans=fact[n]*inv[n-r];
	ans%=mod;
	ans*=inv[r];
	ans%=mod;

	return ans;
}

