long long int mpow(int m, int k)
{
    if (k == 1)
    {
        return m;
    }
    else if (k == 0)
    {
        return 1;
    }
    else
    {
        if (k % 2 == 1)
        {
            long long int a = mpow(m, k / 2);
            return (a * a * m) % big;
        }
        else
        {
            long long int a = mpow(m, k / 2);
            return (a * a) % big;
        }
    }
