//拡張拡張Euclidの互除法による(階乗)逆元の求め方
//O(N)
void stairs(long long N, vector<long long>& st, long long mod = 1e9 + 7) {
	st.resize(N + 1, 1);
	for (long long n = 2; n <= N; n++) {
		st[n] = (st[n - 1] * n) % mod;
	}
}

LL stair(LL N, LL mod = 1e9 + 7) {
	LL ans = 1;
	for (LL n = 2; n <= N; n++)ans = (ans * n) % mod;
	return ans;
}

void modinvs(long long N, vector<long long>& inv, vector<long long>& sinv, long long mod = 1e9 + 7) {
	inv.resize(N + 1);
	sinv.resize(N + 1);
	inv[1] = 1;
	sinv[0] = 1;
	sinv[1] = 1;
	for (int n = 2; n <= N; n++) {
		inv[n] = mod - (inv[mod % n] * (mod / n)) % mod;
		sinv[n] = (sinv[n - 1] * inv[n]) % mod;
	}
}

//(n^(-1),(n!)^(-1))
PLL modinvs(LL N, LL mod = 1e9 + 7) {
	vector<LL> inv(N + 1);
	inv[1] = 1;
	LL sinv = 1;
	for (int n = 2; n <= N; n++) {
		inv[n] = mod - (inv[mod % n] * (mod / n)) % mod;
		sinv = (sinv * inv[n]) % mod;
	}
	return PLL(inv[N], sinv);
}

long long Comb(long long n, long long k, vector<long long>& st, vector<long long>& sinv, long long mod = 1e9 + 7) {
	if (n < 0)return 0;
	if (k > n || k < 0)return 0;
	long long ans = st[n];
	ans = (ans * sinv[n - k]) % mod;
	ans = (ans * sinv[k]) % mod;
	return ans;
}

LL Comb(LL N, LL K, LL mod = 1e9 + 7) {
	if (N < 0)return 0;
	if (K > N || K < 0)return 0;
	if (K == 0 || K == N)return 1;
	LL ans = stair(N, mod);
	ans = (ans * modinvs(N - K).second) % mod;
	ans = (ans * modinvs(K).second) % mod;
	return ans;
}


int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	LL N, M, K;
	cin >> N >> M >> K;
	Modint ans(0);
	Modint base(M - 1);
	VLL st, inv, sinv;
	stairs(N, st,MOD);
	modinvs(N, inv, sinv, MOD);
	for (LL k = K; k >= 0; k--) {
		Modint temp = modpow(base, N-k-1);
		temp *= Modint(Comb(N - 1, k, st, sinv, MOD));
		ans += temp;
	}
	ans *= Modint(M);
	cout << ans.v << "\n";
	return 0;
}

