long binary_square(long x, long n){
    long m = MOD;
    long ans = 1;
    while(n){
        if(n%2==1){
            ans = ans * x % m;
        }
        x = x * x % m;
        n >>= 1;
    }
    return ans % m;
}

long factorial(long n){
