ll C(ll n, ll r)
{
    if(n == r || r == 0)
    {
        return 1;
    }
    if(mp[{n, r}])
    {
        return mp[{n, r}];
    }

    return mp[{n, r}] = (C(n - 1, r - 1) % MOD + C(n - 1, r) % MOD) % MOD;
}

ll power(ll X, ll N)
{
    ll res = 1;

    while(N > 0)
    {
        if(N & 1)
        {
            res *= X;
            res %= MOD;
        }

        X = X * X;
        X %= MOD;

        N = N >> 1;
    }

    return res;
}

ll calc(ll N, ll M, ll K)
{
    ll ans = 1;
    ans *= M;

    ans *= power(M - 1, N - K - 1);
    ans %= MOD;

    ans *= C(N - 1, K);
    ans %= MOD;

    return ans;

}

