template <typename T>
T power(T a, long long b) {
  T r = 1;
  while (b > 0) {
    if (b & 1) {
      r *= a;
    }
    a *= a;
    b >>= 1;
  }
  return r;
}

template <typename T>
T inverse(T a, T m) {
  a %= m;
  if (a < 0) {
    a += m;
  }
  T b = m, u = 0, v = 1;
  while (a) {
    T t = b / a;
    b -= a * t;
    swap(a, b);
    u -= v * t;
    swap(u, v);
  }
  if (u < 0) {
    u += m;
  }
  return u;
}

template <int _P>
struct modnum {
  static constexpr int P = _P;
 private:
  int v;
 public:
  modnum() : v(0) { }
  modnum(long long _v) {
    v = (int) (_v % P);
    if (v < 0) {
      v += P;
    }
  }
  explicit operator int() const {
    return v;
  }
  bool operator==(const modnum& o) const {
    return v == o.v;
  }
  bool operator!=(const modnum& o) const {
    return v != o.v;
  }
  modnum inverse() const {
    return modnum(::inverse(v, P));
  }
  modnum operator-() const {
    return modnum(v ? P - v : 0);
  }
  modnum operator+() const {
    return *this;
  }
  modnum& operator++() {
    v++;
    if (v == P) {
      v = 0;
    }
    return *this;
  }
  modnum& operator--() {
    if (v == 0) {
      v = P;
    }
    v--;
    return *this;
  }
  modnum operator++(int) {
    modnum r = *this;
    ++*this;
    return r;
  }
  modnum operator--(int) {
    modnum r = *this;
    --*this;
    return r;
  }
  modnum& operator+=(const modnum& o) {
    v += o.v;
    if (v >= P) {
      v -= P;
    }
    return *this;
  }
  modnum operator+(const modnum& o) const {
    return modnum(*this) += o;
  }
  modnum& operator-=(const modnum& o) {
    v -= o.v;
    if (v < 0) {
      v += P;
    }
    return *this;
  }
  modnum operator-(const modnum& o) const {
    return modnum(*this) -= o;
  }
  modnum& operator*=(const modnum& o) {
    v = (int) ((long long) v * o.v % P);
    return *this;
  }
  modnum operator*(const modnum& o) const {
    return modnum(*this) *= o;
  }
  modnum& operator/=(const modnum& o) {
    return *this *= o.inverse();
  }
  modnum operator/(const modnum& o) const {
    return modnum(*this) /= o;
  }
};

