    for(int i = 0;i<=n;++i)
        num[i] = -1;
    LL ans = 0;
    for(LL i = 0;i<=k;++i){
        ans = (ans+(lucas(n-1,i,mod)*quick_pow(m-1,n-i-1,mod))%mod)%mod;
    }
    ans = (ans*m)%mod;
    cout << ans << "\n";
    return 0;
}

