void solve()
{
	READ(llong, N, M, K);
	if (N == 1)
	{
		WRITE(M);
		return;
	}

	if (M == 1)
	{
		WRITE(K < N - 1 ? 1 : 0);
		return;
	}

	llong mod = 998244353;
	ModCombination MOD(200000, mod);

	llong ans = 0;
	REP(i, K+1)
	{
		//DEBUG("i", i, M * modPow(M - 1, N - i - 1, mod), MOD.Combination(N - 1, i));
		ans += M * modPow(M - 1, N - i - 1, mod) % mod * MOD.Combination(N - 1, i) % mod;
		ans %= mod;
	}
	WRITE(ans);
}

