using namespace std;
const int mod = 998244353, p = mod;
LL fpow(LL a, LL b, LL p = mod){LL ans = 1; a %= p; while(b) {if(b & 1) ans = ans * a % p; b >>= 1; a = a * a % p;} return ans;}
LL inv(LL x) {
    return fpow(x, mod - 2, mod);
}
LL gcd(LL a, LL b){return b == 0 ? a : gcd(b, a % b);}
const int N = 2e5 + 7;
LL n, m, k, jc[N];
void init(int n)  //预处理 阶乘 及 逆元(p为质数) O(n)
{
    jc[0] = jc[1] = 1;
    for (int i = 2; i <= n; ++i) {
        jc[i] = (LL)jc[i - 1] * i % p;
    }
}
LL C(LL a, LL b)  //组合数（p为质数）
{
    if (b > a)
        return 0;
    return (LL)jc[a] * fpow(jc[b], p - 2, p) % p * fpow(jc[a - b], p - 2, p) % p;
}
void solve() {
    scanf("%d %d %d", &n, &m, &k);
    LL ans = 0;
    for(int i = 0; i <= min(k, n - 1); i ++) {
        LL cur = C(n - 1, i) * m % mod * fpow(m - 1, n - i - 1) % mod;
        (ans += cur) %= mod;
    }
    printf("%lld\n", (ans % mod + mod) % mod);
}
int main() {
    int T = 1;
    // scanf("%d", &T);
    init(N - 1);
    while(T --) 
        solve();
    return 0;
}

