template <typename number>
pair<number, number> extended_euclid(number a, number b)
{
  number r0, r1, a0, a1, b0, b1;
  r0 = a; r1 = b;
  a0 = 1; a1 = 0;
  b0 = 0; b1 = 1;
  while (r1>0) {
    number q1 = r0 / r1;
    number r2 = r0 % r1;
    number a2 = a0 - q1 * a1;
    number b2 = b0 - q1 * b1;
    r0 = r1 ; r1 = r2;
    a0 = a1 ; a1 = a2;
    b0 = b1 ; b1 = b2;
  }
  number c = r0;
  a = a0; //x
  b = b0; //y
  return  {a, c};
}

template  <typename number>
number inverse_N(number a, number N)
{
  pair<number, number> result = extended_euclid(a, N);
  if(result.first < 0)
  {
    result.first = result.first + N;
  }
  return result.first;
}

ll n, m, k;

ll calc() {
  ll result = m;
  rep(i, n - 1) {
    result = (result * (m - 1)) % mod;
  }
  return result;
}

int main()
{
  cin >> n >> m >> k;
  ll base = calc();
  if(base == 0 ) base = 1;
  ll minv = inverse_N(m - 1, mod);
  ll numerator = n - 1;
  ll denominator = 1;
  ll cand = numerator;
  ll result = base;
  for(int i = 1; i <= k; i++) {
    ll temp = base * minv;
    temp %= mod;
    temp *= cand;
    temp %= mod;
    result += temp;
    result %= mod;
    //分母の更新
    numerator = (numerator * (n - 1 - i)) % mod;
    //分子の更新
    denominator = (denominator * (i + 1)) % mod;
    //組み合わせの更新
    cand = numerator * inverse_N(denominator, mod);
    cand %= mod;
    //減る候補を更新
    minv = minv * inverse_N(m - 1, mod);
    minv %= mod;
  }
  cout << result << endl;
}

