long powm(long x, long a, long m)
{
    long s = 1;
    long p = x % m;
    for (int i = 0; i < 32; i++)
    {
        if((a >> i) & 1){
            s = (s * p) % m;
        }
        p = p*p % m;
    }
    return s;
}

long invm(long x, long m)
{
    return powm(x, m-2, m);
}

vector<long> ntbl, dtbl;
void conbm_init(long a, long m)
{
    ntbl.resize(a+1, 1);
    dtbl.resize(a+1, 1);
    long n = 1, d = 1;
    for (long i = 0; i < n; i++)
    {
        n = (n * (a - i)) % m;
        d = (d * (i + 1)) % m;
        ntbl[i] = n;
        dtbl[i] = d;
    }
}
long conbm(long a, long b, long m)
{
    if(ntbl.size() != a+1) conbm_init(a, m);
    return (ntbl[b-1] * invm(dtbl[b-1], m)) % m;
}

