template<int MOD> struct Fp {
	long long val;
	constexpr Fp(long long v = 0) noexcept : val(v % MOD) { // dinh nghia Fp(v) = (v % MOD)
		if (val < 0) val += MOD;
	}
	constexpr int getmod() { return MOD; }  // get MOD
	constexpr Fp operator - () const noexcept {return val ? MOD - val : 0;} // phep toan "-"
	constexpr Fp operator + (const Fp& r) const noexcept { return Fp(*this) += r; } // phep toan "+="
	constexpr Fp operator - (const Fp& r) const noexcept { return Fp(*this) -= r; } // phep toan "-="
	constexpr Fp operator * (const Fp& r) const noexcept { return Fp(*this) *= r; } // phep toan "*="
	constexpr Fp operator / (const Fp& r) const noexcept { return Fp(*this) /= r; } // phep toan "/="
	constexpr Fp& operator += (const Fp& r) noexcept {val += r.val; if (val >= MOD) val -= MOD; return *this;}
	constexpr Fp& operator -= (const Fp& r) noexcept {val -= r.val;	if (val < 0) val += MOD; return *this;}
	constexpr Fp& operator *= (const Fp& r) noexcept {val = val * r.val % MOD;return *this;}
	constexpr Fp& operator /= (const Fp& r) noexcept { // dinh nghia phep chia, dung thuat toan inverse
		long long a = r.val, b = MOD, u = 1, v = 0;
		while (b) {long long t = a / b;	a -= t * b; swap(a, b);	u -= t * v; swap(u, v);	}
		val = val * u % MOD; if (val < 0) val += MOD;
		return *this;
	}
	constexpr bool operator == (const Fp& r) const noexcept {return this->val == r.val;}
	constexpr bool operator != (const Fp& r) const noexcept {return this->val != r.val;}
	friend constexpr ostream& operator << (ostream &os, const Fp<MOD>& x) noexcept {return os << x.val;}
	friend constexpr Fp<MOD> modpow(const Fp<MOD> &a, long long n) noexcept {
		if (n == 0) return 1; 
		auto t = modpow(a, n / 2); 
		t = t * t; if (n & 1) t = t * a;
		return t;
	}
};

template<class T> struct BiCoef { // tinh C(k, n)
	vector<T> fact_, inv_, finv_;
	constexpr BiCoef() {}
	constexpr BiCoef(int n) noexcept : fact_(n, 1), inv_(n, 1), finv_(n, 1) { init(n); }
	constexpr void init(int n) noexcept {
		fact_.assign(n, 1), inv_.assign(n, 1), finv_.assign(n, 1);
		//int MOD = fact_[0].getmod(); // thuong trong code se co global const nay
		for(int i = 2; i < n; i++){
			fact_[i] = fact_[i-1] * i; // i!
			inv_[i] = -inv_[MOD%i] * (MOD/i); // inverse cua so i
			finv_[i] = finv_[i-1] * inv_[i]; // factorial inverse
		}
	}
	constexpr T C(int k, int n) const noexcept {  // tinh C(k, n)
		if (n < k || n < 0 || k < 0) return 0; 
		return fact_[n] * finv_[k] * finv_[n-k];
	}
	constexpr T fact(int n) const noexcept {if (n < 0) return 0;return fact_[n];}
	constexpr T inv(int n) const noexcept {if (n < 0) return 0;return inv_[n];}
	constexpr T finv(int n) const noexcept {if (n < 0) return 0;return finv_[n];}
};

