        int res = 1ll * m * qpow(m - 1, t - 1) % MOD;
        res = 1ll * res * fac[n - 1] % MOD * inv[t - 1] % MOD * inv[n - t] % MOD;
        ans = (ans + res) % MOD;
    }
    cout << ans << '\n';
}

