ll mybig::pow(ll x, ll n){ //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll mybig::C(ll a, ll b){ //aCbをmod計算
    if(mybig::calcurated_fac == false)
    {
        Calcfac();
    }
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

void mybig::Calcfac()
{
    fac.resize(fac_size + 1);
    ifac.resize(fac_size + 1);
    fac[0] = 1;
    ifac[0] = 1;
    for (long long i = 0; i < fac_size; i++)
    {
        fac[i + 1] = fac[i] * (i + 1) % MOD;               // n!(mod MOD)
        ifac[i + 1] = ifac[i] * mybig::pow(i + 1, MOD - 2) % MOD;
    }
    mybig::calcurated_fac = true;
}

long long mybig::mod(ll a, ll b)
{
	return a - std::floor((long double)a / b) * b;
}
