template <typename T>
T mystd::LCM(T a, T b)
{
    return a * b / GCD(a, b);
}

template <typename T>
T mystd::GCD(T a, T b)
{
    if (a < b)
    {
        T tmp = a;
        a = b;
        b = tmp;
    }

    T r = a % b;
    while (r != 0)
    {
        a = b;
        b = r;
        r = a % b;
    }
    return b;
}

template <typename T>
T mystd::LCM(std::vector<T> a)
{
    if (a.size() < 2)
    {
        return 1;
    }
    else
    {
        T lcm = LCM(a[0], a[1]);
        for (size_t i = 2; i < a.size(); i++)
        {
            T lcm_temp = LCM(lcm, a[i + 1]);
            if (lcm < lcm_temp)
            {
                lcm = lcm_temp;
            }
        }
        return lcm;
    }
}

template <typename T>
T mystd::GCD(std::vector<T> a)
{
    if (a.size() < 2)
    {
        return 1;
    }
    else
    {
        T gcd = GCD(a[0], a[1]);
        for (size_t i = 2; i < a.size(); i++)
        {
            T gcd_temp = GDC(gcd, a.list[i + 1]);
            if (gcd < gcd_temp)
            {
                gcd = gcd_temp;
            }
        }
        return gcd;
    }
}

template <typename T>
T mystd::LCM(mylist<T> a)
{
    if (a.list.size() < 1)
    {
        return 1;
    }
    else
    {
        T gcd = GCD(a[0], a[1]);
        for (size_t i = 1; i < a.size() - 1; i++)
        {
            T gcd_temp = GCD(gcd, a[i + 1]);
            if (gcd < gcd_temp)
            {
                gcd = gcd_temp;
            }
        }
        return gcd;
    }
}

template <typename T>
T mystd::GCD(mylist<T> a)
{
    if (a.list.size() < 1)
    {
        return 1;
    }
    else
    {
        T gcd = GCD(a.list[0], a.list[1]);
        for (size_t i = 1; i < a.list.size() - 1; i++)
        {
            T gcd_temp = GCD(gcd, a.list[i + 1]);
            if (gcd < gcd_temp)
            {
                gcd = gcd_temp;
            }
        }
        return gcd;
    }
}

long long mystd::pow(long long x, long long n)
{
    long long ans = 1;
    while (n != 0)
    {
        if (n & 1)
            ans = ans * x % MOD;
        x = x * x % MOD;
        n = n >> 1;
    }
    return ans;
}

template <typename T>
T mystd::C(T n, T r)
{
    if (!calcurated_fac) Calcfac(fac_size);
    if (n == 0 && r == 0)
        return 1;
    if (n < r || n < 0)
        return 0;
    T tmp = ifac[n - r] * ifac[r] % MOD;
    return tmp * fac[n] % MOD;
}

void mystd::Calcfac(size_t size)
{
    fac.resize(size + 1);
    ifac.resize(size + 1);
    fac[0] = 1;
    ifac[0] = 1;
    for (long long i = 0; i < size; i++)
    {
        fac[i + 1] = fac[i] * (i + 1) % MOD;               // n!(mod MOD)
        ifac[i + 1] = ifac[i] * pow(i + 1, MOD - 2) % MOD; // k!^{MOD-2} (mod MOD) ←累乗にmpowを採用
    }
    calcurated_fac = true;
}

