long long power(long long X,long long P,long long M)
{
  long long s;

  if(P==0)
  {
    return 1;
  }
  else if(P%2==0)
  {
    s=power(X,P/2,M);
    s*=s;
    s%=M;
    return s;
  }
  else
  {
    s=power(X,P-1,M)*X;
    s%=M;
    return s;
  }
}

long long comb(long long X,long long Y)
{
  long long s,t,u;

  s=1;
  for(t=1;t<=Y;t++)
  {
    s*=t;
    s%=MOD;
  }

  s=power(s,MOD-2,MOD);

  u=1;
  for(t=X;t>=X-Y+1;t--)
  {
    u*=t;
    u%=MOD;
  }

  s=s*u;
  s%=MOD;

  return s;
}

