template <long long MOD> class Combination_calcurator {
  using ll = long long;
  using modint = mod::modInt<MOD>;

private:
  std::vector<modint> fac;
  std::vector<modint> facinv;

public:
  Combination_calcurator(ll max) {
    fac.resize(max + 1);
    facinv.resize(max + 1);
    fac[0] = 1;
    for (int i = 1; i <= max; i++) {
      fac[i] = fac[i - 1] * modint(i);
    }
    facinv[max] = fac[max].inverse();
    for (int i = max - 1; i >= 0; i--) {
      facinv[i] = facinv[i + 1] * modint(i + 1);
    }
  }
  modint calc(ll n, ll r) { return fac[n] * facinv[r] * facinv[n - r]; }
};

constexpr ll MOD = 998244353;
using modint = mod::modInt<MOD>;
int main() {
  modint m;
  int n, k;
  cin >> n >> m >> k;
  auto com = Combination_calcurator<MOD>(n);
  auto ans = modint(0);
  for (int i = 0; i <= k; i++) {
    ans += m * (m - modint(1)).pow(n - i - 1) * com.calc(n - 1, i);
  }
  cout << ans << endl;
}

