ll const N = 2e5+1;
vector<ll> fact(N, 1), inv(N, 1);

ll power(ll x, ll y)  
{  
    int res = 1;     // Initialize result  

    x = x % MOD; // Update x if it is more than or  
                // equal to p 

    if (x == 0) return 0; // In case x is divisible by p; 

    while (y > 0)  
    {  
        // If y is odd, multiply x with result  
        if (y & 1)  
            res = (res*x) % MOD;  

        // y must be even now  
        y = y>>1; // y = y/2  
        x = (x*x) % MOD;  
    }  
    return res;  
}  


ll ncr(ll a, ll b)
{
    ll ans = fact[a];
    ans = (ans * inv[b]) % MOD;
    ans = (ans * inv[a - b]) % MOD;
    return ans;
}

void solve()
{
    for(int i = 2; i < N; i++)
    {
        fact[i] = (fact[i - 1] * i) % MOD;
        inv[i] = power(fact[i], MOD - 2);
    }

   ll n,m,k;
   cin>>n>>m>>k;
   ll ans = 0;
   for(int i=0;i<=k;i++)
   {
        ll p = ncr(n-1,i)%MOD;
        p = (p*m)%MOD;
        ll temp = power(m-1,n-i-1)%MOD;
        p = (temp*p)%MOD;
        ans = (ans + p)%MOD;
   }
   cout<<ans;
}

