ll fac[M], inv[M];
ll n, m, k;
ll quick_mod(ll k, ll b) {
    ll ans = 1;
    while(b) {
        if(b & 1) ans = ans * k % mod;
        k = k * k % mod;
        b >>= 1;
    }
    return ans;
}
void init(){
    fac[0] = 1;
    for(int i = 1; i <= N; i++) fac[i] = i * fac[i - 1] % mod;
    inv[N] = quick_mod(fac[N], mod - 2);
    for(int i = N - 1; i >= 0; i--) inv[i] = inv[i + 1] * (i + 1) % mod;
}
ll C(ll x, ll y) {
    return (fac[x] * inv[y] % mod) * inv[x - y] % mod;
}
int main(){
    init();
    scanf("%lld%lld%lld", &n, &m, &k);
    ll res = 0;
    for(ll t = n - k; t <= n; t++) {
        res = (res + (C(n - 1, t - 1) * m % mod) * quick_mod(m - 1, t - 1) % mod) % mod;
    }
    printf("%lld\n", res);
    return 0;
}

