    mint operator+(const mint& a) const { mint res(*this); return res+=a; }
    mint operator-(const mint& a) const { mint res(*this); return res-=a; }
    mint operator*(const mint& a) const { mint res(*this); return res*=a; }
    bool operator==(const int& n) const { mint a(n); return this->x == a.x; }
    bool operator==(const ll& n) const { mint a(n); return this->x == a.x; }
    bool operator!=(const int& n) const { mint a(n); return this->x != a.x; }
    bool operator!=(const ll& n) const { mint a(n); return this->x != a.x; }
    mint pow(ll t) const {
        mint res = mint(1),a(*this);
        while(t > 0) {
            if(t&1) res *= a;
            t >>= 1;
            a *= a;
        }
        return res;
    }
    // for prime mod
    mint inv() const { return pow(mod-2); }
    mint& operator/=(const mint& a) { return (*this) *= a.inv(); }
    mint operator/(const mint& a) const { mint res(*this); return res/=a; }
};
ostream& operator<<(ostream& os,const mint& m) { return os << m.x; }

class combination {
  vector<mint> fact, ifact;
public:
  combination(int n):fact(n+1),ifact(n+1) {
    assert(n < mod);
    fact[0] = mint(1);
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*mint(i);
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*mint(i);
  }
  mint operator()(int n, int k) {
    if (k < 0 || k > n) return mint(0);
    return fact[n]*ifact[k]*ifact[n-k];
  }
} comb(100010);

