ll q_pow( ll x, ll y ){
    if( y == 0 )
        return 1;
    if( y == 1 ){
        return x % MOD;
    }
    ll ret = 1;
    while( y ){
        if( ( y & 1ll ) )
            ret = ret * x % MOD;
        x = x * x % MOD;
        y >>= 1ll;
    }
    return ret;
}

