template<typename IntType>
IntType all_pattern(IntType a, IntType b, IntType mod_ = 1000000007) {
  IntType res = 1;
  for (a %= mod_; b; a = a * a % mod_, b >>= 1) {
    if (b & 1) res = res * a % mod_;
  }
  return res;
}

struct fast_combination {
    fast_combination(int n, int mod_) :fac(n+1, 0), finv(n+1, 0), inv(n+1, 0), mod_(mod_) {
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        for (int i=2; i<=n; ++i) {
            fac[i] = fac[i-1] * i % mod_;
            inv[i] = mod_ - inv[mod_%i] * (mod_/i) % mod_;
            finv[i] = finv[i-1] * inv[i] % mod_;
        }
    }

    int64_t operator()(int n, int k) {
        if (n > fac.size()-1) return -1;
        if (n < k || n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n-k] % mod_) % mod_;
    }

    int64_t multichoose(int n, int k) {
        return this->operator ()(n+k-1, k);
    }

    std::vector<int64_t> fac, finv, inv;
    int mod_;
};

