ll modpow(ll a, ll b)
{
    if (b == 0) return 1;
    ll u = modpow(a, b / 2);
    u = (u * u)%mod;
    if (b%2) u = (u * a)%mod;
    return u;
}

void fillup(ll n)
{
    fact[0] = 1;
    for (ll i = 1; i <= n; i++) {
        fact[i] = ((fact[i - 1]%mod) * (i%mod))%mod;
    }
    finv[n] = modpow(fact[n], mod - 2);
    for (ll i = n - 1; i >= 0; i--) {
        finv[i] = finv[i + 1] * (i + 1)%mod;
    }
}

ll ncr(ll n, ll r)
{
    ll ans = fact[n] * finv[r]%mod * finv[n - r];
    return (ans%mod + mod)%mod;
}

