ll Tree[4*maxn];
void update_max(int node,int start,int end,int i,ll val){
	if(start==end){
		Tree[node]=val;
		return;
	}
	int mid=((start+end)>>1);
	if(i<=mid)
		update_max(2*node+1,start,mid,i,val);
	else
		update_max(2*node+2,mid+1,end,i,val);
	//According to the question,change from here
	Tree[node]=(Tree[2*node+1]+Tree[2*node+2])%mod;
}
ll query_max(int node,int start,int end,int l,int r){ 
	if(start>end||end<l||start>r)
		return 0;//0 in case of sum , high value in case of min , low value in case of max and soooo on 
	if(start>=l&&end<=r)
		return(Tree[node]);
	int mid = (start+end)/2 ; 
	ll p1 = query_max(node*2+1, start, mid, l,r);
	ll p2 = query_max(node*2+2, mid+1, end , l,r);
	return (p1+p2)%mod;
}
