class Mo {
public:

    const int mod = MOD;

    inline int add(int a, int b) const {
        a += b;
        return a < mod ? a : a - mod; 
    }

    inline int sub(int a, int b) const {
        a -= b;
        return a < 0 ? a + mod : a;
    }

    inline int mul(long long a, long long b) const {
        a *= b;
        return a < mod ? a : a - a / mod * mod;
    }

    inline int pow_mod(long long a, long long b) const {
        long long res = 1;
        res %= mod;
        while (b) {
            if (b & 1) {
                res = mul(res, a);
            }
            a = mul(a, a);
            b >>= 1;
        }
        return res;
    }

    inline int inv(int a) const {
        return pow_mod(a, mod - 2);
    }

    vector<int> fact, finv;
    void init_comb_1(int n = 1000000) {
        fact.resize(n + 5);
        finv.resize(n + 5);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = mul(fact[i - 1], i);
        }
        finv[n] = inv(fact[n]);
        for (int i = n - 1; i >= 0; i--) {
            finv[i] = mul(finv[i + 1], i + 1);
        }
    }

    ////  M
    //
    ////  N

    // if n is not big, don't forget init_comb_1 !
    inline int C1(int n, int m) {
        if (n < m) return 0;
        return mul(mul(fact[n], finv[m]), finv[n - m]);
    }

    // if n is big
    inline int C2(int n, int m) {
        if (n < m) return 0;
        if (m > n - m) {
            m = n - m;
        }
        int a = 1, b = 1;
        for (int i = 1; i <= m; i++) {
            a = mul(a, n - i + 1);
            b = mul(b, i);
        }
        return mul(a, inv(b));
    }
} mo;

