const int64_t M = 998244353, G = 3; // 998244353,1004535809,469762049 : G = 3

int64_t qpow(int64_t a, int64_t b) {
	if(b == 0) return 1;
	int64_t t = qpow(a, b/2);
	t = t * t % M;
	if(b & 1) return t * a % M;
	else return t;
}

int64_t inv(int64_t n) {
	return qpow(n, M - 2);
}

int64_t pos[N];

void NTT(int64_t* a, int64_t k, bool inverse = false) {
	for(int64_t i=1;i<(1<<k);i++) pos[i] = (pos[i>>1] >> 1) | ((i & 1) << (k - 1));
	for(int64_t i=0;i<(1<<k);i++) if(pos[i] < i) swap(a[pos[i]], a[i]);
	for(int64_t len = 2; len <= (1 << k); len <<= 1) {
		int64_t omega = qpow(G, (M - 1) / len);
		if(inverse) omega = inv(omega);
		for(int64_t i = 0; i < (1 << k); i += len) {
			int64_t cur = 1;
			for(int64_t j = i; j < i + len / 2; j++) {
				int64_t l = a[j], r = a[j+len/2];
				a[j] = (l + r * cur % M) % M;
				a[j+len/2] = (l - r * cur % M + M) % M;
				cur = cur * omega % M;
			}
		}
	}
}

