int constexpr p = 998244353;
using Mod = modulo<p>;

factorial<p, 200010> const fact;

using namespace std;

void solve(int N, int M, int K, vector<Mod> const &powtab) {
  Mod sum = 0;
  for (int c = 0; c <= K; ++c) {
    Mod x = fact.comb(N-1, c);
    int l = N - c;
    sum += x * Mod(M) * powtab[l-1];
  }
  cout << sum.data() << "\n";
}

int main() {
  // cout << fixed << setprecision(10);

  int N, M, K;
  cin >> N >> M >> K;

  if (M == 1) {
    cout << (K >= N - 1 ? 1 : 0) << endl;
    return 0;
  }

  vector<Mod> powtab(N+4);
  powtab[0] = 1;
  for (int i = 1; i < N; ++i) {
    powtab[i] = powtab[i-1] * Mod(M-1);
  }

  solve(N, M, K, powtab);
  return 0;
}

