long long modpow(long long a, long long n, long long p)
{
    long long out = 1;
    while (n)
    {
        if (n & 1)
        {
            out = out * a % p;
        }
        a = a * a % p;
        n >>= 1;
    }
    return out;
}

long long modinv(long long a, long long p)
{
    long long b = p, u = 1, v = 0;
    while (b)
    {
        long long t = a / b;
        a -= t * b;
        std::swap(a, b);
        u -= t * v;
        std::swap(u, v);
    }
    u %= p;
    if (u < 0)
        u += p;
    return u;
}

