    int n,m,k;
    cin>>n>>m>>k;
    COM_initialize();
    mint paint = m ;
    for (int i = n-1 ; i >= 0; --i) {
        if(i <= k ){
            mint group = COM(n-1,i);
            ans += group * paint;
        }
        paint *= (m-1);
    }

    cout<<ans.x<<endl;

    return 0;
}

