ll mod=998244353;
vector <ll> factorials;
ll modExp(ll x, ll n)
{
    if (n==0) return 1;
    if (n==1) return x%mod;
    ll ans = modExp(x,n/2);
    ans = (ans*ans)%mod;
    if (n%2) ans*=x;
    return ans%mod;
}

ll modInv(ll a)
{
    return modExp(a, mod-2)%mod;
}

ll choose(ll n, ll k)
{
    ll num = factorials[n];
    ll den=(modInv(factorials[n-k])*modInv(factorials[k]))%mod;
    return (num*den)%mod;
}

