{
    fact[0] = facti[0] = 1;
    for (long long int i = 1; i < N; i++)
    {
        fact[i] = (fact[i - 1] * i) % M;
        facti[i] = cans(1, fact[i]);
    }
    long long int n, m, k;
    cin >> n >> m >> k;
    long long int ans = 0;
    for (long long int i = 0; i <= k; i++)
    {
        long long int tans = power(m - 1, n - 1 - i);
        tans = (tans * fact[n - 1]) % M;
        tans = (tans * facti[n - 1 - i]) % M;
        tans = (tans * facti[i]) % M;
        ans = (ans + tans) % M;
    }
    ans = (ans * m) % M;
    cout<<ans;
}

