    fac[0] = 1;
    facInv[0] = 1;
    for(int i=1; i<=MX; i++){
        fac[i] = fac[i-1]*i;
        facInv[i] = inv(fac[i]);
    }
}

// C(n, k)
mi choose(int n, int k){
    if(k<0) return 0;
    if(n<0) return 0;
    if(k>n) return 0;

    mi res = fac[n]*facInv[n-k]*facInv[k];
    return res;
}


