typedef long long ll;

int N, M, K;

ll f[MAX_N], rf[MAX_N];
ll inv(ll x) {
    ll res = 1;
    ll k = MOD - 2;
    ll y = x;
    while (k) {
        if (k & 1) res = (res * y) % MOD;
        y = (y * y) % MOD;
        k /= 2;
    }
    return res;
}
void init() {
    f[0] = 1;
    for (int i = 1; i < MAX_N; i++) f[i] = (f[i - 1] * i) % MOD;
    for (int i = 0; i < MAX_N; i++) rf[i] = inv(f[i]);
}
ll comb(int n, int k) {
    ll a = f[n]; // = n!
    ll b = rf[n-k]; // = (n-k)!
    ll c = rf[k]; // = k!

    ll bc = (b * c) % MOD;

    return (a * bc) % MOD;
}

ll modpow(ll a, ll n) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % MOD;
    a = a * a % MOD;
    n >>= 1;
  }
  return res;
}

ll modinv(ll a) {
  return modpow(a, MOD - 2);
}

void solve() {
  ll ans = 0;

  for (int k = 0; k <= K; k++) {
    ll n = modpow(M-1, N-k-1);
    n = (n * M) % MOD;
    ans = ans + (n * comb(N-1, k)) % MOD;
  }

  printf("%lld\n", ans % MOD);
}

