using namespace std;
typedef long long ll;

ll power(ll n, ll p, ll mod) {
    ll ans = 1;
    while (p > 0) {
        if (p & 1) ans = ans * n % mod;
        n = n * n % mod;
        p >>= 1;
    }
    return ans;
}

class CombinationN {
   public:
    CombinationN(int n, int maxk) {
        N = n; K = maxk + 1; 
        fac = new ll[K];
        numerator = new ll[K];

        fac[0] = 1; numerator[0] = 1;
        REP(i, 1, K) {
            fac[i] = fac[i - 1] * i % MOD;
            numerator[i] = numerator[i - 1] * (n - i + 1) % MOD; 
        }
    }

    ll cnr(int k) {
        if (N - k < k) return cnr(N - k);
        return numerator[k] * power(fac[k], MOD - 2, MOD) % MOD;
    }

   private:
    int N, K;
    ll *fac, *numerator;
};

int main() {
    int N, M, K; cin >> N >> M >> K;

    CombinationN comb(N - 1, K);

    ll ans = 0;
    REP(k, 0, K + 1) ans = (ans + ((comb.cnr(k) * M) % MOD * power(M - 1, N - 1 - k, MOD)) % MOD) % MOD; 
    cout << ans << endl;

    return 0;
}

