ll mod_pow(ll x, ll n, ll mod){
    //xのn乗を計算するのにn乗を2進表記にして計算
    //x^22 = x^16 + x^4 + x^2
    ll ret=1;
    while(n>0){
        if(n&1){
            ret=(ret*x)%mod;//答えに付加
        }
        x=(x*x)%mod;//2乗
        n >>=1;
    }
    return ret;
}

