ll repeatSquare(ll a,ll n){
	ll answer = 1;

	while(n > 0){
		if(n & 1){	//nが奇数なら先に答えの方にa^1をかけておく事で残りのa^n-1を2分割できるようにしている
			answer = answer * a % mod_num;
		}
		a = a * a % mod_num;
		n = n>>1;	//nを2で割ると同じ
	}
	return answer;
}

