ll pow_f(ll b, ll e, ll M = ::M2) {
    ll ans = 1;
    b = b % M;
    while (e) {
        if (e&1) {
            ans = (ans * b) % M;
        }
        b = (b * b) % M;
        e >>= 1;
    }
    return ans;
}

ll modinv(ll x) {
    return pow_f(x, M2-2, M2);
}

ll nCr(ll n, ll r) {
    if (r > n || n < 0 || r < 0) { return 0; }
    if (n == r || r == 0) { return 1; }
    r = min(r, n-r);
    ll ans = 1;
    for (ll i = 1; i <= r; ++i) {
        ans = (ans * ((n-i+1)% M2)) % M2;
        ans = (ans * modinv(i)) % M2; 
    }
    return ans % M2;
}

