vpll to_prime(ll n) {
	vpll prime_factor;
	for (ll i = 2; i * i <= n; i++) {
		ll count = 0; while (n % i == 0) { count++; n /= i; }
		if (count) { pair<ll, ll> temp = { i, count };	prime_factor.emplace_back(temp); }
	}
	if (n != 1) { pair<ll, ll> temp = { n, 1 }; prime_factor.emplace_back(temp); }
	return prime_factor;
}

