// 二部グラフ判定(O(E))  edge -> リスト
//---------------------------------------------------------------
bool is_bipartite(vvll edge)
{
	ll N = edge.size();
	vll color(N, -1);
	color[0] = 0;
	queue<ll> Q;
	Q.push(0);
	while (!Q.empty())
	{
		ll now = Q.front();
		Q.pop();

		for (int i : edge[now])
		{
			if (color[i] == -1)
			{
				color[i] = (color[now] == 0 ? 1 : 0);
				Q.push(i);
			}
			else if (color[i] == color[now])
			{
				return false;
			}
		}
	}
	return true;
}

