const long long MOD = 998244353;

ll powm(ll x, ll y, ll mod = 1e9 + 7)
{
    ll ans = 1;
    while (y > 0) {
        if (y % 2) {
            ans = (ans * x) % mod;
        }
        x = (x * x) % mod;
        y >>= 1;
    }
    return ans;
}

ll nCr(ll n, ll r, ll mod = 1e9 + 7)
{
    static ll prev_r = 1e9 + 7;
    static ll x = 1;
    static ll y = 1;

    ll start_i = 0;
    if (prev_r <= r) {
        start_i = prev_r;
    } else {
        x = 1;
        y = 1;
    }
    prev_r = r;
    for (ll i = start_i; i < r; i++) {
        x *= n - i;
        x %= mod;
    }
    for (ll i = start_i; i < r; i++) {
        y *= i + 1;
        y %= mod;
    }

    ll res = x * powm(y, mod - 2, mod);
    return res % mod;
}

void solve(long long N, long long M, long long K)
{
    ll ans = 0;
    for (ll i = 0; i <= K; i++) {
        ll val = M * powm(M - 1, N - i - 1, MOD);
        val %= MOD;
        val *= nCr(N - 1, i, MOD);
        val %= MOD;
        ans += val;
        ans %= MOD;
    }
    cout << ans << endl;
}

