typedef long long ll;
const ll MOD = 998244353;

const int MAX = 100001;

long long fac[MAX], finv[MAX], inv[MAX];

ll mpow(ll x, ll n){ //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main()
{
  uint64_t N, M, K;
  cin >> N >> M >> K;

  COMinit();

  uint64_t ans = 0;
  for (uint64_t k=0; k<=K; ++k) {
    uint64_t X = M;
    X *= mpow(M-1,N-1-k) % MOD;
    X %= MOD;
    //cerr << "X:" << X << endl;
    //cerr << N-k << "C" << k << "=" << COM(N-k,k) << endl;
    ans += ((COM(N-1,k)%MOD) * X)%MOD;
    ans %= MOD;
  }

  cout << ans%MOD << endl;

  return 0;
}

