using namespace std;
const int64_t mod = 998244353;
vector<int64_t> fact;
vector<int64_t> finv;

int64_t power(int64_t a, int64_t b) {
  int64_t res = 1;
  while (b > 0) {
    if (b & 1) res = res * a % mod;
    a = a * a % mod;
    b >>= 1;
  }
  return res;
}

int64_t comb(int64_t n, int64_t r) {
  if (n >= r)
    return ((fact[n] * finv[r]) % mod * finv[n - r]) % mod;
  else
    return 0;
}

int main(void) {
  ios::sync_with_stdio(false);
  int64_t N, M, K;
  cin >> N >> M >> K;

  fact.resize(N + 1);
  finv.resize(N + 1);
  fact[0] = 1;
  for (int i = 1; i <= N; ++i) {
    fact[i] = (fact[i - 1] * i) % mod;
  }
  finv[N] = power(fact[N], mod - 2);
  for (int i = N - 1; i >= 0; --i) {
    finv[i] = (finv[i + 1] * (i + 1)) % mod;
  }

  int64_t answer = 0;
  for (int i = 0; i <= K; ++i) {
    // (N-1)C(i)
    int64_t tmp0 = comb(N - 1, i);
    //cout << "comb " << N - 1 << "C" << i << "=" << tmp0 << endl;
    // (M-1)^(N-1-i)
    int64_t tmp1 = power(M-1, N-1-i);
    int64_t tmp = (tmp0 * tmp1) % mod;
    // M * (N-1)C(i) * (M-1)^(N-1-i);
    tmp = M * tmp % mod;
    answer = (answer + tmp) % mod;
  }
  cout << answer << endl;
  return 0;
}

