template <typename T>
class Combination
{
    const vector<T> fact;
    const vector<T> ifact;
    const size_t size;

    vector<T> calc_fact(const size_t n)
    {
        vector<T> ret(n + 1);
        ret[0] = (T)1;
        for (size_t i = 1; i <= n; i++)
        {
            ret[i] = ret[i - 1] * (T)i;
        }
        return ret;
    }

    vector<T> calc_ifact(const size_t n)
    {
        vector<T> ret = calc_fact(n);
        ret[n] = (T)1 / ret[n];
        for (size_t i = n; i > 0; i--)
        {
            ret[i - 1] = ret[i] * (T)i;
        }
        return ret;
    }

public:
    Combination(const long long n) : fact(calc_fact(n)), ifact(calc_ifact(n)), size(n)
    {
    }

    T operator()(const size_t n, const size_t k)
    {
        if (k < 0 || k > n || n > this->size)
        {
            return (T)0;
        }
        return this->fact[n] * this->ifact[k] * this->ifact[n - k];
    }
};

int main()
{
    constexpr long long MOD = 998244353;
    size_t N, M, K;
    cin >> N >> M >> K;

    Mod<MOD> ans = 0;
    Combination<Mod<MOD>> com(N + 5);
    vector<Mod<MOD>> power(N + 5);
    power[0] = 1;
    for (size_t i = 1; i < N; i++)
    {
        power[i] = power[i - 1] * (M - 1);
    }

    for (size_t i = 0; i <= K; i++)
    {
        Mod<MOD> tmp = M * power[N - 1 - i];
        if (i > 0)
        {
            tmp *= com(N - 1, i);
        }
        ans += tmp;
    }

    cout << ans << endl;
}

