  for (size_t i = 2; i < fact_mod.size(); i++) {
    fact_mod[i] = (i * fact_mod[i - 1]) % mod;
    inv_mod[i] = mod - (inv_mod[mod % i] * (mod / i)) % mod;
    inv_fact_mod[i] = (inv_mod[i] * inv_fact_mod[i - 1]) % mod;
  }

  uint32_t ans = 0;
  for (size_t k = 0; k < K + 1; k++) {
