    res *= res;
    res %= MOD;
    if(n%2) res *= a;
    return res%MOD;
}

ll modinv(ll a){
    return modpow(a,MOD-2);
}

ll comb(ll x,ll y,vector<ll> aa){
    ll ans1 = aa[x];
    ll ans2 = aa[y]*aa[x-y]%MOD;
    return ans1*ans2%MOD;
}

int main(){
    ll n,m,k; cin >> n >> m >> k;
    ll ans = 0;
    vector<ll> mod(n);
    mod[0] = 1;
    for(int i = 1;i < n;++i){
        mod[i] = mod[i-1]*(m-1)%MOD;
    }
    vector<ll> ki(n);
    ki[0] = 1;
    for(int i = 1;i < n;++i){
        ki[i] = ki[i-1]*i%MOD;
    }
    for(ll i = 0; i <= k; ++i){
        ll cnt = mod[n-i-1] *m%MOD;
        cnt = cnt * comb(n-1,i,ki) % MOD;
        ans = (ans + cnt) %MOD;
    }
    cout << ans << endl;
}

