struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) { (x *= a.x) %= mod; return *this;}
  mint operator+(const mint a) const { return mint(*this) += a;}
  mint operator-(const mint a) const { return mint(*this) -= a;}
  mint operator*(const mint a) const { return mint(*this) *= a;}
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(mod-2);}
  mint& operator/=(const mint a) { return *this *= a.inv();}
  mint operator/(const mint a) const { return mint(*this) /= a;}
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

struct combination {
  vector<mint> fact, ifact;
  combination(int n):fact(n+1),ifact(n+1) {//階乗、その逆元も存在する。
    assert(n < mod);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
  }
  //nCk
  mint operator()(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n]*ifact[k]*ifact[n-k];
  }
  //nPk
  mint p(int n,int k){
  return fact[n]*ifact[n-k];
  }
  //ABC154F optimize
  //∑(i<=n)nCi
  mint flatcomb(int n){
      return ((mint)2).pow(n);
  }
  //∑(i<=n:i%2==0)nCi
  mint flateven(int n){
      return ((mint)2).pow(n-1);
  }
  //∑(i<=n:i%2==1)nCi
  mint flatodd(int n){
      return ((mint)2).pow(n-1);
  }

  //∑(i<=k)(i+j)Ci
  mint sig1comb(int j,int k){
      return operator()(j+k+1,k);
  }
  //∑(1<=s<=i<=k)(i+j)Ci
  mint sig1rangecomb(int s,int j,int k){
      return sig1comb(j,k)-sig1comb(j,s-1);
  }
  //∑(i<=k)∑(j<=l)(i+j)Ci
  mint sig2comb(int k,int l){
      return operator()(k+l+2,k+1)-1;
  }
  //∑(1<=s<=i<=k)∑(1<=t<=j<=l)(i+j)Ci
  mint sig2rangecomb(int s,int t,int k,int l){
      return sig2comb(k,l)-sig2comb(k,t-1)-sig2comb(s-1,l)+sig2comb(s-1,t-1);
  }

}comb(200005);//100005まで計算（どこまで必要かで変更）

