#include <bits/stdc++.h>
using namespace std;

const int64_t MOD = 998244353;

//mod逆元を使ったnCkの計算(速)
const int64_t MAX = 510000;
//const int64_t MOD = 1000000007;

int64_t fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算
int64_t COM(int64_t n, int64_t k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

//繰り返し二乗法
int64_t pown(int64_t x, int64_t n) { 
  int64_t ans = 1;
  while (n > 0) {
    if ((n & 1) == 1) {
      ans = ans * x;
      ans %= MOD;
    }
    x = x * x;//一周する度にx, x^2, x^4, x^8となる
    x %= MOD;
    n >>= 1; //桁をずらす n = n >> 1
  }
  return ans;
}


int main(){
  int64_t N, M, K;
  cin >> N >> M >> K;
  int64_t ans = 0;
  COMinit();
  for(int i=0; i<=K; i++){
    int64_t plus = M*pown(M-1,N-i-1);
    plus %= MOD;
    plus *= COM(N-1,i);
    plus %= MOD;
    ans += plus;
    ans %= MOD;
  }
  cout << ans << endl;
}

