	for(int i=0;i<=K;i++){
		int t = M;
		t = mod(t * beki(M-1,N-1-i));
		t = mod(t * C.junretsu(N-1-i,i));
		ans = mod(ans + t);
	}

	cout<<ans<<endl;

	return 0;
}

