long long solve (int m, vector<vector<long long>> &d,int n, int k) {
    if(d.at(n).at(k) != 0) return d.at(n).at(k);
    else if(k == 0) {
        long long ans = 1LL;
        for(int i = 0; i < n; i++) {
            ans*=(m-1);
            if(ans >= 998244353) {
                ans %= 998244353;
            }
        }
        d.at(n).at(k) = ans;
        return ans;
    }
    else if(n == 0) {
        d.at(n).at(k) = 1;
        return 1;
    }
    else return ((m-1)*solve(m, d, n-1,k) + solve(m,d,n-1,k-1));
}
