const int maxn = 2e5+5;
const int MOD = 998244353;
int F[maxn], inv[maxn], Finv[maxn];

void init() {
    inv[1] = 1;
    for(int i = 2; i < maxn; ++i) {
        inv[i] = (MOD - MOD / i) * 1ll * inv[MOD % i] % MOD; 
    }
    F[0] = Finv[0] = 1;
    for(int i = 1; i < maxn; i ++){
        F[i] = F[i-1] * 1ll * i % MOD;
        Finv[i] = Finv[i-1] * 1ll * inv[i] % MOD;
    }
}

int comb(int n, int m){   //comb(n, m) C(n, m) 
    if(m < 0 || m > n) return 0;
    return F[n] * 1ll * Finv[n - m] % MOD * Finv[m] % MOD;
}

int pow(int a, int b) {
    int ret = 1;
    while(b) {
        if(b&1) ret = 1LL*ret*a%MOD;
        a = 1LL*a*a%MOD;
        b >>= 1;
    }
    return ret;
}

void run_case() {
    int n, m, k;
    cin >> n >> m >> k;
    init();
    LL ans = 0;
    for(int i = 0; i <= k; ++i) {
        LL tmp = 1LL*m*comb(n-1,i)*pow(m-1, n-1-k);
        ans = (ans + tmp) % MOD;
    }
    cout << ans;
}


