struct binom {
    vl fac, ifac;
    binom(ll N) : fac(N+1), ifac(N+1) {
        fac[0] = 1;
        FOR(i, 1, N+1) fac[i] = (fac[i-1] * i) % MOD;
        ifac[N] = exp(fac[N], MOD-2);
        FORD(i, 0, N) ifac[i] = (ifac[i+1] * (i+1)) % MOD;
    }

    ll get(ll n, ll k) {
        return (((fac[n] * ifac[k]) % MOD) * ifac[n-k]) % MOD;
    }
};

