template <typename T>
T nCk(int n, int k) {
  if (k > n) return 0;
  T ret = 1;
  for (auto i = 0; i < std::min(n - k, k); ++i) {
    ret *= n - i;
    ret /= i + 1;
  }
  return ret;
}

template <typename T>
T power(T x, int n) {
  T ans{1};
  while (n) {
    if (n % 2) ans *= x;
    x *= x;
    n >>= 1;
  }
  return ans;
}

