    if(k == 0) return 1;
    return (rf[k] * rf[n - k]% MODD * f[n]) % MODD;
}

ll solve() {
    LL(n, m, k);
    f.assign(n + 1, 0);
    rf.assign(n + 1, 0);
    f[0] = 1;
