    rep(i, 1, n + 1) {
        f[i] = (i * f[i - 1]) % MODD;
        rf[i] = modinv(f[i], MODD);
    }
    ll ans = 0;

    rep(i, 0, k + 1) {
        ans += (binom(n - 1, k - i) * modpow(m - 1, n - (k - i) - 1, MODD)) % MODD;
    }
    out(m * ans % MODD);
    return 0;
}

