const int mod = 998244353;

ll inv[200010];
ll fac[200010], fac_inv[200010];

ll C(int n, int k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return ((fac[n] * fac_inv[k] % mod) * fac_inv[n - k]) % mod;
}

void comb_init()
{
	int N = 200005;
	inv[1] = 1;

	for (int i = 2; i <= N; ++i) {
		inv[i] = mod - (mod / i) * inv[mod % i] % mod;
	}

	fac[0] = fac_inv[0] = 1;

	for (int i = 1; i <= N; ++i) {
		fac[i] = (fac[i - 1] * i) % mod;
		fac_inv[i] = (fac_inv[i - 1] * inv[i]) % mod;
	}
}

inline ll mod_pow(ll a, ll x, ll m)
{
	if (x == 0) return 1;

	ll res = mod_pow(a, x / 2, m);

	res *= res;
	res %= m;

	if (x % 2) {
		res *= a;
		res %= m;
	}

	return res;
}


int N,M,K;

signed main()
{
	cin >> N >> M >> K;

	comb_init();

	int ans = 0;

	for (int i = 0; i <= K; ++i) {
		int add = 0;

		add = M * mod_pow(M - 1, N - i - 1, mod) % mod;
		add *= C(N - 1, i);

		ans += add;
		ans %= mod;
		//printf("i=%lld, add=%lld\n",i,add);
	}

	cout << ans << endl;
}

