LL qpow(LL base, LL pow) {
    return pow?((pow&1?base:1)*qpow(base*base%MOD, pow/2))%MOD:1;
}
LL qpow2(LL base, LL pow) {
    LL res = 1;
    while(pow) {
        if(pow&1) {
            res = res*base%MOD;
        }
        base = base*base%MOD;
        pow /= 2;
    }
    return res%MOD;
}

