const ll N = 2e5 + 10, MOD = 998244353;
ll ans;
ll fac[N] = {1}, ifac[N] = {1}, ps[N] = {1};
ll C(ll m, ll n){
	return fac[n] * ifac[m] % MOD * ifac[n - m] % MOD; 
}
ll binPow(ll x, ll y){
	ll ans = 1;
	while(y){
		if(y & 1){
			ans = ans * x % MOD;
		}
		x = x * x % MOD;
		y >>= 1;
	}
	return ans;
}
ll sum(ll l, ll r){
	if(l > r)return 0;
	if(l == 0)return ps[r];
	return (ps[r] - ps[l - 1] + MOD) % MOD;
}
void solve(){
	ll n, m, k;
	cin >> n >> m >> k; 
	if(n == k - 1){
		cout << m << '\n';
		return;
	}
	for(int i = 1; i <= n; ++i)ps[i] = ps[i - 1] * (m - 1) % MOD;
	for(int i = 1; i <= n; ++i)ps[i] = (ps[i] + ps[i - 1]) % MOD;
	n --; 
	ll ans = m * binPow(m - 1, n - 1);
	for(int i = 1; i <= k; ++i){
		ll cur = C(i, n) * binPow(2, i - 1) % MOD * sum(n + 1 - i, n) % MOD * m % MOD;
	//	cout << C(i, n) << ' ' << binPow(2, i - 1) << ' ' << sum(n + 1 - i, n) << '\n';
		ans = (ans + cur) % MOD;
	}
	cout << ans << '\n';
}
