const ll MOD = 998244353;

ll ppow(ll a, ll b) {
  a %= MOD;
  ll res = 1;
  while (b) {
    if (b & 1) {
      res = (res * a) % MOD;
    }
    a = (a * a) % MOD;
    b >>= 1;
  }
  return res;
}

const int MAX = 1010101;

long long fac[MAX], finv[MAX], inv[MAX];

void binom_init() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

long long binom(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll N, M, K;

int main() {
  binom_init();
  cin >> N >> M >> K;

  ll ans = 0;
  for (ll k = K; k >= 0; --k) {
    ll comb = binom(N - 1, k);
    ll patterns = M * ppow(M - 1, N - k - 1) % MOD;
    ll add = comb * patterns % MOD;
    ans += add;
    ans %= MOD;
  }
  cout << ans << endl;
}

