  for(int k = 0; k <= K; k++){
    ans += (long long)binom.get(N - 1, k) * M % mod * power(M - 1, N - k - 1) % mod;
    ans %= mod;
  }

  if(ans < 0ll) ans += mod;
  cout << ans << endl;

  return 0;
}

