// {{{ extgcd
template <class T>
struct extgcd_solution {
  T gcd, x, y;
};

template <class T = Z>
constexpr extgcd_solution<T> extgcd(T a, T b) {
  if (b == 0) return { a, 1, 0 };
  if (a < b) {
    auto res = extgcd(b, a);
    return { res.gcd, res.y, res.x };
  }
  auto prev = extgcd(b, a % b);
  return {
    prev.gcd,
    prev.y,
    prev.x - prev.y * (a / b)
  };
}
