template <class T>
class Combinations {
  private:
    vector<T> factorials;
  public:
    Combinations(int maximum): factorials(maximum + 1) {
      factorials[0] = 1;
      for (auto i = 1; i <= maximum; i++)
        factorials[i] = factorials[i - 1] * T(i);
    }
    inline T factorial(int n) {
      return ix(factorials, n);
    }
    inline T permutation(int n, int r) {
      return ix(factorials, n) / ix(factorials, r);
    }
    inline T combination(int n, int r) {
      return ix(factorials, n) / (ix(factorials, r) * ix(factorials, n - r));
    }
    inline T homogeneous(int n, int r) {
      return combination(n + r - 1, r);
    }
};
