    for(int i = 2; i < maxn; ++i) {
        inv[i] = (MOD - MOD / i) * 1LL * inv[MOD % i] % MOD; 
    }
    F[0] = Finv[0] = 1;
    for(int i = 1; i < maxn; i ++){
        F[i] = F[i-1] * 1LL * i % MOD;
        Finv[i] = Finv[i-1] * 1LL * inv[i] % MOD;
    }
}

LL comb(int n, int m){   //comb(n, m) C(n, m) 
    if(m < 0 || m > n) return 0;
    return F[n] * 1LL * Finv[n - m] % MOD * Finv[m] % MOD;
}

LL poww(LL a, LL b) {
    LL ret = 1;
    while(b) {
        if(b&1) ret = 1LL*ret*a%MOD;
        a = 1LL*a*a%MOD;
        b >>= 1;
    }
    return ret;
}

