long long int N, M, K;
long long int MOD = 998244353;

long long int POW(long long int a, long long int k) {
	if (k == 0) { return 1; }
	if (k == 1) { return a; }

	if (k % 2 == 1) { return (a*POW(a, k - 1)) % MOD; }

	long long int tmp = POW(a, k / 2);
	return (tmp*tmp) % MOD;
}

long long int INV(long long int a) {
	return POW(a, MOD - 2);
}

long long int P[200005], IP[200005];

long long int C(int n, int k) {
	long long int ret = P[n];

	ret *= IP[k]; ret %= MOD;
	ret *= IP[n - k]; ret %= MOD;

	return ret;
}

int main(void) {

	cin >> N >> M >> K;

	P[0] = 1;
	for (long long int i = 1; i <= N; i++) {
		P[(int) i] = (P[(int)i - 1] * i) % MOD;
	}

	for (long long int i = 0; i <= N; i++) {
		IP[i] = INV(P[i]);
	}

	long long int ans = 0;

	for (int k = 0; k <= K; k++) {
		long long int tmp = (C((int)N-1, k)*POW(M - 1,N-1- k)) % MOD;
		tmp *= M; tmp %= MOD;
		ans += tmp;
		ans %= MOD;
	}



	cout << ans << endl;


	return 0;
}

