	fac[0] = 1;
	for (long long i = 1; i <= n; ++i) fac[i] = fac[i - 1] * i % p;
	inv[n] = getInv(fac[n], p);
	for (long long i = n - 1; i >= 0; --i) inv[i] = inv[i + 1] * (i + 1) % p;
}

long long C(long long n, long long m) {
	if (m < 0 || m > n) return 0;
	return fac[n] * inv[m] % MOD * inv[n - m] % MOD;
}

