		else{
			ans[i] = ans[i+1] * (M-1);
			ans[i] %= MOD;
		}
		ans1[i] = ans[i] * COM(N-1, i);
		ans1[i] %= MOD;
	}

	rep(i,K+1){
		sum += ans1[i];
		sum %= MOD;
	}
	cout << sum << endl;
}

