const int MOD = 998244353;

int takemod(int a, int mod = MOD){a%=mod;if(a<0)a+=mod;return a;}

int fast_exp(int base, int expo, int mod = MOD) {
	int res=1;
	while(expo>0) {
		if(expo&1) res=(res*base)%mod;
		base=(base*base)%mod;
		expo>>=1;}
	return res;}

int modinv(int a, int mod = MOD){return takemod(fast_exp(takemod(a, mod), mod-2, mod), mod);}


const int N = 2e5 + 10;
int fac[N];
//PICK ONE
bool init = false;
void factorial() {
	fac[0] = 1;
	init = true;
	for(int i = 1; i < N; i++) {
		fac[i] = (fac[i - 1] * i)%MOD;
	}
}
int choose(int n, int k) {
	if(k < 0 or k > n) return 0;
	if(k == 0 or k == n) return 1;
	if(!init) factorial();
	int res = fac[n];
	int den = (fac[k] * fac[n - k])%MOD;
	res = (res * modinv(den))%MOD;
	return res;
}


