#include <bits/stdc++.h>

using namespace std;

const int MOD = 998244353;
const int MAX_N = 2000010;

int64_t fa[MAX_N];  // n! mod MOD
int64_t fb[MAX_N];  // n!^(MOD - 2) mod MOD ≡ 1 / n!

int64_t modpow(int64_t base, int64_t k, int64_t mod) {
  base %= mod;
  int64_t answer = 1;
  while (k > 0) {
    if (k & 1) answer = (answer * base) % mod;
    base = (base * base) % mod;
    k >>= 1;
  }
  return answer;
}

// nCk =  n! / (k! * (n - k)!)
//     ≡ n! * k!^(MOD-2) * (n-k)!^(MOD-2) mod MOD
int64_t nCk(int64_t n, int64_t k, int64_t mod) {
  if (n == 0 || k == 0) return 1;
  if (n < 0 || k < 0) return 0;
  int64_t answer = fa[n];
  answer = answer * fb[k] % mod;
  answer = answer * fb[n - k] % mod;
  return answer;
}

int main() {
  int N, M, K;
  cin >> N >> M >> K;
  N--;

  fa[0] = 1;
  fb[0] = 1;
  for (int i = 0; i + 1 < MAX_N; i++) {
    fa[i + 1] = fa[i] * (i + 1) % MOD;
    fb[i + 1] = fb[i] * modpow(i + 1, MOD - 2, MOD) % MOD;
  }

  int64_t answer = 0;
  for (int k = 0; k <= K; k++) {
    int64_t tmp = (M * nCk(N, k, MOD)) % MOD;
    tmp = tmp * modpow(M - 1, N - k, MOD) % MOD;
    answer = (answer + tmp) % MOD;
  }

  cout << answer % MOD << endl;

  return 0;
}

