  for (int i = 0; i < N; i++) {
    W[i] = make_pair(V[i], i);
  }
  return W;
}

vi divisors(int N) {
  vi ret;
  for (int i = 1; i * i <= N; i++) {
    if (N % i == 0) {
      ret.pb(i);
      if (i * i != N) ret.pb(N / i);
    }
  }
  SORT(ret);
  return ret;
}

map<int, int> prime_factors(int N) {
  map<int, int> ret;
  for (int i = 2; i * i <= N; i++) {
    while (N % i == 0) {
      ret[i]++;
      N /= i;
    }
  }
  if (N != 1) ret[N]++;
  return ret;
}

