LL bin_pow(LL n, LL k) {
  if (k == 0) {
    return 1;
  }

  if (k & 1) {
    return (n * bin_pow(n, k - 1)) % p;
  }

  LL tmp = bin_pow(n, k / 2);
  return (tmp * tmp) % p;
}

LL inv(LL x) { return bin_pow(x, p - 2); }

LL coeff(LL n, LL k) {
  return ((fac[n] * inv_fac[n - k]) % p * inv_fac[k]) % p;
