template<typename A, size_t N> auto max(A (&a)[N], int l = -1, int r = -1) {    set_lr12(l, r, N);    auto res = max(a[l]);    if (l == r) {        return -INF<decltype(res)>();    }    rep(i, l + 1, r)res = max(res, max(a[i]));    return res;}
