  fac_mod((int)(n + 1));
  ifac_mod((int)(n + 1));
  vector<ll> mpow(n, 0);
  vector<ll> ncj(n, 0);
  REP(i, n) {
    mpow[i] = pow_mod((ll)(m - 1), i);
    ncj[i] = nCk_mod((ll)(n - 1), (ll)i);
  }
  ll ans = 0;
  REP(i, k + 1) {
    // cout << mpow[n - 1 - i] << " " << ncj[i] << " "
    //  << ((m * mpow[n - 1 - i]) % MOD * ncj[i]) % MOD << endl;
    ans += ((m * mpow[n - 1 - i]) % MOD * ncj[i]) % MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}

