    {
        power[i] = power[i - 1] * (M - 1);
    }

    for (size_t i = 0; i <= K; i++)
    {
        Mod<MOD> tmp = M * power[N - 1 - i];
        if (i > 0)
        {
            tmp *= com(N - 1, i);
        }
        ans += tmp;
    }

    cout << ans << endl;
}

