int ex_gcd(long long a, long long b, long long& x, long long& y)
{
	if (b == 0)
	{
		x = 1;
		y = 0;
		return a;
	}
	long long ans = ex_gcd(b, a % b, x, y);
	long long tmp = x;
	x = y;
	y = tmp - a / b * y;
	return ans;
}

int mod_inverse(long long a, long long m)
{
	long long x, y;
	ex_gcd(a, m, x, y);
	return (x % m + m) % m;
}


