class TaskE {
private:
	Debugger debugger;
	const int MOD = 998244353;
	vector<int> f;

	int inv(int x){
		int ans = 1;
		int e = MOD-2;
		while(e){
			if(e&1){
				ans = (long long)ans * x % MOD;
			}
			x = (long long) x * x % MOD;
			e/=2;
		}
		return ans;
	}

	int comb(int n, int k){
		int ans = (long long)f[n] * inv(f[k]) % MOD; 
		ans = (long long)ans * inv(f[n-k]) % MOD;
		return ans;
	}

public:

	void solveOne(int it){
		int n, m , k;
		cin >> n >> m >> k;
		f.assign(n+1, 0);
		f[0] = 1;
		for(int i = 1; i <= n; i++){
			f[i] = (long long)f[i-1] * i % MOD;
		}
		vector<int> calc(n+1);
		calc[1] = m;
		for(int i = 2; i <= n; i++){
			calc[i] = (long long) calc[i-1] * (m-1) % MOD;
		}

		int ans = 0;
		for(int pieces = n-k; pieces <= n; pieces++){
			ans += (long long)comb(n-1,pieces-1) * calc[pieces] % MOD;
			ans %= MOD;
		}
		cout << ans << endl;
	}

	void solve(){
		int tc = 1;
		for(int it = 1; it <= tc; it++){
			solveOne(it);
		}
	}
};


