struct Combinations {
    int max, mod;
    VLL fac, finv, inv;

    Combinations(int _max, int _mod) : fac(_max), finv(_max), inv(_max) {
        max = _max;
        mod = _mod;
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        REP2(i, 2, max) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = mod - inv[mod % i] * (mod / i) % mod;
            finv[i] = finv[i - 1] * inv[i] % mod; 
        }
    }

