}

mint mpow(ll a, ll b){ // a^b
  if(b == 0){
    return 1;
  }
  mint p = 1;
  if(b % 2 == 0){
    p = mpow(a, b/2) * mpow(a, b/2);
  }
  else{
    p = mpow(a, b/2) * mpow(a, b/2) * a;
  }
  return p;
}

