//Power with MOD: O(logp)
template<typename T>
T mod_pow(T a, int p)
{
	if (p == 0)return 1;
	else if (p == 1)return a;
	else if (p % 2 == 0)
	{
		ll h = mod_pow(a, p / 2);
		return h * h % MOD;
	}
	else return (mod_pow(a, p - 1) * a) % MOD;
}

//Combination using factorial: O(n)
struct comb_fact
{
	int N;
	vector<ll> fact, fact_inv;
	comb_fact(int n):N(n)
	{
		fact = vector<ll>(N+1,1);
		fact_inv = vector<ll>(N+1,1);
		rep(i, n)
		{
			fact[i+1] = (fact[i]*ll(i+1)) % MOD;
			fact_inv[i+1]=(fact_inv[i]*mod_pow(ll(i+1),MOD-2)) % MOD;
		}
	};

	ll comb(ll n, ll m)
	{
		return (((fact[n]*fact_inv[m]) % MOD) * fact_inv[n-m]) % MOD;
	}
};


void solve()
{
	ll n, m, k;
	cin >> n >> m >> k;
	comb_fact cf(n);
	vector<ll> a(n+1);
	a[0] = m;
	rep(i, n)a[i+1] = (a[i]*(m-1)) % MOD;
	ll ans = 0;
	rep(i, k+1)
	{
		ans += (a[n-1-i]*cf.comb(n-1,i)) % MOD;
		ans %= MOD;
	}
	cout << ans << endl;
	return;
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

