/**
 * @title Mod Combination
 * @brief 前計算O(N + \log mod)$ で実際に計算するときはO(1)$
 */
template<class T>
struct ModComb {
	vector<T> fact;
	vector<T> facti;
	ModComb(int n) : fact(n+1), facti(n+1) {
		fact[0] = 1;
		for (int i = 1; i < n + 1; i++) {
			fact[i] = fact[i-1] * i;
		}
		facti[n] = 1 / fact[n];
		for (int i = n-1; i >= 0; i--) {
			facti[i] = facti[i+1] * (i + 1);
		}
	}
	T C(int n, int r) const {
		if(n < 0 || r < 0 || n < r) return 0;
		return fact[n] * facti[r] * facti[n-r];
	}
	T P(int n, int r) const {
		if(n < 0 || r < 0 || n < r) return 0;
		return fact[n] * facti[n-r];
	}
	T H(int n, int r) const {
		if(n < 0 || r < 0) return 0;
		return C(n + r - 1, r);
	}
};
using modcomb = ModComb<modint>;

signed main(){
	int N, M, K; cin >> N >> M >> K;
	modcomb mc(2e6);
	auto f = [&](int r) {
		int n = N - 1;
		modint res = mc.C(n, r);
		res *= modint(M-1).power(r);
		return res * M;
	};
	modint res = 0;
	rep(i, K+1) {
		int r = N - 1 - i;
		res += f(r);
	}
	cout << res << endl;
	return 0;
}

