long long pow_mod(long long a, long long b, long long c) {
	long long ret = 1;
	while (b) {
		if (b & 1) {
			ret *= a;
			ret %= c;
		}
		a *= a;
		a %= c;
		b >>= 1;
	}
	return ret;
}

