    f1.resize(n + 1);
    f1[n] = modinv(f0[n]);
    for (int i = n; i > 0; i--) {
        f1[i - 1] = (ll)f1[i] * i % P;
    }
}
ll fact(int k) {
    return f0[k];
}
ll comb(int n, int k) {
    if (n < k || k < 0) return 0;
    return (ll)f0[n] * f1[k] % P * f1[n - k] % P;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    init(n);

    ll r = 0;
    for (int i = 0; i <= k; i++) {
        r += comb(n - 1, i) * powmod(m - 1, n - 1 - i) % P;
    }

    cout << r % P * m % P << endl;

    return 0;
}

