  pre_inv[N - 1] = inv(fact[N - 1]);
  for(int i = N - 2; i >= 0; i --) {
    pre_inv[i] = mul(pre_inv[i + 1], i + 1);
  }
}

ll ncr(ll n, ll r)
{
