LL mul(LL a, LL b) {
	return a * b % mod;
}

LL fpow(LL a, LL b) {
	LL res = 1;
	while (b > 0) {
		if (b & 1) mul(res, a);
		mul(a, a);
		b >>= 1;
	}
	return res;
}

LL inv(LL a) {
	return fpow(a, mod - 2);
