class Combination {
private:
    int64_t mod; // 元, 素数でないとNG
    int64_t max_size; // 最大値, 10^7まで
    vector<int64_t> factorial; // 階乗
    vector<int64_t> inverse; // 逆元
    vector<int64_t> inverse_factorial; // 逆元の階乗

    void init() {
        // 値は1で初期化する
        factorial.assign(max_size, 1);
        inverse.assign(max_size, 1);
        inverse_factorial.assign(max_size, 1);
        for (auto i = 2; i < max_size; i++) {
            factorial[i] = factorial[i - 1] * i % mod;
            inverse[i] = mod - inverse[mod % i] * (mod / i) % mod; // 拡張Euclidの互除法の変形版
            // inverse[i] = modinv(i); // Fermatの小定理
            inverse_factorial[i] = inverse_factorial[i - 1] * inverse[i] % mod;
            // cout << i << " " << factorial[i] << " " << inverse[i] << " " << inverse_factorial[i] << endl;
        }
    };
public:;
    Combination(int64_t mod, int64_t max_size) {
        this->mod = mod;
        assert(max_size < 1e7);
        this->max_size = max_size + 1;
        // テーブル生成
        init();
    };
    virtual ~Combination(){};

    int64_t modpow(int64_t a, int64_t n) {
        int64_t ret = 1;
        while(n > 0) {
            if(n & 1) ret = ret * a % mod;
            a = a * a % mod;
            n >>= 1;
        }
        return ret;
    };
    int64_t modinv(int64_t a) { return modpow(a, mod - 2); };
    int64_t combination(int64_t n, int64_t k) {
        if (n < k) return 0;
        if (n < 0 or k < 0) return 0;
        // cout << factorial[n] << " " << inverse_factorial[k] << " " << inverse_factorial[n - k] << endl;
        return factorial[n] * (inverse_factorial[k] * inverse_factorial[n - k] % mod) % mod;
    };
};

int main(){
    int n, m, k;
    cin >> n >> m >> k;

    const int mod = 998244353;
    int64_t ans = 0;
    Combination c(mod, n);
    // n-1個のブロックからk個の左隣と同じ色となるブロックを選ぶ (n-1)C(k)
    // 色の塗り分け m * 1^k * (m - 1)^(n - 1 - k)
    // k以下なので0~kまで足し合わせ
    for (auto i = 0; i <= k; i++) {
        ans = (ans + (c.combination(n - 1, i) * (m * c.modpow(m - 1, n - 1 - i) % mod) % mod)) % mod;
    }
    cout << ans << endl;

    return 0;
}

