const long long MOD=998244353;

long long modmypower(long long a, long long b){
  if(b==1){
    return a%MOD;
  }else if(b%2==0){
    long long c=modmypower(a,b/2);
    return (c*c)%MOD;
  }else{
    long long c=modmypower(a,(b-1)/2);
    return (((c*c)%MOD)*a)%MOD;
  }
}

long long modfactorial(long long x){
  if(x<=1) x=1;
  else for(long long i=x-1; i>0; i--) x=((x*i)%MOD);
  return x;
}

long long modinv(long long x){
  return modmypower(x,MOD-2);
}

long long modc(long long n, long long r){
  long long x=modfactorial(n);
  long long d=(modinv(modfactorial(r))*modinv(modfactorial(n-r)))%MOD;
  return (x*d)%MOD;
}

int main(){
  long long N,M,K; cin >> N >> M >> K;

  long long result=0;
  for(long long i=0; i<=K; i++){
    long long t=(M*modmypower(M-1,N-1-i))%MOD;
    t*=modc(N-1,i);
    t%=MOD;
    result+=t;
    result%=MOD;
  }
  cout << result << endl;
}

