  vector<long long>com(N + 1);
  com[0] = 1;
  for (int i = 1; i <= N; i ++) {
    com[i] = com[i - 1] * (N - i) * flip(i, mo);
    com[i] %= mo;
  }
  for (int i = 0; i <= K; i ++) {
