    int n, m, k;
    cin >> n >> m >> k;
    init();
    LL ans = 0;
    for(int i = 0; i <= k; ++i) {
        LL tmp = 1LL*m*comb(n-1,i)%MOD*poww(m-1, n-1-i)%MOD;
        ans = (ans + tmp) % MOD;
    }
    cout << ans;
}


