	cin >> N >> M >> K;

	init_nCr(2 * 1e5);

	long long ans = 0;
	for (int i = 0; i <= K; i++){
		long long add = calc(N - i, M) * nCr(N - 1, i);
		ans += add;
		ans %= MOD;
	}

