    cin >> N >> M >> K;
    Combination comb(500000);
    mint ans = 0;
    for(int i = 0; i <= K; i++) {
        mint tmp = 1;
        tmp *= comb.COM(N - 1, i);
        tmp *= M;
        tmp *= mint(M - 1).pow(N - i - 1);
        ans += tmp;
    }
    print(ans);
}

