ll FPM(ll x,ll power)
{
    ll ans = 1;
    while(power)
    {
        if(power & 1)
        {
            ans = (ans * x) % mod;
        }
        x = (x * x) % mod;
        power >>= 1;
    }
    return ans % mod;
}

ll C(ll a, ll b)
{
    return f[a] * inv[a - b] % mod * inv[b] % mod;
}

void solve()
{
    cin >> N >> M >> K;
    ll m = max(N, M);
    f[0] = 1;
    for(int i = 1;i <= m; i++) // 阶乘预处理
        f[i] = f[i - 1] * i % mod;
    inv[m] = FPM(f[m], mod - 2);
    for(ll i = m - 1; i >= 0; i--)
        inv[i] = inv[i + 1] * (i + 1) % mod; //求逆元
    ll ans = 0;
    ll cnt = FPM(M - 1, N - K - 1);
    for(ll i = N - K - 1;i <= N - 1; i++)
    {
        ans = (ans + C(N - 1, i) % mod * M % mod * cnt % mod) % mod;
        cnt = cnt * (M - 1) % mod;
    }
    cout<< ans << endl;
}

