      tmp *= pow_mod(fractal.at(N-1-i),MOD-2,MOD);
      tmp %= MOD;
      tmp *= pow_mod(fractal.at(i),MOD-2,MOD);
      tmp %= MOD;
    }
    tmp *= M;
    tmp %= MOD;
    tmp *= pow_mod(M-1,N-1-i,MOD);
    tmp %= MOD;
    ans += tmp;
    ans %= MOD;
  }
  cout << ans << "\n";
}

