const uint64_t MAGIC = 998244353;

uint64_t PowerMod(uint64_t n, uint64_t k, uint64_t mod) {
    uint64_t ret = 1;
    while (k) {
        if (k & 1) {
            ret = ret * n % mod;
        }
        n = n * n % mod;
        k >>= 1;
    }
    return ret;
}

class ChooseMod {
    public:
    ChooseMod(size_t max_n , uint64_t mod):mod_(mod) {
        fac_.resize(max_n + 1);
        inv_.resize(max_n + 1);
        fac_[0] = inv_[0] = 1;
        for (size_t i = 1; i <= max_n; ++i) {
            fac_[i] = fac_[i-1] * i % mod_;
            inv_[i] = PowerMod(fac_[i], mod_ - 2, mod_);
        }
    }
    uint64_t Choose(uint64_t n, uint64_t k) {
        return fac_[n] * inv_[n-k] % mod_ * inv_[k] % mod_;
    }
    uint64_t Fac(size_t x) {
        return fac_[x];
    }
    private:
    uint64_t mod_;
    vector<uint64_t> fac_;
    vector<uint64_t> inv_;
};

