class Combination {
    private:
    vector<int> x, y;
    int mod = (int)1e9 + 7;

    void make(int n) {
        x.resize(n+1);
        y.resize(n+1);        
        x[0] = y[0] = 1;
        for (int i = 1; i <= n; i++) {
            x[i] = (x[i-1]*i) % mod;
            y[i] = modpow(x[i],mod-2);
        }
    }

    int modpow(int x, int n) {
        int ret = 1;
        while (n > 0) {
            if ((n & 1)) {
                ret = ret * x % mod;
            }
            x = x * x % mod;
            n >>= 1;
        }
        return ret;
    }

    public:
    Combination(int n) {
        make(n);
    }

    Combination(int n, int mod) {
        this->mod = mod;
        make(n);
    }

    int get(int n, int r) {
        if (n < r) return 0;
        return x[n] * y[n - r] % mod * y[r] % mod;
    }

};

int modpow(int x, int n) {
    int ret = 1;
    while (n > 0) {
        if ((n & 1)) {
            ret = ret * x % mod;
        }
        x = x * x % mod;
        n >>= 1;
    }
    return ret;
}

void run(){
    int n,m,k;
    cin>>n>>m>>k;
    Combination comb(n,mod);
    int ans=0;
    rep(i,k+1){
        ans+=m*comb.get(n-1,i)%mod*modpow(m-1,n-1-i)%mod;
        ans%=mod;
    }
    cout<<ans<<endl;
}

