typedef long long ll;
using namespace std;

ll mod = 998244353, u = 1, d[200001];

ll mypow(ll x, ll y){
  if(x <= 0 || y <= 0) return 1;
  if(y == 1) return x;
  ll z = mypow(x, y / 2) % mod;
  if(y % 2 == 1){
    return ((z * z) % mod) * x % mod;
  }
  else{
    return (z * z) % mod;
  }
}

void pc(ll l){
  for(ll i = l; i >= 1; i--){
    u = (u * i) % mod;
  }
  ll x = 1;
  for(ll i = 1; i <= l; i++){
    x = (x * i) % mod;
    d[i] = mypow(x, mod - 2);
  }
}

ll choose(ll l, ll r){
  return ((u * d[r]) % mod) * d[l - r] % mod;
}

void solve(){
  ll n, m, k, x, y, z; cin >> n >> m >> k;
  x = (mypow(m - 1, n - 1) * m) % mod;
  ll ans = x;
  z = mypow(m - 1, n - k - 2);
  pc(n - 1);
  for(ll i = k; i >= 1; i--){
    y = choose(n - 1, i);
    z = (z * (m - 1)) % mod;
    ans = (ans + (m * ((y * z) % mod) % mod)) % mod;
    //cout << y << " " << z << " " << ans << endl;
  }
  cout << ans << endl;
  return;
}

int main(){
  solve();
  return 0;
}

