const int MOD_TABLE_SIZE = 1000000 + 10;
ll inv[MOD_TABLE_SIZE];
ll fac[MOD_TABLE_SIZE];
ll facinv[MOD_TABLE_SIZE];

void mod_table_init() {
  inv[1] = 1;
  for(int i = 2; i < MOD_TABLE_SIZE; i++) {
    inv[i] = MOD - (MOD / i) * inv[(int)MOD % i] % MOD;
  }
  fac[0] = facinv[0] = 1;
  for(int i = 1; i < MOD_TABLE_SIZE; i++) {
    fac[i] = (fac[i-1] * (ll)i) % MOD;
    facinv[i] = (facinv[i-1] * inv[i]) % MOD;
  }
}

inline ll P(int a, int b) {
  if(a<b) return 0LL;
  return fac[a] *  facinv[a-b] % MOD;
}

inline ll C(int a, int b) {
  if(a<b) return 0LL;
  return (fac[a] * facinv[b] % MOD) * facinv[a-b] % MOD;
}

inline ll H(int a, int b) {
  return C(a+b-1,b);
}

int main() {
  mod_table_init();
  int N, M, K; cin>>N>>M>>K;
  vector<ll> beki(N, 1);
  for(int i = 1; i < N; i++) beki[i] = mul(beki[i-1], M-1);
  ll ans = 0;
  for(int i = 0; i <= K; i++) {
    ll tmp = C(N-1, i);
    chmul(tmp, beki[N-i-1]);
    //    cout << N-1 << " " << i << " " << tmp << endl;
    chadd(ans, tmp);
  }
  chmul(ans, M);
  cout << ans << endl;
  return 0;
}

