  if(y == -1) y = MOD - 2;
  ll res = 1LL;
  while(y) {
    if(y & 1) res = (res * x) % MOD;
    x = (x * x) % MOD;
    y >>= 1;
  }
  return res;
}

ll ncr(ll n, ll r) {
  if(n < r or n < 0 or r < 0) return 0;
  ll cur = f[n];
  ll p = inv[r];
  p = (p * inv[n - r]) % MOD;
  return cur * p % MOD;
}

