struct Mod {
    static int mod;
    int64 x;

    static void Euclidean(int64 a, int64 b, int64& x, int64& y) {
        if (b == 0) {
            x = 1;
            y = 0;
            return;
        }
        int64 x0, y0;
        Euclidean(b, a%b, x0, y0);
        x = y0;
        y = x0 - a/b * y0;   
    }

    Mod() : x(0) {}

    Mod(int64 x) : x(x) {
        if (this->x >= mod)
            this->x %= mod;
        if (this->x < 0)
            this->x += mod;
    }

    bool operator == (const Mod& other) {
        return x == other.x;
    }

    bool operator != (const Mod& other) {
        return x != other.x;
    }

    void operator += (const Mod& other) {
        x += other.x;
        if (x >= mod)
            x -= mod;
    }

    Mod operator + (const Mod& other) const {
        Mod result = *this;
        result += other;
        return result;
    }

    void operator -= (const Mod& other) {
        x -= other.x;
        if (x < 0)
            x += mod;
    }

    Mod operator - (const Mod& other) const {
        Mod result = *this;
        result -= other;
        return result;
    }

    void operator *= (const Mod& other) {
        x *= other.x;
        x %= mod;
    }

    Mod operator * (const Mod& other) const {
        Mod result = *this;
        result *= other;
        return result;
    }

    Mod Inv() const {
        int64 a, b;
        Euclidean(x, mod, a, b);
        return a;
    }

    Mod operator - () const {
        Mod result = *this;
        result.x = mod - result.x;
        return result;
    }

    void operator /= (const Mod& other) {
        *this *= other.Inv();
    }

    Mod operator / (const Mod& other) const {
        Mod result = *this;
        result /= other;
        return result;
    }

    Mod operator ^ (int exponent) const {
        Mod a = *this;

        Mod result = 1;

        while (exponent) {
            if (exponent & 1) {
                result *= a;
            }
            a *= a;
            exponent >>= 1;
        }

        return result;
    }
};

