class Combinatorics {
    vector<Mod> fac, inv_fac;    
    vector<vector<Mod>> comb;

  public:
    void PrecomputeFactorials(int n) {
        fac.resize(n+1);
        inv_fac.resize(n+1);

        fac[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fac[i] = fac[i-1] * i;
        }

        inv_fac[n] = fac[n].Inv();
        for (int i = n-1; i >= 0; --i) {
            inv_fac[i] = inv_fac[i+1] * (i+1);
        }
    }

    Mod Fac(int n) {
        return fac[n];
    }

    Mod InvFac(int n) {
        return inv_fac[n];
    }

    Mod Comb(int n, int k) {
        if (comb.empty()) {
            return fac[n] * inv_fac[k] * inv_fac[n - k];
        }
        return 0;
    }
} COMB;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N, M, K;

    cin >> N >> M >> K;

    COMB.PrecomputeFactorials(N);

    Mod res(0);

    Mod dif = M - 1;

    for (int k = 0; k <= K; k++) {
        auto c = COMB.Comb(N - 1, k);
        res += c * (dif ^ (N - 1 - k));
    }
    res *= M;

    cout << res << "\n";

    return 0;
}

