  for (int l = k + 1; l < n; l++) {
    // 少なくとも l 組は同じ色
    lint add = COM(n - 1, l) * modpow(m, n - l);
    add %= MOD;

    if ((l - k) % 2 == 1) ans = ans + add;
    else                  ans = ans - add + MOD;
    ans %= MOD;
  }

  sum = sum - ans + MOD;
  sum %= MOD;
  cout << sum << endl;

  return 0;
}

