#ifndef FACT_MOD_CACHE_HPP
#define FACT_MOD_CACHE_HPP


/*
usage:

tools::fact_mod_cache<3> cache(5);
cache.fact(5); //=> 0 (5! mod 3)
*/

namespace tools {
  template <std::uint_fast32_t P>
  class fact_mod_cache {
  private:
    std::size_t m_max;
    std::vector<int_mod<P>> m_data;
    std::vector<int_mod<P>> m_inv_data;

  public:
    fact_mod_cache(const std::size_t max) :
      m_max(max),
      m_data(max + 1),
      m_inv_data(max + 1) {
      m_data[0] = int_mod<P>(1);
      for (std::size_t i = 1; i <= max; ++i) {
        m_data[i] = m_data[i - 1] * int_mod<P>(static_cast<std::int_fast32_t>(i));
      }
      m_inv_data[max] = m_data[max].inv();
      for (std::size_t i = max - 1; i != std::numeric_limits<std::size_t>::max(); --i) {
        m_inv_data[i] = m_inv_data[i + 1] * int_mod<P>(static_cast<std::int_fast32_t>(i + 1));
      }
    }

    constexpr int_mod<P> fact(const std::size_t i) const {
      return m_data[i];
    }

    constexpr int_mod<P> inv_fact(const std::size_t i) const {
      return m_inv_data[i];
    }

    constexpr int_mod<P> combination(const std::size_t n, const std::size_t r) const {
      return 0 <= r && r <= n ? m_data[n] * m_inv_data[n - r] * m_inv_data[r] : int_mod<P>(0);
    }
  };
}

