int64_t p=998244353;

int64_t pinv(int64_t a){
  int64_t p1=p-2;
  int64_t k=a;
  int64_t Ans=1;
  while(p1>0){
    if(p1%2==1){
      Ans*=k;
      Ans%=p;
    }
    k*=k;
    k%=p;
    p1/=2;
  }
  return Ans;
}

