inline ll mod(ll a, ll mod) {
	if (a > 0) return a % mod;
	if (a % mod == 0) return 0;
	ll x = -a / mod + 1;
	a += x * mod;
	return a % mod;
}
ll powm(ll a, ll b, ll m) {
	if (b == 0) {
		return 1;
	} else if (b % 2 == 0) {
		ll d = powm(a, b / 2, m);
		return (d * d) % m;
	} else {
		return (powm(a, b - 1, m) * a) % m;
	}
}
// 本体

constexpr ll MAXN  = 2e5;
ll fact[MAXN + 1]  = {};
ll ifact[MAXN + 1] = {};
void init_fact(ll n, ll mod) {
	fact[0] = ifact[0] = 1;
	for (int i = 0; i < n; i++) {
		fact[i + 1]	 = ((i + 1) * fact[i]) % mod;
		ifact[i + 1] = powm(fact[i + 1], mod - 2, mod);
	}
}

ll nci_m(ll n, ll i, ll mod) {
	return fact[n] * ifact[i] % mod * ifact[n - i] % mod;
}

int main() {
	IOS();
	ll MOD = 998244353;
	ll n, m, k;
	cin >> n >> m >> k;
	init_fact(n, MOD);
	ll ans = 0;
	for (int i = 0; i <= k; i++) {
		ans += nci_m(n - 1, i, MOD) * m % MOD * powm(m - 1, n - i - 1, MOD) % MOD;
		ans %= MOD;
	}
	dump(ans);
}

