ll mod = 998244353;
ll d[200001];
ll e[200001];
ll go(ll x, ll y) {
	if (y == 0)return 1;
	else if (y == 1)return x;
	else if (y & 1) {
		return x * go(x, y - 1) % mod;
	}
	else {
		ll tmp = go(x, y / 2);
		return tmp * tmp % mod;
	}
}
ll go2(ll x, ll y) {
	ll cnt = d[x];
	ll tmp = d[x - y] * d[y] % mod;
	tmp = go(tmp, mod - 2);
	cnt *= tmp; cnt %= mod;
	return cnt;
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0); cout.tie(NULL);
	d[1] = 1;
	for (ll i = 2; i <= 200000; i++) {
		d[i] = d[i - 1] * i; d[i] %= mod;
	}
	ll n, m, k; cin >> n >> m >> k;
	if (m == 1) {
		if (k == n - 1) {
			cout << 1 << '\n';
		}
		else cout << 0 << '\n';
		return 0;
	}
	d[0] = 1;
	e[1] = m - 1;
	for (int i = 2; i <= 200000; i++) {
		e[i] = e[i - 1] * (ll)(m - 1); e[i] %= mod;
	}
