	for (ll i = 1; i <= n - 1; i++) {
		if (n - i - 1 <= k) {
			ll tmp = m * e[i]; tmp %= mod;
			tmp *= go2(n - 1, i); tmp %= mod;
			ans += tmp; ans %= mod;
		}
	}
	cout << ans << '\n';

}

