typedef long long          num;

using namespace std;

template<int mod>
struct modulo {
	int w;
	operator int&() { return w; }

	modulo() {}
	modulo(int w) { this->w = w; fix(); }
	void inline fix() { w %= mod; if (w < 0) w += mod; }
	modulo inline fix(int w) const { w %= mod; if (w < 0) w += mod; return w; }

	modulo inline operator + (modulo b) { int r = w + b; if (r > mod) r -= mod; return r; }
	modulo& operator += (modulo b) { if ((w += b.w) >= mod) w -= mod; return *this; }
	modulo inline operator - (modulo b) { int r = w - b; if (r < 0) r += mod; return r; }
	modulo& operator -= (modulo b) { if ((w -= b.w) < 0) w -= mod; return *this; }
	modulo inline operator * (modulo b) { modulo r = *this; r *= b; return r; }
	modulo& operator *= (modulo b) { w = (num) w * b.w % mod; return *this; }
	modulo inline operator / (modulo b) { modulo r = *this; r /= b; return r; }
	modulo& operator /= (modulo b) { w = (num) w * b.inv() % mod; return *this; }

	modulo inline inv() const {
		int a = w, m = mod, u = 0, v = 1, t;
		for (; a != 0; t = m / a, m -= t * a, swap(a, m), u -= t * v, swap(u, v));
		return fix(u);
	}

	modulo inline pow(int p) const {
		if (!w)  return 0;
		modulo a = *this, r = 1;
		for (; p > 0; a *= a, p >>= 1) if (p & 1) r *= a;
		return r;
	}
};
