struct Elem {
	int min_diff;
	int last_diff;
	bool operator<(const Elem &rh)
	{
		if (min_diff == rh.min_diff) {
			return last_diff > rh.last_diff;
		}
		else {
			return min_diff > rh.min_diff;
		}
	}
};

inline int min(int a, int b)
{
	return (a < b) ? a : b;
}

int main()
{
	int N;
	static Elem elems[1000 * 1000];
	scanf("%d", &N);
	for (int i = 0; i < N; i++) {
		static char S[1000 * 1000 + 1];
		scanf("%s", S);

		size_t len = strlen(S);
		int cur = 0;
		int min_diff = 0;
		for (size_t t = 0; t < len; t++) {
			int diff = (S[t] == '(') ? 1 : -1;
			cur += diff;
			min_diff = min(cur, min_diff);
		}
		elems[i].min_diff = min_diff;
		elems[i].last_diff = cur;
	}

	std::sort(elems, elems + N);
	int cur = 0;
	bool ok = true;
	for (int i = 0; i < N; i++) {
		if (cur + elems[i].min_diff < 0) {
			ok = false;
			break;
		}
		cur += elems[i].last_diff;
	}
	puts((ok && cur == 0) ? "Yes" : "No");

	return 0;
}


