const ll MOD = 998244353;
const int N = 2e5 + 5;

ll f[N], inv[N];
ll n, m, k;

ll get(ll x, ll y) {
  if(y == -1) y = MOD - 2;
  ll res = 1LL;
  while(y) {
    if(y & 1) res = (res * x) % MOD;
    x = (x * x) % MOD;
    y >>= 1;
  }
  return res;
}

ll ncr(ll n, ll r) {
  if(n < r or n < 0 or r < 0) return 0;
  ll cur = f[n];
  ll p = inv[r];
  p = (p * inv[n - r]) % MOD;
  return cur * p % MOD;
}

void solve() {
  cin >> n >> m >> k;
  f[0] = inv[0] = 1;
  for(int i = 1; i < N; i++) {
    f[i] = (f[i - 1] * i) % MOD;
    inv[i] = get(f[i], -1);
  }
  ll ans = 0;
  for(ll i = 1; i <= k + 1; i++) {
    ll p = get(m, i);
    ll q = get(m - 1, n - i);
    ll cur = p * q % MOD;
    ans += (cur) % MOD;
    //cout << cur * ncr(n - 1, i - 1) << '\n';
    ans %= MOD;
  }
  print(ans);
}

int main() {
  int t; t = 1;
  while(t--) solve();
}

