//累乗(power)a^n(mod10^9+7)
long long power(long long a,long long n){
  long long count=a,sum=1;
  while(n>0){
    if(n%2==1)
      sum*=count;
    count*=count;
    count%=998244353;
    sum%=998244353;
    n/=2;
  }
  return sum;
}

long long int comb(long long int n,long long int r){
  long long x=1,y=1,i;
  for(i=0;i<r;i++){
    x*=n-i;
    y*=r-i;
    x%=998244353;
    y%=998244353;
  }
  y=power(y,998244351);
  return (x*y)%998244353;
}

int main(){
  long long n,m,k,x,y=0,i;
  scanf("%lld%lld%lld",&n,&m,&k);
  for(i=0;i<=k;i++){
    x=m*power(m-1,n-i-1)%998244353;
    y+=x*comb(n-1,i)%998244353;
    y%=998244353;
  }
  printf("%lld\n",y);
  return 0;
}

