// 和 - 取得
int
fGetModSum(
	int piVal1					// <I> 値１
	, int piVal2				// <I> 値２
)
{
	return (piVal1 + piVal2) % D_MOD;
}

// 積 - 取得
int
fGetModMulti(
	int piVal1					// <I> 値１
	, int piVal2				// <I> 値２
)
{
	return (int)((long long)piVal1 * (long long)piVal2 % D_MOD);
}

// べき乗 - 取得
int
fGetModPower(
	int piBase					// <I> 基数
	, int piIdx					// <I> 指数
)
{
	// 基数
	if (piBase == 0) {
		return 0;
	}

	// 平方リスト - 作成
	int li1Val[100];
	li1Val[0] = piBase;
	int liCnt = 1;
	int liIdx = 1;
	while (piIdx > liIdx) {
		li1Val[liCnt] = fGetModMulti(li1Val[liCnt - 1], li1Val[liCnt - 1]);
		liCnt++;
		liIdx += liIdx;
	}

	// べき乗 - 取得
	int liVal = 1;
	while (piIdx > 0) {
		if (piIdx >= liIdx) {
			piIdx -= liIdx;
			liVal = fGetModMulti(liVal, li1Val[liCnt - 1]);
		}
		liCnt--;
		liIdx /= 2;
	}

	return liVal;
}

// 階乗リスト - 作成
int
fMakeModFact(
	int piMax					// <I> 最大値
)
{
	int i;

	si1ModFact[0] = 1;
	si1ModFact[1] = 1;
	for (i = 2; i <= piMax; i++) {
		si1ModFact[i] = fGetModMulti(si1ModFact[i - 1], i);
	}

	return 0;
}

// 階乗リスト(逆元) - 作成
int
fMakeModFactR(
	int piMax					// <I> 最大値
)
{
	int i;

	for (i = 0; i <= piMax; i++) {
		si1ModFactR[i] = fGetModPower(si1ModFact[i], D_MOD - 2);
	}

	return 0;
}

// nCk - 取得
int
fGetModnCk(
	int piN						// <I> N
	, int piK					// <I> K
)
{
	if (piN < piK) {
		return 0;
	}
	if (piK < 0) {
		return 0;
	}
	int liCnt = fGetModMulti(si1ModFact[piN], si1ModFactR[piN - piK]);
	return fGetModMulti(liCnt, si1ModFactR[piK]);
}

// 実行メイン
int
fMain(
)
{
	int i;
	char lc1Buf[1024];

	// ブロック数・色数・組数 - 取得
	int liBCnt, liCCnt, liPCnt;
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
	sscanf(lc1Buf, "%d%d%d", &liBCnt, &liCCnt, &liPCnt);
	if (liBCnt == 1) {
		return liCCnt;
	}
	if (liCCnt == 1) {
		if (liPCnt < liBCnt - 1) {
			return 0;
		}
		else {
			return 1;
		}
	}

	// 階乗リスト - 作成
	fMakeModFact(liBCnt - 1);
	fMakeModFactR(liBCnt - 1);

	// 組数でループ
	int liSum = 0;
	for (i = 0; i <= liPCnt; i++) {

		// １ブロック目
		int liPtn = liCCnt;

		// 異色
		int liVal = fGetModPower(liCCnt - 1, liBCnt - 1 - i);
		liPtn = fGetModMulti(liPtn, liVal);

		// 同色
		liVal = fGetModnCk(liBCnt - 1, i);
		liPtn = fGetModMulti(liPtn, liVal);

		// 合計 - 加算
		liSum = fGetModSum(liSum, liPtn);
	}

	return liSum;
}

