long component(int n, int k) {
  long result = 1;
  int i = 0, multi;

  multi = n;
  while(i < k) {
    result *= multi;
    multi--;
    i++;
  }
  i = k;
  while(i > 0) {
    result /= i;
    i--;
  }

  return result;
}

long pow_amari(int x, int y, long key) {
  int i = 0;
  long result = 1;
  while (i < y) {
    result *= x;
    if (result >= key) {
      result = result % key;
    }
    i++;
  }
  return result;
}

