	for (i = 1; i <= n; i++)
		fact[i] = fact[i - 1] * i % p;
	long long int ans = 0;
	for (i = 0; i <= k; i++)
		ans = (ans + comb(n - 1, i, p) * modpow(m - 1, n - i - 1, p) % p * m % p) % p;
	printf("%lld\n", ans);
	return 0;
}

