class ModInt(
    v: Long
) {
    val value: Long

    init {
        value = v % M
    }

    constructor (value: Int): this(value.toLong())

    operator fun plus(rhs: ModInt): ModInt {
        return ModInt((value + rhs.value) % M)
    }
    operator fun minus(rhs: ModInt): ModInt {
        return ModInt((value - rhs.value + M) % M)
    }
    operator fun times(rhs: ModInt): ModInt {
        return ModInt((value * rhs.value) % M)
    }
    operator fun div(rhs: ModInt): ModInt {
        return ModInt(value * inv(rhs.value) % M)
    }
    private fun inv(v: Long): Long {
        return M - (((M / v) * inv(M % v)) % M)
    }

    fun pow(v: Int): ModInt {
        var result = 1L
        var x = v
        var vv = value
        while (x != 0) {
            if ((x and 1) != 0) {
                result = (result * vv) % M
            }
            vv = (vv * vv) % M
            x = x ushr 1
        }
        return ModInt(result)
    }

    override fun toString(): String {
        return value.toString()
    }

    companion object {
        private const val M = 998244353

        val ZERO = ModInt(0)
        val ONE = ModInt(1)

        var FACT = Array<ModInt>(0) { ModInt.ZERO }
        var INV = Array<ModInt>(0) { ModInt.ZERO }
        var INVFACT = Array<ModInt>(0) { ModInt.ZERO }

        fun prepareFact(N: Int) {
            FACT = Array<ModInt>(N+1) { ModInt.ONE }
            INV = Array<ModInt>(N+1) { ModInt.ONE }
            INVFACT = Array<ModInt>(N+1) { ModInt.ONE }

            val MM = ModInt(M)

            if (N > 1) FACT[1] = FACT[0] * ModInt(1)
            for (i in 2..N) {
                FACT[i] = FACT[i-1] * ModInt(i)
                INV[i] = MM - ModInt(M / i) * INV[M % i]
                INVFACT[i] = INVFACT[i-1] * INV[i]
            }
        }

        fun comb(n: Int, k: Int): ModInt {
            return FACT[n] * INVFACT[k] * INVFACT[n-k]
        }
    }
}

class Indexer(
    val Y: Int,
    val X: Int,
    val dy: Int = 0,
    val dx: Int = 0
) {
    val size: Int
