fun solve() {

    val (N, M, K) = nextInts()

    ModInt.prepareFact(N-1)

    var pow = ModInt(M-1).pow(N-1-K)
    val MM = ModInt(M)

    var result = ModInt.ZERO
    for (k in K downTo 0) {
        result += pow * ModInt.comb(N-1, k) * MM
        pow *= ModInt(M-1)
    }

    put(result)
}

