class LongMod(var num: Long, val MOD: Long = 1_000_000_007L) {
    init {
        this.num = (this.num%this.MOD + this.MOD)%this.MOD
    }
    constructor(numStr: String, MOD: Long = 1e9.toLong()+7) :
            this(0L, MOD) {
        if (numStr.isEmpty()) return
        var rv = numStr.reversed()
        var d = 1L
        rv.forEach{ c ->
            this.num += (c - '0') * d
            this.num %= MOD
            d *= 10
            d %= MOD
        }
    }
    override operator fun equals(other: Any?): Boolean {
        if (other !is LongMod) return false
        return this.num % this.MOD == other.num % this.MOD
    }
    operator fun unaryMinus(): LongMod {
        return LongMod(-this.num)
    }
    private operator fun plusAssign(other: LongMod): Unit {
        if ((this.num + other.num) >= this.MOD) {
            this.num -= this.MOD
        }
        this.num += other.num
    }
    private operator fun minusAssign(other: LongMod): Unit {
        if ((this.num + this.MOD - other.num) >= this.MOD) {
            this.num -= this.MOD
        }
        this.num += this.MOD - other.num
    }
    private operator fun timesAssign(other: LongMod): Unit {
        this.num *= other.num
        this.num %= this.MOD
    }
    operator fun plus(other: LongMod): LongMod {
        val res = LongMod(this.num, this.MOD)
        res += other
        return res
    }
    operator fun minus(other: LongMod): LongMod {
        val res = LongMod(this.num, this.MOD)
        res -= other
        return res
    }
    operator fun times(other: LongMod): LongMod {
        val res = LongMod(this.num, this.MOD)
        res *= other
        return res
    }
    fun pow(n: Long): LongMod {
        if (n == 0L) return LongMod(1L, this.MOD)
        var x = this.pow(n / 2)
        x.timesAssign(x)
        if (n % 2 == 1L) x.timesAssign(this)
        return x
    }
    fun inv(): LongMod {
        return this.pow(this.MOD - 2)
    }
    operator fun divAssign(other: LongMod): Unit {
        this *= other.inv()
    }
    operator fun div(other: LongMod): LongMod {
        val res = LongMod(this.num, this.MOD)
        res /= other
        return res
    }
}

class NckLongModTbl(val N: Long, val MOD: Long = 1_000_000_007L) {
    private var fact = arrayOf<LongMod>()
    private var iFact = arrayOf<LongMod>()
    init {
        val n = N.toInt()
        this.fact = Array<LongMod>(n+1){LongMod(0L, MOD)}
        this.iFact = Array<LongMod>(n+1){LongMod(0L, MOD)}
        this.fact[0] = LongMod(1L, MOD)
        for (i in 1..n) {
            this.fact[i] = this.fact[i-1] * LongMod(i.toLong(), MOD)
        }
        this.iFact[n] = this.fact[n].inv()
        for (i in n downTo 1) {
            this.iFact[i-1] = this.iFact[i] * LongMod(i.toLong(), MOD)
        }
    }
    fun nCkMod(N: Long, K: Long): LongMod {
        if (K < 0 || N < K) return LongMod(0L, MOD)
        val n = N.toInt(); val k = K.toInt()
        return this.fact[n] * this.iFact[k] * this.iFact[n-k]
    }
}

