				baseColorNum[i] = baseColorNum[i - 1]*(m - 1);
				baseColorNum[i] %= mod;
			}
//			System.out.println("i = "+i+" base = "+baseColorNum[i]);

			int remain = n - i;

			if(remain > k){
				continue;
			}

			long tmp = repeatablePow(i, remain, mod) * baseColorNum[i];
			tmp %= mod;

//			System.out.println("i = "+i+" tmp = "+tmp);

			result += tmp;
			result %= mod;

		}

		System.out.println(result);
