  static long reverseMod(long n, long mod) { // nのmodにおける逆元、すなわち1/nを求めるメソッド
    return modpow(n, mod-2, mod);
  }

  static long modpow(long a, long b, long mod) { // a*b(mod)を求めるメソッド
    long res = 1;
    while (b > 0) {
      if ((b & 1) == 1) {
        res = res * a;
      }
      a = a*a;
      b >>= 1;
    }
    return res;
  }
