public class Main implements Runnable{

	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Beginner Contest 167 E問題
		 * 考察メモ
		 *
		 */
		int N = io.nextInt(), M = io.nextInt(), K = io.nextInt();
		ModUtility mod = new ModUtility(new Prime(998_244_353), 1_000_000);
		ModInteger ans = mod.create(0);
		for (int i = 0;i <= K;++ i) {
			ans.addEqual(mod.create(mod.pow(M - 1, N - 1 - i)).multiplyEqual(mod.combination(N - 1, i)));
		}
		io.println(ans.multiplyEqual(M));
	}

	/** デバッグ用コードのお供に */
	private static boolean DEBUG = false;
	/** 確保するメモリの大きさ(単位: MB)*/
	private static final long MEMORY = 64;
	private final FastIO io;
	private final String[] args;

	public static void main(String[] args) {
	        Thread.setDefaultUncaughtExceptionHandler((t, e) -> {e.printStackTrace(); System.exit(1);});
	        new Thread(null, new Main(args), "", MEMORY * 1048576).start();
	}

	public Main(String[] args) {
		this(new FastIO(), args);
	}

	public Main(FastIO io, String... args) {
		this.io = io;
		this.args = args;
		if (DEBUG) io.setAutoFlush(true);
	}

	@Override
	public void run() {
		try {
			solve(io, args);
		} catch (Throwable e) {
			throw e;
		} finally {
			io.flush();
		}
	}

