			int h = k + 1;
			for (int i = 0;i <= n;++ i) {
				for (int j = 1, l = Math.min(i, k);j <= l;++ j) pertition[i * h + j] = pertition[i * h + j - 1] + pertition[(i - j) * h + j];
				for (int j = i;j < k;++ j) pertition[i * h + j + 1] = pertition[i * h + j];
