class Combination {
    long[] fact;
    long[] ifact;
    long M;

    private long mpow(long x, long n) {
        long ans = 1;
        while (n != 0) {
            if ((n & 1) == 1) ans = ans * x % M;
            x = x * x % M;
            n = n >> 1;
        }
        return ans;
    }

    private long inv(long x) {
        return mpow(x, M - 2);
    }

    public Combination(int n, long M) {
        assert n < M;
        this.M = M;
        fact = new long[n + 1];
        ifact = new long[n + 1];

        fact[0] = 1;
        ifact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = (fact[i-1]*i) % M;
        ifact[n] = inv(fact[n]);
        for (int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i % M;
    }

    public long c(int n, int k) {
        if (k < 0 || k > n) return 0;
        return ((fact[n]*ifact[k] % M)*ifact[n-k] % M);
    }
}

