        int M = sc.nextInt();
        int K = sc.nextInt();

        long mod = 998244353;
        Combination comb = new Combination(200005, mod);

        long ans = 0;
        long col = M; 
        for (int x = N - 1; x >= 0; x--) {
            long now = col;
            now *= comb.c(N - 1, x);
            if (x <= K) {
                ans += now;
                ans %= mod;
            }
            col *= M-1;
            col %= mod;
        }
        System.out.println(ans % mod);

        return;
    }

}

