class Combination {
    private List<Long> fact = new ArrayList<>();
    private List<Long> invFact = new ArrayList<>();

    private void build(int n) {
        if (fact.isEmpty()) {
            fact.add(1L);
            invFact.add(1L);
        }
        for (int i = fact.size(); i <= n; i++) {
            fact.add(fact.get(i - 1) * i % Main.mod);
            invFact.add(pow(fact.get(i), Main.mod - 2));
        }
    }

    private void rangeCheck(long n, long r) {
        if (n < r) {
            throw new IllegalArgumentException("n < r");
        }
        if (n < 0) {
            throw new IllegalArgumentException("n < 0");
        }
        if (r < 0) {
            throw new IllegalArgumentException("r < 0");
        }
    }

    long fact(int n) {
        build(n);
        return fact.get(n);
    }

    long invFact(int n) {
        build(n);
        return invFact.get(n);
    }

    long comb(int n, int r) {
        rangeCheck(n, r);
        return fact(n) * invFact(r) % Main.mod * invFact(n - r) % Main.mod;
    }

    long comb(long n, long r) {
        rangeCheck(n, r);
        r = Math.min(r, n - r);
        long x = 1, y = 1;
        for (long i = 1; i <= r; i++) {
            x = x * (n - r + i) % Main.mod;
            y = y * i % Main.mod;
        }
        return x * inv(y) % Main.mod;
    }

    long perm(int n, int r) {
        rangeCheck(n, r);
        return fact(n) * invFact(n - r) % Main.mod;
    }

    long perm(long n, long r) {
        rangeCheck(n, r);
        long x = 1;
        for (long i = 1; i <= r; i++) {
            x = x * (n - r + i) % Main.mod;
        }
        return x;
    }

    long homo(int n, int r) {
        rangeCheck(n, r);
        return r == 0 ? 1 : comb(n + r - 1, r);
    }

    long homo(long n, long r) {
        rangeCheck(n, r);
        return r == 0 ? 1 : comb(n + r - 1, r);
    }

    long inv(long a) {
        return pow(a, Main.mod - 2);
    }

    long pow(long a, long b) {
        long x = 1;
        while (b > 0) {
            if (b % 2 == 1) {
                x = x * a % Main.mod;
                b--;
            } else {
                a = a * a % Main.mod;
                b /= 2;
            }
        }
        return x;
    }
}

