public class Main {

    static int n, m, k;
    static long DIV = 998244353;
    static long[] mx;
    static long[] kai;
    static long[] kaiinv;
    static long[] nci;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        mx = new long[n+10];
        kai = new long[n+10];
        kaiinv = new long[n+10];
        nci = new long[n+10];


        long mkai = 1;
        for (int i = 1; i < kai.length; i++) {
            if(i == 1){
                mx[i] = m;
            }else{
                mx[i] = (mx[i-1] * (m-1)) % DIV;
            }
            mkai *= i;
            mkai %= DIV;
            kai[i] = mkai;
            kaiinv[i] = inverseElement(mkai, DIV);
        }

        nci[0] = 1;
        long mnci = 1;
        for (int i = 1; i < nci.length; i++) {
            mnci *= (n - i);
            mnci %= DIV;
            nci[i] = (mnci * kaiinv[i]) % DIV;
        }

        long ans = 0;

        for (int i = n; i >= n - k; i--) {
            ans += (mx[i] * nci[n-i]) % DIV;
            ans %= DIV;
        }

        System.out.println(ans);
    }

    public static long inverseElement(long a, long n){
        long b = n, u=1, v=0;
        while(b > 0) {
            long t = a/b;
            a -= t*b;
            u -= t*v;
            //swap
            t = a;
            a = b;
            b = t;
            t = u;
            u = v;
            v = t;
        }
        u = u % n;
        if(u < 0) u += n;
        return u;
    }

    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte())
                return buffer[ptr++];
            else
                return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr]))
                ptr++;
            return hasNextByte();
        }

        public String next() {
            if (!hasNext())
                throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            if (!hasNext())
                throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
                throw new NumberFormatException();
            return (int) nl;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

