		int K = ni();
		X = new long[N+1];
		X[N-1] = M;
		for (int i = N-2; i >= 0; i--) {
			X[i] = (X[i+1] * (M-1)) % MOD;
		}
		COMinit();
		long ans = 0;
		for (int i = 0; i <= K; i++) {
			ans = (ans + (X[i] * COM(N-1, i)) % MOD) % MOD;
//			out.println("ans = " + ans + "  X[" + i + "] = " + X[i]
//							+ "  COM(" + (N-1) + ", " + i + ") = " + COM(N-1,i));
		}
		out.println(ans);
	}
	int MAX = 2100000;
	long[] fac, finv, inv;			// a! (fac[a])   (a!)の-1乗 (finv[a])

	// テーブルを作る前処理　→　これを呼んでから COM() を呼ぶ
	void COMinit() {
		fac = new long[MAX];
		finv = new long[MAX];
		inv = new long[MAX];
		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for (int i = 2; i < MAX; i++){
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}
	// 組み合わせの数を計算する(a個の中からb個を選ぶ）
	long COM(int n, int k){
		if (n < k)		return 0;
		if (n < 0 || k < 0)		return 0;
		return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	}

