public void solve() {
	int n = ni();
	int m = ni();
	int k = ni();
	long ans = pow_m(m, n);
	for(int i = 1; i <= n - k - 1; i ++) {
		long tmp = C(n - 1, i - 1);
		tmp *= pow_m(m - 1, i - 1);
		tmp = mod(tmp);
		tmp *= m;
		tmp = mod(tmp);
		ans -= tmp;
		ans = mod(ans);
	}
	prtln(ans);
}



