			fac[i]=fac[i-1]*i;
			fac[i]%=MOD;
		}

		inv[n]=pow(fac[n],(int) (MOD-2));
		for(int i=n-1;i>=0;i--)
		{
			inv[i]=inv[i+1]*(i+1);
			inv[i]%=MOD;
		}
	}



