//			if (i >= k - 5 || i <= 5 || nextPattern < 0 || pattern < 0 || mult < 0 || countPattern < 0) {
//				System.out.println("k " + i + " next " + nextPattern + " pattern " + pattern + " mult " + mult + " countPattern " + countPattern);
//			}
		}

		// 出力
		System.out.println(countPattern);
		sc.close();
	}

	public static int combi(int n, int r) {
		if (n - r < r) {
			r = n - r;
		}

		int[] numerator = new int[r];
		int[] denominator = new int[r];

		for (int i = 0; i < r; i++) {
			numerator[i] = n - i;
			denominator[i] = r - i;
		}

		for (int i = 0; i < r; i++) {
			for (int j = 0; j < r; j++) {
				if (numerator[i] % denominator[i] == 0) {
					numerator[i] /= denominator[i];
					break;
				}
			}
		}

		int temp = 1;
		for (int i = 0; i < r; i++) {
			temp = limitOff((long)temp * (long)numerator[i]);
		}

//		System.out.println("combi " + n + " " + r + " " + temp);
		return temp;
	}

	public static int multi(int a, int b) {
		long limit = Long.MAX_VALUE - (long) 998244353;
		long la = (long) a;
		long lb = (long) b;
		int result = 0;

		long div = limit / la;
		while (lb > 0) {
			if (div < lb) {
				result = limitOff((long)result + la * div);
				lb -= div;
			} else {
				result = limitOff((long)result + la * lb);
				lb = 0;
			}
		}
		return result;
	}

	public static int limitOff(long base) {
		int limit = 998244353;
		int temp = (int) base;
		if (base > limit) {
			temp = (int) (base % limit);
		}
//		System.out.println("limitOff " + base + " -> " + limit + " * " + (int) (base / limit) + " + " + temp);
		return temp;
	}
}

import java.util.*;
public class Main {
  	private static final int MAX = 510000;
	private static long[] fac = new long[MAX];
	private static long[] inv = new long[MAX];
	private static long[] finv = new long[MAX];
	private static final int constant = 998244353;

  	public Main() {
    	fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for(int i = 2; i < MAX; i++) {
			fac[i] = fac[i - 1] * i % constant;
			inv[i] = constant - inv[constant%i] * (constant / i) % constant;
			finv[i] = finv[i - 1] * inv[i] % constant;
		}
    }

    public static void main(String[] args){
		Scanner s = new Scanner(System.in);
		int N = s.nextInt();
		int M = s.nextInt();
		int K = s.nextInt();

		final LongBinaryOperator pow = (i, j) -> {
			long result = 1;
			while(j > 0) {
				if((j & 1) == 1)
					result = (result * i) % constant;
				i = (i  * i) % constant;
				j >>= 1;
			}
			return result;
		};

		final IntUnaryOperator function = i -> {
			return (int)(M * getNewCom(N - 1, i) % constant * pow.applyAsLong(M-1, N-i-1) % constant);
		};

		long result = 0;
		for(int i = 0; i < K + 1; i++) {
			result = (result + function.applyAsInt(i)) % constant;
		}

		System.out.println(result);
    }

  	private static long getNewCom(int n, int k) {
		if( n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * (finv[k] * finv[n - k] % constant) % constant;
	}
}

import java.util.*;

public class Main {
    static final long MODVAL = 998244353L;
    static long dp[][];
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        dp = new long[N+1][2];
        // s番目までのブロックを塗って重複塗りがk回の塗り方はdp[s][k]通りだとする。
        // dp[s+1][k] = dp[s][k] * (M-1) + dp[s][k-1]
        // 1st param: 1 -> N
        // 2nd param: 0 -> K
        dp[1][0] = M;
        long result = 0L;
        for(int k=0; k<=K; k++) {
            int current = k % 2;
            int previous = (k+1) % 2;
            switch(k) {
                case 0:
                    dp[1][current] = M;
                    break;
                case 1:
                    dp[1][current] = 0;
                    dp[1][previous] = M;
                    break;
                default:
                    dp[1][current] = 0;
                    dp[1][previous] = 0;
                    break;
            }
            for(int s=1; s<=N-1; s++) {
                if(k==0) {
                    dp[s+1][current] = (dp[s][current] * (M-1)) % MODVAL;
//                    System.out.println(String.format("dp[%d][%d]=%d", s+1, k, dp[s][current]));
                } else {
                    dp[s+1][current] = (dp[s][current] * (M-1) + dp[s][previous]) % MODVAL;
//                    System.out.println(String.format("dp[%d][%d]=%d", s+1, k, dp[s][current]));
                }
            }
            result = (result + dp[N][current]) % MODVAL;
        }
        System.out.println(result);
    }
}

