import java.util.StringTokenizer;

public class Main {
    private static final int MOD = 998244353;

    public static void main(final String[] args) {
        final FastScanner scanner = new FastScanner(System.in);
        final int n = scanner.nextInt();
        final long m = scanner.nextInt();
        final long k = scanner.nextInt();

        if (n == 1) {
            System.out.println(m);
            return;
        }

        final CombinationCalculator calculator = new CombinationCalculator(n, MOD);

        long answer = 0;
        long base = m;
        for (int j = 1; j < n; j++) {
            base *= m - 1;
            base %= MOD;
        }

        final long inv = modInv(m - 1);
        for (int i = 0; i <= k; i++) {
            long multi = base * calculator.calc(n - 1, i);
            multi %= MOD;
            answer += multi;
            answer %= MOD;

            base *= inv;
            base %= MOD;
        }

        System.out.println(answer);
    }

    private static long modInv(final long a) {
        return modPow(a, MOD - 2);
    }

    private static long modPow(long a, long n) {
        long res = 1;
        while (n > 0) {
            if ((n & 1) != 0) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            n >>= 1;
        }
        return res;
    }

    private static class CombinationCalculator {
        private final int size;
        private final int mod;
        private final long[] factorials;
        private final long[] invertedElements;
        private final long[] invertedFactorials;

        CombinationCalculator(final int size, final int mod) {
            this.size = size;
            this.mod = mod;
            this.factorials = new long[size];
            this.invertedElements = new long[size];
            this.invertedFactorials = new long[size];
            init();
        }

        private void init() {
            factorials[0] = 1;
            factorials[1] = 1;
            invertedFactorials[0] = 1;
            invertedFactorials[1] = 1;
            invertedElements[1] = 1;
            for (int i = 2; i < size; i++) {
                factorials[i] = factorials[i - 1] * i % mod;
                invertedElements[i] = mod - invertedElements[mod % i] * (mod / i) % mod;
                invertedFactorials[i] = invertedFactorials[i - 1] * invertedElements[i] % mod;
            }
        }

        /**
         * mod 込みで nCk を計算した結果を返す．
         *
         * @param n 組み合わせの対象となる数
         * @param k 組み合わせる個数
         * @return 組み合わせの結果
         */
        long calc(final int n, final int k) {
            return factorials[n] * (invertedFactorials[k] * invertedFactorials[n - k] % mod) % mod;
        }
    }


    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.util.function.*;
public class Main {
  	private static final int MAX = 510000;
	private static long[] fac = new long[MAX];
	private static long[] inv = new long[MAX];
	private static long[] finv = new long[MAX];
	private static final int constant = 998244353;

  	public Main() {
    	fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for(int i = 2; i < MAX; i++) {
			fac[i] = fac[i - 1] * i % constant;
			inv[i] = constant - inv[constant%i] * (constant / i) % constant;
			finv[i] = finv[i - 1] * inv[i] % constant;
		}
    }

    public static void main(String[] args){
		Scanner s = new Scanner(System.in);
		int N = s.nextInt();
		int M = s.nextInt();
		int K = s.nextInt();

		final LongBinaryOperator pow = (i, j) -> {
			long result = 1;
			while(j > 0) {
				if((j & 1) == 1)
					result = (result * i) % constant;
				i = (i  * i) % constant;
				j >>= 1;
			}
			return result;
		};

		final IntUnaryOperator function = i -> {
			return (int)(M * getNewCom(N - 1, i) % constant * pow.applyAsLong(M-1, N-i-1) % constant);
		};

		long result = 0;
		for(int i = 0; i < K + 1; i++) {
			result = (result + function.applyAsInt(i)) % constant;
		}

		System.out.println(result);
    }

  	private static long getNewCom(int n, int k) {
		if( n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * (finv[k] * finv[n - k] % constant) % constant;
	}
}

