class CombMod {

  // デフォルトのMAX値
  static final int MAX = 200_010;

  List<Long> fac;
  List<Long> finv;

  CombMod() {
    combIni(MAX);
  }

  CombMod(int m) {
    fac = new ArrayList<>();
    finv = new ArrayList<>();
    combIni(m);
  }

  void combIni(int max) {
    fac.add(1L);
    fac.add(1L);
    finv.add(1L);
    finv.add(1L);
    for (int i = 2; i <= max; i++) {
      fac.add(MyMod.mul(fac.get(i - 1), i));
      finv.add(MyMod.div(finv.get(i - 1), i));
    }
  }

  long combMOD(int n, int r) {
    if (n < r) return 0L;
    if (n < 0 || r < 0) return 0L;
    if (r == 0) return 1L;
    return MyMod.mul(fac.get(n), MyMod.mul(finv.get(r), finv.get(n - r)));
  }
}

