class SegmentTree{

    //------------------------------------------------------------
    // 2 * n - 1 : 木全体のノード数
    // i + n - 1 : 配列のi番目が対応するノードの番号
    // 2 * i + 1, 2 * i + 2 : i番目のノードの子ノードの番号
    // (i - 1) / 2 : i番目のノードの親ノードの番号
    //
    // int n = sc.nextInt();
    // long[] a = new long[n];
    // for(int i = 0; i < n; i++) a[i] = sc.nextLong();
    // SegmentTree st = new SegmentTree(a);
    // int l = sc.nextInt() - 1;
    // int r = sc.nextInt() - 1;
    // System.out.println(st.query(l, r));
    //------------------------------------------------------------

    final static long INF = Long.MAX_VALUE / 2;

    // long e = INF; // 単位元
    long e = 0;
    long func(long a, long b){ // 処理
        // return Math.min(a, b);
        return a + b;
    }

    int n; // 配列の要素数を超える最小の2のべき乗
    long[] node;

    SegmentTree(long[] a){
        init(a);
    }

    void init(long[] a){ // 配列aで初期化
        n = 1;
        while(n < a.length){
            n *= 2;
        }
        node = new long[2 * n - 1];
        Arrays.fill(node, e);
        for(int i = 0; i < a.length; i++){
            node[i + n - 1] = a[i];
        }
        for(int i = n - 2; i >= 0; i--){
            node[i] = func(node[2 * i + 1], node[2 * i + 2]);
        }
    }

    void update(int p, long v){ // 配列のp番目をvに変更し、木全体を更新
        p = p + n - 1;
        node[p] = v;
        while(p > 0){
            p = (p - 1) / 2;
            node[p] = func(node[2 * p + 1], node[2 * p + 2]);
        }
    }

    long query(int a, int b){ // 区間[a, b)についてクエリを処理
        return query(a, b, 0, 0, n);
    }

    long query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return e;
        if(a <= l && r <= b) return node[k];
        return func(query(a, b, 2 * k + 1, l, (l + r) / 2), query(a, b, 2 * k + 2, (l + r) / 2, r));
    }

}



class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte(){
        if(ptr < buflen){
            return true;
        }else{
            ptr = 0;
            try{
                buflen = in.read(buffer);
            }catch(IOException e){
                e.printStackTrace();
            }
            if(buflen <= 0){
                return false;
            }
        }
        return true;
    }
    private int readByte(){
        if(hasNextByte()) return buffer[ptr++];
        else return -1;
    }
    private static boolean isPrintableChar(int c){
        return 33 <= c && c <= 126;
    }
    public boolean hasNext(){
        while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasNextByte();
    }
    public String next(){
        if(!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong(){
        if(!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if(b == '-'){
            minus = true;
            b = readByte();
        }
        if(b < '0' || '9' < b){
            throw new NumberFormatException();
        }
        while(true){
            if('0' <= b && b <= '9'){
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt(){
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble(){
        return Double.parseDouble(next());
    }
}

