class Combination {

    /** factorial:階乗 */
    private long fac[];
    /** inverse:逆元（ここでは、fac[i]をMOD-2乗したものをMODで割った余り） */
    private long inv[];
    /** 除数 */
    private int mod;

    /**
     * コンストラクタ
     * @param size 組み合わせの対象となる個数
     * @param mod 除数
     */
    public Combination(int size, int mod){
        this.fac = new long[size +1];
        this.inv = new long[size +1];
        this.mod = mod;

        this.fac[0] = 1;
        this.inv[0] = 1;

        for(int i = 1; i <= size; i++){
            fac[i] = (fac[i -1] * i) %mod;
            inv[i] = modPow(fac[i], (int)mod -2) %mod;
        }
    }

    /**
     * n個の中からr個選ぶ組み合わせの数（nCr）をmodで割った余りを算出する
     * @param n 元の集合の要素数
     * @param r 組み合わせる要素数
     * @return nCr % mod
     */
    public long comb(int n, int r){
        return fac[n] * inv[r] %mod * inv[n - r] %mod;
    }

    /**
     * base^exp をmodで割った余りを算出する
     * @param base 基数
     * @param exp 指数
     * @return base^exp % mod
     */
    private long modPow(long base, int exp) {
        long ret = 1;
        while(exp > 0){
            if((exp & 1) == 1){
                ret = ret * base %mod;
            }
            base = base * base %mod;
            exp >>= 1;
        }
        return ret;
    }

}

import java.util.*;
public class Main {
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		// 文字列の入力
		int n = sc.nextInt();
		long m = sc.nextLong();
		int k = sc.nextInt();

		long limit = 998244353;
		long[] nextPattern = new long[k + 1];
		long[] colorPattern = new long[k + 1];

		//隣り合わせが k + 1 個ある時の色の組み合わせを算出
		long pattern = 1;
		if (k < n - 1) {
			for (int i = 0; i <= n - k - 2; i++) {
				if (i == 0) {
					pattern = m;
				} else {
					pattern = (pattern * (m - 1)) % limit;
				}
			}
		}
		//1～k個の連続が発生する個数を計算する。
		for (int i = 0; i <= k; i++) {
			//どこが隣り合わせになるかの組み合わせ。
			if (i == 0) {
				nextPattern[i] = 1;
			} else if (i > (n - 1) / 2) {
				nextPattern[i] = nextPattern[n - 1 - i];
			} else {
				//nCr = nC(r - 1) * (n - r) / (r + 1) -> nextPattern[i - 1] * (n - i) / i
				//余りの割り算は、モジュラ逆数を掛ける。
				nextPattern[i] = (((nextPattern[i - 1] * (long) (n - i)) % limit) * (long) modinv(i, (int) limit)) % limit;
				if (nextPattern[i] < 0) {
					nextPattern[i] += limit;
				}
			}

			//色の組み合わせ。
			if (i == 0) {
				if (k == n - 1) {
					colorPattern[k - i] = m;
				} else {
					colorPattern[k - i] = (pattern * (m - 1)) % limit;
				}
			} else {
				colorPattern[k - i] = (colorPattern[k - i + 1] * (m - 1)) % limit;
			}
		}

		long countPattern = 0;
		for (int i = 0; i <= k; i++) {
			countPattern = (countPattern + (nextPattern[i] * colorPattern[i]) % limit) % limit;
		}

		// 出力
		System.out.println(countPattern);
		sc.close();
	}

	//モジュラ逆数
	public static int modinv(int a, int m) {
		int tempA = a;
		int tempB = m;
		int x0 = 1;
		int y0 = 0;
		int x1 = 0;
		int y1 = 1;
		while (tempB != 0) {
			int q = tempA / tempB;
			int temp = tempA;
			tempA = tempB;
			tempB = temp % tempB;
			temp = x0;
			x0 = x1;
			x1 = temp - q * x1;
			temp = y0;
			y0 = y1;
			y1 = temp - q * y1;
		}
		return x0 % m;
	}
}

import java.io.*;
import java.util.*;

public class Main {
    static PrintWriter out = new PrintWriter(System.out);
    static Scanner sc = new Scanner(System.in);
    static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    long mod = 998244353;
    long[] fac, inv;
    public static void main(String[] args) throws IOException {
        Main main = new Main();
        main.solve();
        out.flush();
    }
    void solve(){
        int n = sc.nextInt(), m = sc.nextInt(), k = sc.nextInt();
        fac = new long[n+1]; inv = new long[n+1];
        fac[0] = 1; inv[0] = 1;
        for(int i=1;i<=n;i++) fac[i] = i*fac[i-1]%mod;
        inv[n] = power(fac[n],mod-2);
        for(int i=n-1;i>0;i--){
            inv[i] = (i+1)*inv[i+1]%mod;
        }
        long ans = 0;
        for(int i=0;i<=k;i++){
            // there are exactly i pair of adjacent blocks that have the same color
            // then we lose i blocks
            long tempN = n-i;
            long cur = m*power(m-1,tempN-1)%mod*comb(n-1,i)%mod;
            ans = (ans+cur)%mod;
        }
        ans %= mod;
        out.println(ans);
    }
    long comb(int n, int m){
        if(n<m ) return 0;
        return fac[n]*inv[m]%mod*inv[n-m]%mod;
    }
    long power(long base, long p){
        long ans = 1;
        while(p>0){
            if(p%2==1) ans = ans*base%mod;
            base = base*base%mod;
            p /= 2;
        }
        return ans;
    }
}

