			invFac[i-1] = (i*invFac[i])%MOD;
		}

		long ans = 0;
		for (int k = 0; k <= K; k++) {
			long choose = (((fac[N-1]*invFac[k])%MOD)*invFac[N-1-k])%MOD;
			long other = (M*power(M-1,N-k-1,MOD))%MOD;
