        combination c = new combination(n);
        long ans = 0;
        long now = m;
        for(int x = n-1; x >= 0; x--){
            long tmp = now;
            tmp *= c.comb(n-1,x)%mod;
            tmp %= mod;
            if(x <= k){
                ans += tmp;
                ans %= mod;
            }
            now *= m-1;
            now %= mod;
        }
        System.out.println(ans%mod);
