    static class EColorfulBlocks {
        public void solve(int testNumber, InputReader c, OutputWriter w) {
            final long mod = 998244353;
            int n = c.readInt(), m = c.readInt(), k = c.readInt();

            long res = 0;
            long fact[] = new long[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % mod;
            }

            for (int p = n - k; p <= n; p++) {
                long ans = Utils.ncr(n - 1, p - 1, fact, mod);
                ans = (ans * m) % mod;
                ans = (ans * Utils.power(m - 1, p - 1, mod)) % mod;
                res += ans;
                res %= mod;
            }

            w.printLine(res);


        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class Utils {
        public static long modInverse(long a, long m) {
            return power(a, m - 2, m);
        }

        public static long ncr(long n, long r, long[] fac, long mod) {
            if (n < 0 || r < 0) {
                return 0;
            }
            long p = mod;
            return (fac[(int) n] * modInverse(fac[(int) r], p)
                    % p * modInverse(fac[(int) (n - r)], p)
                    % p) % p;
        }

        public static long power(long x, long y, long p) {
            long res = 1;
            x = x % p;
            while (y > 0) {
                if ((y & 1) == 1) {
                    res = (res * x) % p;
                }
                y = y >> 1;
                x = (x * x) % p;
            }
            return res;
        }

    }

