class Combination {
  long[] factorial; //階乗
  long[] inverse; //逆元
  final long MOD;
  public Combination(int n, long mod){
    this.MOD = mod;
    factorial = new long[n + 1];
    inverse = new long[n + 1];
    factorial[0] = 1;
    inverse[0] = 1;
    for (int i = 1; i <= n; i++) {
      factorial[i] = factorial[i - 1] * i % MOD;
      inverse[i] = pow(factorial[i], MOD - 2);
    }
  }
  long p(int n, int r){
    return factorial[n] * inverse[n - r] % MOD;
  }
  long c(int n, int r){
    return factorial[n] * inverse[r] % MOD * inverse[n - r] % MOD;
  }
  long pow(long x, long n) {
    long answer = 1l;
    while (n > 0) {
      if((n & 1) == 1){
        answer = answer * x % MOD;
      }
      x = x * x % MOD;
      n >>= 1;
    }
    return answer;
  }
}

import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに実装したソースコード
 */
public class Main {

	private static final long MOD = 998_244_353;

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt(), m = scanner.nextInt(), k = scanner.nextInt();
			// n-1_C_i のmod結果を格納する配列
			long[] c = new long[n];
			c[n - 1] = c[0] = 1;
			IntStream.rangeClosed(1, (n - 1) / 2)
					.forEach(i -> c[n - 1 - i] = c[i] = c[i - 1] * (n - i) % MOD * modpow(i, MOD - 2) % MOD);
			// (m-1)^i のmod結果を格納する配列
			long[] mp = new long[n];
			mp[0] = 1;
			IntStream.range(1, n).forEach(i -> mp[i] = mp[i - 1] * (m - 1) % MOD);
			long result = 0L;
			for (int i = 0; i <= k; i++) {
				result = (result + m * c[i] % MOD * mp[n - 1 - i] % MOD) % MOD;
			}
			System.out.println(result);
		}
	}

	/**
	 * nのmべき乗 mod MOD を計算する
	 * 
	 * @param n
	 * @param m
	 * @return nのmべき乗 mod MOD
	 */
	private static long modpow(long n, long m) {
		long result = 1L;
		while (m > 0) {
			if (1 == (m & 1)) {
				result = result * n % MOD;
			}
			n = n * n % MOD;
			m >>= 1;
		}
		return result;
	}
}

