    public class Fact
    {
        //i!
        private readonly int[] _fact;

        //i!^-1
        private readonly int[] _inv;

        public Fact() : this(200010) { }

        /// <summary>
        /// 1以上N以下の階乗を計算します。
        /// </summary>
        public Fact(int N) {
            var lastFact = ModInt.One;
            _fact = new int[N + 1];
            _fact[0] = 1;
            foreach (int i in Range(1, N + 1)) {
                lastFact *= i;
                _fact[i] = lastFact.Value;
            }

            var lastInv = lastFact.Invert;
            _inv = new int[N + 1];
            _inv[N] = lastInv.Value;
            foreach (int i in Range(N).Reverse()) {
                lastInv *= i + 1;
                _inv[i] = lastInv.Value;
            }

            _inv[0] = _inv[1];
        }

        public int this[int i] => _fact[i];

        /// <summary>
        /// 組み合わせの数 nCr を求めます。
        /// </summary>
        /// <remarks>N以上の数で初期化している必要があります。</remarks>
        public int nCr(int n, int r) {
            if (n - r < 0) return 0;
            if (n >= _fact.Length)
                throw new ArgumentOutOfRangeException(nameof(n), "Fact クラスのインスタンスをn以上で初期化している必要があります。");
            var ret = ModInt.One;
            // n! / (n-r)!r!

            ret *= _fact[n];
            //逆元でかける
            ret *= _inv[n - r];
            ret *= _inv[r];
            return ret.Value;
        }

        /// <summary>
        /// 重複組み合せの数 nHr を求めます。
        /// </summary>
        /// <remarks>N以上の数で初期化している必要があります。</remarks>
        public int nHr(int n, int r) {
            n = r + n - 1;
            if (n - r < 0) return 0;
            if (n >= _fact.Length)
                throw new ArgumentOutOfRangeException(nameof(n), "Fact クラスのインスタンスをn + rより大きな数で初期化している必要があります。");
            return nCr(n, r);
        }

        /// <summary>
        /// 順列の数 nPr を求めます。
        /// </summary>
        /// <remarks>N以上の数で初期化している必要があります。</remarks>
        public int nPr(int n, int r) {
            if (n - r < 0) return 0;
            if (n >= _fact.Length)
                throw new ArgumentOutOfRangeException(nameof(n), "Fact クラスのインスタンスをn以上で初期化している必要があります。");
            var ret = ModInt.One;
            // n! / (n-r)!r!

            ret *= _fact[n];
            //逆元でかける
            ret *= _inv[n - r];
            return ret.Value;
        }
    }

    [DebuggerDisplay("{" + nameof(_value) + "}")]
    public struct ModInt : IEquatable<ModInt>, IComparable<ModInt>
    {
        public const int MOD = Solver.MOD;
        private long _value;
        public static readonly ModInt Zero = new ModInt(0);
        public static readonly ModInt One = new ModInt(1);
        public ModInt(in long value) => _value = (value % MOD + MOD) % MOD;
        public int Value => (int) _value;
        public ModInt Invert => ModPow(this, MOD - 2);
        public static ModInt operator -(ModInt value) {
            value._value = MOD - value._value;
            return value;
        }
        public static ModInt operator +(ModInt left, in ModInt right) {
            left._value += right._value;
            if (left._value >= MOD) left._value -= MOD;
            return left;
        }
        public static ModInt operator -(ModInt left, in ModInt right) {
            left._value -= right._value;
            if (left._value < 0) left._value += MOD;
            return left;
        }
        public static ModInt operator *(ModInt left, in ModInt right) => left._value * right._value % MOD;
        public static ModInt operator /(ModInt left, in ModInt right) => left * right.Invert;
        public static ModInt operator ++(ModInt value) {
            if (value._value == MOD - 1) value._value = 0;
            else value._value++;
            return value;
        }
        public static ModInt operator --(ModInt value) {
            if (value._value == 0) value._value = MOD - 1;
            else value._value--;
            return value;
        }
        public static bool operator ==(ModInt left, in ModInt right) => left.Equals(right);
        public static bool operator !=(ModInt left, in ModInt right) => !left.Equals(right);
        public static implicit operator ModInt(in int value) => new ModInt(value);
        public static implicit operator ModInt(in long value) => new ModInt(value);
        public static explicit operator int(ModInt m) => m.Value;
        public static ModInt ModPow(ModInt value, long exponent) {
