public class CompetitiveProgramming {
  public void Solve() {
    var(N, M, K) = Cin<long, long, long>();
    long ans = 0;

    var fc = new Factorial(N, MOD2);
    for (long i = 0; i <= K; ++i) {
      var cur = M * Power(M - 1, N - i - 1, MOD2) % MOD2 * fc.Comb(N - 1, i) % MOD2;
      ans += cur;
      ans %= MOD2;
    }
    Put(ans);
  }

}

public class Factorial {
  public long[] Fact;
  public long[] invFact;
  long _mod;
  public Factorial(long N, long mod = 1000000007) {
    Fact = new long[N + 1];
    invFact = new long[N + 1];
    _mod = mod;
    Fact[0] = 1;
    Fact[1] = 1;
    for (long i = 2; i <= N; ++i) {
      Fact[i] = Fact[i - 1] * i % _mod;
      Fact[i] %= _mod;
    }
    invFact[N] = Power(Fact[N], _mod - 2, _mod);
    for (long i = N; i > 0; --i) {
      invFact[i - 1] = invFact[i] * i % _mod;
      invFact[i - 1] %= _mod;
    }
  }
  public long Comb(long n, long r) {
    if (n < 0 || r < 0 || n < r) return 0;
    return Fact[n] * invFact[r] % _mod * invFact[n - r] % _mod;
  }
}

public static class Math2 {
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const long MOD2 = 998244353;

  public static long Power(long a, long b, long MOD = 1000000007) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2(long a, long b) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD(long a, long b) {
    while (b > 0) {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM(long a, long b) => (b / GCD(a, b)) * a;
  public static long Comb(long n, long r, int MOD = 1000000007) {
    if (r > n - r) r = n - r;
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno = (Deno * i) % MOD;
      Nume = Nume * (n - i + 1) % MOD;
    }
    return (Nume * inv(Deno)) % MOD;
  }
  public static long Comb2(long n, long r) {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
  public static long inv(long x, int MOD = 1000000007) {
    return Power(x, MOD - 2, MOD);
  }
}
