namespace ABC167E_3
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var M = RInt;
            var K = RInt;

            long mod = 998244353;
            long a = 1;
            long b = ModPow(M - 1, N - 1, mod);
            long memo = ModPow(M - 1, mod - 2, mod);
            long ans = 0;
            for (int i = 0; i <= K; i++)
            {
                ans += a * b % mod;

                a = a * (N - i - 1) % mod * ModPow(i + 1, mod - 2, mod) % mod;
                b = b * memo % mod;
            }
            ans = ans * M % mod;

            Console.WriteLine(ans);
        }

        /// <summary>
        /// a^n (mod p)
        /// nが非常に大きい時に有効
        /// </summary>
        /// <param name="a"></param>
        /// <param name="n"></param>
        /// <param name="mod"></param>
        /// <returns></returns>
        public static long ModPow(long a, long n, long p)
        {
            if (n == 0) return 1;
            if (n == 1) return a % p;
            if (n % 2 == 1) return (a * ModPow(a, n - 1, p)) % p;

            long t = ModPow(a, n / 2, p);
            return (t * t) % p;
        }
    }


