namespace ConsoleApp32
{
    class Program
    {
        static void Main(string[] args)
        {
            var buff = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

            int N = buff[0];
            int M = buff[1];
            int K = buff[2];
            const int mod = 998244353;

            var list = Pattern(N, K, mod);
            long ans = 0;
            for(int i = 0; i <= K; i++)
            {
                ans += Paint(i, list[i], N, M, mod);
                ans %= mod;
            }

            Console.WriteLine(ans);

        }

        static List<long> Pattern(int N, int K, int mod)
        {
            var list = new List<long>();
            list.Add(1);
            var factreal = new List<long>();
            factreal = Factreal(K, mod);
            for(int i = 1; i <= K; i++)
            {
                long value = 1;
                for(int j = 1; j <= i; j++)
                {
                    value *= (N - j);
                    value %= mod;
                }
                value *= Modinv(factreal[i - 1], mod);
                value %= mod;
                list.Add(value);
            }
            return list;
        }

        static long Paint(long n_same, long pattern, int N, int M, int mod)
        {
            long value = M;
            for(int i = 1; i < N - n_same; i++)
            {
                value *= M - 1;
                value %= mod;
            }
            value *= pattern;

            return value;
        }

        static List<long> Factreal(long a, long mod)
        {
            var list = new List<long>();
            long value = 1;
            int i = 1;
            while(i <= a)
            {
                value *= i++;
                value %= mod;
                list.Add(value);
            }
            return list;
        }

        static long Modinv(long a, long m)
        {
            long b = m;
            long u = 1;
            long v = 0;
            while (b != 0)
            {
                long t = a / b;
                a -= t * b;
                (a, b) = Swap(a, b);
                u -= t * v;
                (u, v) = Swap(u, v);
            }
            u %= m;
            if(u < 0)
            {
                u += m;
            }
            return u;
        }

        static (long a, long b) Swap(long a, long b)
        {
            long temp = a;
            a = b;
            b = temp;

            return (a, b);
        }
    }
}

