class Program
{
	static void Main(string[] args)
	{
		string[]str = Console.ReadLine().Split();
		int N = int.Parse(str[0]);
		int M = int.Parse(str[1]);
		int K = int.Parse(str[2]);
		long[]D = new long[K+2];
		D[0] = M;
		long mod = 998244353;
		long[]DA = new long[200010];
		long[]DB = new long[200010];
		DA[0] = 1;
		DB[0] = 1;
		for(var i=1;i<200010;i++){
			DA[i] = DA[i-1]*i%mod;
			DB[i] = DB[i-1]*Mpow(i,mod-2,mod)%mod;
		}
		long ans = 0;
		for(var i=0;i<=K;i++){
          	//Console.Error.WriteLine(Mpow(M-1,N-1-i,mod)+" "+DA[N]+" "+DB[N-i]+" "+DB[i]);
			ans += M * Mpow(M-1,N-1-i,mod) % mod * DA[N-1] % mod * DB[N-1-i] % mod * DB[i] % mod;
			ans %= mod;
		}
		Console.WriteLine(ans%mod);
	}

	public static long Mpow(long x,long n,long m)
	{
		long ans = 1;
		while(n > 0){
			if(n % 2 == 1){
				ans = ans * x % m;
				n -= 1;
			}
			x = x * x % m;
			n /= 2;
		}
		return ans;
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace ConsoleApp32
{
    class Program
    {
        static void Main(string[] args)
        {
            var buff = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

            int N = buff[0];
            int M = buff[1];
            int K = buff[2];
            const int mod = 998244353;

            var list = Pattern(N, K, mod);
            long ans = 0;
            for(int i = 0; i <= K; i++)
            {
                ans += Paint(i, list[i], N, M, mod);
                ans %= mod;
            }

            Console.WriteLine(ans);

        }

        static List<long> Pattern(int N, int K, int mod)
        {
            var list = new List<long>();
            list.Add(1);
            for(int i = 1; i <= K; i++)
            {
                long value = 1;
                for(int j = 1; j <= i; j++)
                {
                    value *= (N - j);
                    value %= mod;
                }
                value *= Modinv(Factreal(i, mod), mod);
                value %= mod;
                list.Add(value);
            }
            return list;
        }

        static long Paint(long n_same, long pattern, int N, int M, int mod)
        {
            long value = M;
            for(int i = 1; i < N - n_same; i++)
            {
                value *= M - 1;
                value %= mod;
            }
            value *= pattern;

            return value;
        }

        static long Factreal(long a, long mod)
        {
            long value = 1;
            while(a != 1)
            {
                value *= a--;
                value %= mod;
            }
            return value;
        }

        static long Modinv(long a, long m)
        {
            long b = m;
            long u = 1;
            long v = 0;
            while (b != 0)
            {
                long t = a / b;
                a -= t * b;
                (a, b) = Swap(a, b);
                u -= t * v;
                (u, v) = Swap(u, v);
            }
            u %= m;
            if(u < 0)
            {
                u += m;
            }
            return u;
        }

        static (long a, long b) Swap(long a, long b)
        {
            long temp = a;
            a = b;
            b = temp;

            return (a, b);
        }
    }
}

