using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public class AtCoderA
{
    static void Main()
    {
        var sc = new Scanner();

        long n = sc.NextLong();
        long m = sc.NextLong();
        long k = sc.NextLong();

        long mod = 998244353;

        long answer = 0;
        for (int i = 0; i <= k; i++)
        {
            long tmp = m * Pow(m - 1, n - i - 1, mod) % mod * Combination(n - 1, i, mod) % mod;
            answer += tmp;
            answer %= mod;
        }

        Console.WriteLine(answer);
    }

    // Combination（mod版）
    private static long Combination(long a, long b, long c)
    {
        long numerator = 1;
        long denominator = 1;
        for (long i = 1; i <= b; i++)
        {
            numerator = Mul(numerator, a - i + 1, c);
            denominator = Mul(denominator, i, c);
        }
        return Div(numerator, denominator, c);
    }

    // 掛け算（mod版）
    private static long Mul(long a, long b, long c)
    {
        return ((a % c) * (b % c)) % c;
    }

    // 割り算（mod版）
    private static long Div(long a, long b, long c)
    {
        return Mul(a, Pow(b, c - 2, c), c);
    }

    // べき乗（mod版）
    private static long Pow(long a, long b, long c)
    {
        if (b == 0)
        {
            return 1;
        }
        else if (b == 1)
        {
            return a % c;
        }
        else if (b % 2 == 0)
        {
            long d = Pow(a, b / 2, c);
            return d * d % c;
        }
        else
        {
            return a * Pow(a, b - 1, c) % c;
        }
    }

