public class AtCoderA
{
    static void Main()
    {
        var sc = new Scanner();

        int n = sc.NextInt();
        int m = sc.NextInt();
        int k = sc.NextInt();

        long mod = 998244353;

        ModInt answer = 0;
        BinomialCoefficient bc = new BinomialCoefficient(n);
        for (int i = 0; i <= k; i++)
        {
            ModInt tmp = m * ModInt.Pow(m - 1, n - i - 1) * bc[n - 1, i];
            answer += tmp;
        }

        Console.WriteLine(answer);
    }

    public struct ModInt
    {
        /// <summary>
        /// 剰余を取る値．
        /// </summary>
        public const long Mod = 998244353;

        /// <summary>
        /// 実際の数値．
        /// </summary>
        public long num;
        /// <summary>
        /// 値が <paramref name="n"/> であるようなインスタンスを構築します．
        /// </summary>
        /// <param name="n">インスタンスが持つ値</param>
        /// <remarks>パフォーマンスの問題上，コンストラクタ内では剰余を取りません．そのため，<paramref name="n"/> ∈ [0,<see cref="Mod"/>) を満たすような <paramref name="n"/> を渡してください．このコンストラクタは O(1) で実行されます．</remarks>
        public ModInt(long n) { num = n; }
        /// <summary>
        /// このインスタンスの数値を文字列に変換します．
        /// </summary>
        /// <returns>[0,<see cref="Mod"/>) の範囲内の整数を 10 進表記したもの．</returns>
        public override string ToString() { return num.ToString(); }
        public static ModInt operator +(ModInt l, ModInt r) { l.num += r.num; if (l.num >= Mod) l.num -= Mod; return l; }
        public static ModInt operator -(ModInt l, ModInt r) { l.num -= r.num; if (l.num < 0) l.num += Mod; return l; }
        public static ModInt operator *(ModInt l, ModInt r) { return new ModInt(l.num * r.num % Mod); }
        public static implicit operator ModInt(long n) { n %= Mod; if (n < 0) n += Mod; return new ModInt(n); }

        /// <summary>
        /// 与えられた 2 つの数値からべき剰余を計算します．
        /// </summary>
        /// <param name="v">べき乗の底</param>
        /// <param name="k">べき指数</param>
        /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
        public static ModInt Pow(ModInt v, long k) { return Pow(v.num, k); }

        /// <summary>
        /// 与えられた 2 つの数値からべき剰余を計算します．
        /// </summary>
        /// <param name="v">べき乗の底</param>
        /// <param name="k">べき指数</param>
        /// <returns>繰り返し二乗法により O(N log N) で実行されます．</returns>
        public static ModInt Pow(long v, long k)
        {
            long ret = 1;
            for (k %= Mod - 1; k > 0; k >>= 1, v = v * v % Mod)
                if ((k & 1) == 1) ret = ret * v % Mod;
            return new ModInt(ret);
        }
        /// <summary>
        /// 与えられた数の逆元を計算します．
        /// </summary>
        /// <param name="v">逆元を取る対象となる数</param>
        /// <returns>逆元となるような値</returns>
        /// <remarks>法が素数であることを仮定して，フェルマーの小定理に従って逆元を O(log N) で計算します．</remarks>
        public static ModInt Inverse(ModInt v) { return Pow(v, Mod - 2); }
    }

    public class BinomialCoefficient
    {
        public ModInt[] fact, ifact;
        public BinomialCoefficient(int n)
        {
            fact = new ModInt[n + 1];
            ifact = new ModInt[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++)
                fact[i] = fact[i - 1] * i;
            ifact[n] = ModInt.Inverse(fact[n]);
            for (int i = n - 1; i >= 0; i--)
                ifact[i] = ifact[i + 1] * (i + 1);
            ifact[0] = ifact[1];
        }
        public ModInt this[int n, int r]
        {
            get
            {
                if (n < 0 || n >= fact.Length || r < 0 || r > n) return 0;
                return fact[n] * ifact[n - r] * ifact[r];
            }
        }
        public ModInt RepeatedCombination(int n, int k)
        {
            if (k == 0) return 1;
            return this[n + k - 1, k];
        }
    }

    class Scanner
    {
        private string[] _line;
        private int _index;
        private const char Separator = ' ';

        public Scanner()
        {
            _line = new string[0];
            _index = 0;
        }

        public string Next()
        {
            while (_index >= _line.Length)
            {
                _line = Console.ReadLine().Split(Separator);
                _index = 0;
            }

            return _line[_index++];
        }

        public int NextInt() => int.Parse(Next());
        public long NextLong() => long.Parse(Next());
        public double NextDouble() => double.Parse(Next());
        public decimal NextDecimal() => decimal.Parse(Next());
        public char NextChar() => Next()[0];
        public char[] NextCharArray() => Next().ToCharArray();

        public string[] Array()
        {
            _line = Console.ReadLine().Split(Separator);
            _index = _line.Length;
            return _line;
        }

        public int[] IntArray() => Array().Select(int.Parse).ToArray();
        public long[] LongArray() => Array().Select(long.Parse).ToArray();
        public double[] DoubleArray() => Array().Select(double.Parse).ToArray();
        public decimal[] DecimalArray() => Array().Select(decimal.Parse).ToArray();
    }
}

using System;
using System.IO;
using System.Linq;

namespace AtCoder.R167.E
{
    public static class Solver
    {
        public static void Main()
        {
            using (var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Solve(Console.In, sw);
            }
        }

        public static void Solve(TextReader tr, TextWriter tw)
        {
            WriteAnswer(tw, Parse(tr));
        }

        private static void WriteAnswer(TextWriter tw, int answer)
        {
            tw.WriteLine(answer);
        }

        private static int Parse(TextReader tr)
        {
            var w = tr.ReadLine().Split().Select(c => long.Parse(c)).ToArray();

            return Calc(w[0], w[1], w[2]);
        }

        public static int Calc(long n, long m, long k)
        {
            var modulo = new Modulo(998244353);

            var res = modulo.Create(0);

            var combination = new ModuloInteger[k + 1];
            combination[0] = modulo.Create(1);

            for (int i = 1; i <= k; ++i)
            {
                combination[i] = combination[i - 1] * (n - i) / i;
            }

            for (int i = 0; i <= k; ++i)
            {
                res += combination[i] * m * modulo.Pow(m - 1, n - 1 - i);
            }
            return res;
        }
    }

    public struct ModuloInteger : IEquatable<ModuloInteger>
    {
        readonly long value;
        readonly int mod;

        internal ModuloInteger(long value, int mod)
        {
            this.value = (value + mod) % mod;
            this.mod = mod;
        }

        public bool Equals(ModuloInteger other)
        {
            return mod == other.mod && value == other.value;
        }

        public static ModuloInteger Pow(ModuloInteger x, long n)
        {
            var res = new ModuloInteger(1, x.mod);

            for (; n > 0; n >>= 1, x *= x)
                if ((n & 1) == 1)
                    res *= x;

            return res;
        }

        public override bool Equals(object obj)
        {
            return obj is ModuloInteger && Equals((ModuloInteger)obj);
        }

        public override int GetHashCode()
        {
            return value.GetHashCode() ^ mod.GetHashCode();
        }

        public static bool operator ==(ModuloInteger left, ModuloInteger right)
        {
            return left.Equals(right);
        }

        public static bool operator !=(ModuloInteger left, ModuloInteger right)
        {
            return !(left == right);
        }

        public static ModuloInteger LeftShift(ModuloInteger left, int right)
        {
            return left * Pow(new ModuloInteger(2, left.mod), right);
        }

        public static ModuloInteger operator <<(ModuloInteger left, int right)
        {
            return LeftShift(left, right);
        }

        public static ModuloInteger Add(ModuloInteger left, long right)
        {
            return new ModuloInteger(left.value + right, left.mod);
        }

        public static ModuloInteger operator +(ModuloInteger left, long right)
        {
            return Add(left, right);
        }

        public static ModuloInteger operator -(ModuloInteger left, long right)
        {
            return new ModuloInteger(left.value - right, left.mod);
        }

        public static ModuloInteger operator -(long left, ModuloInteger right)
        {
            return new ModuloInteger(left - right.value, right.mod);
        }

        public static ModuloInteger operator ++(ModuloInteger m)
        {
            return Increment(m);
        }
        public static ModuloInteger Increment(ModuloInteger item)
        {
            return item + 1;
        }

        public static ModuloInteger Multiply(ModuloInteger left, long right)
        {
            return new ModuloInteger(left.value * right, left.mod);
        }

        public static ModuloInteger operator *(ModuloInteger left, long right)
        {
            return Multiply(left, right);
        }

        public static ModuloInteger operator /(ModuloInteger left, long right)
        {
            return Pow(new ModuloInteger(right, left.mod), left.mod - 2) * left;
        }

        public static implicit operator int(ModuloInteger value)
        {
            return ToInt32(value);
        }

        public static int ToInt32(ModuloInteger value)
        {
            return (int)value.value;
        }
    }

    public class Modulo
    {
        readonly int mod;
        public Modulo(int mod)
        {
            this.mod = mod;
        }

        public ModuloInteger Create(long v)
        {
            return new ModuloInteger(v, mod);
        }

        public ModuloInteger Pow(long value, long exponent)
        {
            return ModuloInteger.Pow(Create(value), exponent);
        }
    }
}

