        long result = 0;
        for (int i = 0; i <= K; i++)
        {
            long subtotal = M;
            subtotal *= Mpow(M - 1, N - i - 1, mod);
            subtotal %= mod;
            subtotal *= Combination.combination(N - 1, i);
            subtotal %= mod;
            result += subtotal;
            result %= mod;
        }
        Console.WriteLine(result);
    }
    public static long Mpow(long x, long n, long m)
    {
        long ans = 1;
        while (n > 0)
        {
            if (n % 2 == 1)
            {
                ans = ans * x % m;
                n -= 1;
            }
            x = x * x % m;
            n /= 2;
        }
        return ans;
    }
}
static class Combination
{
    static long combMax;
    static long combMOD;

    static long[] factorial;
    static long[] inverse;
    static long[] factInv;

    public static void combInit(long _max, long _mod)
    {
        combMax = _max;
        combMOD = _mod;
        factorial = new long[combMax];
        inverse = new long[combMax];
        factInv = new long[combMax];

        factorial[0] = factorial[1] = 1;
        factInv[0] = factInv[1] = 1;
        inverse[1] = 1;

        for (int i = 2; i < combMax; i++)
        {
            factorial[i] = factorial[i - 1] * i % combMOD;
            inverse[i] = combMOD - inverse[combMOD % i] * (combMOD / i) % combMOD;
            factInv[i] = factInv[i - 1] * inverse[i] % combMOD;
        }
    }

    public static long combination(int n, int k)
    {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return factorial[n] * (factInv[k] * factInv[n - k] % combMOD) % combMOD;
    }
}

