public class AtCoderA
{
    static void Main()
    {
        var sc = new Scanner();

        long n = sc.NextLong();
        long m = sc.NextLong();
        long k = sc.NextLong();

        long mod = 998244353;

        long answer = 0;
        long tmpBefore = 0;
        for (int i = 0; i <= k; i++)
        {
            if (i == 0)
            {
                tmpBefore = Mul(m, Pow(m - 1, n - i - 1, mod), mod);
            } else
            {
                tmpBefore = Div(tmpBefore, m - 1, mod);
            }
            long tmpAnswer = Mul(tmpBefore, Combination(n - 1, i, mod), mod);
            answer += tmpAnswer;
            answer = answer % mod;
        }

        Console.WriteLine(answer);
    }

    // Combination（mod版）
    private static long Combination(long a, long b, long c)
    {
        long numerator = 1;
        long denominator = 1;
        for (long i = 1; i <= b; i++)
        {
            numerator = Mul(numerator, a - i + 1, c);
            denominator = Mul(denominator, i, c);
        }
        return Div(numerator, denominator, c);
    }

    // 掛け算（mod版）
    private static long Mul(long a, long b, long c)
    {
        return ((a % c) * (b % c)) % c;
    }

    // 割り算（mod版）
    private static long Div(long a, long b, long c)
    {
        return Mul(a, Pow(b, c - 2, c), c);
    }

    // べき乗（mod版）
    private static long Pow(long a, long b, long c)
    {
        if (b == 0)
        {
            return 1;
        }
        else if (b == 1)
        {
            return a % c;
        }
        else if (b % 2 == 0)
        {
            long d = Pow(a, b / 2, c);
            return d * d % c;
        }
        else
        {
            return a * Pow(a, b - 1, c) % c;
        }
    }

    class Scanner
    {
        private string[] _line;
        private int _index;
        private const char Separator = ' ';

        public Scanner()
        {
            _line = new string[0];
            _index = 0;
        }

        public string Next()
        {
            while (_index >= _line.Length)
            {
                _line = Console.ReadLine().Split(Separator);
                _index = 0;
            }

            return _line[_index++];
        }

        public int NextInt() => int.Parse(Next());
        public long NextLong() => long.Parse(Next());
        public double NextDouble() => double.Parse(Next());
        public decimal NextDecimal() => decimal.Parse(Next());
        public char NextChar() => Next()[0];
        public char[] NextCharArray() => Next().ToCharArray();

        public string[] Array()
        {
            _line = Console.ReadLine().Split(Separator);
            _index = _line.Length;
            return _line;
        }

        public int[] IntArray() => Array().Select(int.Parse).ToArray();
        public long[] LongArray() => Array().Select(long.Parse).ToArray();
        public double[] DoubleArray() => Array().Select(double.Parse).ToArray();
        public decimal[] DecimalArray() => Array().Select(decimal.Parse).ToArray();
    }
}

using System;
using static System.Console;

namespace abc167
{
    class Program
    {
        const int keyNum = 998244353;
        static void Main()
        {
            var nmk = ReadLine().Split(' ');
            var n = int.Parse(nmk[0]);
            var m = int.Parse(nmk[1]);
            var k = int.Parse(nmk[2]);

            WriteLine(CB(n, m, k));
        }
        static int CB(int n, int m, int k)
        {
            if (m == 1)
            {
                if (k == n - 1)
                {
                    return 1;
                }
                else
                {
                    return 0;
                }
            }
            int[] facts = null;
            int[] revFacts = null;
            GetFactorialsDiv(n, keyNum, out facts, out revFacts);

            var total = 0L;
            for (var i = 0; i <= k; ++i)
            {
                var subTotal = ((long)NCRDiv(n - 1, i, facts, revFacts, keyNum) * m) % keyNum;
                subTotal = (subTotal * Exp(m - 1, n - i - 1, keyNum)) % keyNum;
                total = (total + subTotal) % keyNum;
            }
            return (int)total;
        }

        static void GetFactorialsDiv(int n, int keyNum, out int[] facts, out int[] revFacts)
        {
            facts = new int[n + 1];
            revFacts = new int[n + 1];

            facts[0] = 1;
            var tmp = 1L;
            for (var i = 1; i <= n; ++i)
            {
                tmp = (tmp * i) % keyNum;
                facts[i] = (int)tmp;
            }
            // n!^-1 = n!^(m-2) (mod m)
            tmp = Exp(facts[n], keyNum - 2, keyNum);
            revFacts[n] = (int)tmp;
            for (var i = n; i > 1; --i)
            {
                tmp = (tmp * i) % keyNum;
                revFacts[i - 1] = (int)tmp;
            }
        }
        static long Exp(int n, int k, int keyNum)
        {
            if (k == 0)
            {
                return 1;
            }
            if (k == 1)
            {
                return n;
            }
            var half = Exp(n, k / 2, keyNum);
            var result = (half * half) % keyNum;
            return ((k % 2) == 0) ? result : ((result * n) % keyNum);
        }
        static int NCRDiv(int n, int r, int[] facts, int[] revFacts, int keyNum)
        {
            if (r == 0 || r == n)
            {
                return 1;
            }
            if (r == 1)
            {
                return n;
            }
            var result = 1L;
            result = (result * facts[n]) % keyNum;
            result = (result * revFacts[r]) % keyNum;
            result = (result * revFacts[n - r]) % keyNum;
            return (int)result;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace ConsoleApp
{
    class Program
    {
        static void Main(string[] args)
        {
            var input = Console.ReadLine().Split().Select(long.Parse).ToArray();
            var N = input[0];
            var M = input[1];
            var K = input[2];
            var mod = 998244353;

            var calc = new CombinationCalculator(N - 1, mod);

            var mArray = new long[N];
            mArray[0] = 1;
            for (int i = 1; i < N; i++) mArray[i] = mArray[i - 1] * (M - 1) % mod;

            long ans = 0;
            for (int k = 0; k <= K; k++)
            {
                ans += (M * calc.nCr(N - 1, k) % mod) * mArray[N - 1 - k] % mod;
                ans %= mod;
            }

            Console.WriteLine(ans);
        }

        public class CombinationCalculator
        {
            public long Mod { get; }
            public Dictionary<long, long> Factorial { get; }
            public Dictionary<long, long> FactorialInverse { get; }

            public CombinationCalculator(long max, long mod)
            {
                Mod = mod;
                Factorial = new Dictionary<long, long> { { 0, 1 }, { 1, 1 } };
                FactorialInverse = new Dictionary<long, long> { { 0, 1 }, { 1, 1 } };
                for (long i = 2; i <= max; i++)
                {
                    Factorial.Add(i, Factorial[i - 1] * i % Mod);
                    FactorialInverse.Add(i, FactorialInverse[i - 1] * Inverse(i) % Mod);
                }
            }

            public static long ExtGcd(long a, long b, out long x, out long y)
            {
                if (b == 0)
                {
                    x = 1;
                    y = 0;
                    return a;
                }
                var d = ExtGcd(b, a % b, out y, out x);
                y -= a / b * x;
                return d;
            }

            public long Inverse(long a)
            {
                long x;
                long y;
                var d = ExtGcd(a, Mod, out x, out y);
                if (d != 1) return -1;
                return x < 0 ? x + Mod : x;
            }

            public long nCr(long n, long r)
            {
                return (Factorial[n] * FactorialInverse[r] % Mod) * FactorialInverse[n - r] % Mod;
            }
        }
    }
}

