            for (int i = n - 1; i >= 0; i--)
            {
                var tmp = color;
                tmp = (tmp * Combination(n - 1, i)) % mod;
                if(i <= k) ans = (ans + tmp) % mod;
                color = (color * (m - 1)) % mod;
            }
