namespace AtCoder
{
	class Program
	{
		static long mod = 998244353;
		static long[] fac, finv, inv;

		static void Main(string[] args)
		{
			var firstLine = ReadLine().Split(' ').Select(value => long.Parse(value)).ToArray();
			var n = firstLine[0];
			var m = firstLine[1];
			var k = firstLine[2];

			CombinationInitialize(n);

			long count = 0;
			for(long i = n - 1 - k; i <= n - 1; i++)
			{
				count += ModPow(m - 1, i, mod) * Combination(n - 1, n - 1 - i);
				count %= mod;
			}

			WriteLine(count * m % mod);
		}

		private static long ModPow(long a, long n, long mod)
		{
			long answer = 1;

			while(n > 0)
			{
				if((n & 1) == 1)
				{
					answer = answer * a % mod;
				}
				a = a * a % mod;
				n >>= 1;
			}

			return answer;
		}

		private static long Combination(long n, long k)
		{
			if(n < k)
			{
				return 0;
			}
			if(n < 0 || k < 0)
			{
				return 0;
			}

			return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
		}

		private static void CombinationInitialize(long n)
		{
			fac = new long[n + 1];
			finv = new long[n + 1];
			inv = new long[n + 1];

			fac[0] = fac[1] = 1;
			finv[0] = finv[1] = 1;
			inv[1] = 1;

			for(long i = 2; i <= n; i++)
			{
				fac[i] = fac[i - 1] * i % mod;
				inv[i] = mod - inv[mod % i] * (mod / i) % mod;
				finv[i] = finv[i - 1] * inv[i] % mod;
			}
		}
	}
}

using System;

class Modulo
{
    private const int MOD = 998244353;
    private readonly int[] m_facs;
    public int Mul(int a, int b) => (int)(Math.BigMul(a, b) % MOD);
    public Modulo(int n)
    {
        m_facs = new int[n + 1];
        m_facs[0] = 1;
        for (int i = 1; i <= n; ++i)
            m_facs[i] = Mul(m_facs[i - 1], i);
    }
    public int Fac(int n) => m_facs[n];
    public int Pow(int a, int m)
    {
        switch (m)
        {
            case 0:
                return 1;
            case 1:
                return a;
            default:
                int p1 = Pow(a, m / 2);
                int p2 = Mul(p1, p1);
                return ((m % 2) == 0) ? p2 : Mul(p2, a);
        }
    }
    public int Div(int a, int b) => Mul(a, Pow(b, MOD - 2));
    public int Ncr(int n, int r)
    {
        if (n < r) return 0;
        if (n == r) return 1;
        int res = Fac(n);
        res = Div(res, Fac(r));
        res = Div(res, Fac(n - r));
        return res;
    }
}


