        a1 = (a1 * m) % MOD;
        long a2 = md.Ncr(n - 1, k);
        a1 = (a1 * a2) % MOD;
        return a1;
    }
    static void getAns(int n, int m, int k)
    {
        var md = new Modulo(n);
        var ans = 0L;
        for (int i = 0; i <= k; i++)
        {
            ans += calc(n, m, i ,md);
            ans %= MOD;
        }
        Console.WriteLine(ans);
    }
}

