            long res = 0;
            long[] pows = new long[n];
            pows[0] = 1;
            for(int i = 1; i < n; i++)
            {
                pows[i] = pows[i - 1] * (m - 1);
                pows[i] %= mask;
            }
            for (long i = n - 1; n - 1 - i <= k; i--)
            {
