    public static void Main()
    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var m = int.Parse(line[1]);
        var k = int.Parse(line[2]);
        getAns(n, m, k);

    }
    static long calc (int n, int m, int k)
    {
        var md = new Modulo(n);
        long a1 = md.Pow(m - 1, n - k - 1);
        a1 = (a1 * m) % MOD;
        long a2 = md.Ncr(n - 1, k);
        a1 = (a1 * a2) % MOD;
        return a1;
    }
    static void getAns(int n, int m, int k)
    {
        var ans = 0L;
        for (int i = 0; i <= k; i++)
        {
            ans += calc(n, m, i);
            ans %= MOD;
        }
        Console.WriteLine(ans);
    }
}

