			var modu = new Modulo(N);
			int ans = 0;
			for (int k = 0; k <= K; k++) {
				// M * (M - 1)^(N - k - 1)
				var m = 1;
				if (0 < k) {
					m = modu.Ncr(N - 1, k);// Modulo.CalcNcr(N-1, k);
				}

				var p = Modulo.Pow(M - 1, N - k - 1);
				var mp = Modulo.Mul(M, p);
				var mpm = Modulo.Mul(mp, m);

				ans = Modulo.Add(ans, mpm);
			}
			WriteLine(ans);
		}

