        long ans = 0;

        long[] comb = new long[box_num];
        comb[0] = 1;

        for (int i = 1; i < box_num; i++)
        {
            comb[i] = comb[i-1] * (box_num - i);
            comb[i] = Mod(comb[i], 998244353);
            comb[i] *= GetInv(i, 998244353);
            comb[i] = Mod(comb[i], 998244353);
        }


        for (int k = 0; k <= K; k++)
        {
            long temp = c_num * PowerMod(c_num - 1, box_num - 1-k, 998244353);
            temp = Mod(temp, 998244353);

            temp *= comb[box_num-k-1];
            temp = Mod(temp, 998244353);

            ans += temp;
            ans = Mod(ans, 998244353);
        }



        WriteLine(ans);
    }



