	for(i=INT_LENGTH-1;i>=0;--i)
	{
		if(flag)
		{
			str=str sprintf("%0" INT_WORD_SIZE "d",A[i]);
		}
		else if(A[i]>0)
		{
			str=sprintf("%d",A[i]);
			flag=1;
		}
	}
	if(!flag)str="0";
	return (negflag?"-":"")str;
