function add_num(A,x)
{
	if(x>0)add_num_impl(A,x);
	else if(x<0)sub_num_impl(A,-x);
}
function add_num_impl(A,x,i)
{
	i=0;
	while(i<INT_LENGTH)
	{
		A[i]+=x%INT_BASE;
		x=int(x/INT_BASE);
		if(A[i]>=INT_BASE)
		{
			A[i]-=INT_BASE;
			A[i+1]+=1;
		}
		++i;
	}
	A[INT_LENGTH]%=2;
}
function sub_num_impl(A,x,i)
{
	i=0;
	while(i<INT_LENGTH)
	{
		A[i]+=INT_BASE-x%INT_BASE-(i!=0);
		x=int(x/INT_BASE);
		if(A[i]>=INT_BASE)
		{
			A[i]-=INT_BASE;
			A[i+1]+=1;
		}
		++i;
	}
	A[INT_LENGTH]=(A[INT_LENGTH]+1)%2;
}
function mul_num(A,x,i,negflag)
{
	if(isneg(A))
	{
		negflag+=1;
		neg(A);
	}
	if(x<0)
	{
		negflag+=1;
		x=-x;
	}
	for(i=INT_LENGTH-1;i>=0;--i)
	{
		A[i]*=x;
	}
	for(i=0;i<INT_LENGTH-1;++i)
	{
		A[i+1]+=int(A[i]/INT_BASE);
		A[i]%=INT_BASE;
	}
	A[INT_LENGTH-1]%=INT_BASE;
	if(negflag==1)neg(A);
}
function div_num(A,x,negflag,dividend,divisor,diff)
{
	if(isneg(A))
	{
		negflag+=1;
		neg(A);
	}
	if(x<0)
	{
		negflag+=1;
		x=-x;
	}
	copy(A,dividend);
	input_num(sprintf("%.f",to_str(dividend)/x),A);
	copy(A,divisor);
	mul_num(divisor,x);
	neg(divisor);
	add(dividend,divisor);
	diff=0;
	while(isneg(dividend))
	{
		diff-=1;
		add_num(dividend,x);
	}
	input_num(x,divisor);
	while(cmp(dividend,divisor)!=-1)
	{
		diff+=1;
		add_num(dividend,-x);
	}
	add_num(A,diff);
	if(negflag==1)neg(A);
}
function mod_num(A,x,negflag,t,i,ret)
{
	if(isneg(A))
	{
		negflag=1;
		neg(A);
	}
	t=1;
	for(i=0;i<INT_LENGTH;++i)
	{
		ret+=t*A[i];
		t=t*INT_BASE%x;
	}
	ret%=x;
	if(negflag&&ret>0)ret=x-ret;
	input_num(ret,A);
	return ret;
}
function input_num(x,A,negflag,i)
{
	if(x=="-0")x="0";
	if(x<0)
	{
		negflag=1;
		x=-x;
	}
	for(i=0;i<INT_LENGTH;++i)
	{
		A[i]=x%INT_BASE;
		x=int(x/INT_BASE);
	}
	A[INT_LENGTH]=0;
	if(negflag)neg(A);
}
function power(a,b,x,ret,A)#return value(a**b%x)
{
	a%=x;
	if(a^b<1e15)return a^b%x;
	input_num(1%x,ret);
