def powmod(n, r, mod)
  if r.zero?
    1
  elsif r.odd?
    (n * powmod(n, r - 1, mod)) % mod
  else
    (powmod(n, r / 2, mod) ** 2) % mod
  end
end

def extended_euclidean(u,v)
    r0 = u; r1 = v; r1 = v; s0 = 1; s1 = 0; t0 = 0; t1 = 1;
    while r1 != 0 
      q = r0 / r1;
      r = r0 - q * r1;
      s = s0 - q * s1;
      t = t0 - q * t1;
      r0 = r1;
      s0 = s1;
      t0 = t1;
      r1 = r;
      s1 = s;
      t1 = t;
    end
    t0 < 0 ? t0 + u : t0
end

