	}
	return r
}

// 階乗
// A,B,C -> ABC, ACB, BAC, BCA, CAB, CBA
func factorial(n uint64) uint64 {
	var i uint64
	var r uint64 = 1
	if n <= 1 {
		return 1
	}
	for i = n; i > 0; i-- {
		r *= i
	}
	return r
}

// 順列(n元集合からk個の元を取り出す順番無視の組み合わせ)
// A,B,C -> 2枚 -> AB, AC, BA, BC, CA, CB = 6
func permutation(n, r uint64) uint64 {
	if r == 0 {
		return 1
	}

	var i uint64
	var rtn uint64 = 1
	for i = 0; i < (r + 1); i++ {
		rtn *= n - i
	}
	return rtn
	//return factorial(n) / factorial(n-r)
}

// 組み合わせ（n個の異なるものからr個選ぶ組み合わせ）
// A,B,C -> 2枚 -> AB, AC, BC = 3
func combination(n, r uint64) uint64 {
	return permutation(n, r) / factorial(r)
}

