func Factorial(N int) (F, Finv, Inv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  Inv = make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  Inv[0] = 1
  Inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    Inv[i] = p - Inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * Inv[i] % p
  }
  return
}

func Comb(F, Finv *[]int, A ...int) int {
  S := SumInt(A...)
  C := (*F)[S]
  for _, a := range A {
    C *= (*Finv)[a]
    C %= p
  }
  return C
}

const p = 998244353

func Solve() {
  var N, M, K int
  NextInt(&N, &M, &K)
  F, Finv, _ := Factorial(MaxInt(N, M))
  k := 1
  for 1 << uint(k) <= N { k++ }
  P := make([]int, k)
  P[0] = M - 1
  for i := range P[1:] { P[i + 1] = P[i] * P[i] % p }
  Pow := func(k int) int {
    a := 1
    for i := 0; 0 < k; i++ {
      if k % 2 == 1 { a = a * P[i] % p }
      k /= 2
    }
    return a
  }
  ans := 0
  for k := 0; k <= K; k++ {
    ans += (M * Pow(N - 1 - k) % p) * Comb(&F, &Finv, N - k - 1, k) % p
    ans %= p
  }
  Write(ans)
}

