func main() {
	mod = 1000000007
	buf := make([]byte, 0)
	sc.Buffer(buf, mod)
	sc.Split(bufio.ScanWords)
	d := 998244353
	n := intScanner()
	m := intScanner()
	k := intScanner()
	cs := make([]int, n)
	cs[0] = m
	for i := 1; i < n; i++ {
		cs[i] = cs[i-1] * (m - 1) % d
	}
	ans := 0
	fact := make([]int, n+1)
	fact[0] = 1
	inv := make([]int, n+1)
	inv[0] = modinv(1, d)
	for i := 1; i < n+1; i++ {
		fact[i] = fact[i-1] * i % d
		inv[i] = modinv(fact[i], d)
	}
	for i := n - 1 - k; i < n; i++ {
		ans += cs[i] * (fact[n-1] * inv[n-1-i] % d * inv[i] % d) % d
		ans %= d
	}
	fmt.Println(ans)
}
func modinv(a, m int) int {
	b, u, v := m, 1, 0
	for {
		t := a / b
		a -= t * b
		u -= t * v
		a, b, u, v = b, a, v, u
		if b == 0 {
			break
		}
	}
	u %= m
	if u < 0 {
		u += m
	}
	return u
}

