func powMod(n, m, mod int64) int64 {
	var i int64
	var r int64 = 1
	for i = 0; i < m; i++ {
		r = (r * (n)) % mod
	}
	return r
}

// 階乗
// A,B,C -> ABC, ACB, BAC, BCA, CAB, CBA
func factorial(n int64) int64 {
	var i int64
	var r int64 = 1
	for i = n; i > 0; i-- {
		r *= i
	}
	return r
}

// 順列(n元集合からk個の元を取り出す順番無視の組み合わせ)
// A,B,C -> 2枚 -> AB, AC, BA, BC, CA, CB = 6
func permutation(n, r int64) int64 {
	return factorial(n) / factorial(n-r)
}

// 組み合わせ（n個の異なるものからr個選ぶ組み合わせ）
// A,B,C -> 2枚 -> AB, AC, BC = 3
func combination(n, r int64) int64 {
	return permutation(n, r) / factorial(r)
}

