func main() {
	fac = make([]int, 2e5+1)
	ifac = make([]int, 2e5+1)
	inv := make([]int, 2e5+1)
	fac[0], fac[1] = 1, 1
	ifac[0], ifac[1] = 1, 1
	inv[0], inv[1] = 1, 1
	for i := 2; i < 2e5+1; i++ {
		fac[i] = (fac[i-1] * i) % mod
		inv[i] = (mod - inv[mod%i]*(mod/i)) % mod
		if inv[i] < 0 {
			inv[i] += mod
		}
		ifac[i] = (ifac[i-1] * inv[i]) % mod
	}

	pows = make(map[int]map[int]int)
	var n, m, k int
	fmt.Scan(&n, &m, &k)
	var ans int
	for i := 0; i <= k; i++ {
