const (
	m = 998244353
)

func invMod(a int) int {
	b, c, n := 1, 0, m
	for n != 0 {
		q := a / n
		r := a % n
		a, b, c, n = n, c, b-q*c, r
	}
	if a == 1 {
		return b
	}
	panic("Not invertible")
}

func mpow(x, y int) int {
	result := 1
	for y != 0 {
		if y&1 == 1 {
			result *= x
			result %= m
		}
		x *= x
		x %= m
		y >>= 1
	}
	return result
}

var (
	fac []int
)

func initFactorialTable(n int) {
	fac = make([]int, n+1)
	fac[0] = 1
	for i := 0; i < n; i++ {
		fac[i+1] = fac[i] * (i + 1) % m
	}
}

func mcomb(n, k int) int {
	if n == 0 && k == 0 {
		return 1
	}
	if n < k || k < 0 {
		return 0
	}
	return fac[n] * invMod(fac[n-k]) % m * invMod(fac[k]) % m
}

func main() {
	defer flush()

	N := readInt()
	M := readInt()
	K := readInt()

	initFactorialTable(N)

	result := 0
	for i := 0; i < K+1; i++ {
		t := M * mcomb(N-1, i)
		t %= m
		t *= mpow(M-1, N-1-i)
		t %= m
		result += t
		result %= m
	}
	println(result)
}

