func main(){
    // 読み込み
    intread := nextIntVec()
    // ブロック数
    block := intread[0]
    // 色の数
    color := intread[1]
    // 同じ色が隣り合って良いマス
    same := intread[2]

    // 全ての通りから重なっている部分を引く
    //same が0の場合
    bigblock := big.NewInt(int64(block))
    bigcolor := big.NewInt(int64(color))
    bigwari := big.NewInt(998244353)
    all := big.NewInt(1)
    if same == 0 {
        bigcolor2 := big.NewInt(int64(color-1))
        all = bigblock
        for i := 1; i < block; i++ {
            all.Mul(all,bigcolor2)
        }
        fmt.Println(all.Mod(all,bigwari))
    } else {
        all = all.Exp(bigcolor,bigblock,nil)
        // 隣が禁止の数だけ連なっている通りを計算

        //このマス分だけ同じ色で塗られてはいけない
        same = same + 2
        masu1 := big.NewInt(0)
        for i := block; i > same - 1 ; i-- {
            masu2 := big.NewInt(int64(i - same + 1))
            masu1.Add(masu1,masu2)
        }
        masu1.Mul(masu1,bigcolor)
        all.Sub(all,masu1)
        all.Mod(all,bigwari)
        fmt.Println(all)
    }
}

