var mod uint64 = 998244353

var maxfac uint64 = 200001
var fac []uint64  // n! % mod
var ifac []uint64 // k!^(mod-2) % mod

func initCombination() {
	fac = make([]uint64, maxfac)
	ifac = make([]uint64, maxfac)
	fac[0] = 1
	ifac[0] = 1
	var i uint64
	for i = 0; i < maxfac-1; i++ {
		fac[i+1] = fac[i] * (i + 1) % mod
		ifac[i+1] = ifac[i] * powMod(i+1, mod-2) % mod
	}
}
func combination(n, r uint64) uint64 {
	if n == 0 && r == 0 {
		return 1
	}
	if n < r || n < 0 {
		return 0
	}
	var rtn uint64 = fac[n] * ifac[r] % mod
	rtn = rtn * ifac[n-r] % mod
	return rtn
}

func powMod(n, m uint64) uint64 {
	var ans uint64 = 1
	for m != 0 {
		if (m % 2) != 0 {
			ans = ans * n % mod
			if m == 1 {
				break
			}
		}
		n = n * n % mod
		m = m / 2
	}
	return ans
}

