// github.com/EndlessCheng/codeforces-go
func run(_r io.Reader, _w io.Writer) {
	in := bufio.NewReader(_r)
	out := bufio.NewWriter(_w)
	defer out.Flush()
	const mod = 998244353

	pow := func(x, n int) int {
		x %= mod
		res := 1
		for ; n > 0; n >>= 1 {
			if n&1 == 1 {
				res = res * x % mod
			}
			x = x * x % mod
		}
		return res
	}
	inv := func(a int) int { return pow(a, mod-2) }
	const mx int = 3e5
	F := [mx + 1]int{1}
	invF := [mx + 1]int{inv(1)}
	for i := 1; i <= mx; i++ {
		F[i] = F[i-1] * i % mod
		invF[i] = inv(F[i])
	}
	comb := func(n, k int) int { return F[n] * invF[k] % mod * invF[n-k] % mod }

	var n, m, k, ans int
	Fscan(in, &n, &m, &k)
	for i := 0; i <= k; i++ {
		v := m
		v = v * comb(n-1, i) % mod
		v = v * pow(m-1, n-1-i) % mod
		ans = (ans +v) % mod
	}
	Fprint(out, ans)
}

