const mod = 998244353

func mpow(n, p int) int {
	if n == 0 {
		return 0
	}
	ret := 1
	x := n
	for p > 0 {
		if p%2 == 1 {
			ret *= x
			ret %= mod
		}
		x *= x
		x %= mod
		p /= 2
	}
	return ret
}

var fact [210000]int
var ifact [210000]int

func nCk(n, k int) int {
	if n < k || k < 0 {
		return 0
	}
	ret := (fact[n] * ifact[k]) % mod
	ret *= ifact[n-k]
	ret %= mod
	return ret
}

