export class CacheUtil {
  private static _tmp = {};

  /**
   * 値を取得する
   * @param key キー
   * @param getter 値が undefined のときに実行するゲッター
   * @return 値
   */
  static getValue<T>(key: string, getter: () => T): T {
    if (CacheUtil._tmp[key] === undefined) {
      CacheUtil._tmp[key] = getter();
    }
    return CacheUtil._tmp[key];
  }
}

/**
 * 整数ユーティリティー
 */
export class IntUtil {
  /**
   * aをbで割った時の商と余りを求める。
   * @param a 割られる数
   * @param b 割る数
   * @return [商, 余り]
   */
  static extraQ(a: number, b: number): [number, number] {
    const r = a % b;
    return [(a - r) / b, r];
  }

  /**
   * 最大公約数を求める。
   * @param x 数値1
   * @param y 数値2
   * @return [最大公約数r, a, b] (ただしa, bは ax + by = r となる整数)
   */
  static gcd(x: number, y: number): [number, number, number] {
    let r0 = x;
    let r1 = y;
    let a0 = 1;
    let a1 = 0;
    let b0 = 0;
    let b1 = 1;
    while(r1 > 0) {
      const [q, r] = IntUtil.extraQ(r0, r1);
      const a = a0 - q * a1;
      const b = b0 - q * b1;
      r0 = r1;
      r1 = r;
      a0 = a1;
      a1 = a;
      b0 = b1;
      b1 = b;
    }
    return [r0, a0, b0];
  }

  /**
   * 最小公倍数を求める。
   * @param x 数値1
   * @param y 数値2
   * @return 最小公倍数
   */
  static lcm(x: number, y: number): number {
    let gcd = IntUtil.gcd(x, y);
    return x * y / gcd;
  }

  /**
   * pを法とした時のxの逆数を返す
   * @param x 数値
   * @param p xと互いに素である数値
   * @return x^{-1} (mod p)
   */
  static inverseMod(x: number, p: number): number {
    const [r, a, _] = IntUtil.gcd(x, p);
    if (r != 1) {
      throw new Error(`NOT COPRIME: IntUtil.inverseMod(${x}, ${p})`);
    }

    return a >= 0 ? (a % p) : (p + (a % p));
  }
}

