const MOD = 998244353;

const N = 2 * 10^^5 + 10;
long[N] fact;
long[N] invfact;

void initFact() {
    fact[0] = fact[1] = 1;
    foreach (i; 2..N)
        fact[i] = fact[i-1] * i % MOD;

    invfact[N-1] = modPow(fact[N-1], MOD-2, MOD);
    foreach_reverse (i; 0..N-1)
        invfact[i] = invfact[i+1] * (i+1) % MOD;
}

long nck(long n, long k) {
    long x = fact[n] * invfact[k] % MOD;
    return x * invfact[n-k] % MOD;
}

long calc(int n, int m, int k) {
    initFact();

    long ans = 0;
    foreach (i; 0..k+1) {
        auto x = m * modPow(m-1, n-i-1, MOD) % MOD;
        x = x * nck(n-1, i) % MOD;
        ans = (ans + x) % MOD;
    }
    return ans;
}

