def mod_pow(x: int, a: int, mod: int) -> int:
    if a == 1:
        return x
    if a % 2:
        return x * mod_pow(x, a - 1, mod) % mod
    t = mod_pow(x, a // 2, mod)
    return t ** 2 % mod


def mod_inverse(a: int, mod: int) -> int:
    def ext_gcd(a: int, b: int) -> (int, int, int):
        x, y = [1, 0], [0, 1]
        while b:
            q, a, b = a // b, b, a % b
            x = [x[1], x[0] - q * x[1]]
            y = [y[1], y[0] - q * y[1]]
        return (a, x[0], y[0])
    g, x, _ = ext_gcd(a, mod)
    assert g == 1, 'Modular inverse does not exist.'
    return x % mod


def mod_inverse2(x: int, mod: int) -> int:
    return mod_pow(x, mod - 2, mod)


def mod_factorial(x: int, mod: int, limit: int = 0) -> int:
    result = 1
    for i in range(x, limit, -1):
        result *= i
        result %= mod
    return result


def mod_combinations(n: int, k: int, mod: int) -> int:
    assert 0 <= k <= n, 'n and k should be 0 <= k <= n.'

    lower, upper = min(k, n - k), max(k, n - k)
    numer = mod_factorial(n, mod, upper)
    denom = mod_factorial(lower, mod)
    return numer * mod_inverse(denom, mod) % mod


