    }
    let d = 998244353;
    let mut a = m * pow_m(m - 1, n - 1, d) % d;
    let mut ans = a;
    for i in 0..k {
        a = a * (n - 1 - i) % d * inv_m((i + 1) * (m - 1), d) % d;
        ans += a
    }
    println!("{}", ans % d);
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

fn inv_m(n: usize, d: usize) -> usize {
    pow_m(n, d - 2, d)
}

