fn modpow(mut a: usize, mut e: usize, m: usize) -> usize {
    let mut res = 1;
    while e > 0 {
        if (e & 1) == 1 {
            res = res * a % m;
        }
        a = a * a % m;
        e >>= 1;
    }
    res
}

