        let mut inv = vec![ModInt::one(); n];
        let mut fact = vec![ModInt::one(); n];
        let mut inv_fact = vec![ModInt::one(); n];
        for i in 2..n {
            inv[i] = ModInt::new(MOD / i as u32) * (-inv[MOD as usize % i]);
            fact[i] = fact[i-1] * ModInt::new(i as u32);
            inv_fact[i] = inv_fact[i-1] * inv[i];
        }

        Combination {
            inv: inv,
            fact: fact,
            inv_fact: inv_fact,
        }
    }

    pub fn get(&self, x: usize, y: usize) -> ModInt {
        self.fact[x] * self.inv_fact[y] * self.inv_fact[x-y]
    }
