const MOD: i64 = 998244353;
struct Combination {
    fact: Vec<i64>,
    fact_inv: Vec<i64>,
}
impl Combination {
    fn init(n: usize) -> Combination {
        let mut fact = vec![0 as i64; n];
        let mut fact_inv = vec![0 as i64; n];
        fact[0] = 1;
        fact[1] = 1;
        fact_inv[0] = 1;
        fact_inv[1] = 1;
        for i in 2..n {
            fact[i] = fact[i - 1] * i as i64 % MOD;
        }
        for i in 2..n {
            let k = i as i64;
            fact_inv[i] = fact_inv[(MOD % k) as usize] * (MOD - MOD / k) % MOD;
        }
        for i in 2..n {
            fact_inv[i] = fact_inv[i - 1] * fact_inv[i] % MOD;
        }

        Combination { fact, fact_inv }
    }

    fn get(&self, n: usize, r: usize) -> i64 {
        if n == 0 || r == 0 {
            return 1;
        }
        self.fact[n] * self.fact_inv[n - r] % MOD * self.fact_inv[r] % MOD
    }
}

fn pow_mod(x: i64, y: i64, m: i64) -> i64 {
    if x == 0 {
        if y == 0 {
            return 1;
        } else {
            return 0;
        }
    }
    if y == 0 {
        return 1;
    }
    if (y & 1) == 1 {
        x * pow_mod(x * x % m, y >> 1, m) % m
    } else {
        pow_mod(x * x % m, y >> 1, m)
    }
}

#[fastout]
fn main() {
    input! {
        n: i64,
        m:i64,
        k:i64,
    }

    let mut ans: i64 = 0;
    let ncr = Combination::init((n + 1) as usize);
    for i in 0..(k + 1) {
        let j = n - 1 - i;
        ans += pow_mod(m - 1, j as i64, MOD) * ncr.get((n - 1) as usize, i as usize) % MOD;
        ans %= MOD;
    }
    ans = ans * m % MOD;
    println!("{}", ans);
}

