/// a.pow(b) mod m
fn pow_mod(a: usize, mut b: usize, m: usize) -> usize {
    let mut t = a;
    let mut ans = 1;
    while b != 0 {
        if (b & 1) != 0 {
            ans = (ans * t) % m;
        }
        b >>= 1;
        t = (t * t) % m;
    }
    ans
}

