            let mut fact = vec![ModInt::<T>::new(0); n + 1];
            let mut ifact = vec![ModInt::<T>::new(0); n + 1];
            fact[0] = ModInt::<T>::new(1);
            for i in 1..=n {
                fact[i] = fact[i - 1] * i.into();
            }
            ifact[n] = fact[n].inv();
            for i in (1..=n).rev() {
                ifact[i - 1] = ifact[i] * i.into();
            }
            Comb { fact, ifact }
        }
        pub fn of(&self, n: usize, k: usize) -> ModInt<T> {
            if n < k {
                0i64.into()
            } else {
                self.fact[n] * self.ifact[k] * self.ifact[n - k]
            }
        }
        #[doc = " combination with repetition"]
        pub fn rep(&self, n: usize, k: usize) -> ModInt<T> {
            self.of(n + k - 1, k)
        }
        pub fn perm(&self, n: usize, k: usize) -> ModInt<T> {
            if n < k {
