        let mut c = vec![vec![0; b[0].len()]; a.len()];
        for i in 0..a.len() {
            for k in 0..b.len() {
                for j in 0..b[0].len() {
                    c[i][j] = c[i][j] + a[i][k] * b[k][j];
                }
            }
        }
