    }
    pub fn matrix_pow(a_: &[Vec<i64>], mut n: i64) -> Vec<Vec<i64>> {
        let mut a: Vec<Vec<i64>> = a_.to_vec();
        let mut b = vec![vec![0; a.len()]; a.len()];
        for i in 0..a.len() {
            b[i][i] = 1;
        }
        while n > 0 {
            if n & 1 == 1 {
                b = matrix_mul(&b, &a);
            }
            a = matrix_mul(&a, &a);
            n >>= 1;
        }
        b
    }
