        ifact[i - 1] = ifact[i] * Fp(i as u32);
    }

    let binom = |n, r| fact[n] * ifact[r] * ifact[n - r];

    println!(
        "{}",
        (Fp(m as u32)
            * (0..=k)
                .map(|i| Fp(m as u32 - 1).pow((n - 1 - i) as u32) * binom(n - 1, i))
                .sum())
        .0
    );
}

