fn input_tuple() -> (u64, u64, u64) {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    let vec: Vec<u64> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
    (vec[0], vec[1], vec[2])
}

fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % MOD).pow(2) % MOD;
    } else {
      return binary_power(x, n - 1) % MOD * x % MOD;
    }
}

fn inverse_mod(n: u64) -> u64 {
    binary_power(n, MOD-2)
}

fn main() {
    let (n, m, k) = input_tuple();

    // 同じ色が隣り合っている組が0の場合
    let mut combination_buf = 1;
    let mut ans = m % MOD * binary_power(m - 1, n - 1) % MOD;

    for i in 1..(k+1) {
        combination_buf = combination_buf * (n - i) % MOD * inverse_mod(i) % MOD;
        // println!("{}", combination_buf);
        let num = combination_buf * m % MOD * binary_power(m - 1, n - 1 - i) % MOD; 
        ans += num;
        ans %= MOD;
    }
    println!("{}", ans);
}

