type M = Modu32<modulos::Modulo998244353>;
#[derive(Clone, Debug)]
pub struct MemorizedFactorial {
    n: usize,
    fact: Vec<M>,
    inv_fact: Vec<M>,
}
impl MemorizedFactorial {
    pub fn new(max_n: usize) -> MemorizedFactorial {
        let mut fact = vec![M::new(1); max_n + 1];
        let mut inv_fact = vec![M::new(1); max_n + 1];
        for i in 1..(max_n + 1) {
            fact[i] = fact[i - 1] * M::new(i as u32);
            inv_fact[i] = inv_fact[i - 1] / M::new(i as u32);
        }
        MemorizedFactorial {
            n: max_n + 1,
            fact: fact,
            inv_fact: inv_fact,
        }
    }
    pub fn combination(&self, n: usize, r: usize) -> M {
        if r <= n {
            self.fact[n] * self.inv_fact[r] * self.inv_fact[n - r]
        } else {
            M::new(0)
        }
    }
    pub fn permutation(&self, n: usize, r: usize) -> M {
        if r <= n {
            self.fact[n] * self.inv_fact[n - r]
        } else {
            M::new(0)
        }
    }
    pub fn homogeneous_product(&self, n: usize, r: usize) -> M {
        if n != 0 && r != 0 {
            self.combination(n + r - 1, r)
        } else {
            M::new(1)
        }
    }
}
fn main() {
    input! { n, m, k };
    let fact = MemorizedFactorial::new(n);
    let mut ans = M::zero();
    for i in 0..=k {
        ans += fact.combination(n - 1, i) * M::new(m as u32) * M::new(m as u32 - 1).pow(n - i - 1);
    }
    println!("{}", ans);
}

