const M: i64 = 998244353;

fn mod_inverse(mut a: i64, m: i64) -> i64 {
    use std::mem::swap;

    let mut b = m;
    let mut u = 1;
    let mut v = 0;

    while b > 0 {
        let mut t = a / b;
        a -= t * b;
        swap(&mut a, &mut b);
        u -= t * v;
        swap(&mut u, &mut v);
    }

    u %= m;
    return if u < 0 { u + m } else { u };
}

fn solve<R: std::io::BufRead>(mut sc: Scanner<R>) {
    let n: i64 = sc.get();
    let m: i64 = sc.get();
    let k: i64 = sc.get();

    if m == 1 {
        println!("{}", if k == n - 1 { 1 } else { 0 });
    } else {
        let m_minus_1_inv = mod_inverse(m - 1, M);
        let ans = (0..=k)
            .scan(
                (0..(n - 1)).fold(m, |a, _| a * (m - 1) % M),
                |a, i| {
                    let a_ = *a;
                    *a = *a * m_minus_1_inv % M
                            * (n - (i + 1)) % M
                            * mod_inverse(i + 1, M) % M;
                    Some(a_)
                })
            .fold(0, |a, x| (a + x) % M);
        println!("{}", ans);
    }
}

