const CUSTOM_STACK_SIZE_MIB: Option<usize> = Some(128);
const INTERACTIVE: bool = false;

fn main() -> std::io::Result<()> {
  match CUSTOM_STACK_SIZE_MIB {
    Some(stack_size_mib) => std::thread::Builder::new()
      .name("run_solver".to_owned())
      .stack_size(stack_size_mib * 1024 * 1024)
      .spawn(run_solver)?
      .join()
      .unwrap(),
    None => run_solver(),
  }
}

fn run_solver() -> std::io::Result<()> {
  let stdin = std::io::stdin();
  let reader = stdin.lock();
  let stdout = std::io::stdout();
  let writer = stdout.lock();
  macro_rules! with_wrapper {
    ($($wrapper:expr)?) => {{
      let mut writer = $($wrapper)?(writer);
      solve(reader, &mut writer)?;
      writer.flush()
    }};
  }
  if cfg!(debug_assertions) {
    with_wrapper!()
  } else if INTERACTIVE {
    with_wrapper!(std::io::LineWriter::new)
  } else {
    with_wrapper!(std::io::BufWriter::new)
  }
}

fn solve<R, W>(reader: R, mut writer: W) -> std::io::Result<()>
where
  R: BufRead,
  W: Write,
{
  let mut _scanner = lib::io::Scanner::new(reader);
  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.parse_next::<$T>()?.unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($T:ty; $n:expr) => {
      _scanner.parse_next_n::<$T>($n)?.unwrap()
    };
    ($($T:ty),+; $n:expr) => {
      iter::repeat_with(|| -> std::io::Result<_> { Ok(($(scan!($T)),+)) })
        .take($n)
        .collect::<std::io::Result<Vec<_>>>()?
    };
  }
  #[allow(unused_macros)]
  macro_rules! scan_bytes_map {
    ($f:expr) => {
      _scanner.map_next_bytes($f)?
    };
    ($f:expr; $n:expr) => {
      _scanner.map_next_bytes_n($n, $f)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! print {
    ($($arg:tt)*) => {
      write!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! println {
    ($($arg:tt)*) => {
      writeln!(writer, $($arg)*)?
    };
  }
  {
    #[allow(unused)]
    mod old_lib {
      use std::fmt::{self, Debug, Display, Formatter};
      use std::hash::{Hash, Hasher};
      use std::iter::{Product, Sum};
      use std::marker::PhantomData;
      use std::ops::{Add, AddAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign};

      pub trait Constant<T> {
        fn get() -> T;
      }

      pub enum _998244353 {}

      impl Constant<u32> for _998244353 {
        fn get() -> u32 {
          998244353
        }
      }

      pub struct ModU32<Mod> {
        _phantom: PhantomData<fn() -> Mod>,
        repr: u32,
      }

      impl<Mod: Constant<u32>> Clone for ModU32<Mod> {
        fn clone(&self) -> Self {
          Self::from_repr(self.repr)
        }
      }

      impl<Mod: Constant<u32>> Copy for ModU32<Mod> {}

      impl<Mod: Constant<u32>> PartialEq for ModU32<Mod> {
        fn eq(&self, other: &Self) -> bool {
          self.repr.eq(&other.repr)
        }
      }

      impl<Mod: Constant<u32>> Eq for ModU32<Mod> {}

      impl<Mod: Constant<u32>> Default for ModU32<Mod> {
        fn default() -> Self {
          ModU32::from_repr(u32::default())
        }
      }

      impl<Mod: Constant<u32>> Hash for ModU32<Mod> {
        fn hash<H>(&self, state: &mut H)
        where
          H: Hasher,
        {
          self.repr.hash(state);
        }
      }

      impl<Mod: Constant<u32>> Debug for ModU32<Mod> {
        fn fmt(&self, f: &mut Formatter) -> fmt::Result {
          Debug::fmt(&self.repr, f)
        }
      }

      impl<Mod: Constant<u32>> Display for ModU32<Mod> {
        fn fmt(&self, f: &mut Formatter) -> fmt::Result {
          Display::fmt(&self.repr, f)
        }
      }

      impl<Mod: Constant<u32>> ModU32<Mod> {
        pub fn new(value: u32) -> Self {
          Self::from_repr(value % Mod::get())
        }

        fn from_repr(repr: u32) -> Self {
          debug_assert!(repr < Mod::get());
          ModU32 {
            _phantom: PhantomData,
            repr: repr,
          }
        }

        pub fn repr(self) -> u32 {
          self.repr
        }

        pub fn inverse(self) -> Self {
          let mut a = self.repr as i64;
          let mut b = Mod::get() as i64;
          let mut u = 1i64;
          let mut v = 0i64;
          while b != 0 {
            let t = a / b;
            a -= t * b;
            ::std::mem::swap(&mut a, &mut b);
            u -= t * v;
            ::std::mem::swap(&mut u, &mut v);
          }
          u %= Mod::get() as i64;
          if u < 0 {
            u += Mod::get() as i64;
          }
          Self::from_repr(u as u32)
        }

        pub fn pow(mut self, mut n: u32) -> Self {
          let mut acc = ModU32::from_repr(1);
          while n > 0 {
            if n % 2 == 1 {
              acc *= self;
            }
            self *= self;
            n /= 2;
          }
          acc
        }
      }

      impl<Mod: Constant<u32>> Add for ModU32<Mod> {
        type Output = Self;

        fn add(mut self, rhs: Self) -> Self {
          self += rhs;
          self
        }
      }

      impl<Mod: Constant<u32>> AddAssign for ModU32<Mod> {
        fn add_assign(&mut self, rhs: Self) {
          self.repr += rhs.repr;
          if self.repr >= Mod::get() {
            self.repr -= Mod::get();
          }
        }
      }

      impl<Mod: Constant<u32>> Sub for ModU32<Mod> {
        type Output = Self;

        fn sub(mut self, rhs: Self) -> Self {
          self -= rhs;
          self
        }
      }

      impl<Mod: Constant<u32>> SubAssign for ModU32<Mod> {
        fn sub_assign(&mut self, rhs: Self) {
          if self.repr < rhs.repr {
            self.repr += Mod::get();
          }
          self.repr -= rhs.repr;
        }
      }

      impl<Mod: Constant<u32>> Mul for ModU32<Mod> {
        type Output = Self;

        fn mul(self, rhs: Self) -> Self {
          Self::from_repr((self.repr as u64 * rhs.repr as u64 % Mod::get() as u64) as u32)
        }
      }

      impl<Mod: Constant<u32>> MulAssign for ModU32<Mod> {
        fn mul_assign(&mut self, rhs: Self) {
          *self = *self * rhs;
        }
      }

      impl<Mod: Constant<u32>> Div for ModU32<Mod> {
        type Output = Self;

        fn div(self, rhs: Self) -> Self {
          self * rhs.inverse()
        }
      }

      impl<Mod: Constant<u32>> DivAssign for ModU32<Mod> {
        fn div_assign(&mut self, rhs: Self) {
          *self *= rhs.inverse();
        }
      }

      impl<Mod: Constant<u32>> Sum for ModU32<Mod> {
        fn sum<I>(iter: I) -> Self
        where
          I: Iterator<Item = Self>,
        {
          let mut acc = ModU32::from_repr(0);
          for x in iter {
            acc += x;
          }
          acc
        }
      }

      impl<Mod: Constant<u32>> Product for ModU32<Mod> {
        fn product<I>(iter: I) -> Self
        where
          I: Iterator<Item = Self>,
        {
          let mut acc = ModU32::from_repr(1);
          for x in iter {
            acc *= x;
          }
          acc
        }
      }

      pub fn mod_pow<Mod: Constant<u32>>(base: u32, n: u32) -> ModU32<Mod> {
        ModU32::new(base).pow(n)
      }

      pub fn mod_binomial<Mod: Constant<u32>>(mut n: u32, mut k: u32) -> ModU32<Mod> {
        let mut acc = ModU32::from_repr(1);
        while k != 0 {
          {
            let n = n % Mod::get();
            let k = k % Mod::get();
            if n < k {
              return ModU32::from_repr(0);
            }
            acc *= (n - k + 1..n + 1).map(ModU32::from_repr).product();
            acc /= (1..k + 1).map(ModU32::from_repr).product();
          }
          n /= Mod::get();
          k /= Mod::get();
        }
        acc
      }

      pub struct ModBinomialTable<Mod> {
        fact: Vec<ModU32<Mod>>,
        inv_fact: Vec<ModU32<Mod>>,
      }

      impl<Mod: Constant<u32>> ModBinomialTable<Mod> {
        pub fn new(max: u32) -> Self {
          let mut fact = vec![ModU32::default(); (max + 1) as usize];
          let mut inv_fact = vec![ModU32::default(); (max + 1) as usize];
          fact[0] = ModU32::from_repr(1);
          for i in 1..max + 1 {
            fact[i as usize] = fact[(i - 1) as usize] * ModU32::new(i);
          }
          inv_fact[max as usize] = fact[max as usize].inverse();
          for i in (1..max + 1).rev() {
            inv_fact[(i - 1) as usize] = inv_fact[i as usize] * ModU32::new(i);
          }
          ModBinomialTable {
            fact: fact,
            inv_fact: inv_fact,
          }
        }

        pub fn mod_binomial(&self, n: u32, k: u32) -> ModU32<Mod> {
          if n < k {
            ModU32::from_repr(0)
          } else {
            self.fact[n as usize] * self.inv_fact[k as usize] * self.inv_fact[(n - k) as usize]
          }
        }
      }
    }

    type M = old_lib::ModU32<old_lib::_998244353>;

    let (n, m, k) = scan!(u32, u32, u32);

    let table = old_lib::ModBinomialTable::<old_lib::_998244353>::new(n);

    let ans = (0..=k)
      .map(|a| table.mod_binomial(n - 1, a) * M::new(m) * M::new(m - 1).pow(n - a - 1))
      .sum::<M>();
    println!("{}", ans);
  }
  Ok(())
}

