mod fact {
    use num::traits::One;
    pub struct Fact<T: One>(Vec<T>);
    impl<T: One + Copy + From<usize> + Into<usize>> Fact<T> {
        pub fn new() -> Self {
            Self(vec![T::one()])
        }
        pub fn fact(&mut self, x: T) -> T {
            let a = self.0.len();
            let b: usize = x.into();
            for i in a..=b {
                self.0.push(self.0[i - 1] * T::from(i));
            }
            self.0[b]
        }
    }
}

