fn pow_mod(mut a: i64, mut n: i64, m: i64) -> i64 {
  let mut res: i64 = 1;
  while n > 0 {
    if n & 1 == 1 {
      res = res * a % m;
    }
    a = a * a % m;
    n >>= 1;
  }
  res
}

fn combination(mut n: i64, c: i64, m: i64) -> i64 {
  let mut upe = 1;
  let mut dow = 1;
  for i in 1..c + 1 {
    upe = upe * n % m;
    dow = dow * i % m;

    n -= 1;
  }
  upe * pow_mod(dow, m-2, m) % m
}
