fn run<R: Read, W: Write, E: Write>(r_: &mut R, w_: &mut W, err: &mut E) {
  let (n, m, k) = r!(r_; i64, i64, i64);
  let c = 998244353i64;

  let mut sum = 0i64;
  for x in 0..k + 1 {
    let mut ans = pow_mod(m - 1, n - x - 1, c);
    ans = (ans * m) % c;
    ans = (ans * combination(n - 1, x, c)) % c;
    sum += ans;
    sum %= c;
  }
  w!(w_; sum);
}

