mod enumeration {
    pub struct Enumeration {
        fact: Vec<usize>,
        finv: Vec<usize>,
        modulo: usize,
    }
    impl Enumeration {
        pub fn new(n: usize, modulo: usize) -> Enumeration {
            let mut fact: Vec<usize> = vec![1; n];
            let mut inv: Vec<usize> = vec![1; n];
            let mut finv: Vec<usize> = vec![1; n];
            for i in 2..n {
                fact[i] = fact[i - 1] * (i as usize) % modulo;
                inv[i] = modulo - (modulo / (i as usize)) * inv[(modulo as usize % i)] % modulo;
                finv[i] = inv[i] * finv[i - 1] % modulo;
            }
            Enumeration {
                fact: fact,
                finv: finv,
                modulo: modulo,
            }
        }
        pub fn c(&self, n: usize, k: usize) -> usize {
            if n < k {
                return 0;
            }
            self.fact[n] * self.finv[n - k] % self.modulo * self.finv[k] % self.modulo
        }
    }
}

