fn main() {
    let (n, m, k): (usize, usize, usize) = (read::<usize>(), read::<usize>(), read::<usize>());
    let c = Comb::fact_new();
    let mut ans = 0;
    for kk in 0..k + 1 {
        ans += (m * c.nCr(n - 1, kk) % MOD) * Comb::p_mod(m - 1, n - 1 - kk) % MOD;
        ans %= MOD;
    }
    println!("{}", ans % MOD);
}

