static mut MAX_N: usize = 1;
static mut FACT: Vec<Mint> = Vec::<Mint>::new();
static mut IFACT: Vec<Mint> = Vec::<Mint>::new();
static mut COMB_FLAG: bool = false;
fn comb_init(n: usize) {
   unsafe {
      COMB_FLAG = true;
      MAX_N = n;
      FACT = vec![Mint::new(1); MAX_N + 1];
      IFACT = vec![Mint::new(1); MAX_N + 1];
      for i in 1..MAX_N + 1 {
         FACT[i] = FACT[i - 1] * Mint::from(i as i64);
      }
      IFACT[MAX_N] = FACT[MAX_N as usize].inv();
      for i in (1..MAX_N + 1).rev() {
         IFACT[i - 1] = IFACT[i] * Mint::from(i as i64);
      }
   }
}
fn comb_check(n: usize, r: usize) -> bool { unsafe { !(n > MAX_N || r > n) } }
fn comb(n: usize, r: usize) -> Mint {
   unsafe {
      if !COMB_FLAG {
         panic!("FACT is not init");
      }
   }
   if !comb_check(n, r) {
      Mint::from(0)
   } else {
      unsafe { FACT[n] * IFACT[r] * IFACT[n - r] }
   }
}

