fn pow_mod(mut a: i64, mut n: i64, m: i64) -> i64 {
  let mut res: i64 = 1;
  while n > 0 {
    if n & 1 == 1 {
      res = res * a % m;
    }
    a = a * a % m;
    n >>= 1;
  }
  res
}

fn extended_euclidean(u: i64, v: i64) -> i64 {
  let mut r0 = u;
  let mut r1 = v;
  let mut s0 = 1;
  let mut s1 = 0;
  let mut t0 = 0;
  let mut t1 = 1;
  while r1 != 0 {
    let q = r0 / r1;
    let r = r0 - q * r1;
    let s = s0 - q * s1;
    let t = t0 - q * t1;
    r0 = r1;
    s0 = s1;
    t0 = t1;
    r1 = r;
    s1 = s;
    t1 = t;
  }
  if t0 < 0 {
    t0 + u
  } else {
    t0
  }
}

fn combination(mut n: i64, r: i64, m: i64) -> i64 {
  let mut upe = 1;
  let mut dow = 1;
  for i in 1..r + 1 {
    upe = upe * n % m;
    dow = dow * i % m;

    n -= 1;
  }
  upe * pow_mod(dow, m - 2, m) % m
}
