#[derive(Copy, Clone, PartialEq, Debug)]
struct ModInt(usize);

const MOD: usize = 998244353;
impl ModInt {
    fn pow(self, power: usize) -> Self {
        if power == 0 {
            return ModInt(1);
        }
        if power % 2 == 0 {
            let t = self.pow(power/2);
            return t * t;
        }
        self * self.pow(power-1)
    }

    fn inv(self) -> Self {
        self.pow(MOD - 2)
    }
}

impl Add for ModInt {
    type Output = Self;

    fn add(self, rhs: Self) -> Self {
        let mut tmp = self;
        tmp.0 += rhs.0;
        if tmp.0 >= MOD {
            tmp.0 -= MOD;
        }
        tmp
    }
}

impl AddAssign for ModInt {
    fn add_assign(&mut self, rhs: Self) {
        *self = *self + rhs;
    }
}

impl Sub for ModInt {
    type Output = Self;

    fn sub(self, rhs: Self) -> Self {
        let mut ret = self;
        if ret.0 < rhs.0 {
            ret.0 += MOD;
        }
        ret.0 -= rhs.0;
        ret
    }
}

impl SubAssign for ModInt {
    fn sub_assign(&mut self, rhs: Self) {
        *self = *self - rhs;
    }
}

impl Mul for ModInt {
    type Output = Self;

    fn mul(self, rhs: ModInt) -> Self {
        let mut ret = self;
        ret.0 *= rhs.0;
        ret.0 %= MOD;
        ret
    }
}

impl MulAssign for ModInt {
    fn mul_assign(&mut self, rhs: Self) {
        *self = *self * rhs;
    }
}

impl Div for ModInt {
    type Output = ModInt;

    fn div(self, rhs: ModInt) -> Self {
        let mut ret = self;
        ret.0 *= rhs.inv().0;
        ret.0 %= MOD;
        ret
    }
}

impl DivAssign for ModInt {
    fn div_assign(&mut self, rhs: Self) {
        *self = *self / rhs;
    }
}

impl fmt::Display for ModInt {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

struct Com {
    n: usize,
    fac: Vec<ModInt>,
    finv: Vec<ModInt>,
}

impl Com {
    fn new(n: usize) -> Self {
        let mut ret = Com {
            n: n,
            fac: vec![ModInt(0); n+1],
            finv: vec![ModInt(0); n+1],
        };
        ret.com_init();
        ret
    }
    fn com_init(&mut self) {
        self.fac[0] = ModInt(1);
        self.fac[1] = ModInt(1);
        self.finv[0] = ModInt(1);
        for i in 2..self.n+1 {
            self.fac[i] = self.fac[i-1] * ModInt(i);
        }
        self.finv[self.n] = self.fac[self.n].inv();
        for i in (2..self.n+1).rev() {
            self.finv[i-1] = self.finv[i] * ModInt(i);
        }
    }
    fn com(&self, n: usize, k: usize) -> ModInt {
        if n < k {
            return ModInt(0);
        }
        self.fac[n] * self.finv[k] * self.finv[n - k]
    }
}

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin.bytes().map(|c| c.unwrap() as char));
    let N: usize = sc.get();
    let M: usize = sc.get();
    let K: usize = sc.get();
    let com = Com::new(N-1);
    let mut ans = ModInt(0);
    for k in 0..=K {
        ans += com.com(N-1, k) * ModInt(M) * ModInt(M-1).pow(N-k-1);
    }
    println!("{}", ans);
}

