impl ModInt {
    fn pow(&self, n: u64) -> ModInt {
        if n == 0 {
            return ModInt(1);
        }
        let prev = self.pow(n / 2);
        if n % 2 == 1 {
            prev.clone() * prev * self.clone()
        } else {
            prev.clone() * prev
        }
    }

    fn inverse(&self) -> ModInt {
        self.pow(MOD - 2)
    }

    fn comb(&self, k1: &ModInt) -> ModInt {
        let mut ret = ModInt(1);
        let ModInt(k) = k1;
        for i in 0..(*k) {
            ret = ret * ModInt(k - i) / ModInt(i + 1);
        }
        ret
    }
}

