struct Comb {
    div: usize,
    g1: Vec<usize>,
    g2: Vec<usize>,
}
impl Comb {
    #[allow(dead_code)]
    fn new(nmax: usize) -> Self {
        let mut g1 = vec![1; nmax + 1];
        let mut g2 = vec![1; nmax + 1];
        let mut inv = vec![0; nmax + 1];
        inv[1] = 1;
        let div = 998244353;
        for i in 2..(nmax + 1) {
            g1[i] = g1[i - 1] * i % div;
            inv[i] = div - (inv[div % i] * (div / i)) % div;
            g2[i] = (g2[i - 1] * inv[i]) % div;
        }
        Comb {
            div: div,
            g1: g1,
            g2: g2,
        }
    }
    #[allow(dead_code)]
    fn compute(&self, n: usize, k: usize) -> usize {
        (((self.g1[n] * self.g2[k]) % self.div) * self.g2[n - k]) % self.div
    }
}

fn main() {
    input! {
        n: usize,
        m: usize,
        k: usize,
    }

    let comb = Comb::new(n);
    let mut res = ModInt::new(0);
    for i in 0..k + 1 {
        let j = n - 1 - i;
        res += ModInt::new(comb.compute(n - 1, j)) * m * ModInt::new(m - 1).pow(j);
    }
    println!("{}", res);
}

